window.PAPERS = [{"id": "2609.14230", "t": "An All-van-der-Waals Qubit", "a": "Sein Park, Sameia Zaman, Junghyun Kim, Junyoung An, Daniel Rodan-Legrain, Hung-Yu Tsao, Chia-Chin Tsai, Aranya Goswami, Réouven Assouly, William P. Banner, Gabriel D. Cutter, Kenji Watanabe, Takashi Taniguchi, Terry P. Orlando, Gil-Ho Lee, Kyle Serniak, Max Hays, Jeffrey A. Grover, Philip Kim, Pablo Jarillo-Herrero, Joel Î-j. Wang, William D. Oliver", "d": "2026-09-17", "s": 94.4, "x": "An all-van-der-Waals superconducting qubit is built from a NbSe$_2$-hBN-NbSe$_2$ junction in which the thin hBN layer provides both the Josephson coupling and the shunt capacitance between two NbSe$_2$ islands, giving a merged-element transmon. cQED characterization yields average $T_1 = 55$ μs, Hahn-echo $T_{2E} = 21$ μs and Ramsey $T_{2R} = 1.9$ μs, comparable to conventional Al-AlO$_x$-Al qubits in a much smaller footprint."}, {"id": "2609.18081", "t": "Remote Adiabatic Controlled-Z Gate between Distant Superconducting Qubits", "a": "Si-Yu Xu, Yi-Rong Jin, Wen-Gang Zhang, Hai-Feng Yu", "d": "2026-09-17", "s": 81.3, "x": "A remote adiabatic controlled-Z gate is proposed and simulated for two frequency-tunable superconducting qubits joined by a multi-mode coaxial cable, with the cable-mediated interaction removing the need for tunable couplers. For a 30 cm cable modelled with ten standing-wave modes, the optimized gate reaches an infidelity of $4.71\\times10^{-7}$ in 376.7 ns without decoherence."}, {"id": "2609.17165", "t": "Phase-stable voltage bias for Josephson photonics devices", "a": "Amir Hosein Esmaeili, Naveen Nehra, Alexandre Paquette, Mona Arabmohammadi, Baptiste Monge, Alexandre Rogalle, Francois Cyrenne-Bergeron, Yannick Lapointe, Nicolas Lavoie, Nicolas Bourlet, Max Hofheinz", "d": "2026-09-17", "s": 68.3, "x": "A Josephson voltage standard is integrated as a noise-tolerant phase reference for dc-biased Josephson photonics devices, and that reference is shown to transfer coherently to an inelastic Cooper-pair tunneling amplifier through the superconducting order parameter. The low-phase-noise bias gives a 14 dB enhancement in averaged gain, improved quantum-limited noise performance, and the first observation of phase-sensitive gain and squeezing in a dc-biased amplifier."}, {"id": "2609.17787", "t": "Superconducting levitation and control of a high-reflectivity micromirror", "a": "Philipp Koller, Jannek J. Hansen, David Walcher, Tomáš Plichta, Rémi Claessen, Martin Žemlička, Philip Schmidt, Rhys G. Povey, Stefan Minniberger, Stefan Putz, Markus Aspelmeyer, Michael Trupke", "d": "2026-09-17", "s": 51.2, "x": "A 30 μg optical micromirror, made of a silicon membrane with a high-reflectivity dielectric stack attached to superconducting microspheres, is stably levitated in a magnetic quadrupole field at cryogenic temperature. With magnetic feedback stabilizing the transverse motion, optical interferometry of the axial displacement reaches a sensitivity of order 100 pm/$\\sqrt{\\mathrm{Hz}}$ near the 167 Hz axial trap frequency."}, {"id": "2609.16488", "t": "Error-Bounded Fixed-Point Design of Super-Sample-Rate IIR Filters for Real-Time Superconducting Qubit Flux Predistortion", "a": "Matt Huszabianlou, Angelos Ioannou, Nirmalendu Bikash Patra, Anastasiia Butko, Gang Huang, Irfan Siddiqi", "d": "2026-09-16", "s": 89.2, "x": "Fixed-point number formats for real-time flux-predistortion filters are derived from a step-response error tolerance and implemented on the open-source QubiC FPGA platform. A super-sample-rate IIR structure with scattered look-ahead pipelining takes the feedback recursion out of the critical path, so an integrator, a second-order section and a 20-tap FIR run at a 500 MHz fabric clock for 1 GS/s flux lines, using 88 DSP slices and adding 162 ns of latency."}, {"id": "2609.15604", "t": "Parametric two-qubit gates via Landau-Zener interference", "a": "Simon Geisert, Albert Hertel, Soeren Ihssen, Zhongyi Jiang, Paul Kugler, Nicolas Zapata, Nicolas Gosling, Ameya Nambisan, Yuan Gao, Asier Galicia, Jéferson R. Guimarães, Yorgo Haddad, Marc Neis, Harsh Bhardwaj, Dmitriy A. Volkov, Juan Cereijo, Marcello Guardascione, Yebin Liu, Markus Jerger, Pavel Bushev, Frank Wilhelm-Mauch, Wolfgang Wernsdorfer, Shai Machnes, Mohammad Ansari, Rami Barends, Ioan M. Pop", "d": "2026-09-16", "s": 87.2, "x": "A two-qubit gate is built from interference between consecutive Landau-Zener transitions of a flux-tunable coupler that is driven sinusoidally through resonance with the data qubits; the coupler returns to its initial state as the qubits swap, giving a gate locally equivalent to iSWAP. It is demonstrated on a modular flip-chip flux-qubit device and on a monolithic transmon device, where the population-swap fidelity is about 0.98, limited by $T_2^\\mathrm{echo} = 2.2$ µs."}, {"id": "2609.16133", "t": "Pulse-Level Compilation of Measurement-Free Recovery in Transmon Circuits", "a": "Yi-Han Yu, Kai Xu, Heng Fan", "d": "2026-09-16", "s": 78.7, "x": "This paper demonstrates compilation of quantum error correction recovery rules directly into fixed open-loop control pulses for transmon circuits, using conditional transition frequencies as a control resource. In a four-qubit repetition-code ring, the resulting input-independent waveform protects logical coherence under Pauli-X noise and logical population under amplitude damping, with a scalable two-color scheduling architecture."}, {"id": "2609.17465", "t": "Quantum Compiler Design for Fault-Tolerant Quantum Computing", "a": "Chenghong Zhu, Jiahan Chen, Keming He, Hongshun Yao, Zhaohui Yang, Jin-Guo Liu, Anbang Wu, Xiaotong Ni, Xingsheng Luan, Zhuo Fu, Shenggen Zheng, Xin Wang", "d": "2026-09-16", "s": 56.2, "x": "This survey presents a full-stack view of quantum compiler design for fault-tolerant quantum error correction, organizing compiler techniques into three interacting layers: logical-level QEC compilation, physical-level QEC realization, and decoder runtime integration. The work reviews surface-code lattice-surgery compilers, beyond-surface-code and qLDPC code-surgery frameworks, syndrome-extraction scheduling, hardware-aware implementation on superconducting/trapped-ion/neutral-atom platforms, and real-time decoding algorithms including matching, belief propagation, and neural approaches."}, {"id": "2609.16630", "t": "Two-qubit gates for the soft 0-π qubit", "a": "Zhenxing Liu, Eli Weissler, Joshua Combes", "d": "2026-09-16", "s": 55.9, "x": "This work proposes a microwave-activated CZ gate for capacitively coupled soft 0-π qubits operating via direct transitions to non-computational states, achieving simulated fidelity of approximately 99.9% at gate time ~160 ns in the idealized zero-disorder limit. The paper also develops single-qubit X gates by driving the θ mode (25 ns, 99.758% fidelity) and demonstrates that this coupling architecture supports two-qubit gates beyond CZ."}, {"id": "2609.16159", "t": "Towards Block-Level Fault-Tolerant Quantum Simulation on Small High-Rate Non-CSS Codes", "a": "Zhuangzhuang Chen, Narayanan Rengaswamy", "d": "2026-09-16", "s": 54.6, "x": "This work investigates circuit-level fault tolerance for logical Pauli-rotation (Trotter) circuits implemented on the [[8,3,3]] non-CSS stabilizer code using block-level constructions that preserve the Trotter pattern under encoding. A circuit-level memory pseudo-threshold of $1.5\\times10^{-3}$ is established for the Chao–Reichardt protocol, but the encoded Trotter implementation exhibits asymmetric logical-$X$ and logical-$Z$ failure channels due to phase faults on the parity ancilla propagating into undetectable logical operators with trivial syndrome."}, {"id": "2609.14197", "t": "Fast CZ gate in hybrid fluxonium-transmon systems with tunable couplers", "a": "Peng Xu, Yunlong Wang, Yuechen Mu, Ling Jiang, Peng Zhao, Shengjun Wu, Xiaohong Yan", "d": "2026-09-15", "s": 93.5, "x": "A CZ gate is proposed for a fluxonium and a fixed-frequency transmon joined by a flux-tunable transmon coupler, driven only by the flux applied to the coupler. Simulations give a 25 ns microwave-free gate with fidelity above 99.99% and leakage below $10^{-5}$ without decoherence, about 99.9% with realistic relaxation and dephasing, and infidelity below $10^{-4}$ when spectator qubits are added."}, {"id": "2609.14081", "t": "Broadband Purcell Filter for Fast Superconducting Qubit Reset and Readout", "a": "Yu Zhao, Zhixu Chen, Hanxian Liu, Mingze Liu, Zixing Liu, Hao Pang, Meiyan Wan, Changkun Wu, Liuzhu Zhong, Sai Li, Yuefeng Yuan, Yuxuan Zhou, Ji Jiang, Ji Chu, Song Liu", "d": "2026-09-15", "s": 93.4, "x": "A three-quarter-wavelength coplanar-waveguide Purcell filter with two notches (intrinsic at 5.6 GHz, bandstop at 4.9 GHz) and an added reset stub separates the readout and reset paths, so each can be made fast without shortening $T_1$. Measured on a device: a Purcell-limited $T_1$ floor above 1 ms across 4.7-5.9 GHz, 500 ns single-shot readout without a Josephson parametric amplifier, and 100 ns reset with 99.6% efficiency."}, {"id": "2609.15477", "t": "Engineering dissipation and control pulses for high-fidelity fault-tolerance quantum computing", "a": "Shao-Wei Xu, Zhe-Yuan Zhang, Yi-Tong Shi, Ye-Hong Chen, Yan Xia", "d": "2026-09-15", "s": 62.2, "x": "The authors design a control protocol for two-photon-dissipation-stabilized cat qubits using shortcut-to-adiabaticity inverse engineering within an effective two-level model of the cat subspace. They identify an optimal-robustness condition against systematic drive errors and show that dissipative confinement suppresses dephasing-induced leakage out of the cat manifold."}, {"id": "2609.13673", "t": "Effect of Buried-Interface Preparation for Nb Superconducting Resonators on InP", "a": "Logan S. Kusher, Ding Peng, Zihua Zhu, Arunav Bordoloi, Axel Leblanc, Lukas J. Baker, Nichae Adnan, Jacob Issokson, Alvin Wang, Frederik Knudsen, Krishna Dindial, Melissa Mikalsen, Taha Kaleem, Andrei Vrajitoarea, Yingge Du, Patrick J. Strohbeen, Javad Shabani", "d": "2026-09-15", "s": 58.4, "x": "Three InP surface preparations before Nb sputtering are compared: untreated, in-situ Ar+ milling, and sulfur passivation. S-passivation gives the cleanest, sharpest buried interface and higher $T_c$, yet single-photon $Q_i$ is similar for all three (about 84k-130k), indicating the resonators are not limited by loss at the Nb-InP interface."}, {"id": "2609.15860", "t": "Probing Residual Noise at a Decoherence Sweet Spot in a $^{28}$Si/SiGe Spin Qubit", "a": "Shinwoo Lee, Hanseo Sohn, Jaemin Park, Hyeongyu Jang, Jonginn Yun, Jun Yoneda, Lucas E. A. Stehouwer, Davide Degli Esposti, Giordano Scappucci, Dohun Kim", "d": "2026-09-15", "s": 54.7, "x": "Two neighbouring $^{28}$Si/SiGe micromagnet spin qubits are compared, one sitting at a sweet spot where the longitudinal field gradient is locally minimized. At the sweet spot $T_2^*$ reaches 67 µs and CPMG coherence 4.6 ms versus $T_2^* = 5.2$ µs next door, with residual noise consistent with $^{29}$Si nuclear spins at 800 ppm."}, {"id": "2609.13055", "t": "Unified scaling of transmon sub-resonant parametric drive strength limits", "a": "Jacob Repicky, Girish Kumbhar, Mingkang Xia, Roman Baskov, Param Patel, Maria Nowicki, Luigi Frunzio, Steven M. Girvin, Michael Hatridge", "d": "2026-09-14", "s": 93.5, "x": "Measurements on 14 transmons with a wide range of anharmonicities show that the largest usable sub-resonant drive amplitude, above which the spectrum hybridizes strongly ('chaos') and the transmon leaves its logical states, is set by a single parameter, $\\gamma = \\omega_q/\\alpha$. The threshold scales as $\\eta_\\mathrm{max} \\propto \\gamma^{0.61}$, with a prefactor that depends only weakly on the normalized drive frequency."}, {"id": "2609.13065", "t": "Error Correction in a Distributed Quantum Computer", "a": "E. M. Ainley, A. Agrawal, T. Araki, A. R. Martínez, D. Main, E. Malinowski, J. A. Blackmore, S. Chen, P. Drmota, M. Mallweger, D. P. Nadlinger, R. Srinivas, S. C. Benjamin, G. Araneda, D. M. Lucas", "d": "2026-09-14", "s": 80.9, "x": "This is the first experimental demonstration of distributed error detection and correction: stabilizers are measured across two trapped-ion modules about 2 m apart, using a photonically generated Bell pair between network qubits as a shared ancilla for the data qubits. A distributed $[[2,1,1]]$ repetition code detects phase flips in real time, and feedforward corrects arbitrary single-qubit Pauli errors on a Bell state shared between the modules."}, {"id": "2609.12592", "t": "Factoring six-digit integers with superconducting quantum circuits", "a": "Xi Zhang, Xinsheng Tan, Yang Yu", "d": "2026-09-14", "s": 68.0, "x": "A superconducting transmon coupled to a cavity implements single-qubit factorization by encoding integers $N$ and candidate factors $(p,q)$ into an effective two-level Hamiltonian via microwave drives, then identifying factor pairs by spectroscopic detection of zero eigenvalues. The protocol successfully factors six-digit integers such as $N=113569$ (factors $337 \\times 337$) without requiring two-qubit gates or entanglement."}, {"id": "2609.12565", "t": "Security Implications of Measurement Based Crosstalk on Superconducting Quantum Computers", "a": "Subarna Adhikari, Kimmo Halunen", "d": "2026-09-14", "s": 57.5, "x": "This work demonstrates that measurement-induced crosstalk on superconducting quantum processors can leak information about victim qubits to adjacent attacker qubits, enabling potential side-channel attacks. Using Support Vector Machine classifiers on VTT Q50 hardware, the authors achieve 76.30% accuracy for single-victim classification and 53.37% for two-victim scenarios, showing hardware-dependent vulnerability compared to prior IBM work (96% accuracy)."}, {"id": "2609.10834", "t": "Programmable CMOS DAC Operating in Cryogenic Environments for Controlling Superconducting Qubits", "a": "A. Pelteku, D. Reitz, M. Covington, A. Frederick, H. Adebayo, K. D. Hillaire, N. Mitran, Z. Steffen, R. Schwartz, Z. Stegen, J. X. Przybysz, J. Yager, C. Walter, T. Graves, D. Meyer, J. Clark, G. R. Boyd, A. Pesetski", "d": "2026-09-11", "s": 94.7, "x": "A current-output CMOS DAC operating at cryogenic temperatures is designed and tested for setting the flux coupled to superconducting qubits or for use in readout. Its pulse amplitude and rise and fall slopes are set digitally and its width by external triggers, and measurements of the planar 90 nm CMOS chip closely match circuit predictions."}, {"id": "2609.11034", "t": "Engineered two-photon dissipative confinement of a Kerr-cat qubit using SISIS quantum circuit refrigerator", "a": "Shumpei Masuda, Tsuyoshi Yamamoto, Shuji Nakamura, Daichi Sugiyama, Akiyoshi Tomonaga", "d": "2026-09-11", "s": 79.9, "x": "A quantum circuit refrigerator (QCR) made from a superconductor-insulator-superconductor-insulator-superconductor (SISIS) junction coupled to a Kerr parametric oscillator is analysed theoretically as a way to keep a Kerr-cat qubit inside its qubit subspace. It has an operating regime where single-photon absorption is suppressed and two-photon absorption dominates, so it removes leakage with a much smaller phase-flip penalty than the usual SINIS refrigerator while the bit-flip rates stay comparable."}, {"id": "2609.10691", "t": "Dissipative quantum mechanics of Andreev bound states", "a": "Mikhail S. Kalenkov, Andrei D. Zaikin", "d": "2026-09-11", "s": 74.5, "x": "A microscopic scheme describes the ac Josephson effect in superconducting junctions as dissipative quantum dynamics of the subgap Andreev bound states. It is aimed at highly transparent junctions at subgap bias voltages, where Landau-Zener tunnelling between Andreev levels combines with the loss of quasiparticles into the continuum, and it yields an extra dissipative, phase-dependent term in the current-phase relation."}, {"id": "2609.10666", "t": "Walking Floquet code circuits for zero-overhead leakage reduction", "a": "Hanna Westerheim, Kaavya Sahay, Shruti Puri", "d": "2026-09-11", "s": 71.6, "x": "This work introduces two zero-overhead walking circuits for the honeycomb Floquet code (hFC)—the swirling and sliding variants—that periodically remove leakage via anticommuting two-body measurements while preserving code distance to Pauli errors. Numerical simulations reveal that in the experimentally relevant waterfall regime, entropic effects allow the hFC to outperform the same-distance walking surface code despite lacking asymptotic advantages for some noise models."}, {"id": "2609.10146", "t": "Post-fabrication trimming of a 1024-pixel, single-photon counting, Microwave Kinetic Inductance Detector array with a pixel pitch of 150 micron", "a": "Wilbert Ras-Vinke, Hessel Schulte, David J. Thoen, Kevin Kouwenhoven, Steven A. H. de Rooij, Tonny A. H. M. Coppens, Jochem J. A. Baselmans, Pieter J. de Visser", "d": "2026-09-11", "s": 69.2, "x": "Microwave Kinetic Inductance Detectors (MKIDs) with a 1024-pixel array at 150 µm pixel pitch suffer from significant frequency scatter caused by both fabrication variations and tight packing, limiting detector yield for frequency-division multiplexing. Post-fabrication electron-beam trimming of interdigitated capacitor finger lengths reduces frequency scatter from $1.1 \times 10^{-2}$ to $3.5 \times 10^{-4}$ and increases yield from 76% to 94% with no degradation in quality factor or noise."}, {"id": "2609.10655", "t": "Conditional-squeezing gate in superconducting circuits", "a": "Roman Schiaffino, Fernando C. Lombardo, Juan Pablo Paz", "d": "2026-09-11", "s": 65.9, "x": "This paper implements a conditional-squeezing gate in superconducting circuits that applies state-dependent squeezing to a SQUID-terminated resonator mode, controlled by a dispersively coupled qubit. A refocusing technique suppresses unwanted effects from slowly varying Hamiltonian terms, enabling high-fidelity encoding of arbitrary qubit states into superpositions of squeezed states with fidelities exceeding 0.99."}, {"id": "2609.05222", "t": "A double-resonator coupler for high-fidelity two-qubit gates between superconducting qubits", "a": "Seunghyeon Jin, Seungha Woo, Shinyoung Hwang, June-Young M. Lee, Jeongmin Shim, Sunje Kim, Dae Seok Han, Jaeho Shin, Eunjong Kim", "d": "2026-09-10", "s": 92.1, "x": "A double-resonator coupler (DRC) for transmons is proposed: two resonators joined by a single Josephson junction and a capacitor, whose common and differential modes give two exchange paths between the qubits that interfere. Flux-tuning the differential mode cancels ZZ completely at the idle point for detunings well outside the straddling regime, and near half a flux quantum gives $|\\mathrm{ZZ}| \\approx 70$ MHz, enough for a 20 ns CZ gate with simulated coherent infidelity below $10^{-5}$ and fidelity above 99.9% once relaxation and flux noise are included."}, {"id": "2609.00772", "t": "Superconducting Flux Memory for Cryogenic Applications", "a": "Gregory R. Boyd, Jeremy Clark, Mark Covington, David G. Ferguson, Aref Fouladi, Keith D. Hillaire, Moe Khalil, John McFarland, Aaron Pesetski, Anthony J. Przybysz, John X. Przybysz, Sambarta Rakshit, Aruna N. Ramanayaka, Brian Sears, Robert Smith, Colin Stack, Robert M. Young, Tony X. Zhou", "d": "2026-09-10", "s": 89.4, "x": "On-chip flux memory stores persistent currents in superconducting loops to flux-bias circuits such as qubits, and three cell types are built and compared. Once a cell is set, the room-temperature DC sources can be switched off, and a transmon biased this way held its target frequency for 20 hours."}, {"id": "2609.07250", "t": "Qubit-Based Benchmarking of InP HEMT LNAs: Readout Fidelity Versus Power Consumption", "a": "Junjie Li", "d": "2026-09-10", "s": 79.5, "x": "Cryogenic InP HEMT low-noise amplifiers with 53%, 60% and 70% channel indium content are benchmarked with a qubit in the loop, using the single-shot IQ readout histogram as the figure of merit instead of a Y-factor noise temperature. Readout SNR and assignment fidelity peak for the 60% device, which beats a commercial reference amplifier by about 5% on average, although the 60% and 70% devices have similar Y-factor noise temperatures and the 70% device has the most gain."}, {"id": "2609.09495", "t": "Certifying bipartite entanglement on a superconducting processor from a corrected QAOA cost layer", "a": "Carlos-Miguel Lorenzo", "d": "2026-09-10", "s": 62.7, "x": "This pre-registered study on a five-qubit superconducting processor certifies bipartite entanglement in a depth-one QAOA cost layer via two-qubit tomographic negativity of 0.077 (95% CI [0.065, 0.091]), with the entanglement signal controlled by CZ pulse amplitude and peaking at conditional phase $|\\zeta| = \\pi$. The entanglement certificate collapses by depth three and no optimization advantage emerges at depth three, highlighting how device physics—not algorithm design—governs QAOA behavior on current hardware."}, {"id": "2609.09426", "t": "Josephson energy of superconducting junctions: amorphous versus crystalline tunnel barriers", "a": "Wanting Zhang, Aldilene Saraiva-Souza, Félix Beaudoin, Xianghua Kong, Hong Guo, Yu Zhu", "d": "2026-09-10", "s": 52.8, "x": "First-principles NEGF-DFT calculations of Al/AlO$_x$/Al Josephson junctions show that amorphous Al$_2$O$_3$ barriers produce a mean $E_J/h$ of 2.78 GHz with 4.67 GHz standard deviation, spanning nearly two orders of magnitude, compared to 0.73 GHz for crystalline Al$_2$O$_3$. The variability arises from percolation-like tunneling pathways formed by stoichiometric inhomogeneity in the amorphous oxide, but a realistic $200 \times 200$ nm$^2$ junction self-averages over $>2 \times 10^4$ microscopic regions."}, {"id": "2609.07076", "t": "Single-tone drive-enhanced CROT gate for bosonic quantum error correction", "a": "Shushen Qin, Long D. H. My, Adrian Copetudo, Amon M. Kasper, Yvonne Y. Gao, Hui Khoon Ng", "d": "2026-09-09", "s": 69.6, "x": "This work demonstrates a direct implementation of the controlled-rotation (CROT) gate for bosonic quantum error correction in circuit QED, using drive-enhanced cross-Kerr interactions between two cavity modes coupled to a transmon. The scheme operates at a single transmon drive frequency and preserves the code-agnostic error-propagation properties essential for rotation-symmetric bosonic codes like cat and binomial codes."}, {"id": "2609.08569", "t": "Fabrication And Characterization Of High-Quality Nb/Al-AlO$_x$/Nb Cross-Type Josephson Tunnel Junctions Utilising CMP-based Planarisation Techniques", "a": "Alexander Stoll, Andreas Reifenberger, Daniel Hengstler, Andreas Fleischmann, Christian Enss", "d": "2026-09-09", "s": 67.9, "x": "This paper demonstrates wafer-scale fabrication of high-quality Nb/Al-AlO$_x$/Nb cross-type Josephson junctions using chemical-mechanical polishing (CMP) for planarization instead of lift-off processes, achieving >90% yield and junction areas down to $1\times1$ µm$^2$. The CMP-based process produces uniform critical current density $j_c \backsim 220$ A/cm$^2$ and resistance ratio $R_{\rm sg}/R_N \backsim 38$, with area-independent characteristic voltage $V_c \backsim 1.4$ mV demonstrating consistent tunnel barrier quality across the wafer."}, {"id": "2609.07613", "t": "Experimental realization of quantum-computing-enhanced sensing", "a": "Yifang Xu, Hongwei Huang, Yilong Zhou, Yunlai Zhu, Chuanlong Ma, Lida Sun, Lintao Xiao, Ziyue Hua, Weiting Wang, Zijie Chen, Weizhou Cai, Hekang Li, Haohua Wang, Xiaoting Wang, Ming Li, Chang-Ling Zou, Luyan Sun", "d": "2026-09-09", "s": 63.5, "x": "This work experimentally demonstrates quantum-computing-enhanced sensing by implementing Grover's algorithm in a superconducting cavity-qubit system, where the unknown signal directly generates the phase oracle to enable frequency identification. The protocol achieves quantum amplitude amplification spanning over 128 photons in Fock space and resolves ~4× more candidate frequencies than classical sequential search for the same number of signal interrogations."}, {"id": "2609.08348", "t": "Instantaneous-Frame Theory of Strongly Driven Parametric Gates", "a": "Kentaro Kubo, Shinichi Inoue, Jushin Tei, Yinghao Ho, Yasunobu Nakamura, Hayato Goto", "d": "2026-09-09", "s": 55.5, "x": "Parametric two-qubit gates with tunable couplers are accurately described using instantaneous eigenstates as a natural moving frame for driven dynamics, where the non-Abelian Berry connection governs transitions, achieving quantitative agreement with exact simulations across double-transmon, capacitively shunted double-transmon, and single-transmon coupler architectures. This instantaneous-frame theory successfully predicts both exchange couplings and conditional $ZZ$ phases in regimes where conventional idle-frame models fail, while substantially reducing reliance on computationally demanding exact simulations."}, {"id": "2609.07235", "t": "Asymmetric quantum error correction efficiently tackles application-specific noise effects", "a": "Abhishek Yadav, Peter K. Schuhmacher, Michael Epping", "d": "2026-09-09", "s": 53.6, "x": "This work compares how bit-flip ($X$) and phase-flip ($Z$) Pauli noise asymmetrically affect QAOA performance on a flight-gate assignment problem, finding that bit-flip errors cause larger degradation in the optimized cost across layer-level and gate-level noise models. The authors exploit this asymmetry to propose using asymmetric quantum error-correction codes, demonstrating that a $(5,3)$ quantum parity code achieves performance comparable to a symmetric $(5,5)$ code while using 10 fewer physical qubits."}, {"id": "2609.01334", "t": "Fast Microwave-free State Preparation and Measurement of Superconducting Qubits", "a": "R. Abraham, F. Amet, P. Anderson, M. Arrigo, J. Arteaga, C. J. Ballard, C. Barker, T. Barnes, P. Bechmann, R. Bhatt, K. Blaine, T. M. Borman, J. Botimer, G. R. Boyd, P. Bradley, A. D. Brandon, T. K. Bristol, A. Bulkos, R. M. Burnett, D. Burrowes, D. N. Cakan, N. Carniero, T. Chamberlin, D. Chen, M. Chilcote, B. G. Christensen, I. Christie, J. Clark, D. Clarke, J. M. Cochran, J. C. Collini, K. Connolly, G. Costa, D. Cowger, B. Dalfort, R. D. Dawson, D. Davies, S. Deitemeyer, N. DeNigris, F. Densmore, S. J. Di Giacomo, S. G. Diamond, R. DiCiro, S. M. Disseler, K. Dixon, J. Donnelly, E. Donohue, M. Downing, B. Eastin, N. Edwards, M. Ehsani, S. Ellis, R. Epstein, D. Ferguson, P. Fischer, S. Friedensen, D. Gabriel, M. A. Gettelman, A. Gillam, G. Gilmore, J. Goode, E. Goodwin, M. Gottschalk, A. L. Graninger, T. Graves-Abe, J. Hackley, N. Hartman, B. Heacock, B. Heischmidt, P. Helms, R. Hinkey, B. Hong, S. T. Howard, D. Jensen, N. Johns, D. R. Johnson, J. Johnson, H. Kaplan, Z. Keane, S. Keebaugh, C. Kegerreis, K. Kelcourse-Oquendo, M. S. Khalil, D. Killeen, A. S. Knutson, T. Kohler, M. Kornecki, F. Koutsouli, A. Krick, K. L. Krycka, J. Kuan, D. Lad, J. R. Lane, N. J. Laurita, A. C. Lee, A. R. Lemmon, E. M. Leonard, L. M. D. Leonard, J. Leventis, M. P. Lilly, A. Lisiewski, L. Llano, M. Longo, C. Lostoski, Z. Lou, M. G. Loving, D. Ludwig, N. Luhrs, J. L. Lund, K. A. Maddock, R. J. Magyar, K. Mahmud, T. A. Manning, A. I. Marakov, A. D. McCreary, P. F. McLaughlin, J. R. Medford, E. Metz, A. L. Middleton, A. Miklich, R. Miller, J. Mlack, M. Mucci, N. Mungo, T. Murphy, R. E. Murray, O. Naaman, J. Nakamura, M. Noevere, S. Novikov, M. E. Nowakowski, C. Nunez, K. N. Ogg, B. Oshokoya, D. Paz, A. Pesetski, T. Pillsbury, C. Pinion, A. D. Pitcock, A. J. Przybysz, P. Quarterman, D. Queen, I. Ramos, S. L. Reed, D. Reitz, M. Rennie, S. Reza, B. Richman, K. H. Rigdon, C. Rotella, M. Rudolph, E. Sadler, T. Safford, D. Saha, A. E. Saia, D. I. Santiago, R. Schwartz, A. Schwarzkopf, M. Scott-Jones, S. L. Sendelbach, S. J. Shapiro, A. N. Sharma, M. E. Sherwin, A. Sierakowski, J. N. Sills, R. Simha, N. Siwak, J. Smith, C. Snyder, H. Solomon, N. S. Sperlein, L. St. Marie, K. Stalpes, S. F. Steers, Z. Stegen, R. M. Stein, T. I. Stephenson, M. Stoutimore, J. D. Strand, J. A. Strong, E. Swain, S. Swami, A. Tamang, I. Thompson, A. B. Tokarchik, N. Tralshawala, D. Tran, S. Tyler, L. Upton, G. Van Dyke, J. Vannucci, K. Vempati, J. S. Vogel, R. Vyas, M. Wagner, P. Warner, N. Washington, B. Way, M. A. Wayne, D. Wehella-Gamage, M. E. Weippert, T. Weitzel, J. Wenner, L. White, S. Whitsitt, A. Wilkinson, R. Willey, I. Yandow, J. Yang, L. Yu, F. Yumiceva, V. Zheng, R. Zimmerman, C. Zinn, J. Ziskind", "d": "2026-09-08", "s": 98.0, "x": "Fast microwave-free state preparation and measurement of superconducting qubits is demonstrated using strong coupling between a high-coherence computational qubit (CQ) and a flux qubit (FQ), achieving >99% fidelity in 10 ns for each operation. Combined with quantum flux parametron amplification and an analog-to-digital converter, full quantum-to-digital conversion is completed in 15 ns—an order of magnitude faster than dispersive readout—while remaining compatible with scalable superconducting digital control systems."}, {"id": "2609.05192", "t": "Dynamical Reduction of Two Series Josephson Junctions to a Synthetic High-Transparency Josephson Element", "a": "Claudio Guarcello, Sergio Pagano, Carlo Barone, Alessandro Bruno, A. Mert Bozkurt, Giovanni Filatrella", "d": "2026-09-07", "s": 66.7, "x": "Two series Josephson junctions with areas scaled in ratio $\\alpha$ can be reduced to a single effective high-transparency element with $\\mathcal{T} = 4\\alpha/(1+\\alpha)^2$, whose validity under dynamical drive is systematically investigated through normalized voltage-waveform RMS error. The reduction remains accurate to $\\epsilon_V \\lesssim 10^{-4}$–$10^{-5}$ over broad frequency and amplitude ranges but breaks down in the strongly nonlinear near-resonant regime where internal relative-phase dynamics emerge."}, {"id": "2609.05226", "t": "TETRIS-Q: Tiling-based Effective Transient-fault Reduction on Interleaved Superconducting Qubits", "a": "Marzio Vallero, Gioele Casagranda, Flavio Vella, Paolo Rech", "d": "2026-09-07", "s": 66.2, "x": "TETRIS-Q is a planar-mesh tiling algorithm that combines substrate-level phonon barriers with QEC code interleaving to suppress radiation-induced correlated faults in superconducting qubits. Through over 51 million simulations on rotated surface codes, the approach achieves logical error reductions exceeding 99.8% and reduces observable transient duration by 80%, with sparse tiling enabling 87% cost reductions in barrier implementation."}, {"id": "2609.04704", "t": "Strong-Drive Limits in Josephson Circuits: From Chaos to an Unbound-Resonance Threshold", "a": "Xinyuan You, Aniket Maiti, Yao Lu", "d": "2026-09-07", "s": 61.9, "x": "This paper develops a unified description of strong-drive limits in flux- and charge-driven Josephson circuits across drive frequency and dc flux bias using classical phase-space analysis and Floquet–Markov simulations. At low frequency, bound-state resonances and separatrix chaos govern the response with a dc-bias-dependent chaos threshold, while at high frequency a distinct unbound-resonance transition occurs where the dissipative steady state transfers from the central bound-state region to outer resonances formed by above-barrier running trajectories."}, {"id": "2609.05177", "t": "Transparency-engineered SQUID cells for Kerr-free three-wave-mixing Josephson metamaterials", "a": "Claudio Guarcello, A. Mert Bozkurt, Carlo Barone, Giovanni Filatrella, Alessandro Bruno, Sergio Pagano", "d": "2026-09-07", "s": 53.0, "x": "This paper introduces the TRAIL cell, a transparency-engineered rf-SQUID unit cell using two series Josephson junctions to achieve Kerr-free three-wave mixing, where the quartic nonlinearity vanishes while cubic nonlinearity persists. A Kerr-free operating ridge is identified in the $\\left(\\beta, \\Phi\\right)$ parameter space by tuning junction asymmetry $\\beta = I_{c2}/I_{c1}$ and magnetic flux bias, enabling selective control over nonlinear coefficients $c_3$ and $c_4$ in the local potential expansion."}, {"id": "2609.03059", "t": "Flux noise without flux tunability in superconducting qubits", "a": "Daniel Kruti, Roman-Pascal Riwar", "d": "2026-09-04", "s": 82.5, "x": "Starting from a quantum-geometric description of Faraday induction, the paper derives how magnetic sources (surface or substrate spins, and current-carrying flux lines) couple to thin-film superconducting circuits with realistic geometry. The main finding is that flux noise limits the qubit quality factor as well as dephasing, even for qubits with no loop: if surface spins cause the universal $1/f$ flux noise, the limit lies between about $10^{8}$ and $10^{10}$, not far above today's record quality factors of $10^{7}$ to $10^{8}$."}, {"id": "2608.25027", "t": "Real-time decoder for a MegaQuOp quantum computer using a single CPU", "a": "Min Ye, Andrii Maksymov, Nicolas Delfosse", "d": "2026-09-04", "s": 68.5, "x": "This work demonstrates an end-to-end real-time decoder for a universal fault-tolerant trapped-ion quantum computer capable of processing workloads with up to 408 logical qubits and one million logical $T$ gates using only a single conventional CPU. The decoder achieves computational stretch (additional syndrome-extraction cycles due to decoding latency) below 0.3% at $p_{\text{CNOT}}=10^{-4}$ and below 12% at $p_{\text{CNOT}}=5\times10^{-4}$ across all tested benchmarks."}, {"id": "2609.03194", "t": "Experimental validation of a compact fault-tolerant architecture for trapped ions", "a": "Noah Berthusen, Ali Lavasani, Asmae Benhemou, M. S. Allman, Joan Dreiling, Brian Estey, Cameron Foltz, Trent Jacobs, Michael Mills, Annie Jihyun Park, Adam P. Reed, David Hayes, Tzvetan S. Metodi, Andrew C. Potter", "d": "2026-09-04", "s": 66.4, "x": "The $[[20,2,6]]$ $C_4$-Helix code has been experimentally validated on Quantinuum Helios as a complete fault-tolerant architecture on a 98-qubit trapped-ion processor, with logical operations outperforming physical baselines without postselection. Repeated QEC achieves $4.6^{+6.2}_{-2.6}\\times10^{-5}$ error per logical qubit per cycle, two-qubit logical Clifford gates achieve $2.8^{+1.0}_{-1.6}\\times10^{-4}$ error, and a heterogeneous three-logical-qubit GHZ state prepared via chain-map to a distance-5 surface code reaches $99.925^{+0.068}_{-0.245}\\%$ fidelity."}, {"id": "2608.06636", "t": "Approaching the Fundamental Limit of Single-Shot Qubit Frequency Tracking with an Adiabatic Tangentially-Modulated Pulse", "a": "Itamar Oren, Luke I. Dyer, Calum Holker, Gerardo A. Paz-Silva, Chih Hwan Yang", "d": "2026-09-04", "s": 59.8, "x": "The adiabatic tangentially-modulated (ATM) pulse is a single-shot qubit frequency tracker that produces a sigmoidal detuning response with independently tunable sensitivity and range through amplitude and frequency modulation derived from quantum adiabatic theory. A single ATM measurement achieves sensitivity $S \\approx 81$ kHz comparable to 100-shot Bayesian Ramsey averaging while maintaining robustness to $\\pm 10$ dB amplitude noise, enabling tracking of kilohertz-scale frequency noise with a white-noise floor of $P_N^{\\mathrm{floor}} \\propto G^2 f_s$ at high feedback gain."}, {"id": "2609.04132", "t": "Characterizing Large Scale Quantum Systems with Error Per Circuit Layer", "a": "Travis Hurant, Arian Vezvaee, Swarnadeep Majumder, Aniket Dalvi, Jude Alnas, Kenneth R. Brown", "d": "2026-09-04", "s": 59.3, "x": "Error Per Circuit Layer (EPCL) is an overlap-based circuit-level benchmarking protocol that estimates effective layer polarization by measuring the overlap between output states of two identically evolved quantum registers, avoiding classical simulation of ideal distributions. Numerical simulations validate EPCL under depolarizing and coherent noise while identifying sensitivity to register covariance and coherent entangling-layer errors, and hardware demonstrations on IBM Berlin show clear exponential decay in 8- and 16-qubit implementations."}, {"id": "2609.01817", "t": "Bosonic quantum control with a weakly coupled fluxonium qubit", "a": "Anaida Ali, Shantanu R. Jha, Shoumik D. Chowdhury, Lev-Arcady Sellem, Max Hays, William D. Oliver, Baptiste Royer", "d": "2026-09-03", "s": 83.3, "x": "This work numerically demonstrates Echoed Conditional Displacement (ECD) gates for bosonic control using a fluxonium qubit, achieving vacuum-subspace fidelities exceeding 99.9% and GKP logical fidelities near 99%. The authors develop a semiclassical framework accounting for all-order dispersive terms via displacement transformation, revealing saturation of the dispersive shift $\\chi_\\mathrm{eff}(|\\alpha|^2)$ at large resonator amplitudes and deriving an improved ECD pulse sequence that compensates for photon loss and higher-order nonlinearities."}, {"id": "2609.02372", "t": "Implementation of quantum gates by Floquet analysis of kicked quantum system", "a": "Andrea De Luca, Carola Ciaramelletti, Simone Paganelli", "d": "2026-09-03", "s": 61.7, "x": "This work synthesizes high-fidelity quantum gates in superconducting linear chains by mapping periodic pulsed driving onto Floquet quasi-energy resonance conditions, achieving iSWAP gates in a three-qubit processor and demonstrating multi-excitation transport with $t_\text{gate} \thicksim 170$–430 ns in a seven-site architecture. Robustness analysis reveals sharp performance degradation under sub-percent static disorder ($\theta \thicksim 10^{-3}$) in linear topologies, suggesting closed-loop ring geometries as a mitigation strategy."}, {"id": "2609.01848", "t": "Error accumulation in dissipative quantum circuits", "a": "Nadir Samos-Sáenz de Buruaga, Rodrigo M. C. Pereira, Karol Życzkowski, Sergey Denisov, Pedro Ribeiro", "d": "2026-09-03", "s": 59.9, "x": "This work establishes universal error accumulation in dissipative random quantum circuits, deriving closed-form expressions for average fidelity decay that depend only on dissipation strength, system size, and depth, while being insensitive to microscopic details like Kraus rank at the mean-fidelity level. The analysis identifies regimes where dissipative noise can or cannot be reproduced by effective unitary errors, providing guidance for distinguishing physical error mechanisms in NISQ devices."}, {"id": "2609.01901", "t": "Need One Bell-pair Only (NOBOL) for Low-Overhead Fault-Tolerant Quantum Computing", "a": "Sean Grzenda, Shahram Babaie, Chunming Qiao", "d": "2026-09-03", "s": 58.2, "x": "This paper proposes NOBOL, a method for implementing logical CNOT gates between distant qubits encoded in arbitrary CSS codes using only a single Bell pair and local operations. The approach achieves logarithmic circuit depth $O(\\log \\tau)$ where $\\tau$ is the weight of the logical operator, reducing the entanglement overhead from linear in code size $N$ to a single shared pair."}, {"id": "2609.02641", "t": "Transversal Gates and Magic State Distillation in an Optimally Synthesized Spin-Qubit Shuttling Bus", "a": "Pau Escofet, Andrii Semenov, Niall Murphy, Elena Blokhina, Carmen G. Almudéver, Sergi Abadal, Eduard Alarcón", "d": "2026-09-03", "s": 51.8, "x": "This work extends a 1D spin-qubit shuttling bus architecture optimized for syndrome extraction to support transversal two-qubit logical gates via pairwise interactions between data qubits from distant logical elements, with all-to-all connectivity and logical error rates reaching $2 \\times 10^{-10}$ per syndrome-extraction round at distance $d=21$. The architecture integrates ancilla-sharing schemes to compress the physical footprint, explores 2D junction-based connectivity to reduce inter-qubit distances, and demonstrates application to 15-to-1 magic state distillation with optimized logical-qubit placement via Quantum Reverse Mapping."}, {"id": "2609.02828", "t": "Effective Sub-Quantum Readout for Non-Monochromatic Axion Signals in High-$Q$ Haloscopes", "a": "Junu Jeong, Max Silva-Feaver", "d": "2026-09-03", "s": 51.4, "x": "For non-monochromatic axion signals in high-$Q$ cavities ($Q_c \\gg Q_a$), operating a Josephson Parametric Amplifier with the cavity resonance centered at the half-pump frequency allows the axion signal to symmetrically populate both signal and idler bands, effectively halving the Standard Quantum Limit from 1 quantum to 0.5 quanta per frequency bin. After optimal matched filtering over the merged spectral lineshape, this configuration yields an overall noise floor of $1/\\sqrt{2}$ quanta and doubles the scanning rate compared to conventional non-degenerate operation."}, {"id": "2609.02226", "t": "Coherent microwave-to-optical transduction with Yb:YSO spins strongly coupled to a 3D resonator", "a": "Ujjwal Gautam, Nasser Gohari Kamel, Sourabh Kumar, Daniel Oblak", "d": "2026-09-03", "s": 50.7, "x": "This work demonstrates continuous-wave microwave-to-optical transduction using a 5 ppm doped Yb:YSO crystal coupled to a 3D loop-gap resonator, achieving an internal efficiency of $2\\times10^{-8}$ and 200 kHz bandwidth at zero magnetic field. The measurement establishes strong spin-microwave coupling ($g_{m,\\mathrm{ens}}/2\\pi = 850$ kHz, $C_m = 2.6$) and projects that optimized parameters (50 ppm doping, reduced beam diameter, increased pump power) could reach $10^{-4}$ efficiency while preserving the long coherence times ($T_{2,\\mathrm{o}} = 800$ µs, $T_1 = 1.3$ ms) needed for quantum memory integration."}, {"id": "2608.29399", "t": "FIREQ: FPGA Instrumentation for Readout and Qubit control", "a": "Giuseppe La Capra, Fabio Calabrese, Giorgio D'Amico, Christian Conti, Andrea De Simone, Deborah Volpe, Angelo Nucciotti, Roldolfo Carobene, Claudio Gatti, Andrea Giachero, Fabrizio Riente", "d": "2026-09-02", "s": 79.1, "x": "FIREQ is an open-source RFSoC-based framework for superconducting qubit control and readout implemented on an AMD Zynq UltraScale+ ZCU216, combining modular AXI-compliant firmware with a PYNQ-based software stack to achieve direct RF synthesis up to 9.3 GHz, 107 ps pulse-duration resolution, and 1.7 ns event-timing resolution. End-to-end validation on a superconducting qubit yields $T_1 = 6.94$ µs and $T_2^* = 13.50$ µs, with normalized resource utilization competitive with existing RFSoC frameworks while maintaining low BRAM footprint through envelope interpolation and memory-efficient buffering."}, {"id": "2609.00939", "t": "Robust CZ gate against flux line memory", "a": "Yao Song, Xiu-Hao Deng", "d": "2026-09-02", "s": 67.3, "x": "This work models flux line memory in superconducting qubit control as a stateful classical actuator coupled to the quantum system, deriving first-order error generators for each actuator state component using Dyson expansion. Robust CZ pulses are designed by suppressing these generators and minimizing residual flux line state at gate exit, achieving $F_\\mathrm{avg}=99.998\\%$ for single gates and $99.97\\%$ over ten consecutive gates with $2.3\\times10^3$ reduction in sequence infidelity versus baseline."}, {"id": "2609.01593", "t": "Understanding the superconducting proximity effect in semiconductors through quantum oscillations", "a": "Milo Coombs, Teun A. J. van Schijndel, Yu Wu, Jason T. Dong, Yilmaz Gul, Julian Choi, Christopher J. Palmstrøm, Greg P. Mazur", "d": "2026-09-02", "s": 50.9, "x": "Quantum oscillations of a buried InAs quantum well beneath Al, Sn, V, Nb, Ta and Re films directly measure the semiconductor's normal-state parameters—density, mass, $g$-factor, mobility and quantum lifetime—that are renormalized but not accessible to tunnelling spectroscopy. Every metal creates a distinct interface subband with occupation falling into two classes determined by orbital character rather than work function, while the buried well's mass and $g$-factor remain invariant at $0.040\\text{–}0.044\\,m_e$ and $|g_\\mathrm{eff}| = 4.9 \\pm 0.2$ across all films, and its quantum lifetime either improves or remains unchanged."}, {"id": "2608.31154", "t": "Engineering multi-photon dissipation with a dc-voltage-biased Josephson junction", "a": "Marco Paradina, Ambroise Peugeot, Roberto Negrin, Oscar Novat, Tristan Villain, Anil Murani, Jean-Loup Ville, Sébastien Jezouin, Raphaël Lescanne, Audrey Bienfait, Benjamin Huard", "d": "2026-09-01", "s": 84.0, "x": "A dc-voltage-biased SQUID couples a high-Q memory resonator to a lossy buffer mode, engineering single-, two-, and four-photon dissipation through dynamical Coulomb blockade where the energy $2eV$ from Cooper pair tunneling matches multi-photon transitions. The approach suppresses parasitic nonlinearities by construction compared to parametrically pumped couplers, with measured two-photon loss rate $\\kappa_2/2\\pi = 0.51$ MHz and maximum two-to-one coupling $g_2^{\\mathrm{max}}/2\\pi = 18.5 \\pm 0.5$ MHz."}, {"id": "2608.29282", "t": "Anomalous Frequency Shift in Low-Loss Superconducting Granular Aluminum Resonators", "a": "Patrick Winkel, Daniil S. Antonenko, Vishakha Gupta, Neel Thakur, Pavel Kurilovich, Luigi Frunzio, Leonid I. Glazman, Robert J. Schoelkopf", "d": "2026-09-01", "s": 83.6, "x": "Superconducting granular aluminum (grAl) resonators with quality factors up to $1.85 \times 10^6$ exhibit anomalous positive frequency shifts with increasing temperature and readout power at $T < 200$ mK, contradicting standard Mattis–Bardeen and TLS predictions. The authors explain the temperature dependence via quasiparticles in a Josephson-junction network with spatially nonuniform superconducting gaps ($\\delta\\Delta_0 \\sim h f_0$), but the observed dissipation remains unexplained by two orders of magnitude at low temperatures."}, {"id": "2608.28906", "t": "Design and Modeling of the Charge Readout of a SiMOS Quantum Dot with a Single Electron Transistor and CryoCMOS", "a": "Adam Quinn, Troy England, Andrew Li, Sharmila Mustari Nandita", "d": "2026-09-01", "s": 66.7, "x": "This paper presents design techniques and compact models for a cryogenic CMOS readout ASIC (QNDR1) that combines a single electron transistor (SET) with integrated amplification for SiMOS quantum dot spin qubits. The work includes the first Verilog-A models for double-island and asymmetric-sensing-dot SETs, a 22 nm FDSOI cryogenic PDK at 3.8 K, and simulation results demonstrating $22.5$ to $106.2$ MV/A gain with input-referred noise of $32$ pA rms and power consumption dominated by preamplifier stages consuming $10$–$16$ µW."}, {"id": "2608.31093", "t": "Device characterization of Si$/$SiGe double quantum dots using exchange oscillations in Earth's magnetic field", "a": "Holly G. Stemp, Harry Hanlim Kang, Chih Hwan Yang, Gabriel D. Cutter, Frederike Brockmeyer, Patrick J. Strohbeen, Max Hays, Jeffrey A. Grover, William D. Oliver", "d": "2026-09-01", "s": 53.7, "x": "This work demonstrates zero-applied-field characterization of Si/SiGe double quantum dots using exchange oscillations driven by residual nuclear-spin gradients, enabling measurement of singlet coherence, residual exchange, and exchange-dependent decay without micromagnets or calibrated multi-axis control. CPMG sequences with up to $N=70$ refocusing pulses extend singlet coherence from $T_2^*=1.17±0.02$ µs to $T_2^{\text{CPMG}}=74.8±1.8$ µs, while oscillation-phase analysis resolves residual exchange in the tens-of-kilohertz regime across the $(1,1)$ charge cell and reveals a broad decay-rate enhancement between 20–40 MHz exchange frequency."}, {"id": "2608.27789", "t": "Scaling Alternating-Bias-Assisted Annealing for Precision Transmon Frequency Targeting on Superconducting Quantum Processors", "a": "Xiqiao Wang, Mark Field, Teng Zhang, Xian Wu, Ferhat Aydinoglu, Joel Howard, Angela Q. Chen, Sara Elzeiny, Robert Smith, Timothy McSorley, Nicholas Sharac, Eyob Sete, Alysson Gold, Hilal Cansizoglu, Greg Stiehl, Josh Mutus, Kameshwar Yadavalli, Andrew Bestwick, Stefano Poletto, Raja Katta, David P. Pappas", "d": "2026-08-31", "s": 89.4, "x": "This work demonstrates scalable alternating-bias-assisted annealing (ABAA) for transmon frequency tuning on 150 mm wafers, achieving $\\sigma = 0.50 \\pm 0.05\\%$ junction resistance precision and $98.8\\%$ component-level yield through multi-channel parallel tuning. Implementation on the Rigetti Cepheus-1-36Q quantum processor achieves empirical frequency targeting precision of $\\sigma \\sim 30$ MHz in both $f_{01}^{\\mathrm{max}}$ and qubit-qubit detuning, directly enabling high two-qubit gate fidelities."}, {"id": "2608.28535", "t": "Hardware-Efficient Error Mitigation and Shot-Efficient Sampling on IBM Quantum Hardware", "a": "Sumit Chongder", "d": "2026-08-31", "s": 78.5, "x": "This paper evaluates error mitigation and finite-shot sampling on an IBM Quantum Heron processor using a fixed measurement budget, finding that standard zero-noise extrapolation (ZNE) and pilot-variance-based adaptive shot allocation do not uniformly improve mean-squared error relative to uniform allocation or raw measurement. Hardware experiments on 156-qubit ibm_marrakesh with median two-qubit error $2.99 \\times 10^{-3}$ and readout error $1.45 \\times 10^{-2}$ show that adaptive ZNE outperformed uniform allocation at only 2 of 6 tested budgets (average MSE ratio 2.16), and that coupler selection from calibration data produced errors comparable to multiple circuit layers."}, {"id": "2608.28463", "t": "Fabrication-free assessment of microwave losses in germanium-based dielectrics and superconductors", "a": "Haoran Lu, Kushagra Aggarwal, Xiangqin Wang, Pauline Drexler, Daniel Tong, Maciej W. Olszewski, Anand Ithepalli, Lingda Kong, Debdeep Jena, Peter L. McMahon, David A. Muller, Dominique Bougeard, Valla Fatemi", "d": "2026-08-31", "s": 70.7, "x": "A flip-chip sensing technique enables fabrication-free measurement of microwave losses in target materials by placing them above a sensor chip with superconducting resonators separated by SU-8 pillars, avoiding processing-induced damage that confounds traditional resonator fabrication. Applied to Ge/SiGe heterostructures and superconducting films, the method reveals that bare Ge and composition-graded SiGe virtual layers exhibit loss tangents of $(183 ± 37) × 10^{-6}$ and $(200 ± 29) × 10^{-6}$, respectively, with HF treatment reducing the as-grown Ge/SiGe QW heterostructure loss from $(658 ± 464) × 10^{-6}$ to $(108 ± 18) × 10^{-6}$."}, {"id": "2608.28428", "t": "Kerr nonlinearity and three-wave mixing in superconducting resonators hosting Al-InAs weak links", "a": "Vittorio Buccheri, Ivo P. C. Cools, Nermin Trnjanin, Ankit Khola, Oleg Shvetsov, Thomas Kanne, Jesper Nygård, Attila Geresdi, Simone Gasparinetti", "d": "2026-08-31", "s": 50.2, "x": "This work demonstrates tunable Kerr and cubic nonlinearities in a superconducting NbTiN resonator hosting two aluminum-capped indium arsenide nanowire weak links, with independent flux and gate control over each junction. The authors achieve zero Kerr nonlinearity ($K/2\\pi \\approx 0$ kHz) while maintaining substantial cubic nonlinearity ($|g_3| \\approx 35$–$70$ kHz), and experimentally demonstrate three-wave mixing parametric amplification with on-off gain exceeding 20 dB, reaching 25 dB in the optimized double-junction configuration."}, {"id": "2608.27045", "t": "A Superconducting Phase Transition Single-Electron Transistor", "a": "Gorka Aizpurua-Iraola, Thomas H. Swift, Felix-Ekkehard von Horstig, Domenic Prete, James Kirkman, Grayson M. Noah, Fabio Olivieri, Alberto Gomez-Saiz, M. Fernando Gonzalez-Zalba", "d": "2026-08-28", "s": 68.1, "x": "The work demonstrates a superconducting phase-transition radio-frequency single-electron transistor (PTSET) that exploits a superconducting-to-normal phase transition in a high-kinetic-inductance TiN inductor to enhance charge sensing sensitivity for semiconductor spin qubits. The device achieves one order of magnitude improvement in the large-signal regime and two orders of magnitude in the small-signal regime compared to conventional rfSETs."}, {"id": "2608.11733", "t": "A 12-CNOT Double Qubit Excitation Gate", "a": "Irfansha Shaik", "d": "2026-08-28", "s": 61.8, "x": "This work presents the first 12-CNOT decomposition of the double-qubit excitation operator $U^{ij}_{kl}(\\theta) = \\exp[-i\\theta/8(\\sum_m c_m P_m)]$, which rotates between computational basis states $|0011\\rangle$ and $|1100\\rangle$. The new circuit improves upon state-of-the-art 13-CNOT implementations with reduced CNOT depth (8, ∼27% reduction; 7 with output relabeling, ∼36% reduction) and total circuit depth (15, ∼25% reduction)."}, {"id": "2608.26018", "t": "The Gain-Engineered Transmon", "a": "Ian Yang, Francesco Adinolfi, Alessandro Bruno, Venus Hasanuzzaman Kamrul, Daniel Z. Haxell, Alexander Grimm", "d": "2026-08-27", "s": 96.6, "x": "The gain-engineered transmon realizes a noise-biased qubit in a standard transmon-cavity system by adding a single microwave tone that creates frequency-selective single-photon gain on the $|e\\rangle$–$|f\\rangle$ transition, suppressing relaxation errors while preserving coherent control. The $|g\\rangle$–$|f\\rangle$ encoding achieves $T_1 = 2.22$ ms (×16.7 enhancement over $|g\\rangle$–$|e\\rangle$) with $T_2^E = 65$ µs and 99.58% gate fidelity, enabling scalable noise-biased error correction."}, {"id": "2608.25484", "t": "Low-leakage superconducting-qubit measurement with sub-100-ns total duration", "a": "Peter A. Spring, Adrian L. Hesse, Shiyu Wang, Shuhei Tamate, Yasunobu Nakamura", "d": "2026-08-27", "s": 96.0, "x": "Fast dispersive readout of a superconducting transmon qubit is demonstrated with 97(1) ns total measurement duration (from pulse start until measurement-induced π-pulse error drops below $10^{-4}$), achieving 0.17(1)% assignment error with a 58 ns pulse. Measurement-induced leakage is suppressed to $2.7(2) \\times 10^{-5}$ per measurement by operating at small qubit–resonator detuning ($\\omega_r/\\omega_q = 1.24$) where multiphoton resonances are weak and traversed diabatically."}, {"id": "2608.25645", "t": "Phase-sensitive cascade quantum amplifier with nearly noiseless operation", "a": "Ilari Lilja, Ekaterina Mukhanova, Michael Perelshtein, Kirill Petrovnin, Stanislav Khaldeev, Visa Vesterinen, Gheorghe Sorin Paraoanu, Pertti Hakonen", "d": "2026-08-27", "s": 85.5, "x": "A SQUID-based Josephson Parametric Amplifier (JPA) fabricated with VTT SWAPS technology was cascaded with a Traveling-Wave Parametric Amplifier (TWPA) to demonstrate phase-sensitive parametric amplification at 6 GHz with system noise temperature of $94 \\pm 12$ mK. This represents $0.06$ added photons in the phase-sensitive regime, well below the standard quantum limit of $288$ mK achieved in phase-preserving operation ($351 \\pm 53$ mK, $0.71$ added photons)."}, {"id": "2608.25503", "t": "High-Fidelity Entangled States in a Connectivity-Four Fluxonium Quantum Processor", "a": "J. Schirk, N. Bruckmoser, S. M. Taubenberger, F. Wallner, N. J. Glaser, M. Zetzl, L. Huang, I. Tsitsilin, M. Werninghaus, L. Södergren, K. Liegener, C. M. F. Schneider, Stefan Filipp", "d": "2026-08-27", "s": 82.5, "x": "A fluxonium quantum processor using lumped-element resonator couplers achieves a connectivity-four unit cell with single-qubit gate fidelities exceeding 99.9%, residual ZZ interactions below 1 kHz, and two-qubit RIP-gate fidelities exceeding 99% via refocused pulse sequences that suppress spectator errors. GHZ states up to five qubits are prepared with tomographic fidelities reaching 90%, demonstrating multi-qubit entanglement compatible with surface-code error correction."}, {"id": "2608.25959", "t": "Dissipatively Stabilized 0-n Fock Qubits for Noise-Biased Quantum Computing", "a": "Su Direkci, Simon Lieu, Kyungjoo Noh, Connor T. Hann", "d": "2026-08-27", "s": 81.5, "x": "We propose a dissipatively stabilized 0-n Fock qubit that encodes information in the ground state $|0\\rangle$ and n-th excited state $|n\\rangle$ of an anharmonic oscillator, achieving exponentially suppressed bit-flip errors with increasing n through the separation of logical levels. We demonstrate a practical implementation using a multimode lossy filter to engineer frequency-selective dissipation, and show bit-flip probabilities approaching $10^{-8}$ for controlled-X gates with cat qubits using $n\\geq 9$, enabling logical error rates of $10^{-6}$ in a repetition code at distance $d=9$."}, {"id": "2608.24084", "t": "Lifting connectivity bottlenecks in superconducting quantum processors via enriched native two-qubit gates", "a": "Hanyi Wang, Jingzhe Guo, Lijun Sun, Zhaohui Yang, Weizhi Tao, Xingye Yuan, Qiankun Wang, Bihao Guo, Chunwang Liu, Rui Yang, Yang Li, Yu Fan, Jiasheng Hu, Junhe Wang, Shuyue Zheng, Shengbin Wang, Xinfang Zhang, Feng Wu, Hantao Sun, Jianxin Chen", "d": "2026-08-26", "s": 73.0, "x": "The paper demonstrates that enriched native two-qubit control via the AshN scheme—combining tunable coupling with simultaneous microwave drives—enables SWAP absorption into adjacent gates, effectively increasing the connectivity of superconducting qubit processors with fixed coupling graphs. On benchmark circuits with 1D and 2D topologies, AshN compilation achieves 45.2% and 43.7% reductions in two-qubit gate count compared to controlled-Z, with experimental validation on an 8-qubit Dicke state achieving 0.736 fidelity and certified genuine multipartite entanglement even under connectivity defects."}, {"id": "2608.23681", "t": "Bang-bang protocol for nondispersive qubit readout", "a": "Nina del Ser, Yinan Chen, Jacob Steiner, Gil Refael", "d": "2026-08-26", "s": 70.3, "x": "This paper presents a bang-bang protocol for nondispersive qubit readout using sudden quenches of the qubit-resonator coupling instead of adiabatic parameter sweeps. The protocol achieves fast, high-fidelity quantum-non-demolition readout with errors scaling as $1/N_\\mathrm{eff}$ by exploiting dynamics in the Jaynes-Cummings model with a large photon number $N_\\mathrm{eff}$."}, {"id": "2608.21983", "t": "Automating detection of Two-Level Systems in Superconducting Qubits", "a": "Rama Khalil, Cameron J. Kopas, Avinash Pathapati, Rory Cochrane, Xiqiao Wang, Hossein Taghinejad, Vito Iaia, Josh Mutus, Yaniv J. Rosen, Jared H. Cole, David P. Pappas, Alexander V. Balatsky", "d": "2026-08-25", "s": 93.2, "x": "Two complementary automated pipelines for detecting two-level system (TLS) defects in superconducting transmons via SWAP spectroscopy are presented: one-dimensional decay-rate fitting (1D-DRF) and a deterministic computer-vision framework (2D-CV) exploiting temporal persistence of coherent population suppression. Deployed across 52 flux-tunable transmons on Rigetti processors, both methods reveal that moderate ($\\sim 10\\%$) post-fabrication frequency trimming via Alternating-Bias Assisted Annealing (ABAA) selectively suppresses strongly dissipative defect channels while leaving total TLS count unchanged, reducing span-integrated loss by a factor of $\\sim 2$ ($6.9\\,\\text{kHz} \\to 3.1\\,\\text{kHz}$)."}, {"id": "2608.21512", "t": "Robust cavity metrology beyond the limits of Pound-Drever-Hall", "a": "Ibukunoluwa Adisa, Won Chan Lee, Yanqin Huang, Nathan Schine, Kevin C. Cox, Alicia J. Kollár", "d": "2026-08-25", "s": 69.2, "x": "This work presents robust cavity metrology observables based on the scissors phase $\\Sigma = 2\\phi_0 - (\\phi_- + \\phi_+)$ that eliminate systematic errors in Pound-Drever-Hall (PDH) spectroscopy caused by sideband amplitude imbalance and demodulation-phase errors. An experimentally efficient observable $\\mathbb{S}_Q = E_- E_+ E_0^2 \\sin\\Sigma$ is introduced that requires only addition and multiplication (no arctangent) and is demonstrated in both optical cavity locking and superconducting qubit readout."}, {"id": "2608.23159", "t": "Taming Spacetime Overhead and Design Complexity in Distributed Fault-Tolerant Superconducting Quantum Computation", "a": "Qinjing Yu, Ke Liu", "d": "2026-08-25", "s": 60.1, "x": "This paper presents a hardware-grounded distributed architecture for fault-tolerant superconducting quantum computation and a comprehensive resource-estimation protocol for surface-code-based modular processors connected via noisy inter-chip links. Using RSA-2048 factorization as a benchmark under experimentally anchored parameters ($p_b = 10^{-3}$, $p_s = 10^{-2}$, inter-chip gates up to $25 \times$ slower), the distributed architecture requires only 2.0 million physical qubits and 4.4 days compared to a monolithic baseline of 1.3 million qubits and 3.4 days, with overhead nearly scale-invariant across module capacities from thousands to hundreds of thousands qubits per chip."}, {"id": "2608.23460", "t": "Satisfying Quantum Codes: Physics-Informed and Hardware-Aware Code Design with SAT Solvers", "a": "Ben DalFavero, William M. Watkins, Margarite L. LaBorde, Vincent Russo, Ethan Egger, Gregory Quiroz, Ryan LaRose", "d": "2026-08-25", "s": 51.7, "x": "This paper presents a SAT-based computational framework for designing quantum error correction codes that can incorporate physics-inspired symmetries and hardware-specific noise models. The authors prove code design is NP-complete, demonstrate a SAT–UNSAT phase transition in random instances, and experimentally validate the approach by discovering novel codes—including extensions of a 100-qubit Fermi-Hubbard code in minutes and surface codes outperforming the XZZX code under biased noise."}, {"id": "2608.20453", "t": "Practical Error Suppression and Mitigation for Reliable Quantum Computing", "a": "Han-Ze Li, Mengjie Yang, Xianquan Yan, Dax Enshan Koh, Ching Hua Lee, Ruizhe Shen", "d": "2026-08-24", "s": 79.6, "x": "This review surveys error suppression and mitigation techniques across the NISQ-to-FTQC transition, treating error correction, suppression, and mitigation as complementary layers of a unified strategy rather than isolated approaches. The work emphasizes practical implementation of hardware-aware circuit design, coherent-error suppression, readout mitigation, noise extrapolation, and classical inference on near-term devices, with extensions to encoded and logical-qubit settings."}, {"id": "2608.19602", "t": "High fidelity control of superconducting qubits with optical transmitted signal", "a": "Yu-Huai Li, Daojin Fan, Na Li, Fusheng Chen, Shaowei Li, Dong-Dong Li, Yu Xu, Jin Lin, Ming Gong, He-Liang Huang, Hui Deng, Yulin Wu, Haoran Qian, Shaojun Guo, Futian Liang, Xiaobo Zhu, Cheng-Zhi Peng, Jian-Wei Pan", "d": "2026-08-21", "s": 97.6, "x": "This work demonstrates optical-assisted transmission of microwave control signals for superconducting qubits, modulating XY and Z control signals on a 1490 nm directly modulated laser at room temperature and regenerating them with InGaAs photodiodes at the 4 K stage of a dilution refrigerator. Single-qubit and two-qubit CZ gates achieve fidelities of 99.915% ± 0.005% and 99.676% ± 0.041%, respectively, meeting surface-code error-correction thresholds while reducing heat load and enabling thousand-channel scalability."}, {"id": "2608.05686", "t": "Provably Efficient Self-Calibrating Quantum Fault Tolerance", "a": "Weiyuan Gong, Hong-Ye Hu", "d": "2026-08-21", "s": 59.2, "x": "This paper establishes a theoretical framework for self-calibrating quantum fault tolerance, proving that syndrome measurements collected during quantum error correction can simultaneously protect logical information and stabilize hardware control parameters. The framework proves convergence to $\\varepsilon$ detection rate within $O(1/\\varepsilon^2)$ epochs for time-independent drifts and demonstrates code-distance-independent scalability for quantum LDPC codes."}, {"id": "2608.19696", "t": "Coherence protection of a silicon hole spin qubit with phase-modulated microwave driving", "a": "Sayyid I. Ibad, Yusuke Sato, Takuma Kuno, Itaru Yanagi, Toshiyuki Mine, Ryuta Tsuchiya, Digh Hisamoto, Hiroyuki Mizuno, Raisei Mizokuchi, Jun Yoneda, Tetsuo Kodera", "d": "2026-08-21", "s": 53.4, "x": "A phase-modulated concatenated continuous driving (CCD) technique suppresses low-frequency charge and hyperfine noise in hole spin qubits in silicon quantum dots. The method stabilizes Rabi oscillations, extends decay times, and maintains coherence protection during gate operations."}, {"id": "2608.18699", "t": "An ultracompact dilution refrigerator for fast quantum device characterization", "a": "Clment Geffroy, Dorian Nicolas, Eric Eyraud, Shelender Kumar, Supriya Mandal, Julien Jarreau, Laura Kowalski, Laurent Del-Rey, Didier Dufeu, Nicolas Roch, Wolfgang Wernsdorfer, Quentin Ficheux, Matias Urdampilleta", "d": "2026-08-20", "s": 76.7, "x": "An ultracompact dilution refrigerator (3 kg, 100 mm diameter) achieves a full cooldown–warm-up cycle to 70 mK in 2.1 hours when fully wired for microwave measurements, delivering 20 µW cooling power at 100 mK. Complete characterization of a two-fluxonium device demonstrates state-of-the-art performance with single-qubit gate fidelities reaching 99%, enabling high-throughput quantum device screening without sacrificing measurement quality."}, {"id": "2608.18332", "t": "Generalizing Pauli Checks for Qudit-based Quantum Error Detection and Mitigation", "a": "Noble Agyeman-Bobie, Quinn Langfitt, Salahedeen Issa, Nikos Hardavellas, Kaitlin N. Smith", "d": "2026-08-20", "s": 62.7, "x": "This paper generalizes Pauli Check Sandwiching (PCS) from qubits to qudits of arbitrary dimension $d$ by constructing checks from Heisenberg-Weyl operators that deterministically map errors to unique ancilla readouts. The protocol achieves unit fidelity under joint post-selection on noiseless checks and is validated numerically across $d = 2$ to $9$, demonstrating error-mitigated fidelities above $97.5\\%$ under realistic depolarizing noise."}, {"id": "2608.17020", "t": "Multi-purpose quantum laboratories from superconducting circuits", "a": "Arpit Arora, Emily M. Been, William Munizzi, Joel Wang, Taylor L. Patti, Aaron Chou, Prineha Narang", "d": "2026-08-19", "s": 83.2, "x": "This review unifies superconducting circuits (SCs) as multi-purpose quantum laboratories spanning condensed matter physics, dark matter detection, and quantum information science. SCs leverage their high-quality microwave resonators and coherent control capabilities to simultaneously serve as precision measurement instruments for discovering emergent quantum phenomena and as platforms for generating and manipulating quantum resources like entanglement and magic."}, {"id": "2608.17400", "t": "Quantum sensors that compute: quantum computational magnetic-field sensing using a superconducting qubit", "a": "Purnendu Sen, Mathieu Ouellet, Saeed A. Khan, Wayne Wang, Sridhar Prabhu, Alen Senanian, William P. Banner, William D. Oliver, Peter L. McMahon", "d": "2026-08-19", "s": 76.3, "x": "This work demonstrates quantum computational sensing (QCS) using a single superconducting transmon qubit with an integrated SQUID loop, where quantum signal processing interleaves sensing operations with trained control unitaries to encode task-relevant information into measurement outcomes prior to readout. For binary classification of static magnetic fields, the protocol achieves 3.0–14.9 percentage point accuracy improvements over Ramsey-based phase estimation, and for oscillating fields achieves 3.8–20.1 percentage points over dynamical decoupling, with advantages growing for more complex classification tasks."}, {"id": "2608.17189", "t": "Fast Nondestructive Readout for High-Clock-Rate Atom Array Quantum Processor", "a": "Xu-Zhao-Qiu Zeng, Chang You, Qing-Wei Wang, Zi-Feng Li, Yi Ji, Dong An, Chao Yu, Jia-Rui Liu, Zi-Mo He, Jia-Rui Gu, Yuhao Mei, Hao-Wen Cheng, Yu-Chen Zhang, Rui Lin, Zhan Wu, Jun Rui, Jun Zhang, Ming-Cheng Chen, Yu-Hao Deng, Chao-Yang Lu, Jian-Wei Pan", "d": "2026-08-19", "s": 75.9, "x": "This work demonstrates fast nondestructive readout (FNDR) for neutral-atom arrays by combining real-time photon counting with adaptive per-site optical hiding to suppress unnecessary photon scattering, reducing average probe time to 15 µs and achieving state-averaged discrimination infidelity of $4.1 \\times 10^{-5}$ with atom loss of $2.1 \\times 10^{-4}$. Operating repeated quantum circuits at 1.7 kHz clock rate with atoms reused over 120 consecutive rounds—nearly sevenfold faster than previous records—FNDR removes measurement as the dominant bottleneck for fault-tolerant quantum computation."}, {"id": "2608.02773", "t": "Quantum error correction at ultra-low overhead", "a": "Zhide Lu, Weikang Li, Dong-Ling Deng", "d": "2026-08-18", "s": 69.1, "x": "Cornucopia codes are a family of quantum low-density parity-check codes achieving encoding rates exceeding $1/2$ while maintaining pseudo-thresholds above $0.4\\%$ under circuit-level noise, designed for efficient implementation on reconfigurable neutral-atom arrays through co-optimized code geometry and atom-rearrangement protocols. A single $[[2844, 1426, 18]]$ code block encodes 1426 logical qubits with extrapolated logical error rates of $2.6 \\times 10^{-16}$ per logical qubit per cycle at physical error rate $0.1\\%$, achieving greater than tenfold reduction in qubit overhead compared to bivariate bicycle codes."}, {"id": "2608.16702", "t": "Time-optimal quantum gates with bang-bang control in multilevel systems", "a": "Valentín Reparaz, Santiago Ferreyra, María José Sánchez, Daniel Domínguez, Leandro Tosi", "d": "2026-08-18", "s": 51.1, "x": "This work applies Pontryagin's Principle to determine time-optimal bang-bang pulse sequences for single-qubit $\\pi/2$ gates, proving that the fastest implementation consists of discrete maximum-amplitude pulses alternating with idle periods. The framework is demonstrated on a transversally driven two-level system with exact analytic solutions, then extended to the fluxonium superconducting circuit where coherent suppression of leakage through interference conditions enables high-fidelity operation despite strong driving."}, {"id": "2608.14357", "t": "Native multi-qubit gates on a single-junction unimon circuit", "a": "Sasu Tuohino, Mikko Möttönen, Matti Silveri", "d": "2026-08-17", "s": 97.3, "x": "The multiunimon is a single-junction superconducting circuit encoding three qubits with native controlled-controlled-NOT gates achieved via microwave drives on a branched coplanar waveguide structure. Simulations demonstrate twelve three-qubit gates with mean fidelity $99.56\\%$ at $20$ ns gate times, limited primarily by dielectric loss, with coherent-error-only simulations suggesting fidelities approaching $99.99\\%$ at $60$ ns."}, {"id": "2608.13627", "t": "A scalable edge-pass Purcell filter for high-fidelity readout of superconducting qubits", "a": "Xudong Liao, Yuan Li, Sainan Huai, Shuyi Pan, Zhenxing Zhang, Zhiwen Zong, Kunliang Bu, Yulei Ye, Wen Zheng, Xinsheng Tan, Yang Yu, Xiaopei Yang, Tianqi Cai, Shengyu Zhang", "d": "2026-08-17", "s": 86.1, "x": "This work demonstrates scalable edge-pass Purcell filters for superconducting qubits that use a single transmission edge to separate readout and qubit bands, realized as compact lumped-element high-pass (HPF) or low-pass (LPF) filters. The HPF achieves 99.46(4)% average readout fidelity in 150 ns and the LPF achieves 99.49(3)% in 130 ns, with single-qubit gate fidelities of 99.94% and 99.93% respectively, while providing effective Purcell protection that strengthens with filter order and includes an intrinsic dissipation mode for qubit reset."}, {"id": "2608.08500", "t": "Crystalline Germanium Josephson Junctions", "a": "Frederik H. Knudsen, Axel Leblanc, Yiliu Li, Patrick J. Strohbeen, Jechiel van Dijk, Logan Kusher, Arunav Bordoloi, Alisa Danilenko, Xiangchao Ma, Salva Salmani-Rezaie, Javad Shabani", "d": "2026-08-17", "s": 63.8, "x": "This work demonstrates crystalline Josephson junctions fabricated from Ga-doped Ge superconductors grown entirely by molecular beam epitaxy, featuring atomically sharp interfaces and a 0.5 nm Si weak link with no amorphous barrier. The devices exhibit strong Josephson coupling in the ultra-short regime and an unconventional magnetic-field enhancement of switching current attributed to quasiparticle-assisted thermalization through Al contacts."}, {"id": "2607.27392", "t": "Anomalous Microwave Response in YBCO Resonators beyond the Two-Level-System Model", "a": "Kaiwen Zheng, Nathan J. Johnson, Nathan T. Thobaben, Sidharth Duthaluru, Haochen Shen, Denae T. Cherry, David S. Wisbey, Kater W. Murch", "d": "2026-07-31", "s": 86.8, "x": "CPW resonators fabricated from YBCO thin films exhibit $Q_i$ of $4\\times10^3$–$10^4$ at 70 mK, reaching maxima of $8\\times10^3$–$1.2\\times10^4$ near 6 K, with anomalous low-temperature frequency shifts and losses that cannot be explained by conventional two-level-system models. The low-temperature frequency upturn is consistent with a paramagnetic response from defect-induced local moments or Andreev bound states, while the loss follows an unexplained logarithmic temperature dependence."}, {"id": "2607.28479", "t": "Mitigating quantum decoherence via global optimal control", "a": "Ashkan Abedi, Roberto Menta, Julien Despres, Marco Polini, Francesco Caravelli, Vittorio Giovannetti", "d": "2026-07-31", "s": 62.1, "x": "This work investigates decoherence in a globally driven superconducting ladder architecture using tensor-network simulations and demonstrates that relaxation is the dominant dissipative error, degrading single-qubit and two-qubit gate fidelities. Pulse optimization via GRAPE reduces gate duration by nearly an order of magnitude (from ~3000 ns to ~320 ns for the Hadamard), restoring high fidelities ($\\mathcal{F} \\approx 0.96$) across dissipation rates up to $\\gamma_- = 0.08$ µs$^{-1}$ ($T_1 \\approx 12.5$ µs)."}, {"id": "2607.28605", "t": "Logical computation with canonical lifted product codes", "a": "Han Zheng, Guo Zheng, Liang Jiang, Qian Xu", "d": "2026-07-31", "s": 60.3, "x": "This work develops a complete fault-tolerant logical instruction set for a family of lifted-product (LP) quantum error-correcting codes by identifying a canonical logical basis with cyclic and row-column-parallel structure. The canonical LP codes achieve high rates with distances up to 20, encoding hundreds to thousands of logical qubits while supporting low-overhead modular gate implementations and highly parallel measurements."}, {"id": "2607.27930", "t": "Design of a Quantum Error Correction Decoder Exploiting Temporal Parallelism", "a": "Leo Itoh, Takuya Kasamura, Hidetsugu Irie, Junichiro Kadomoto", "d": "2026-07-31", "s": 59.0, "x": "This paper proposes a microarchitecture for sandwich decoding using the Union-Find algorithm with temporal parallelism to accelerate surface code QEC, achieving 35% average latency reduction at code distance $d=21$ compared to batch decoding while maintaining a logical error threshold of 1.5% under phenomenological noise. The design is implemented as an ASIC in TSMC 22 nm and 7 nm processes, with detailed RTL and synthesis results demonstrating sub-microsecond decoding latencies suitable for superconducting qubit cycles."}, {"id": "2607.27527", "t": "Noise-resilient and Scalable Quantum Error Correction for Nuclear Spin Qubits in Silicon with Electron Shuttling", "a": "Wayne M. Witzel, Matthew D. Grace, Dwight R. Luhman", "d": "2026-07-31", "s": 54.0, "x": "This paper introduces electron pair interferometry (EPI), a measurement protocol for nuclear spin qubits in silicon quantum dots that uses shuttled electron pairs to read out parity via singlet/triplet interference, enabling a complete gate set for universal quantum computation tailored to CSS quantum error correction. The approach maintains robustness to charge noise and demonstrates controlled sensitivity to magnetic field inhomogeneities, leveraging recent advances in isotopically enriched silicon (single-digit ppm $^{29}$Si), large quantum dot arrays, and coherent electron shuttling."}, {"id": "2607.27644", "t": "Quantum LDPC codes with design rate 1/5 and good performance below 1000 physical qubits", "a": "Yifan Hong", "d": "2026-07-31", "s": 50.4, "x": "This work introduces quantum LDPC codes with design rate $1/5$ constructed from balanced products of classical codes with non-abelian $\\mathbb{Z}_{\\ell_1} \\rtimes \\mathbb{Z}_{\\ell_2}$ (ZSZ) group symmetries, achieving code-capacity memory efficiency $kd^2/n$ superior to prior constructions for block lengths below 1000 physical qubits. Under idling-free circuit-level depolarizing noise at $0.1\\%$ strength with GPU-accelerated Relay-belief-propagation decoding, ZSZ-LP codes with $d \\in \\{10,12,14,16,18\\}$ approach the gigaquop and teraquop regimes with latencies of 1–2 ms, and syndrome extraction on reconfigurable atom arrays requires 30–60 ms rearrangement overhead per round."}, {"id": "2607.27123", "t": "Hardware-efficient erasure-error detection with an integer fluxonium", "a": "Junyoung An, Helin Zhang, Jeffrey M. Gertler, Kate Azar, Renée DePencier Piñero, Michael Gingras, Junghyun Kim, Bethany M. Niedzielski, Ilan T. Rosen, Mollie E. Schwartz, Joel Î-j. Wang, Terry P. Orlando, Jeffrey A. Grover, Max Hays, Kyle Serniak, William D. Oliver", "d": "2026-07-30", "s": 91.4, "x": "This work demonstrates erasure-error detection and conversion in a single integer fluxonium where the ground state $|g\\rangle$ and second excited state $|f\\rangle$ form the logical qubit and the first excited state $|e\\rangle$ encodes erasures. By exploiting the integer fluxonium's energy landscape to suppress direct $|f\\rangle \\to |g\\rangle$ transitions while enabling dominant $|f\\rangle \\to |e\\rangle$ relaxation, the device achieves ancilla-free mid-circuit erasure checks using the readout resonator with minimal dephasing of logical states via careful suppression of the dispersive shift $\\chi_{gf}$."}, {"id": "2607.27094", "t": "Native CCZ Gate with Fluxonium Qubits and a Microwave-Driven Coupler", "a": "Grigoriy S. Mazhorin, Tatyana A. Chudakova, Alena S. Kazmina, Nikolai G. Berezkin, Arina V. Zotova, Artyom M. Polyanskiy, Nikolay N. Abramov, Mikhail A. Tarkhov, Alexander M. Mumlyakov, Igor V. Trofimov, Elizaveta A. Krivko, Nikita Yu. Rudenko, Maxim V. Chichkov, Vladimir I. Chichkov, Ilya A. Simakov", "d": "2026-07-30", "s": 91.3, "x": "A native three-qubit CCZ gate locally equivalent to Toffoli is demonstrated on a fluxonium processor with a microwave-driven transmon coupler, achieving 99.39(5)% fidelity in 65 ns. This native implementation avoids the eight two-qubit gates required by conventional decomposition, reaching performance competitive with CZ gates at 99.94% fidelity."}, {"id": "2607.26242", "t": "Precise 2D electric field density simulations for superconducting quantum devices", "a": "Zydrunas Gimbutas, Wei-Ren Syong, Nhi Nguyen, Ariana Taylor, Joel N. Ullom, Bradley K. Alpert, Douglas A. Bennett, Corey Rae H. McRae", "d": "2026-07-30", "s": 75.4, "x": "A fast boundary integral equation solver for 2D electrostatic problems achieves 100× speedup over finite-element methods with relative errors around $10^{-7}$ for participation ratio calculations in superconducting coplanar waveguides. The method uses Green's first identity to avoid field squaring near corner singularities, revealing that the metal-air sidewall and triple junction deviate from assumed linear participation scaling with dielectric constant, while other interfaces follow the linearity assumption."}, {"id": "2607.26161", "t": "A two-dimensional piezo-optomechanical transducer", "a": "Tian Xie, Nelson Ooi, Linus Woodard, Sultan Malik, Felix Mayor, Oliver A. Hitchcock, André G. Primo, Wentao Jiang, Samuel Gyger, Amir H. Safavi-Naeini", "d": "2026-07-30", "s": 67.8, "x": "A two-dimensional piezo-optomechanical transducer using band-structure engineering converts microwave photons to optical photons via mechanical phonons, achieving 0.85% internal conversion efficiency at 10 mK with photon-phonon pair generation near the mechanical ground state. The design overcomes thermal and fabrication challenges of prior one-dimensional transducers by using a spatially-graded $\\Gamma$-potential to directly engineer collective mechanical modes that robustly couple to both the optical cavity ($g_{\\mathrm{om}}/2\\pi = 540$ kHz for mode 1) and an integrated lithium niobate piezoelectric element ($\\gamma_{\\mathrm{em}}/2\\pi = 4.6$ kHz at room temperature)."}, {"id": "2607.27111", "t": "Effective Hamiltonians for Predictive Quantum Control", "a": "Razvan Stanescu, Hugo Ribeiro", "d": "2026-07-30", "s": 61.7, "x": "The paper investigates how the choice of effective Hamiltonian affects predictive quantum control for transmon qubits, comparing the standard Duffing approximation with a more faithful diagonalized-transmon model that retains the full cosine potential's spectral and control-operator properties. Correction fields derived from the Duffing Hamiltonian substantially reduce error within that model but fail to transfer effectively to an independently calibrated diagonalized-transmon baseline pulse, demonstrating that small differences in transition frequencies and charge-matrix elements compound during driven evolution into substantially different dynamical error generators."}, {"id": "2607.27204", "t": "Fault-Tolerant Logical Operations and Efficient State Preparation in Modular Quantum Architectures with Noisy Interfaces", "a": "Siddardha Chelluri, Riccardo Mengoni, Tom Darras, Julien Laurat, Eleni Diamanti, Ioannis Lavdas", "d": "2026-07-30", "s": 59.4, "x": "This work analyzes fault-tolerant logical operations in modular quantum architectures by simulating distributed CNOT gates via lattice surgery between noisy QPUs connected by imperfect Bell pairs, and develops efficient protocols for preparing distributed logical GHZ states. The key finding is that interfaces tolerate noise up to $\\alpha = 20$ times higher than intra-QPU noise (threshold degradation only $2$–$3 \\times 10^{-3}$), and ancilla minimization for GHZ state preparation reduces to a polynomial-time vertex-cover problem on spanning trees."}, {"id": "2607.26480", "t": "Feedback stabilization of multi-qubit Hamiltonian parameters enabled by single-shot measurement-based sequential Monte Carlo", "a": "Hyeongyu Jang, Jaemin Park, Younguk Song, Jinwoong Kim, Hanseo Sohn, Lucas E. A. Stehouwer, Davide Degli Esposti, Giordano Scappucci, Dohun Kim", "d": "2026-07-30", "s": 54.1, "x": "A sequential Monte Carlo estimation framework enables real-time feedback stabilization of both single-qubit frequencies and two-qubit exchange couplings in a four-qubit semiconductor quantum dot device using minimal measurement data. Single-shot, one-bit frequency estimation achieves approximately twofold coherence time improvement over conventional Bayesian strategies, and two-bit sequential estimation suppresses both quasi-static drift and exchange-interaction noise."}, {"id": "2607.24946", "t": "Numerical Modeling of Quasiparticle-Induced Dissipation in Fluxonium Qubits", "a": "Kate Azar, Max Hays, Kyle Serniak", "d": "2026-07-29", "s": 92.4, "x": "This work numerically models quasiparticle (QP)-induced energy relaxation in fluxonium qubits, showing that the widely-assumed energy hierarchy $\\varepsilon - \\Delta \\ll \\hbar\\omega_{ij} \\ll \\Delta$ breaks down in realistic conditions, leading to QP sensitivity at bias points previously thought protected. The analysis covers both preexisting QP tunneling and photon-assisted tunneling (PAT) processes, revealing that gap asymmetry of order $\\delta\\Delta \\sim \\hbar\\omega_{01}$ is needed to suppress cold QP-induced relaxation, while PAT-induced protection occurs only for a narrow monochromatic drive window near $2\\Delta$."}, {"id": "2607.25941", "t": "Sampling hard circuits with verifiably high fidelity", "a": "Simon Martiel, Jay-U Chung, Alireza Seif, Soumik Ghosh, Ian Hincks, Abhinav Deshpande, Hidetaka Manabe, Hanfeng Gu, Feng Pan, Bill Fefferman, Jay M. Gambetta, Ali Javadi-Abhari", "d": "2026-07-29", "s": 80.9, "x": "This work introduces doped Clifford circuits (DCS) that combine sampling-based quantum advantage with verifiable high fidelity by embedding structured circuits in spacetime codes for error detection. A 64-qubit, depth-73 circuit doped with 314 T gates achieves a fidelity lower bound of 0.349 with 95% confidence through syndrome measurements, while effective gate error suppression reaches 10× after post-selection."}, {"id": "2607.24947", "t": "Realizing Error Suppression in Partially Fault-Tolerant Quantum Simulations with IBM Quantum Computers", "a": "Henry Froland, Dorota M. Grabowska, Sebastian Grieninger, Jeremy Hartse, Anne L. Lashbrook, Zhiyao Li, Ziyuan Li, Sarah J. M. Powell, Martin J. Savage, Xiaojun Yao, Nikita A. Zemlevskiy", "d": "2026-07-29", "s": 75.1, "x": "This work demonstrates error suppression in quantum simulations on IBM's superconducting quantum processors by encoding logical qubits in the [[4,2,2]] Iceberg code and performing partially fault-tolerant syndrome extraction. Using 21 code blocks to simulate 42 logical qubits on ibm_boston, encoded simulations of the Ising model achieve 2–6% improvement in local observable accuracy over unencoded runs in 1D and over 200% improvement in 2D, with performance gains growing with circuit depth in higher dimensions."}, {"id": "2607.25176", "t": "Dissipation Enables Strongly Detuning-Dependent Interference in Pulsed Dynamical Decoupling", "a": "Kenneth DeRose, Jonah Glick, Kefeng Jiang, Hans Johnson, Tanay Roy, Sharika Saraf, Anya Abraham, Hardeep Singh, Tim Kovachy", "d": "2026-07-29", "s": 70.9, "x": "Dissipation from excited-state decay enables pulsed dynamical decoupling (DD) sequences to develop strong sensitivity to static detuning errors, contrary to the usual detuning insensitivity of DD. This dissipation-induced detuning dependence is observed in both a $^{88}$Sr atom interferometer ($T_1 \\approx 21.3$ µs) and a superconducting transmon qubit ($T_1 \\approx 21$ µs) implementing Carr-Purcell sequences, and is repurposed for spectroscopy."}, {"id": "2607.24907", "t": "Fault-tolerant distributed quantum computing with a single nucleus per node", "a": "Yotam Vaknin, Shoham Jacoby, Roi Nevo, Aleksander Kubica, Alex Retzker", "d": "2026-07-29", "s": 64.8, "x": "This work shows that distributed quantum computing with one high-coherence nuclear-spin data qubit per node can achieve fault-tolerant quantum error correction by exploiting biased noise on photon-generated Bell pairs. The key insight is that phase errors on Bell pairs can be engineered to appear solely as measurement errors suppressible by repetition, while bit-flip errors propagate to data qubits where they are corrected by the code itself, eliminating the need for distillation ancillas."}, {"id": "2607.23681", "t": "Mitigation of Measurement-Induced State Transitions via a Fast-Load and Fast-Clear Readout", "a": "Wei-En Lin, Li-Chieh Hsiao, Chen-Hsun Ma, Erh-Hsiang Yeh, Wei-Lun Peng, Hsi-Sheng Goan, Cen-Shawn Wu, Yueh-Nan Chen, Yung-Fu Chen, Chung-Ting Ke, Chii-Dong Chen", "d": "2026-07-28", "s": 89.3, "x": "This work systematically investigates measurement-induced state transitions (MIST) in transmon qubits as a function of offset charge $n_g$ and demonstrates that engineered fast-load and fast-clear pulse shaping suppresses MIST without complex waveforms or feedback. A three-step pulse scheme minimizes both readout and post-readout error probabilities across the full $n_g$ range by controlling diabaticity at avoided crossings via Landau-Zener dynamics."}, {"id": "2607.22852", "t": "Bias-preserving cat-cat CNOT gate via vacuum-conditional beam-splitter", "a": "Yufeng Ye, Connor T. Hann, Kyungjoo Noh, Harald Putterman, Ron Belyansky, Arne L. Grimsmo, Oskar Painter", "d": "2026-07-28", "s": 86.2, "x": "This work proposes a vacuum-conditional beam-splitter (VCB) CNOT gate between dissipative cat qubits that preserves exponential bit-flip suppression via coherent unitary dynamics, avoiding the non-adiabatic errors of Zeno-based schemes. With realistic parameters ($\\chi/2\\pi = 4$ MHz, $K/2\\pi = 4$ kHz, $T_1 = 1$ ms), the gate achieves logical error rates below $10^{-6}$ per cycle in a distance-7 repetition code with 13 cat qubits."}, {"id": "2607.23463", "t": "Purcell-Engineered Hybrid Coupler for Leakage-Suppressed Robust CZ Gates", "a": "Hui Wang, Feng Bao, Yan-Jun Zhao, Xun-Wei Xu", "d": "2026-07-28", "s": 84.6, "x": "This work proposes a Purcell-engineered hybrid coupler architecture for superconducting CZ gates that combines a nonlinear transmon coupler with a coupled Purcell-filter and notch-resonator subsystem to engineer both coherent interactions and leakage-selective dissipation. The optimized gate achieves $F_{\rm avg}=99.74\texttt{%}$, $F_{\rm min}=99.62\texttt{%}$, and maximum leakage of $1.6\times10^{-3}$, reducing leakage nearly twentyfold compared to an optimized single-transmon coupler."}, {"id": "2607.23959", "t": "Scalable Photon-Mediated Two-Qubit Gates with Spectrally Noisy Quantum Emitters", "a": "Shreekanth S. Yuvarajan, W. A. Coish, David Hucul, Herbert F. Fotso", "d": "2026-07-28", "s": 66.1, "x": "POCEG (protocol for optimal cavity-enabled gates) achieves high-fidelity two-qubit state transfer between spectrally mismatched quantum emitters by combining pulse sequences with cavity coupling modulation in the resonant regime or far-detuned pulse driving in the dispersive regime. The protocol demonstrates fidelity exceeding 99.9% for detunings up to $5g$ and spectral noise with correlation times spanning four orders of magnitude, overcoming a major scalability barrier for cavity-mediated gates in solid-state platforms."}, {"id": "2607.22294", "t": "Substrate-metal interface engineering enhances TaN/Ta thin film superconducting resonator performance", "a": "Moritz Singer, Harsh Gupta, Benedikt Schoof, Elena Willinger, Anton Orekhov, Alexandra Schewski, Samuil Kostadinov, Philip Constantin Schneider, Marc Tornow", "d": "2026-07-27", "s": 91.0, "x": "Superconducting resonators made from Ta/TaN bilayers on Si substrates achieve $Q_i = 5.9 \\times 10^5$ at 100 mK when a few-nanometer Ta buffer layer separates the TaN seed layer from the substrate, a 4× improvement over standalone TaN films. TEM imaging shows that the Ta buffer suppresses nitrogen accumulation and structural disorder at the TaN-Si interface, reducing interface-related two-level system losses."}, {"id": "2607.22265", "t": "Low loss superconducting resonators enabled by aluminum microstructural engineering and dielectric trimming", "a": "Mahmoud Almansouri, Umar T. F. Alhuwaymel, Ibraheem AlYousef, Albaraa Shafi, Abdullah Albogime, Igor Getmanov, Ahmed Hajr, Atif Shamim", "d": "2026-07-27", "s": 88.1, "x": "Aluminum grain-size engineering and silicon dielectric-edge trimming both suppress loss in superconducting coplanar waveguide resonators, improving quality factors from $6 \\times 10^4$ to $2.3 \\times 10^6$ on high-resistivity silicon. Substrate heating during $200$ nm aluminum deposition increases grain size to $1.2$ µm and reduces non-TLS loss, while a two-step \"Tropic\" etch (SF$_6$ followed by CHF$_3$) smooths silicon surfaces and suppresses TLS loss."}, {"id": "2607.22138", "t": "Mitigating Capacitive Loading Enables Fast Two-Qubit Gates in Highly Connected Fluxonium Quantum Processors", "a": "Quan Guan, Guo Xuan Chan, Xu Dou, Chunqing Deng, Lijing Jin", "d": "2026-07-27", "s": 85.4, "x": "This work establishes a quantitative theoretical framework for understanding capacitive loading in superconducting circuits, deriving analytical relations between finite qubit capacitance budgets and achievable qubit-coupler coupling strengths. The framework identifies pad-to-ground participation as geometrically optimizable and inter-pad participation as limited by Josephson-junction parasitic capacitance, enabling design principles that achieve two-qubit MAP gates as fast as 27 ns with leakage infidelity below $10^{-3}$ in highly connected 2D fluxonium architectures."}, {"id": "2607.24836", "t": "Can a quantum circuit detect the Unruh effect?", "a": "Pravin Kumar Dahal, Timothy C. Ralph, William J. Munro, Arkady Fedorov, James Q. Quach", "d": "2026-07-27", "s": 60.1, "x": "This paper proposes a superconducting fluxonium circuit modified with a flux-tunable split junction and engineered superinductor to operate as a tunable $\\Lambda$-system for detecting the timelike Unruh effect. Open-system simulations predict $\\sim 10\\%$ ground-state population shift over 530 ns ($\\sim 25$ quasicycles in conformal time), achieving three orders of magnitude sensitivity enhancement over two-level Unruh–DeWitt detectors by exploiting geometric-phase accumulation."}, {"id": "2607.21329", "t": "Quasiparticle-induced transitions in a fluxonium qubit", "a": "Maksim Litskevich, Kesavan Manivannan, Benjamin Byrd, Pavel D. Kurilovich, Vladislav D. Kurilovich, Gianluigi Catelani, Ivan V. Pechenezhskiy", "d": "2026-07-24", "s": 94.2, "x": "This work measures quasiparticle-induced transition rates in fluxonium qubits under controlled on-chip injection and demonstrates that superconducting gap asymmetry $\\delta\\Delta/h \\approx 1.72$ GHz across Josephson junction leads is essential for explaining the external flux dependence of these rates. The results show that accounting for $\\delta\\Delta$ resolves previously reported discrepancies between quasiparticle density bounds in the small junction versus the junction array, yielding consistent $x_{\\mathrm{qp}} \\approx 3 \\times 10^{-6}$ across both elements."}, {"id": "2607.20795", "t": "Component-Level Inverse Design of Transmon Qubits Using Neural Networks", "a": "Olivia Seidel, Firas Abouzahr, Abhishek Chakraborty, Sadman Ahmed Shanto, Saikat Das, Daniel Baxter, Jonathan Asaadi, Nicola Pancotti, Haoyu Yang, Brucek Khailany, Sara Sussman, Enectali Figueroa-Feliciano, Eli M Levenson-Falk, Taylor L. Patti", "d": "2026-07-24", "s": 88.9, "x": "This work demonstrates an inverse-design workflow for superconducting transmon qubits that maps target Hamiltonian parameters ($f_q$ and $\\alpha$) directly to component-level layout parameters via a neural network paired with a frozen forward surrogate. Validation against conventional EM simulation achieves mean percent errors of 0.73% for qubit frequency and 1.58% for anharmonicity on 97 geometrically usable designs, with speedups of $3.9 \\times 10^7$ on CPU and $4.6 \\times 10^7$ on GPU at batch size 2048 relative to single EM extractions."}, {"id": "2607.21360", "t": "Floquet Reservoir Engineering for Remote Logical Entanglement", "a": "Mingxing Yao, Aashish A. Clerk", "d": "2026-07-24", "s": 66.4, "x": "This work introduces dissipative Floquet protocols that stabilize remote entanglement between logical qubits by interleaving continuous engineered dissipation on communication qubits with periodic unitary gates. The protocol overcomes the time-entanglement tradeoff of standard dissipative approaches and achieves autonomous entanglement distillation, with a concrete implementation using cat qubits and transmons in superconducting circuits."}, {"id": "2607.21554", "t": "Strategic Plan for Neutral Atom Quantum Computation", "a": "Adrian J. Menssen, Tout Wang, Michael Gullans, Tom Manovitz, Jacob M. Taylor, Jason Cong, Josiah Sinclair, Ziv Aqua, Daniel J. Blumenthal, J. Pablo Bonilla Ataides, Johannes Borregaard, Antoine Browaeys, Paola Cappellaro, Soonwon Choi, Alexandre Cooper, Robin Côté, Jacob P. Covey, Alexandre Dauphin, Ivana Dimitrova, Matt Eichenfield, Dirk Englund, Jacob Freedman, Akihisa Goban, Brandon Grinkemeyer, Andi Gu, Ruonan Han, Dominik Hangleiter, Aram W. Harrow, Liang Jiang, Eun-ah Kim, Felix W. Knollmann, Aleksander Kubica, Thierry Lahaye, Lucas Lassabliere, Joonho Lee, Bingzhao Li, Mo Li, Wan-Hsuan Lin, Mikhail D. Lukin, Varun Menon, Thomas Propson, Akbar Safari, Mark Saffman, Pascal Scholl, Alexander Schuckert, Giulia Semeghini, Jonathan Simon, David Spierings, Daniel Bochen Tan, Shai Tsesses, Vladan Vuletic, Hanrui Wang, Hanyu Wang, Susanne Yelin, Johannes Zeiher, Hengyun Zhou", "d": "2026-07-24", "s": 51.0, "x": "This strategic plan outlines a comprehensive roadmap for scaling neutral atom quantum computers from current thousands of qubits toward 10,000–100,000 physical qubits required for practical quantum advantage, integrating advances in hardware, photonic control, error correction, and circuit compilation. The plan emphasizes that neutral atoms have demonstrated below-threshold error correction, two-qubit gate fidelities exceeding 99.5%, and dynamically reconfigurable connectivity, positioning the platform to achieve megaquop-scale computations within the next decade."}, {"id": "2607.19543", "t": "Simple, accurate lumped-element models of distributed resonators for superconducting quantum circuits", "a": "Elizabeth H. Kunz, Eli M. Levenson-Falk", "d": "2026-07-23", "s": 83.9, "x": "This work presents a method to replace distributed transmission line resonators in superconducting circuits with accurate single parallel $LC$ lumped elements by fitting scattering parameters in the presence of coupling capacitors. The technique outperforms traditional analytical lumped oscillator models and Foster synthesis approaches, particularly under heavy loading, and is implemented in the open-source package $\\texttt{simpleLOMs}$."}, {"id": "2607.20143", "t": "Biased-noise qubits: a guide to efficient fault-tolerance using the hierarchy of errors", "a": "Diego Ruiz, Jérémie Guillaud, Christophe Vuillot, Mazyar Mirrahimi", "d": "2026-07-23", "s": 82.7, "x": "This review analyzes fault-tolerant protocols for biased-noise qubits where phase-flip errors vastly exceed bit-flip errors, examining three architectures based on available bias-preserving operations. The key finding is that substantial overhead reduction requires either a bias-preserving CX gate or high-fidelity quantum non-demolition readout of multi-qubit Pauli Z operators; with only CZ gates, the noise bias provides negligible practical benefit."}, {"id": "2607.20292", "t": "Microwave-driven same-species sympathetic cooling for trapped ions", "a": "M. C. Smith, E. Vandrey, A. D. Leu, N. Drotleff, A. Agrawal, K. Miyanishi, D. M. Lucas, M. F. Gely", "d": "2026-07-23", "s": 52.1, "x": "This work demonstrates sympathetic cooling of trapped $^{43}$Ca$^+$ ions using same-species and same-isotope ions, with both data and coolant qubits encoded in the ground-state $4S_{1/2}$ manifold and addressed via microwave-driven pulsed sideband cooling. The scheme achieves ground-state cooling of a two-ion rocking mode to $\\bar{n} \\approx 0.16$ phonons with an induced error of $1.7(4) \\times 10^{-4}$ per cooling cycle on the data qubit."}, {"id": "2607.18513", "t": "Observation of a power transfer controlled by the phase of a quantum superposition", "a": "Nathanaël Cottet, Sébastien Jezouin, Bogdan Reznychenko, Alexia Auffèves, Benjamin Huard", "d": "2026-07-22", "s": 87.0, "x": "A superconducting transmon qubit coupled to two transmission lines with asymmetric couplings ($\\gamma_a = 100 \\gamma_b$, $\\gamma_a = 2\\pi \\times 72$ kHz) transfers power between them when driven by two spatially separated modes with canceling classical amplitudes, with the power flow direction controlled by the phase $\\phi$ of the qubit's coherent superposition rather than classical parameters. The stimulated emission power varies as $\\cos\\phi$, reversing direction between $\\phi=0$ and $\\phi=\\pi$, achieving a routing efficiency of 63% for an equal superposition ($|g\\rangle + e^{i\\phi}|e\\rangle$ with $\\theta=\\pi/2$), close to the theoretical bound of 69% set by measured coherence times ($T_1 = 2.22$ µs, $T_2 = 3.21$ µs)."}, {"id": "2607.18401", "t": "Monolithic printed-circuit board RF-trap for electrons", "a": "Zijue Luo, Jae Eu, Tianyi Wang, Boerge Hemmerling", "d": "2026-07-22", "s": 54.0, "x": "A linear Paul trap for electrons was fabricated from a single printed circuit board with two copper layers and an integrated RF resonator, eliminating assembly and reducing manufacturing tolerances compared to multi-component designs. The trap confined electrons with lifetimes of 2.13 ms and secular frequencies up to $90$ MHz radially and $55$ MHz axially."}, {"id": "2607.19187", "t": "Simultaneous calibration of rotation and phase errors in a single experiment", "a": "Tien D. Nguyen, Hung Q. Nguyen", "d": "2026-07-22", "s": 50.9, "x": "This work shows that rotation errors and phase errors in weakly anharmonic qubits follow from a single parametrization $\\mathcal{X}(\\pi/2) = Z(\\delta)X(\\pi/2+\\epsilon)Z(\\delta)$, enabling DRAPE, a single Ramsey-type protocol that simultaneously calibrates both errors by identifying a crossing point in phase-correction sweeps. DRAPE achieves Heisenberg scaling for phase estimation while saturating the standard quantum limit for rotation errors, demonstrated on an IBM transmon with $|1\\rangle\\leftrightarrow|2\\rangle$ encoding, reducing over-rotation from $0.997°$ to $-0.007°$ and phase error from $2.52°$ to $0.0052°$ per gate."}, {"id": "2607.17204", "t": "Heralded Leakage Detection with Preserved Computational-State Coherence in a Fixed-Frequency Transmon", "a": "Takeaki Miyamura, Zhiling Wang, Peter A. Spring, Hiroto Mukai, Kohei Matsuura, Jesper Ilves, Yoshiki Sunada, Yasunobu Nakamura", "d": "2026-07-21", "s": 95.7, "x": "A fixed-frequency transmon qubit demonstrates heralded leakage detection by applying a resonant Rabi drive during dispersive readout, which makes the computational states indistinguishable while preserving distinguishability of higher excited states. The protocol achieves 97.1(3)% leakage-detection fidelity with 2.3(3)% false-flag rate and 92.9(5)% average post-detection state fidelity for equal computational-leakage mixtures, requiring no additional hardware."}, {"id": "2607.17562", "t": "Temporal Diffraction Grating for Engineered Superconducting Qubit Dissipation", "a": "Pratik J. Barge, Kater W. Murch", "d": "2026-07-21", "s": 94.8, "x": "We demonstrate that pulsing a parametrically activated Purcell decay channel in a flux-tunable transmon qubit creates a temporal diffraction grating in the dissipation spectrum. Pulsed on/off modulation reorganizes the qubit's decay into interference fringes analogous to N-slit Fraunhofer diffraction, with each modulation window acting as a temporal aperture whose spacing, contrast, and envelope are controlled by the pulse duration and duty cycle."}, {"id": "2607.17791", "t": "Oval-shaped resonance distortion as a signature of quasiparticle heating effect in a niobium superconducting resonator", "a": "Zhenyuan Sun, Genting Dai, Xiao Geng, Liangliang Yang, Mingjun Cheng, Qing Yu, Jinlin Chang, Yi Yang, Linpan Jiang, Jianshe Liu, Wei Chen", "d": "2026-07-21", "s": 77.8, "x": "We develop a macroscopic quasiparticle heating (QPH) model based on modified Rothwarf–Taylor equations for a niobium CPW resonator, predicting that dissipative nonlinearity manifests as a distinctive oval-shaped distortion of the resonance circle in the complex plane. Experimental measurements on a Nb half-wavelength CPW resonator ($f_r = 4.537$ GHz, $L = 13$ mm) across bath temperatures 20 mK to 1.1 K and readout powers up to 0 dBm confirm this signature, with the model reproducing the observed $Q_r$ degradation and resonance distortion over the QPH-dominated regime."}, {"id": "2607.17992", "t": "A Voltage-Controlled Josephson Frequency Comb", "a": "Giorgio De Simoni, Francesco Giazotto", "d": "2026-07-21", "s": 77.8, "x": "This work proposes a voltage-controlled Josephson frequency-comb generator based on a gate-tunable superconductor–semiconductor–superconductor junction operated as a relaxation oscillator, where electrostatic control of carrier density in an InAs two-dimensional electron gas enables direct tuning of both critical current and Josephson inductance. Time-domain SPICE simulations demonstrate continuous 1–10 GHz frequency coverage with equidistant comb lines whose spacing, central frequencies, and modal power distribution can be dynamically adjusted via gate voltage, with extension to niobium showing $\\sim 100$ GHz bandwidth at temperatures around 3 K."}, {"id": "2607.17202", "t": "Multi-level Random-Telegraph Noise Mitigation using a Single Spectator Qubit", "a": "Yanan Liu, Hongting Song, Areeya Chantasri, Howard M. Wiseman", "d": "2026-07-21", "s": 67.3, "x": "This work extends spectator-qubit noise mitigation from two-level random-telegraph noise to general $L$-level fluctuator processes by developing a map-based formalism with $L \\times L$ matrices and deriving a heuristic adaptive protocol that dynamically selects measurement angle $\\theta_n$ and waiting time $\\tau_n$ based on current noise estimates. Numerical simulations for $L=3$ show decoherence rates of $\\sim 10^{-9}$ under the adaptive strategy, achieving comparable suppression to the two-level case despite noise complexity."}, {"id": "2607.17081", "t": "quchip: A Differentiable Toolkit for Modeling Quantum Devices", "a": "Ibraheem AlYousef", "d": "2026-07-21", "s": 50.6, "x": "quchip is an open-source Python toolkit that assembles device-independent simulations for superconducting quantum chips by explicitly representing device physics, control-line transformations, frames, approximations, dissipation, and observables. Using JAX-native dynamiqs, device and control parameters remain differentiable through time evolution, enabling forward prediction, correction via response-matrix inversion, and inverse parameter recovery from tomography."}, {"id": "2607.16151", "t": "Radiopurity material assays and radiation exposure projections for superconducting qubit measurements at SNOLAB", "a": "Y. Ahmed, B. Binoy, R. Bunker, D. Chauhan, P. Delsing, R. Germond, J. Hall, Z. Hong, A. Iqbal, V. Iyer, A. Klepikova, A. Kubik, S. P. Mantry, A. C. Masuskapoe, C. C. Monk, G. Peng, P. Qin, W. Rau, T. Reynolds, M. Stukel, C. M. Wilson, B. Zatschler, S. Zatschler, A. Zuniga", "d": "2026-07-20", "s": 81.0, "x": "This paper presents material assay results and radiation transport simulations for the QUTEbits collaboration's first deployment of superconducting qubits at SNOLAB, a deep underground facility providing $2$ km of rock shielding. Geant4 and G4CMP simulations predict a total background rate of $0.70$ mHz per Si chip in the shielded CUTE facility, dominated by bulk $^{238}$U and $^{232}$Th contamination, with calibration sources ($^{133}$Ba, $^{252}$Cf) allowing controlled radiation exposure studies."}, {"id": "2607.15757", "t": "Contactless terahertz mapping of wafer-scale superconducting NbTiN thin films", "a": "Yayi Lin, Marc Neis, Marcello Pio Guardascione, Janine Lorenz, Thomas J. Smart, F. Stefan Tautz, Felix Lüpke, Frederik Bolle, Martin Dressel, Rami Barends, Pavel A. Bushev, Marc Scheffler", "d": "2026-07-20", "s": 61.6, "x": "Terahertz spectroscopy is used to map wafer-scale homogeneity of NbTiN thin films on 4-inch and 6-inch Si wafers grown by plasma-enhanced magnetron sputtering, measuring sheet resistance $R_s$ at room temperature via THz-FDS and superconducting properties at cryogenic temperatures via THz-TDS. Room-temperature $R_s$ variations (1.77–7.78% standard deviation) correlate with film thickness and deposition device, while the zero-temperature sheet kinetic inductance $L_{k0}$ follows $R_s$ variations, but critical temperature $T_c$ (13.68–13.81 K) and energy gap $2\\Delta_0$ remain uniform across the wafer."}, {"id": "2607.15909", "t": "Reconstruction of the noise correlation spectral density from the cavity emission in a two-qubit system", "a": "Nadine Lenke, Guido Burkard", "d": "2026-07-20", "s": 60.3, "x": "This work characterizes noise correlations between two cavity-coupled qubits by measuring the cavity emission, developing a perturbative theory in the qubit-cavity coupling $g$ up to third order. The method is demonstrated for white noise (where correlation effects scale as $g^5$ and are negligible), quasi-static noise (linear scaling with correlation spectral density $S_{12}$), and Ornstein-Uhlenbeck noise (intermediate behavior), with a general extraction procedure via the convolution theorem."}, {"id": "2607.16166", "t": "Fast logical operations in quantum LDPC codes using simple resource states", "a": "Mark Webster, Nicolas Delfosse", "d": "2026-07-20", "s": 53.2, "x": "This work accelerates logical operations in quantum LDPC codes by combining cat-state-based measurements of multiple commuting Pauli operators using scheduler codes, achieving 3× speedup for joint logical measurements and up to 74× speedup for random Clifford circuits when integrated with a modified CliNR scheme. The approach is demonstrated numerically on the Q70 and Q102 codes from the walking cat architecture with measurement flip rate $p_F = 6.3 \\times 10^{-3}$ and target error rate $\\varepsilon = 10^{-10}$."}, {"id": "2607.14344", "t": "Collapse and Inversion of the Josephson Potential in a Strongly Driven Superconducting Circuit", "a": "Sercan Deve, Marius Villiers, Marijn A. Morssink, Robin C. Dekker, Gary A. Steele", "d": "2026-07-17", "s": 93.5, "x": "This work demonstrates dynamical collapse and inversion of the Josephson potential in a strongly driven transmon-resonator circuit free of multi-excitation resonances. Through spectroscopy and readout experiments, the authors observe the driven potential vanish at $\\theta_\\mathrm{ac} \\approx 2.405$ (where $J_0(\\theta_\\mathrm{ac}) = 0$) and subsequently invert, realizing autonomous stabilization of the transmon at the unstable equilibrium analogous to an inverted pendulum."}, {"id": "2607.15230", "t": "High-Q superconducting microwave resonators using MBE titanium nitride", "a": "Anand Ithepalli, Haoran Lu, Eegene Clara Chung, Xiangqin Wang, Amit Rohan Rajapurohita, Keun-Yeol Park, Celesta S. Chang, Peter McMahon, Huili Grace Xing, David Muller, Valla Fatemi, Debdeep Jena", "d": "2026-07-17", "s": 93.3, "x": "MBE-grown titanium nitride thin films on c-plane sapphire achieve record crystalline quality (18 arcsec X-ray rocking curve FWHM) and demonstrate superconducting quarter-wavelength coplanar waveguide resonators with internal quality factors $Q_i > 10^6$ at $\\langle n \\rangle \\sim 1$ and 10 mK. The work establishes TiN as a viable platform for high-coherence qubits and identifies a path toward all-epitaxial crystalline Josephson junctions using TiN/MgO/TiN stacks."}, {"id": "2607.15044", "t": "Towards logical entanglement creation in trivalent planar architectures", "a": "Lukas Bödeker, Luis Colmenarez, Sergey Blinov, Ants Remm, Simon Gustavsson, Markus Müller", "d": "2026-07-17", "s": 82.3, "x": "This work develops scalable lattice-surgery protocols for trivalent (degree-3) planar surface-code architectures and benchmarks them against conventional four-valent implementations. Trivalent lattice surgery eliminates the need for additional merging data qubits, reducing resource overhead by $\\mathcal{O}(d)$ qubits and $\\mathcal{O}(d)$ two-qubit gates while achieving up to ~25% logical-fidelity improvement at distance-3 in fluxonium-targeted simulations."}, {"id": "2607.14293", "t": "Real-Time Detection of Charge Jumps in Superconducting Qubits with a Convolutional Neural Network", "a": "Daniel Gaytan-Villarreal, Peter Meiring, Daniel Baxter, Daniel Bowring, Grace Bratrud, Matteo Cremonesi, Giuseppe Di Guglielmo, Grace Wagner, Bowen Xiao", "d": "2026-07-17", "s": 74.2, "x": "A dilated causal convolutional neural network (DCCNN) with 1,649 parameters enables real-time detection of charge jumps in superconducting qubits by identifying discontinuous shifts in qubit frequency during Ramsey tomography, achieving detection efficiency of $0.843 \times 0.022$ on charge jumps of magnitude $|\\_q| \times [0.1, 0.5] e$ at matched false-positive rate with the offline $\\\\\\_chi^2$ baseline. The model is quantized to $\\\\\\_mathrm{ap\\\\_fixed}\\\\\\_\\\\\\_16,6\\\\\\_\\\\\\_$ fixed-point arithmetic and deployed on the Zynq UltraScale+ RFSoC ZCU216 via hls4ml, achieving $6.19 \\_\\\\\\_mu\\\\\\_s$ inference latency while consuming $81.4\\\\\\_\\\\%$ of available block RAM, enabling in-the-loop adaptive control protocols at NEXUS (Fermilab underground)."}, {"id": "2607.14559", "t": "Dispersive Readout of a SiMOS Quantum Dot Using a Flip-Chip Integrated Microwave Resonator", "a": "Vo Kim Hieu Van, Santiago Serrano, Cédric Bohémier, Ajit Dash, Fay E. Hudson, Tuomo Tanttu, Chih Hwan Yang, MengKe Feng, Ensar Vahapoglu, Florian K. Unseld, Wee Han Lim, Andrea Morello, Andrew S. Dzurak, Kok Wai Chan", "d": "2026-07-17", "s": 70.8, "x": "Flip-chip bonding of a SiMOS double quantum dot chip to a superconducting aluminum resonator via indium bumps enables dispersive charge readout with SNR = 1 at 0.3 ms integration time. The integrated device maintains functionality over 60 mK to 760 mK and up to 10 mT in-plane magnetic field, with charge sensitivity limited by the resonator's superconducting properties."}, {"id": "2607.15252", "t": "Coulomb blockade in microscopic material defects as a source of decoherence and noise in solid-state quantum circuits", "a": "R. Banerjee, L. P. Lindoy, M. Hegedus, A. Hutcheson, T. Hawkins, E. Daghigh-Ahmadi, S. Samaddar, T. Barker, J. P. Goff, A. Ya. Tzalenchuk, I. Rungger, S. E. de Graaf", "d": "2026-07-17", "s": 69.2, "x": "Scanning gate microscopy on superconducting resonators reveals Coulomb blockade in microscopic metallic grains as a widespread and significant source of decoherence, competing with two-level-system defects but originating from fundamentally different physics. The mechanism—microwave-driven charge tunnelling producing Sisyphus dissipation—is power-independent, temperature-independent below 1 K, and can be eliminated through improved thin-film fabrication."}, {"id": "2607.14319", "t": "Towards a monolithic platform for coupling superconducting circuits to low-loss microwave phonons in AlScN on 4H-SiC", "a": "Yuanchen Deng, William W. Roberts, Sueli Skinner-Ramos, Dalton Anderson, Katherine Hewey, Xingyu Du, Michael Miller, Brandon Smith, Hwijong Lee, Pingping Chen, Charles Thomas Harris, Roy H. Olsson, Lisa Hackett, Rupert Lewis, Matt Eichenfield", "d": "2026-07-17", "s": 57.2, "x": "This work demonstrates a monolithic platform combining aluminum superconducting circuits on 4H-SiC with piezoelectric 42% Sc-content AlScN on the same substrate for integrated quantum acoustics, enabled by selective AlScN removal to expose low-loss SiC regions. Al-on-SiC resonators achieve $Q_i = 7.5 \times 10^4$ (single-photon, $T_1 = 2.9$ μs at 4.175 GHz) while retained AlScN regions support surface acoustic waves with propagation losses of $1.02 \times 10^{-3}$ dB/μm for Sezawa modes ($\tau_{\text{phonon}} = 7.6$ μs) and $3.16 \times 10^{-3}$ dB/μm for Rayleigh modes ($\tau_{\text{phonon}} = 3.4$ μs) at 7 mK."}, {"id": "2607.13834", "t": "Wireless millikelvin interconnects for superconducting quantum hardware", "a": "Kristopher Barr, Mingyan Zhong, Euan Parry, Manoj Stanley, Qusay Al-Taai, Paniz Foshat, Kaveh Delfanazari, Martin Weides, Nick M. Ridler, Chong Li, Alessandro Rossi", "d": "2026-07-16", "s": 87.9, "x": "This work demonstrates wireless excitation of a superconducting microwave resonator at 20 mK inside a dilution refrigerator, comparing performance against a wired reference at $f_r = 10.8$ GHz using a TX/RX pair with double split-ring resonator metalenses. Direct comparison reveals that wireless excitation preserves intrinsic resonator properties ($Q_i$, $f_r$, temperature-dependent frequency shift from quasiparticles) but exhibits an additional loss channel with $|\\Delta Q_L| \\approx 650$ arising from stray radiation coupling through unintended pathways within the reflective cryostat cavity."}, {"id": "2607.13870", "t": "Phonon down-conversion by normal metals for superconducting devices", "a": "Guglielmo La Magna, Gianluigi Catelani", "d": "2026-07-16", "s": 81.9, "x": "This paper develops a kinetic equation model for phonon down-conversion by normal-metal films, in which high-energy pair-breaking phonons scatter off electrons and lose energy below the qubit gap threshold. The authors solve the coupled equations for electron and phonon distributions in steady state, define a down-conversion efficiency $R_{\rm qp}$ comparing quasiparticle generation rates with and without the metal, and find that efficiency remains near-optimal ($>90\\%$) over a finite metal thickness range with minimum thickness around $0.4\\text{–}1\\,\\mu\\mathrm{m}$ for typical parameters."}, {"id": "2607.14175", "t": "Transducer leakage error suppression using invariant-based shortcut", "a": "Shi-Qiang Qiao, Zheng Shan, Xue-Ke Song, Shi-Lei Su, Liu Ye, Dong Wang", "d": "2026-07-16", "s": 56.5, "x": "This work presents an invariant-based shortcut (Lewis-Riesenfeld) control scheme to suppress transducer leakage errors in hybrid spin-superconducting quantum systems where a resonator mediates interactions between a GaAs RX spin qubit and a transmon. The optimized pulse protocol achieves iSWAP gate and Bell state preparation with >99% fidelity, reducing leakage probability to 0.01 and demonstrating robustness against decoherence and control errors."}, {"id": "2607.13301", "t": "Precision quantum simulation of magnon spectra and interactions", "a": "Trond I. Andersen, Nikita Astrakhantsev, Jeronimo Martinez, Will Morong, Johannes Motruk, Dario Rossi, Brayden Ware, Bryce Kobrin, Weijie Wu, Elizabeth Bennewitz, Manuel Rudolph, Tom Westerhout, Amira Abbas, Rajeev Acharya, Laleh Aghababaie Beni, Ross Alcaraz, Sayra Alcaraz, Markus Ansmann, Frank Arute, Kunal Arya, Walt Askew, Juan Atalaya, Christopher Ayala, Ryan Babbush, Brian Ballard, Joseph Bardin, Hector Bates, Andreas Bengtsson, Majid Bigdeli Karimi, Alexander Bilmes, Simon Bilodeau, Felix Borjans, Alexandre Bourassa, Jenna Bovaird, Dylan Bowers, Leon Brill, Peter Brooks, Michael Broughton, David Browne, Brett Buchea, Bob Buckley, Tim Burger, Brian Burkett, Jamal Busnaina, Nicholas Bushnell, Jonas Bylander, Anthony Cabrera, Juan Campero, Hung-Shen Chang, Silas Chen, Zijun Chen, Ben Chiaro, Liang-Ying Chih, Agnetta Cleland, Bryan Cochrane, Matt Cockrell, Josh Cogan, Paul Conner, Tom Connolly, Harold Cook, Rodrigo Cortinas, William Courtney, Alexander Crook, Benjamin Curtin, Adam Dally, Sayan Das, Martin Damyanov, Dripto Debroy, Himadri Dey, Stijn de Graaf, Laura De Lorenzo, Sean Demura, Lucia De Rose, Agustin Di Paolo, Leon Ding, Howard Dobbs, Paul Donohoe, Ebru Dogan, Ilya Drozdov, Andrew Dunsworth, Rasmus Edholm, Valerie Ehimhen, Alec Eickbusch, Aviv Elbag, Lior Ella, Mahmoud Elzouka, David Enriquez, Catherine Erickson, Lara Faoro, Vinicius Ferreira, Marcos Flores, Leslie Flores Burgos, Sam Fontes, Ebrahim Forati, Jeremiah Ford, Brooks Foxen, Masaya Fukami, Alan Fung, Lenny Fuste, Suhas Ganjam, Gonzalo Garcia, Christopher Garrick, Robert Gasca, Helge Gehring, Robert Geiger, Élie Genois, William Giang, Dar Gilboa, James Goeders, Edward Gonzales, Raja Gosula, Alejandro Grajales Dau, Dietrich Graumann, Joel Grebel, Alex Greene, Jonathan Gross, Jose Guerrero, Tan Ha., Steve Habegger, Tanner Hadick, Ali Hadjikhani, Michael Hamilton, Monica Hansen, Matthew Harrigan, Sean Harrington, Jeanne Hartshorn, Stephen Heslin, Paula Heu, Oscar Higgott, Reno Hiltermann, Jeremy Hilton, Hsin-Yuan Huang, Michael Hucka, Christopher Hudspeth, Ashley Huff, William Huggins, Aditya Jayaraman, Evan Jeffrey, Shaun Jevons, Zhang Jiang, Xiaoxuan Jin, Cody Jones, Chaitali Joshi, Kelsey Josund, Pavol Juhas, Andreas Kabel, Bharath Kannan, Hui Kang, Kiseo Kang, Amir Karamlou, Ryan Kaufman, Tanuj Khattar, Mostafa Khezri, Seon Kim, Paul Klimov, Can Knaut, Alexander Korotkov, Fedor Kostritsa, John Mark Kreikebaum, Ryuho Kudo, Arun Kumar, Ben Kueffler, Vladislav Kurilovich, Vitali Kutsko, Nathan Lacroix, Tiano Lange-Dei, Brandon Langley, Pavel Laptev, Kim-Ming Lau, Emma Leavell, Loïck Le Guevel, Justin Ledford, Joy Lee, Kenny Lee, Brian Lester, Wendy Leung, Matthew Lloyd, Lily Li, Wing Li, Ming Li, Alexander Lill, Mike Lindmark, William Livingston, Aditya Locharla, Erik Lucero, Daniel Lundahl, Aaron Lunt, Sid Madhuk, Donald Macaskill, Aniket Maiti, Ashley Maloney, Salvatore Mandra, Leigh Martin, Orion Martin, Eric Mascot, Paul Masih Das, Anselme Massimino, Melvin Mathews, Cameron Maxfield, Jarrod McClean, Matthew McEwen, Seneca Meeks, Anthony Megrant, Tim Menke, Kevin Miao, Zlatko Minev, Reza Molavi, Sebastian Molina, Shirin Montazeri, Akira Nakamura, Charles Neill, Konstantin Nesterov, Michael Newman, Roselle Ngaloy, Anthony Nguyen, Murray Nguyen, Chia-Hung Ni, Murphy Niu, Nicholas Noll, Sergey Novikov, Logan Oas, Ricky Oliver, Will Oliver, Raymond Orosco, Kristoffer Ottosson, Alice Pagano, Manan Patel, Sherman Peek, David Peterson, Alex Pizzuto, Thomas Plumb-Reyes, Elias Portoles, Rebecca Potter, Orion Pritchard, Sam Probst, Michael Qian, Chris Quintana, Matthew Rakher, Arpit Ranadive, Ganesh Ramachandran, Armin Razavi, Matthew Reagor, Rachel Resnick, David Rhodes, Daniel Riley, Gabrielle Roberts, Roberto Rodriguez, Emma Ropes, Eliott Rosenberg, Emma Rosenfeld, Dario Rosenstock, Elizabeth Rossi, Pedram Roushan, David Rower, Robert Salazar, Kannan Sankaragomathi, Murat Sarihan, Kevin Satzinger, Max Schaefer, Sebastian Schroeder, Henry Schurkus, Aria Shahingohar, Michael Shearn, Aaron Shorter, Shvarts Vladimir, Vlad Sivak, Spencer Small, W. Clarke Smith, David Sobel, Barrett Spells, Sofia Springer, George Sterling, Scott Stonemeyer, John Su, Jordan Suchard, Youngkyu Sung, Aaron Szasz, Alex Sztein, Tomoyuki Tanaka, Madeline Taylor, Jothi Thiruraman, Douglas Thor, Brandur Thorgrimsson, Dogan Timucin, Eifu Tomita, Alfredo Torres, M. Mert Torunbalci, Hao Tran, Abeer Vaishnav, Justin Vargas, Gopinath Vasalamarri, Sergey Vdovichev, Guifre Vidal, Benjamin Villalonga, Meghan Voorhees, Steven Waltman, Jonathan Waltz, Shannon Wang, Danni Wang, James Watson, Yonghua Wei, Travis Weidel, Theodore White, Kristi Wong, Bryan Woo, Christopher Wood, Maddy Woodson, Cheng Xing, Z. Jamie Yao, Ping Yeh, Bicheng Ying, Juhwan Yoo, Noureldin Yosri, Elliot Young, Grayson Young, Adam Zalcman, Ran Zhang, Yaxing Zhang, Yiqing Zhou, Ningfeng Zhu, Nicholas Zobrist, Zhenjie Zou, Sergio Boixo, Yu Chen, Julian Kelly, Hartmut Neven, Vadim Smelyanskiy, Dvir Kafri, L. B. Ioffe, Kostyantyn Kechedzhi, Xiao Mi, Dmitry Abanin", "d": "2026-07-16", "s": 55.8, "x": "This work demonstrates high-precision quantum simulation of magnon spectra and interactions in a 2D XY spin-1/2 magnet using a 97-qubit hybrid analog-digital superconducting processor, achieving $g/(2\\pi) \\approx 9.7$ MHz coupling strength and characterizing both linear and nonlinear magnon response functions with median relative precision of $7 \\times 10^{-3}$ in frequency and $7.8 \\times 10^{-2}$ in decay rate. The technique combines Hamiltonian learning achieving $4.7 \\times 10^{-4}$ per-qubit-per-cycle XEB errors with interleaved digital Z-gate excitation to isolate individual magnon modes, revealing mode-dependent decay rates enhanced near van Hove singularities and suppressed for edge-localized corner modes."}, {"id": "2607.13448", "t": "Deterministic single-electron trapping on solid neon using engineered dielectric surface geometry", "a": "Kundan Surse, Eric Helgemo, Andrew Palmer, Md Serajum Monir, Lukas Delventhal, Thanh Nguyen, Maja Cassidy, Rajib Rahman", "d": "2026-07-16", "s": 53.3, "x": "This work develops a three-dimensional Schrödinger–Poisson framework to model electron trapping on solid neon and proposes engineering the dielectric substrate surface to enable deterministic single-electron confinement. The simulations demonstrate that nanoscale surface roughness (bumps and valleys with $\\sigma_{\\mathrm{rms}} = 3$ nm) substantially perturbs the trapping landscape, but a combination of a planarizing dielectric spacer and selective etching creates controlled potential minima while suppressing parasitic bound states."}, {"id": "2607.12118", "t": "Error correction on an array of superconducting qubits with defective components", "a": "Julien M. Drouet, Xanda C. Kolesnikow, Campbell K. McLauchlan, Georgia M. Nixon, Seok-Hyung Lee, Dominic J. Williamson, Stephen D. Bartlett, Benjamin J. Brown, Robin Harper", "d": "2026-07-15", "s": 90.7, "x": "This work demonstrates distance-5 surface codes on the 120-qubit IBM Nighthawk processor with active defect exclusion strategies that quarantine underperforming qubits and couplers. Combining defect exclusion with noise-informed decoding and leakage post-selection yields a distance-5 code outperforming the best distance-3 instance in one basis."}, {"id": "2607.12394", "t": "Systematic modulation of superconducting gap dynamics in YBCO|BNT|YBCO Josephson Junctions through THz field interaction and BNT ferroelectric barrier", "a": "Sukhanidhan Singh, Muthukkumaran Karthikeyan, Geoffrey Chanda, Thanayut Kaewmaraya, Pairot Moontragoon, Guoxing Sun, Zongjin Li, Anucha Watcharapasorn", "d": "2026-07-15", "s": 59.4, "x": "YBCO/BNT/YBCO Josephson junctions with a 40 nm ferroelectric BNT barrier show robust superconducting coupling and tunable transport under THz excitation at 0.5–2.5 THz. At 1.5 THz near the plasma resonance, the junctions exhibit a critical current of 468.2 µA with an enhanced superconducting gap ($\\Delta = 1.3$ meV) and stable $I_c(T)$ up to 60 K, with BNT polarization increasing from 33.4 to 46.4 µC/cm$^2$ at 30 K."}, {"id": "2607.12988", "t": "A cryogenic neutral-atom platform with full optical access and 2-hour trap lifetime", "a": "Akhil Kumar, Lorenzo Festa, Avishay Grinberg, Eran Reches, Dimitrios Tsevas, Kevin P. Mours, Zhao Zhang, Robin Eberhard, Sebastian Blatt, Andrea Alberti, Johannes Zeiher, Immanuel Bloch, Max Melchner", "d": "2026-07-15", "s": 58.7, "x": "This work demonstrates vacuum-limited trapping lifetimes exceeding 7000 s (∼2 hours) for single $^{88}$Sr atoms in optical tweezers using a simple cryogenic design with a 4 K cold tip, while maintaining full optical access without complex in-vacuum windows. The apparatus achieves high vacuum pressure ($\\sim 2.5 \\times 10^{-12}$ mbar) through material selection (grade 2 titanium), bakeout procedures, and hydrogen cryopumping, without the thermal load constraints that limit scaling in conventional 4 K platforms."}, {"id": "2607.12751", "t": "Traceable In Situ Microwave Power Measurement at the Cryogenic Device Plane in a Dilution Refrigerator", "a": "Paolo Panetta, Andrea Celotto, Alessandro Alocco, Bernardo Galvano, Luca Fasolo, Emanuele Palumbo, Luca Callegaro, Luca Oberto, Patrizia Livreri, Emanuele Enrico", "d": "2026-07-15", "s": 50.3, "x": "This work presents a traceable in situ microwave power measurement method for superconducting quantum circuits in dilution refrigerators using AC/DC thermal substitution with a custom variable temperature stage (VTS). The method combines cryogenic calorimetry with SOLR scattering-parameter calibration to measure incident RF power at the device reference plane, demonstrating measurements from $-43$ to $-58$ dBm with relative uncertainties ranging from 2% to 40%."}, {"id": "2607.10743", "t": "Connectivity-induced surface-loss penalty in superconducting qubit-coupler lattices", "a": "Xu-Yang Gu, Gui-Han Liang, Ming-Chuan Wang, Yongxi Xiao, Cheng-Lin Deng, Zheng-He Liu, Tian-Ming Li, Kai Xu, Zhongcheng Xiang, Heng Fan", "d": "2026-07-14", "s": 83.0, "x": "Finite-element simulations show that embedding superconducting transmon qubits in flip-chip qubit-coupler lattices increases surface dielectric loss: connecting a qubit to four couplers raises the surface-loss rate by a factor of 1.8 and reduces estimated $T_{1}^{\\mathrm{surf}}$ from 133 to 74 µs. Counterintuitively, geometric optimizations that improve isolated-qubit lifetimes (larger qubit-ground gap, opposite-chip holes) can increase the connectivity-induced loss penalty, motivating design rules for low-loss multiqubit processors."}, {"id": "2607.11514", "t": "States dressing analysis in a transmon-transmon-bus system", "a": "P. A. Gladilovich, R. A. Migdisov, A. V. Sabluk, P. S. Burtsev, N. N. Abramov, N. Y. Rudenko, V. I. Chichkov, N. A. Maleeva", "d": "2026-07-14", "s": 78.2, "x": "This work experimentally and theoretically investigates state dressing in a transmon-transmon-bus coupler architecture, measuring how noncomputational states admix into computational states across a tunable parameter range. Three estimation methods—full system, effective mode, and unperturbed mode—are compared, revealing that dressing varies from ~1% to 50% and critically coincides with spectral inversion and effective coupling equalization at $f_U^c \\approx 4.252$ GHz."}, {"id": "2607.11668", "t": "Multi-Stage Mamba-Based Architecture for Fast and Scalable Superconducting Qubit Readout", "a": "Luca Otting, Xiaorang Guo, Emmanouil Giortamis, Benjamin Lienhard, Pramod Bhatotia, Martin Schulz", "d": "2026-07-14", "s": 77.0, "x": "This work presents a multi-stage Mamba-based qubit state discriminator for superconducting quantum processors that achieves 0.906–0.911 geometric-mean readout fidelity while reducing model parameters by 49.6–99.4% compared to prior state-of-the-art approaches. The architecture integrates sequence modeling via a structured state machine for initial state discrimination with a neural error detector for post-correcting relaxation-induced errors, maintaining 0.893 fidelity at 500 ns readout durations and enabling 26% reduction in surface-code logical error rate relative to existing methods."}, {"id": "2607.10249", "t": "Branch-resolved Pauli-block spectroscopy of residual conditional phase in two-qubit gates", "a": "Xudan Chai, Yanwu Gu, Huiqi Xue, Kerui Li, Dong E. Liu", "d": "2026-07-14", "s": 57.7, "x": "Branch-resolved Pauli-block spectroscopy estimates the signed per-cycle residual $ZZ$-rotation angle $\\vartheta_c$ in two-qubit gates by measuring the closed four-moment block $\\{IX, IY, ZX, ZY\\}$ and forming differential branch coherences $C_\\pm$ conditioned on the control qubit. On a QuantumCTek cloud processor (66 transmons with tunable couplers), the echoed protocol achieves near-unit-slope injection response and one-step point-estimate feedback suppression ($|\\vartheta_c|_{R0}/|\\vartheta_c|_{R1} \\approx 16$) while preserving branch contrast $\\min|C| \\gtrsim 0.83$."}, {"id": "2607.11846", "t": "Optimal operating temperature for industry-compatible silicon spin quantum computing: colder is not necessarily better", "a": "Paul Steinacker, Amanda E. Seedhouse, Nard Dumoulin Stuyck, Tuomo Tanttu, MengKe Feng, Santiago Serrano, Ensar Vahapoglu, Samuel K. Bartee, Philip Y. Mai, Alexis Shaw, Andreas Nickl, Sebastian Pauka, Brendan Harlech-Jones, Juan P. Dehollain, Fay E. Hudson, Kok Wai Chan, Thomas A. Ohki, David Reilly, Christopher C. Escott, Chih Hwan Yang, Wee Han Lim, Arne Laucht, Andre Saraiva, Andrew S. Dzurak, Jared H. Cole", "d": "2026-07-14", "s": 54.8, "x": "Silicon spin qubits fabricated in industrial and academic facilities exhibit remarkably consistent power-law degradation of gate fidelity with temperature, with a characteristic crossover near 1 K above which performance degrades rapidly. A system-level power model combining cryogenic cooling requirements with quantum error correction overhead predicts a finite optimal operating temperature of 0.5–1.5 K that balances refrigeration cost against the physical-qubit overhead needed to maintain logical performance."}, {"id": "2607.11647", "t": "Anomalous Dissipation in Current Biased Josephson Systems", "a": "Johannes Hauff, Niklas Gaiser, Joachim Ankerhold, Dominik Maile", "d": "2026-07-14", "s": 54.4, "x": "This paper presents a theoretical analysis of a current-biased Josephson junction with an anomalous dissipative environment created by adding a resistor $R_g$ in series with a capacitor $C$ in parallel to the junction. The work reveals a new phase diffusive regime at low temperatures where quantum tunneling is substantially enhanced, followed by voltage pulses and re-trapping in the next potential minimum, with applications to microwave photon detection and dissipative quantum annealing."}, {"id": "2607.11721", "t": "High-field Josephson effect enabled by a moiré Hofstadter spectrum", "a": "A. Díez-Carlón, M. Cárdenes Wuttig, N. Wei, D. Ivanov, P. Altpeter, P. Hakonen, K. Watanabe, T. Taniguchi, L. I. Glazman, D. K. Efetov", "d": "2026-07-14", "s": 52.6, "x": "Moiré-engineered graphene/hBN Josephson junctions achieve phase-coherent Andreev transport up to 6 T by exploiting Hofstadter minibands, where the moiré potential converts zero-group-velocity Landau levels into dispersive magnetic Bloch bands. This enables high-field superconducting interferometry in the quantum Hall regime via extended electron-hole Andreev trajectories that would be forbidden in conventional ballistic junctions."}, {"id": "2607.09508", "t": "Superconducting singlet-triplet qubits", "a": "Anatoliy Lotkov, Maria Spethmann, Daniel Loss", "d": "2026-07-13", "s": 80.2, "x": "This work proposes superconducting singlet-triplet (SST) qubits—hybrid devices based on parallel-aligned double quantum dots in Josephson junctions—that combine spin-based quantum computing with circuit QED while avoiding the need for spin-orbit interaction. The SST qubits achieve all-to-all connectivity using only $N$ flux lines for $N$ qubits and exhibit linear protection against charge and flux noise."}, {"id": "2607.07798", "t": "Observation of coherent flux-charge interaction in a gate-tunable fluxonium", "a": "Brian D. Isakov, Shikhar Singh, Adrian Parra-Rodriguez, David Feldstein-Bofill, Zhenhai Sun, Anders Kringhøj, Svend Krøjer, Alexandre Blais, Morten Kjaergaard, András Gyenis", "d": "2026-07-10", "s": 87.2, "x": "This work demonstrates coherent flux-charge coupling in a gate-tunable fluxonium by parametrically modulating the critical current of a voltage-tunable InAs/Al Josephson junction, enabling direct interaction between a classical charge variable and a quantum flux operator. The coupling is isolated from parasitic capacitive effects using parity selection rules at half-flux frustration, enabling charge-insensitive yet strongly coupled control via a ChIVE point where $\\partial f_{02}/\\partial E_J = 0$."}, {"id": "2607.07999", "t": "Optimizing LZSM protocol for high-fidelity gates in open-system fluxonium", "a": "Santiago Ferreyra, Valentın Reparaz, Maria Jose Sanchez, Leandro Tosi, Daniel Dominguez", "d": "2026-07-10", "s": 65.3, "x": "This work develops a theoretical framework for optimizing Landau-Zener-Stückelberg-Majorana (LZSM) single-qubit gates in fluxonium circuits, incorporating multilevel dynamics, leakage mitigation, and open-system dissipation. Fast, high-fidelity Y(π/2) rotations are demonstrated with gate errors approaching $10^{-5}$ at 2 ns and $10^{-5}$ at 1.3 ns in optimal architectures accounting for environmental decoherence."}, {"id": "2607.08363", "t": "Stroboscopic Stabilization of Cat Qubits", "a": "Timo Hillmann, Franco Nori, Fernando Quijandría", "d": "2026-07-10", "s": 61.4, "x": "This work proposes stroboscopic stabilization of cat qubits via repeated interactions with an auxiliary two-level system mediated by quadratic Hamiltonians, eliminating the need for engineered two-photon dissipation. The protocol preserves the noise bias, extends to squeezed cat qubits with partial single-photon-loss correction, and is compatible with trapped-ion and circuit-QED platforms."}, {"id": "2607.08078", "t": "Experimental demonstration of entanglement sudden death induced by natural dissipation", "a": "Yan Wang, Hao-Long Zhang, Jia-Hao Lü, Ken Chen, Wen Ning, Li-Hua Lin, Zhen-Biao Yang, Shi-Biao Zheng", "d": "2026-07-10", "s": 52.2, "x": "This work presents the first experimental demonstration of entanglement sudden death (ESD) induced by natural dissipation, where two photonic qubits stored in leaky superconducting circuit QED resonators lose entanglement in finite time despite asymptotic individual decay. Two ancilla qubits prepare and measure the photonic qubit state while monitoring disentanglement dynamics under Markovian spontaneous emission with decay rates $\\kappa_1 \\approx 1/240$ ns$^{-1}$ and $\\kappa_2 \\approx 1/226$ ns$^{-1}$."}, {"id": "2607.06718", "t": "Quantum error correction of a grid-state qubit with state preparation and measurement errors below $10^{-3}$", "a": "Sara Turcotte, Lucas St-Jean, Amélie L. Pessonneaux, Ross Shillito, Bohdan Kulchytskyy, Eliott Ouellet, Jean Olivier Simoneau, Florian Hopfmueller, Matthew Hamer, Pascal Lemieux, Dany Lachance-Quirion, Baptiste Royer, Nicholas E. Frattini", "d": "2026-07-09", "s": 91.9, "x": "This work demonstrates state preparation and measurement (SPAM) errors below $10^{-3}$ for single-mode grid-state qubits in a superconducting cavity coupled to a transmon auxiliary qubit, achieving two orders-of-magnitude improvement over prior art. The improvement combines postselected stabilization-based state preparation with repeated finite-energy measurements, both fully compatible with autonomous quantum error correction."}, {"id": "2607.07614", "t": "Multi-stage Quantum Amplifier Readout Chain", "a": "Logan Howe, Andrea Giachero, Michael Vissers, Corwin Shiu, Shannon Duff, Jason Austermann, Johannes Hubmayr, Joel Ullom", "d": "2026-07-09", "s": 76.3, "x": "A quantum-amplifier-based readout chain (QARC) using two-stage kinetic inductance traveling-wave parametric amplifiers (KTWPAs) achieves nearly quantum-limited noise of ~3 quanta over 2 GHz bandwidth while dissipating three orders of magnitude less power than conventional readout chains that use cryogenic semiconductor amplifiers. The QARC demonstrates an input compression point of -93 dBm and maintains system performance suitable for scaled superconducting detector arrays and space-based observatories."}, {"id": "2607.06670", "t": "Localized Thermometry via Dayem Bridges Integrated on Superconducting Qubit Chips", "a": "Ella O. Lachman, Dave P. Pappas, Jayss Marshall, Josh Y. Mutus", "d": "2026-07-09", "s": 72.7, "x": "This work demonstrates superconducting Dayem bridges integrated on the same chips as transmon qubits as on-chip thermometers, extracting local cryogenic temperature from critical current measurements via the Bardeen relation without requiring microwave control or qubit-specific protocols. The Pd/Ti bilayer bridges (with $T_c = 166$ mK) show excellent stability and agreement with qubit-based thermometry above 50 mK, with measured $T_2^{\\mathrm{Ramsey}}$ correlating inversely with independently measured chip temperature over the 15–150 mK range."}, {"id": "2607.05779", "t": "Separate Control of Transient Leakage Exposure and Endpoint Leakage in Fast Transmon Gates", "a": "Haoran Yang, Fudong Liu, Weilong Wang, Yangyang Fei, Zheng Shan", "d": "2026-07-08", "s": 70.5, "x": "This paper introduces path–endpoint separation pulses (PESP), which decouple control of transient leakage exposure (time-integrated population in noncomputational states) from residual endpoint leakage in fast transmon gates. Using a spectral argument, the authors show that endpoint leakage depends on drive spectral weight at the anharmonicity $\\eta$, while transient exposure depends on spectral weight over a frequency band of width $\\sim 1/T$, making them independently controllable."}, {"id": "2607.05072", "t": "Transmon Phase Gates Controlled by Superconducting Soliton DAC", "a": "Derek Reitz, Tony X. Zhou, Aditya Sharma, Ryan Bilotta, John McFarland, Aref Fouladi, Jacob Glasby, Aruna Ramanayaka, Zachary Stegen, Aaron Pesetski, Mark Covington, Gregory Boyd, Jeremy Clark", "d": "2026-07-07", "s": 91.1, "x": "This paper demonstrates a superconducting soliton digital-to-analog converter (DAC) that converts digital CMOS inputs into smooth flux pulses for controlling transmon qubits, achieving 5.6 ns phase gates with 0.05% excitation probability per gate. The soliton DAC provides passive noise filtering (-80 dB attenuation at transmon frequencies), native multiplexing, and CMOS compatibility, but reveals significant non-local electromagnetic crosstalk (1.6% phase error per gate) from 30 simultaneously triggered DACs on the control chip."}, {"id": "2607.04097", "t": "Full Gate-Voltage Control of a Parity-Protected Superconducting Qubit with an Altermagnetic Josephson Junction", "a": "Guo-Liang Guo", "d": "2026-07-07", "s": 80.4, "x": "This work proposes a parity-protected superconducting qubit based on a gate-tunable superconductor-altermagnet-superconductor Josephson junction, where the altermagnet's momentum-dependent spin splitting generates two Josephson channels with opposite phase shifts that can be tuned to a 0-$\\pi$ transition via electrical gate control. Realistic parameter estimates yield coherence times reaching tens of milliseconds while maintaining fully electrical qubit operations without magnetic-flux biasing."}, {"id": "2607.04082", "t": "A Cross-Platform Analysis of High-Performance Quantum Error Correction Codes", "a": "Bryan Pan, Yufeng Xin", "d": "2026-07-07", "s": 58.6, "x": "This paper presents a lightweight analytical framework for estimating logical error rates of quantum error correction codes across multiple hardware platforms and distributed quantum systems, capturing the dominant contributions from code structure and two-qubit gate overhead. The framework reproduces qualitative trends from full-stack simulations and identifies sweet spots for distributed QEC architectures, revealing that inter-QPU operation overhead critically constrains scalability."}, {"id": "2607.04393", "t": "Atomic oven with rapid thermal response for atom experiments", "a": "Weilong Huang, Congjun Zou, Feiyu Dong, Huirong Xiao, Zejian Ren, Shanchao Zhang", "d": "2026-07-07", "s": 51.5, "x": "An inductively heated atomic oven achieves a 7.65× improvement in heating rate compared to resistive heating, reaching the 773 K target temperature in 4.33 minutes versus 33.13 minutes, and demonstrates stable operation to 1273 K with temperature fluctuations below ±2 K. A collimated ytterbium beam with flux exceeding $10^{14}$ atoms/s at 823 K is generated using a hexagonally packed capillary nozzle array, with the enhanced thermal response enabling faster experimental cycles for quantum gas and precision metrology work."}, {"id": "2607.03193", "t": "Self-Specializing Vision-Language Transmon Chip Calibration in a Physics-Grounded Environment", "a": "Animesh Tripathy, Aswanth Krishnan", "d": "2026-07-06", "s": 74.0, "x": "A vision-language agent calibrates superconducting transmon chips end-to-end by reading measurement plots and maintaining a structured notebook, specializing itself to one persistent drifting device via gradient-free online adaptation of an interpretable device note without weight updates. On hard-tier chips under budget pressure, six iterations raised worst-case CZ fidelity from 0.678 to 0.787; a single accepted note raised it to 0.913 on its paired snapshot, and planted-fault studies confirm the note diagnoses hardware defects truth-free while raising the failure floor."}, {"id": "2607.02804", "t": "Fault-tolerant quantum computation with static atomic buses", "a": "Matteo Bergonzoni, Laura Pecorari, Sam Norrell, Cody Poole, Guido Pupillo, Mark Saffman", "d": "2026-07-06", "s": 61.1, "x": "This work introduces a static neutral-atom architecture using auxiliary mediator atoms to enable long-range entangling gates via Rydberg interactions, eliminating transport-induced heating and latency that scales with code distance. Through co-designed optimal-control pulses achieving $F \\approx 0.999$ fidelity over hundreds of nanoseconds and large-scale error-correction simulations, the architecture demonstrates more than order-of-magnitude improvements in logical error rates compared to atom-shuttling approaches for surface codes ($d \\lesssim 12$) and high-rate LDPC codes."}, {"id": "2607.01473", "t": "Surface code logical operations on a superconducting quantum processor", "a": "Weiping Lin, Shaojun Guo, Yuwei Ma, Zhengzhong Yi, Kai Zhang, Jiahao Bei, Jianbin Cai, Sirui Cao, Danning Chen, Guoben Chen, Jianguo Chen, Kefu Chen, Xiawei Chen, Zhe Chen, Zhiyuan Chen, Zihua Chen, Wenhao Chu, Hui Deng, Xun Ding, Zhuzhengqi Ding, Yajie Du, Bo Fan, Daojin Fan, Yuanhao Fu, Dongxin Gao, Ming Gong, Jiacheng Gui, Cheng Guo, Lianchen Han, Tan He, Linyin Hong, Yisen Hu, He-Liang Huang, Yong-Heng Huo, Chenyan Jiang, Lei Jiang, Tao Jiang, Wei Jiang, Zuokai Jiang, Dayu Li, Dongdong Li, Jiaqi Li, Jinjin Li, Junyun Li, Shaowei Li, Wei Li, Xu Li, Yuan Li, Yuhuai Li, Futian Liang, Nanxing Liao, Jin Lin, Maliang Liu, Yancheng Liu, Haoxin Lou, Kailiang Nan, Meijuan Nie, Le Niu, Wenyi Peng, Haoran Qian, Hao Rong, Tao Rong, Yanyan Shao, Huiyan Shen, Qiong Shen, Ganlin Song, Hong Su, Feifan Su, Chenyin Sun, De Sun, Liangchao Sun, Tianzuo Sun, Yingxiu Sun, Yimeng Tan, Jun Tan, Shibiao Tang, Yueyang Tang, Wenbing Tu, Jiafei Wang, Biao Wang, Chang Wang, Chen Wang, Chu Wang, Jian Wang, Rui Wang, Shengtao Wang, Xinzhe Wang, Zhi Wang, Zuolin Wei, Gang Wu, Yulin Wu, Hongjun Xia, Shouzhong Xia, Shiyong Xie, Zhilin Xie, Liang Xiong, Jianping Xu, Yan Xu, Yu Xu, Chun Xue, Kai Yan, Xin Yan, Weifeng Yang, Xinpeng Yang, Yang Yang, Yicheng Yang, Yangsen Ye, Zhenping Ye, Jianghan Yin, Chong Ying, Jiale Yu, Qinjing Yu, Chen Zha, Shaoyu Zhan, Cha Zhang, Fang Zhang, Haibin Zhang, He Zhang, Huanmei Zhang, Kaili Zhang, Qipeng Zhang, Shijia Zhang, Wen Zhang, Xin Zhang, Yiming Zhang, Yongzhuo Zhang, Ziying Zhang, Guming Zhao, Xintao Zhao, Youwei Zhao, Zhong Zhao, Luyuan Zheng, Fei Zhou, Liang Zhou, Naibin Zhou, Chengjun Zhu, Qingling Zhu, Yongsheng Zhu, Guihong Zou, Haonan Zou, Qiang Zhang, Chao-Yang Lu, Jianxin Chen, Cheng-Zhi Peng, Fusheng Chen, XiaoBo Zhu, Jian-Wei Pan", "d": "2026-07-03", "s": 91.0, "x": "This work demonstrates key elements of patch-based surface-code logical processing on a 107-qubit superconducting processor, implementing code-deformation and lattice-surgery primitives (merge, split, expansion, shrinkage, domain walls, twist defects) and composing them into a Clifford-generating set of logical gates (H, S, CNOT) on distance-3 rotated surface-code patches with multi-round syndrome extraction and neural-network decoding. All operations are performed without post-selection, advancing superconducting surface-code experiments from protected logical memory to active, measurement-based logical operations."}, {"id": "2607.01422", "t": "High-Precision Calibration Workflow Achieves Above $99.9\\%$ CZ Gate Fidelity on a Scalable Superconducting Processor", "a": "Huili Zhang, Meiling Li, Shuang Yang, Yaqing Feng, Yulong Li, Cheng Chen, Pei Liu, Guangming Xue, Haifeng Yu", "d": "2026-07-03", "s": 90.5, "x": "This work develops a closed-loop calibration workflow combining echoed leakage error amplification (ELEA) and context-aware fidelity estimation (CAFE) circuits to achieve CZ gate fidelity exceeding $99.9\\%$ on an 84-qubit superconducting processor with tunable transmon qubits and couplers. Automated recalibration every 0.5 hours maintains gate stability over 9-hour monitoring periods, with median fidelity $99.25\\%$ across 72 parallel CZ gates and coherent error suppressed to $0.007\\%$."}, {"id": "2607.01375", "t": "Bit flips are erasures in dissipative cat qubits", "a": "Filippo Ferrari, Joachim Cohen, Vincenzo Savona, Fabrizio Minganti", "d": "2026-07-03", "s": 58.4, "x": "This paper shows that bit-flip errors in dissipatively stabilized cat qubits are detectable erasures, heralded by strong, time-localized photon bursts from the dissipative buffer used for autonomous quantum error correction. The authors develop a framework based on past quantum states and number-resolved master equations to quantify the detectability of logical failures from emitted signals in autonomous QEC, demonstrating viability with realistic photodetector parameters."}, {"id": "2607.02031", "t": "Idling error suppression through gate scheduling", "a": "Hoiki Madison Liu, Kazunori Maruyama, Hirotaka Oshima, Shintaro Sato", "d": "2026-07-03", "s": 53.8, "x": "This paper proposes suppressing idling errors in superconducting qubits through circuit scheduling that adjusts the timing of Hadamard gates within idle intervals, without inserting additional control pulses. Two strategies are introduced—midpoint placement and random shot-by-shot placement—and validated on a 64-qubit superconducting processor with measured coherence times $T_1 = 5.24$–$32.81$ μs and $T_2 = 8.44$–$43.34$ μs, showing improvements up to 12% in accuracy compared to unfavorable placements."}, {"id": "2607.00490", "t": "A Versatile Analytical Model for Fast and Accurate Determination of Feedline-Coupled Resonators for Superconducting Qubit Readout", "a": "Zhen Luo, Lea Richard, Ivan Tsitsilin, Christian M. F. Schneider, Marco Dietz, Stefan Filipp, Amelie Hagelauer", "d": "2026-07-02", "s": 96.1, "x": "An analytical model using conformal mapping and four-port network analysis determines resonance frequencies and coupling Q-factors for edge-coupled $\\lambda/4$ CPW resonators in flip-chip superconducting qubit readouts. The model is validated against 3D FEM simulations and cryogenic measurements of ten resonators with varying geometries, showing agreement within $\\Delta f_r/f_r < 1\\%$ and $\\Delta Q_c/Q_c < 20\\%$."}, {"id": "2607.00688", "t": "Leakage Mobility and Passive Leakage Removal in Transmons with Tunable Couplers", "a": "Taneli Tolppanen, Gonzalo Martín-Vázquez, Sasu Tuohino, Matti Silveri", "d": "2026-07-02", "s": 79.1, "x": "This work characterizes leakage excitation dynamics in transmon qubits coupled via tunable couplers through analytical and numerical methods, finding that leakage hopping persists at rates of 0.8–10 MHz even when couplers suppress single-excitation exchange or ZZ interactions. Two passive leakage removal units are proposed based on tunable couplers and a junction readout scheme, achieving leakage removal timescales of ~30 ns and ~125 ns respectively."}, {"id": "2607.00429", "t": "Surface Platinum Alloying for Passivation of Oxide Interfaces on Superconducting Niobium Films", "a": "Ananya Chattaraj, Conan Weiland, Bruce Ravel, Kim Kisslinger, Sooyeon Hwang, Xiao Tong, Ajith Pattammattel, Andrew M. Kiss, Steven L. Hulbert, Aswin kumar Anbalagan, Andrew L. Walter, Peter V. Sushko, Mingzhao Liu", "d": "2026-07-02", "s": 74.7, "x": "A Pt overlayer deposited on air-oxidized Nb films undergoes thermally driven reactions that form a Pt-rich Nb–Pt alloy (primarily NbPt$_3$) at the surface while dissolving the native oxide, as confirmed by VEXPS, EXAFS, TEM, and DFT. This encapsulation strategy preserves bulk superconducting properties ($T_c = 9.30 \times 0.10$ K, RRR = 64) while protecting both planar surfaces and device sidewalls against re-oxidation, offering a scalable pathway to reduce TLS-induced decoherence in Nb transmon qubits."}, {"id": "2607.00903", "t": "Characterization of Hydroxyls in Surface Oxide of Superconducting Tantalum and Their Mitigation in Quantum Circuits", "a": "Ekta Bhatia, Nicholas Pieniazek, Aleksandra Biedron, Sandra Schujman, Hunter Frost, Zhihao Xiao, Jakub Nalaskowski, Kevin Musick, Thomas Murray, Satyavolu Papa Rao", "d": "2026-07-02", "s": 71.4, "x": "Recently, tantalum (Ta) has gained attention in superconducting quantum circuits due to the longer coherence times achieved when replacing niobium (Nb) in capacitor pads. Previous literature shows that surface oxides that form upon ambient exposure on superconducting metals such as Ta, Al, and Nb host two-level system (TLS) defects, which are a leading source of microwave loss and decoherence."}, {"id": "2607.00735", "t": "Experimental Quantification of Layered Error Suppression in Fiber-Interconnected Quantum Data Centers", "a": "Seyed Navid Elyasi, Sima Bahrani, Rui Wang, Dimitra Simeonidou, Paolo Monti, Rui Lin", "d": "2026-07-02", "s": 69.5, "x": "This paper experimentally demonstrates layered error suppression in fiber-interconnected superconducting quantum processors using a quantum collisional model to emulate transduction and fiber noise on IBM's 156-qubit Heron r2 device. The combined application of entanglement purification (BBPSSW protocol), Pauli twirling, and readout mitigation recovers remote CNOT fidelity by over 20% in the high-noise regime, with Bell-state fidelity improving from ∼0.42 to ∼0.63 at 10 fiber steps."}, {"id": "2607.00769", "t": "Universal logic circuit for gate-controlled superconductor-based switches operating at liquid-helium temperatures", "a": "Martin Berke, Lőrinc Kupás, Tosson Elalaily, Máté Sütő, Szabolcs Csonka, Péter Makk", "d": "2026-07-02", "s": 65.3, "x": "This work demonstrates a universal logic circuit based on gate-controlled supercurrent (GCS) in NbTiN nanowires that implements AND, OR, NOT, COPY, and more complex gates at 4 K using only three nanowires with two side-gate electrodes each. The device exploits voltage-controlled switching between superconducting and normal states to perform classical logic operations with output voltages reaching ~2 V, enabling direct interfacing with CMOS technology."}, {"id": "2607.00660", "t": "Overcoming the Speed-Fidelity Trade-off in Fast CZ Gates via Cyclic Control", "a": "Ze-An Zhao, Hai-Feng Zhang, Tian-Le Wang, Xiao-Yan Yang, Peng Wang, Ren-Ze Zhao, Sheng Zhang, Zhi-Fei Li, Yuan Wu, Zi-Hao Fu, Sheng-Ri Liu, Peng Duan, Guo-Ping Guo", "d": "2026-07-02", "s": 59.1, "x": "This work identifies that short-timescale waveform distortions break time-reflection symmetry in control pulses, creating an over-constrained optimization problem that limits fast CZ gate fidelity in superconducting qubits. A cyclic control strategy using parameter-space expansion with independent frequency detunings $\\Delta_1$ and $\\Delta_2$ restores controllability and achieves coherent error suppression from 0.27% to 0.12% without increasing gate duration."}, {"id": "2607.00172", "t": "Superconducting Spiral Inductors for RF Reflectometry: Operation at Elevated Temperatures and Magnetic Fields", "a": "Euan Parry, Murat Cubukcu, Patrick Reuvekamp, Manoj Stanley, Jonathan D. Fletcher, Alessandro Rossi", "d": "2026-07-02", "s": 58.4, "x": "This work systematically characterizes NbTiN superconducting spiral inductors under elevated temperatures (2–8 K) and magnetic fields (up to 750 mT) relevant for spin-qubit RF reflectometry. By combining weakly coupled resonator measurements with independent two-port inductance extraction, the authors show that temperature- and field-dependent frequency shifts are primarily inductive in origin and can be reconstructed from kinetic-inductance changes alone."}, {"id": "2606.31306", "t": "Ferroelectric transmon", "a": "M. Donaire, A. Cano", "d": "2026-07-01", "s": 78.9, "x": "The ferroelectric transmon (FEmon) exploits the nonlinear dielectric response of a ferroelectric capacitor shunting a Josephson junction to simultaneously achieve charge-noise insensitivity and enhanced anharmonicity, addressing a fundamental tradeoff in superconducting qubits. The qubit Hamiltonian includes quartic charge terms ($\\hat{H} = \\frac{a}{2}(\\hat{n} - n_g)^2 + \\frac{b}{4}(\\hat{n} - n_g)^4 - E_J \\cos \\hat{\\phi}$) that enable operation near ferroelectric criticality ($a \\to 0$), yielding energy level spacing that scales as $E_C (E_J/E_C)^{2/3}$ rather than the standard transmon's $(E_J/E_C)^{1/2}$ dependence."}, {"id": "2606.31011", "t": "Qubit Readout via State-Dependent Radiative Linewidths", "a": "Yiming Yu, Xinyu Zhao, Jia-Wen Yu, Ke-Xiong Yan, Wei Qin, Ye-Hong Chen, Yan Xia, Franco Nori", "d": "2026-07-01", "s": 62.3, "x": "This work proposes a quantum non-demolition qubit readout based on state-dependent radiative linewidths rather than dispersive frequency shifts, where the qubit state controls the external decay rate of the readout mode via a diagonal Lindblad jump operator. Starting from an empty cavity, this dissipative channel generates output-field separation at $O(t)$ compared to $O(t^2)$ for standard dispersive readout, yielding faster matched-filter SNR accumulation across finite-resource regimes."}, {"id": "2606.30805", "t": "CryoZip: An Efficient Cryogenic Compressor for Quantum Error Correction Syndromes", "a": "Guanchen Tao, Alexander Knapen, Jacob Mack, Gokul Subramanian Ravi, Qirui Zhang, Mehdi Saligane, Dennis Sylvester", "d": "2026-07-01", "s": 60.1, "x": "CryoZip is a cryogenic syndrome compression framework for quantum error correction that achieves up to $48\\times$ compression across surface, BB, and color codes by encoding distances between consecutive active syndromes followed by Huffman encoding. Implemented in 22 nm FDSOI cryo-CMOS and evaluated at 4 K, CryoZip cooperates with lightweight cryogenic predecoders to deliver over $14{,}238\\times$ bandwidth reduction and up to $42\\times$ energy savings while meeting strict $100$ ns latency constraints per syndrome round."}, {"id": "2606.31428", "t": "The limits of erasure-based postselection for quantum error mitigation", "a": "Sam J. Griffiths, Jamie Friel, Brian Vlastakis", "d": "2026-07-01", "s": 54.1, "x": "This work investigates erasure-based postselection for error mitigation in dual-rail transmon qubits, where thermal relaxation becomes a detectable erasure event rather than unheralded amplitude damping. The authors develop a circuit-level simulation framework (erado) and demonstrate that postselection can mitigate erasures in QFT up to erasure check error rates below 3.0%, with postselected dual-rail systems surpassing the noise floor at kiloquop scales where comparable single-rail systems fail."}, {"id": "2606.29475", "t": "A superconducting qutrit link beyond the qubit limit", "a": "Xiang Li, Zheng-Yang Mei, Yang He, Si-Lu Zhao, Yan-Jun Liu, Xiao-Hui Song, Kai Xu, Zhong-Cheng Xiang, Dong-Ning Zheng, Heng Fan", "d": "2026-06-30", "s": 85.5, "x": "This work demonstrates a superconducting microwave link between two independently packaged transmon qutrit nodes, achieving arbitrary qutrit-state transfer with 83.68% mean fidelity and 77.12% process fidelity, and generating remote entanglement with negativity 0.730 and tomography-inferred dense-coding capacity 2.273 bits. The protocol uses transition-selective photon-mediated operations ($e0g1$ sideband and $f0g1$ cavity-assisted Raman) to transfer the $|e\\rangle$ and $|f\\rangle$ amplitudes in distinct temporal modes through a tunable Purcell-filtered interface matched at 7.4347 GHz."}, {"id": "2606.28585", "t": "Voltage-tunable Josephson Junctions on Germanium Quantum Wells with in-situ Aluminum Contacts", "a": "Joshua P. Thompson, Jason T. Dong, Bernardo Langa, Chomani K. Gaspe, Riss Card, Brycelynn Bailey, Shiva Davari, Bethany E. Matthews, Matthew J. Olszta, Silas Hoffman, Thomas M. Hazard, Kyle Serniak, Hugh O. H. Churchill, Kasra Sardashti, Christopher J. K. Richardson", "d": "2026-06-30", "s": 82.8, "x": "Voltage-tunable Josephson junctions are fabricated on MBE-grown shallow Ge quantum wells (16 nm) with in-situ Al contacts on float-zone Si substrates using a deep mesa etch process that enables monolithic integration with low-loss superconducting circuits. The devices demonstrate gate-tunable supercurrents reaching 103 nA at $V_g = -17.5$ V with an $I_C R_N$ product of 8.63 µV and extracted interface transparency of 4–9%."}, {"id": "2606.30606", "t": "Repetition-code-based readout error detection and correction across hardware platforms and generations", "a": "Csaba Czabán, Orsolya Kálmán, Sergey N. Filippov, Zoltán Zimborás", "d": "2026-06-30", "s": 74.8, "x": "This work benchmarks repetition-code-based readout error detection and correction across IBM Heron r1–r3 superconducting processors and Quantinuum H1–H2 trapped-ion devices, varying code distance, hardware generation, and encoding layout. Both error detection (unanimous-vote decoding with post-selection) and correction (majority-vote decoding) improve readout fidelity on every device tested, but the benefit of larger code distances depends strongly on the underlying hardware: on superconducting processors, encoding gate errors offset gains rapidly, whereas trapped-ion devices' lower two-qubit gate error rates allow larger codes to remain advantageous."}, {"id": "2606.30592", "t": "Untangling QLDPC Codes with Biased Noise Ancilla", "a": "Runjiang Bi, Kathleen Chang, Shruti Puri", "d": "2026-06-30", "s": 63.3, "x": "This work demonstrates that restricting noise bias to ancilla qubits in syndrome extraction circuits can significantly improve the performance of quantum low-density parity-check codes without requiring code tailoring or bias-preserving CX gates. For the [[144,12,12]] bicycle bivariate code at circuit noise $p = 2 \times 10^{-3}$ with ancilla bit-flip suppression $\times 50$, ancilla-only biased noise achieves an 8.5-fold reduction in logical error rate compared to depolarizing noise, primarily through elimination of hook errors and reduction of short cycles in the Tanner graph."}, {"id": "2606.28505", "t": "Dissipative Effects in Transmission Line Analogues of Hawking Radiation", "a": "Elián Urtubey, Fernando C. Lombardo, Paula I. Villar", "d": "2026-06-30", "s": 56.6, "x": "This paper analyzes dissipative effects in two superconducting-circuit analogues of Schwarzschild black holes that generate Hawking radiation: a tunable dc-SQUID transmission line and a SNAIL-based transmission line supporting solitonic KdV solutions. Using open quantum systems theory, the authors establish detectability thresholds and show that Hawking temperatures above approximately 73 mK remain distinguishable from thermal backgrounds under realistic experimental conditions."}, {"id": "2606.28189", "t": "Imaging geometry- and phase-controlled spectra in a surface-state Andreev cavity", "a": "Adrian Greichgauer, Yoichi Ando, Jens Brede", "d": "2026-06-29", "s": 62.0, "x": "Scanning tunnelling spectroscopy of Cu(111) islands on superconducting Nb(110) reveals Andreev bound-state spectra controlled by phase accumulation along confined surface-state trajectories. The zero-field excitation energy $E_0$ scales with trajectory length $\\ell$ and the magnetic-field collapse scale $B_0 \\propto 1/w$ with transverse projection, capturing geometry-tuned phase-coherent cavity physics."}, {"id": "2606.27017", "t": "Lattice patch structure for fixed-frequency transmon quantum computer with high-fidelity CNOT gates", "a": "Chanpyo Kim, Jeongsoo Kang, Younghun Kwon", "d": "2026-06-26", "s": 89.1, "x": "This work proposes a lattice-patch architecture coupling four fixed-frequency transmon qubits to a single fixed-frequency coupler, achieving CNOT gate fidelities exceeding 0.98 across all six connectivity directions. The design directly maps onto surface-code plaquettes, eliminating flux-noise sensitivity and reducing coupler count compared to conventional grid or heavy-hexagon architectures."}, {"id": "2606.27415", "t": "Elimination of Flux Trapping in Superconducting Circuits in Ambient Magnetic Fields", "a": "Rohan T. Kapur, Alex Wynn, Sergey K. Tolpygo, Neel Parmar, Anil Mankame, Adam A. Libson, Rabindra Das, Michele Kelley, Pauli Kehayias, Nathaniel J. O'Connor, Collin N. Muniz, Justin L. Mallek, Jennifer M. Schloss", "d": "2026-06-26", "s": 80.5, "x": "This work demonstrates magnetic flux trapping suppression in superconducting circuits using on-chip resistive heaters that generate thermal gradients to drive vortices toward moats (etched holes) during cooldown in ambient magnetic fields $B_r \\leq 60$ µT. Magnetic imaging with NV-diamond microscopy and electrical measurements of Josephson junction chains confirm effective flux removal both during field cooling and from circuit-generated vortices."}, {"id": "2606.24772", "t": "A high-fidelity two-qubit gate for multimode superconducting P-mon qubits", "a": "Frederik Pfeiffer, Federico A. Roy, Niklas J. Glaser, Julius Feigl, Leon Koch, Kevin Kiener, Gleb Krylov, Johannes Schirk, Christian M. F. Schneider, Lasse Södergren, Florian Wallner, Max Werninghaus, Carlos A. Riofrío, Stefan Filipp", "d": "2026-06-24", "s": 96.3, "x": "We demonstrate a 99.62% fidelity CZ gate between two multimode P-mon superconducting qubits coupled via their flux-tunable mediator modes, achieving ZZ-type crosstalk suppressed to 3.6 kHz through mode-selective coupling that keeps computational qubits isolated. The gate exploits qubit-state-dependent frequency shifts from cross-Kerr interactions ($\\alpha_{\\mathcal{AB}} \\approx -164$ and $-108$ MHz) to generate an entangling phase without linear qubit-qubit exchange."}, {"id": "2606.23952", "t": "Biophysical EPR Using Superconducting Resonators", "a": "Austin R. Gamble Jarvi, Hamid R. Mohebbi, Ishit Raval, Omari Culzac, Jack Erickson, Sameh Hegazy, Don Carkner, Andrew Wiles, David G. Cory, Troy W. Borneman", "d": "2026-06-24", "s": 68.9, "x": "A custom X-band pulsed EPR spectrometer based on a 16-strip YBCO superconducting microstrip resonator achieves automated measurement of spin-labeled protein samples at sub-10 μM concentrations using 3.5 μL sample volumes with $\\pm1$ degree phase stability. The system implements advanced DEER protocols (RELOAD, DEER-Stitch, CPMG echo train detection) to achieve 6× SNR improvement and enables unattended sequential measurement of five samples in a single cartridge with performance competitive to standard Q-band systems."}, {"id": "2606.24048", "t": "An Analysis of Speculative Window Decoders for Quantum Error Correction", "a": "Jocelyn Li, Margaret Martonosi", "d": "2026-06-24", "s": 64.5, "x": "This paper evaluates speculative window decoding for quantum error correction across a range of qubit technologies and parameters, extending beyond the superconducting-qubit regime with fast gates where it was previously benchmarked. The work identifies design principles for when speculative decoding outperforms conventional decoding and characterizes regimes where non-speculative decoders are superior."}, {"id": "2606.24869", "t": "Rapid Cavity-Based Mid-Circuit Measurement and Feedforward in a Neutral Atom Array", "a": "Tsai-Chen Lee, Jacquelyn Ho, Yue-Hui Lu, Tai Xiang, Nathaniel B. Vilas, Zhenjie Yan, Dan M. Stamper-Kurn", "d": "2026-06-24", "s": 57.8, "x": "This work demonstrates fast mid-circuit measurement and real-time feedforward in a neutral-atom array by coupling qubits to a high-finesse optical cavity, reducing measurement-and-feedforward cycle times from ~1 ms to below 100 μs. The approach uses site-selective light shifts to protect unmeasured data qubits and Purcell-enhanced photon collection from measured qubits, achieving sub-percent measurement infidelity with less than 2% coherence loss on unread qubits."}, {"id": "2606.22853", "t": "Bunny Codes: Broadening Superconducting Quantum Error Correction Capability through Advanced Control Engineering", "a": "Runshi Zhou, Xingye Yuan, Linghang Kong, Fang Zhang, Kai Zhang, Zhaohui Yang, Jianxin Chen", "d": "2026-06-23", "s": 87.7, "x": "This paper presents Bunny codes, a family of qLDPC codes designed for superconducting hardware that leverages an expanded native gate set (CNOT and CXSWAP) to achieve high code rates on 2D nearest-neighbor connectivity. Through exhaustive search over multiple qubit topologies, the authors demonstrate weight-6 Bunny codes with code rates $\\sim 3\\times$ the toric code in periodic boundaries and $\\sim 2\\times$ the surface code in open boundaries, with logical error rates an order of magnitude lower than comparable toric codes under circuit-level simulation."}, {"id": "2606.22594", "t": "Hierarchical Logical Processor on the Rotated Surface Code with Shuttle Buses", "a": "Zi-Han Chen, Ming-Cheng Chen, Chao-Yang Lu, Jian-Wei Pan", "d": "2026-06-23", "s": 81.7, "x": "This paper proposes the Hierarchical Logical Processor (HLP), which concatenates a high-rate quantum CSS code with the rotated surface code (RSC) to achieve improved qubit efficiency while requiring long-range gates only once every $\\Theta(d_0)$ syndrome extraction rounds. The key innovation is the shuttle bus—an elongated RSC patch enabling transversal hybrid-unit CNOT gates to couple multiple data qubits simultaneously, supporting efficient parallel logical measurements while maintaining suppressed error correlations."}, {"id": "2606.22080", "t": "Optimizing Pump Conditions of Parametric Amplifiers for Fast Multiplexed Readout of Superconducting Qubits", "a": "Jeongwon Kim, Wei Dai, Omrie Ovdat, Akiva Feintuch, Nir Alfasi, Yonuk Chong", "d": "2026-06-23", "s": 77.0, "x": "This work optimizes traveling-wave parametric amplifier (TWPA) pump conditions for frequency-multiplexed readout of superconducting qubits by tuning to maximize SNR improvement at the limiting qubit's readout frequency rather than average SNR. On a five-qubit multiplexed readout chain, the limiting-qubit-optimized pump reduces total multiplexed readout time $T_\text{RO}^\text{(MPX)}$ from 1280 ns to 960 ns (25% reduction, 320 ns savings) while maintaining minimum $\triangle\text{SNR} \\\\\\\\ 6$ dB across all qubits and mean readout fidelity of 95.32%."}, {"id": "2606.22732", "t": "Protecting Qubits from Purcell Decay via Permanent Dipoles", "a": "Alex Krasnok", "d": "2026-06-23", "s": 64.1, "x": "This work shows that a permanent electric dipole on a qubit can suppress cavity-mediated Purcell decay by displacing oscillator wave functions and reducing transverse qubit–cavity exchange, while preserving longitudinal readout coupling. In the displaced rotating-wave approximation, the exchange vanishes exactly at $\\eta = \\sqrt{2}$; in the full-transverse model, strong suppression persists at $\\eta_{\\mathrm{FT}} = 2.60$, yielding cavity-mediated lifetime improvements from $\\kappa T_1 = 11.1$ to $47.3$ and single-shot readout error reduction from $0.21$ to $0.07$ at fixed pointer separation."}, {"id": "2606.21762", "t": "Dynamical Decoupling using Universal Optimal Tracking", "a": "Amit Devra, Emanuel Malvetti, Niklas J. Glaser, Abhishek Agarwal, Ivan Rungger, Santana Lujan, Max Werninghaus, Stefan Filipp, Leo Van Damme, Steffen J. Glaser", "d": "2026-06-23", "s": 62.1, "x": "This work introduces U-TRACK, a family of dynamical decoupling sequences designed using optimal tracking that enforces identity evolution at intermediate checkpoints in addition to the end of the sequence, preventing error accumulation across pulse blocks. Experimental validation on superconducting-qubit platforms demonstrates that U-TRACK4 maintains superior robustness against static detuning and amplitude errors compared to XY4 and UR40, while simulations show it outperforms both sequences under low-frequency random telegraph noise."}, {"id": "2606.22376", "t": "Vibe Calibration: Autonomous Bring-up of a 112-Qubit Superconducting Quantum Processor by a Skill-Orchestrating Language Agent", "a": "Huikai Xu, Jiaxiu Han, Shigang Ou, Cheng Ye, Zisong Shen, Jing Gao, Yijia Wang, Tianrui Che, Yu Song, Weiyang Liu, Lei Wang, Lin-Feng Zhang, Pan Zhang, Hai-Feng Yu", "d": "2026-06-23", "s": 59.0, "x": "Vibe Calibration autonomously calibrates a 112-qubit frequency-tunable transmon processor by orchestrating reusable Skills through a fine-tuned LLM agent, achieving 108/112 qubits in 4.7 hours with 4–5× speedup over manual operation. The system distills expert tacit knowledge via three-phase human-in-the-loop training and demonstrates transfer of calibration workflows across devices without retraining."}, {"id": "2606.20904", "t": "Scanning-probe quantum sensing of microwave and static magnetic field response of an on-chip superconducting resonator", "a": "Senlei Li, Jingcheng Zhou, Zelong Xiong, Hanyi Lu, Hailong Wang", "d": "2026-06-22", "s": 60.2, "x": "Scanning-probe quantum microscopy using a quantum spin sensor locally probes the microwave and static magnetic field environment of an on-chip niobium superconducting resonator. Rabi oscillations enable coherent control of the spin sensor by the resonator's microwave mode, while static field measurements reveal vortex formation and depinning dynamics in the superconductor."}, {"id": "2606.20968", "t": "Profiling the Effective Limits of Error Mitigation via Circuit Replication", "a": "Jeremie Pope, Swaroop Ghosh", "d": "2026-06-22", "s": 51.5, "x": "This paper characterizes circuit replication as a supplemental error mitigation strategy by executing QAOA for Maxcut on IBM's 156-qubit Fez platform with up to 6 parallel replicates on graphs with 5–8 nodes. For small graphs, 6 replicates reduce average standard deviation by 108.8% at the cost of 21.8% degradation in inference strength; for larger graphs, inference strength degrades 35.4% while standard deviation decreases only 20.5%, with variability plateauing between 3–4 replicates under the realistic noise model."}, {"id": "2606.20501", "t": "Fidelity bounds for adiabatic gates and other quantum operations with time-dependent dissipation", "a": "Simon Pettersson Fors, Aniket Patel, Anton Frisk Kockum, Tahereh Abad", "d": "2026-06-19", "s": 66.6, "x": "This Letter generalizes analytical fidelity-reduction formulae from static to time-dependent Markovian dissipation, enabling prediction of average gate fidelity for quantum operations where decoherence rates vary during execution. Application to adiabatic controlled-Z gates in superconducting circuits reveals that flux-dependent noise sensitivity and qubit-coupler hybridization significantly degrade fidelity in tunable architectures."}, {"id": "2606.20317", "t": "Highly crystalline superconducting TiN resonators grown on thermally reconstructed sapphire", "a": "Thomas J. Smart, Marc Neis, Janine Lorenz, Marcello P. Guardascione, Roudy Hanna, Michael Schleenvoigt, Yuan Gao, Joscha Domnick, Benjamin Bennemann, Abdur Rehman Jalil, Jin Hee Bae, Harsh Bhardwaj, F. Stefan Tautz, Felix Lüpke, Detlev Grützmacher, Rami Barends, Pavel A. Bushev, Peter Schüffelgen", "d": "2026-06-19", "s": 60.3, "x": "TiN (111) films grown via plasma-assisted MBE on CO$_2$-laser thermally reconstructed ($\\sqrt{31}\\times\\sqrt{31}$)$R\\pm 9°$ sapphire exhibit sharper rocking curves (FWHM $0.048°$ versus $0.098°$) and more isotropic reciprocal-space-map distributions than films on chemically cleaned sapphire, indicating reduced mosaicity and improved crystalline coherence. Superconducting coplanar waveguide resonators fabricated from both film types achieve median internal quality factors $Q_i \\approx 1.1$–$1.3\\times 10^6$ at single-photon levels ($\\langle n \\rangle \\sim 1$), with many exceeding $10^7$ at higher powers, and comparable superconducting gaps ($\\Delta_\\mathrm{BCS} \\approx 0.63$–$0.67$ meV) and transition temperatures ($T_c \\approx 5.08$–$5.11$ K)."}, {"id": "2606.19628", "t": "Subsystem Quantum Error Correction for Noisy Quantum Metrology", "a": "Qiushi Liu, Sisi Zhou", "d": "2026-06-19", "s": 58.6, "x": "Subsystem quantum error correction enables Heisenberg-limit metrology with substantially reduced overhead compared to standard QEC approaches, requiring at most a single ancilla qubit and syndrome-free recovery procedures. The framework extends to time-dependent signals through Floquet codes, which protect periodic metrological evolution by dynamically encoding information in a logical subsystem while allowing noise to be absorbed into gauge degrees of freedom."}, {"id": "2606.19848", "t": "QMCtwin: Master-Equation Simulation of Syndrome Statistics Beyond Pauli Noise", "a": "Tong Shen, Huo Chen, Benchen Huang, Tyler Takeshita, Arian Vezvaee, Izhar Medalsy, Daniel A. Lidar", "d": "2026-06-19", "s": 52.2, "x": "QMCtwin is a sign-problem-suppressed quantum Monte Carlo framework for master-equation simulation of QEC circuits that directly captures coherent, dissipative, and correlated noise dynamics beyond Pauli approximations. Applied to a distance-7 rotated surface code with 97 physical qubits under realistic superconducting-device noise including relaxation, dephasing, coherent miscalibration ($\\delta_g = 0.1\\%$), residual $ZZ$ crosstalk, and drive detuning, QMCtwin predicts syndrome-extraction biases and syndrome-to-string-parity correlations absent or suppressed in stochastic Pauli-twirled Clifford models."}, {"id": "2606.19482", "t": "Nearest-neighbour gates are all you need: High-rate quantum low-density parity-check codes on a planar grid", "a": "Boren Gu, Tamas Noszko, Vincent Steffan, Jens Niklas Eberhardt, Joschka Roffe, Jens Eisert, Stergios Koutsioumpas", "d": "2026-06-19", "s": 52.0, "x": "This work introduces directional tile codes, a family of quantum low-density parity-check codes compatible with planar nearest-neighbour superconducting qubit architectures, where syndrome extraction uses only iSWAP-based walks on a 2D square grid. The codes achieve circuit-level logical error rates up to 1000× lower than rotated surface codes at comparable footprints (~30 qubits per logical qubit), combining high code efficiency with strictly local connectivity."}, {"id": "2606.20441", "t": "Computing noise-canceling observables via Pauli propagation", "a": "Andrew Eddins, Caleb Johnson, Alberto Baiardi, Francesco Tacchino, Ewout van den Berg, Roy Elkabetz, Vinay Tripathi, Swarnadeep Majumder, Max Rossmannek, Liran Shirizly, Abhinav Kandala", "d": "2026-06-19", "s": 50.5, "x": "This paper introduces two hybrid error-mitigation methods—Propagated Noise Absorption (PNA) and Euclid—that classically propagate observables through inverted noise channels to construct noise-canceling observables measured on noisy quantum hardware. On a 56-qubit superconducting processor, PNA achieves quadratic sampling cost reduction compared to probabilistic error cancellation while outperforming direct Pauli-propagation simulation of noiseless circuits in the non-Clifford regime."}, {"id": "2606.18755", "t": "Quantum simulation of neutrino oscillations with bosonic encoding", "a": "Sandeep Joshi", "d": "2026-06-18", "s": 74.3, "x": "This paper demonstrates quantum simulation of two- and three-flavor neutrino oscillations using Fock-basis encoding of a microwave cavity mode in superconducting circuits, with control via SNAP and displacement gates applied to an ancillary transmon qubit. Pulse-level simulations show oscillation probabilities in close agreement with theoretical predictions despite gate fidelities reduced to ~0.97 (two-flavor) and ~0.925 (three-flavor) by ancilla decoherence."}, {"id": "2606.19339", "t": "Quantum solitons and their quantum walks in transmon arrays", "a": "Ben Blain, Giampiero Marchegiani, Luigi Amico, Gianluigi Catelani", "d": "2026-06-18", "s": 74.2, "x": "This work theoretically investigates spatially localized quantum solitons in linear arrays of capacitively coupled transmons described by the attractive Bose-Hubbard model, and proposes protocols for their preparation and characterization via quantum walks in transmon circuits. The solitonic states are superpositions of the lowest-energy band eigenstates with exponentially localized density profiles, revealing composite-particle behavior distinct from both single-particle and boson-stack dynamics."}, {"id": "2606.19171", "t": "Cavity-enhanced superconductivity in the two-dimensional limit of NbSe2", "a": "Hanxiang Zhang, Zexin Feng, I-Te Lu, Zhiwei Li, Songhao Guo, Qiuyu Shang, Thomas Tan, Xiaodan Lyu, Xiangming Shen, Dening Luan, Mingcheng Panmai, Kenji Watanabe, Takashi Taniguchi, Ranjan Singh, Angel Rubio, Weibo Gao", "d": "2026-06-18", "s": 60.7, "x": "Bilayer NbSe$_2$ coupled to a terahertz CSRR cavity shows a 10% enhancement of $T_c$ (from 3.02 K to 3.41 K) at 0.92 THz resonance, with the effect growing sharply in the two-dimensional limit and scaling roughly four times larger than in ten-layer devices. QED-DFT calculations show the enhancement arises from cavity-induced redistribution of spectral weight in the Eliashberg function, weakening electron-phonon coupling while hardening the logarithmic average phonon frequency, with the sign change in $T_c$ emerging from competition between these effects."}, {"id": "2606.17866", "t": "Experimental Characterization and Modeling of Measurement-Induced State-Transitions in a Fluxonium Superconducting Qubit", "a": "Martijn F. S. Zwanenburg, Jinlun Hu, Eugene Y. Huang, Figen Yilmaz, Siddharth Singh, Christian Kraglund Andersen", "d": "2026-06-17", "s": 84.6, "x": "This work experimentally characterizes measurement-induced state transitions (MIST) in a fluxonium qubit across its full external flux range and validates theoretical models predicting their occurrence. Branch analysis without array modes explains six of eleven identified MIST regions, while Floquet branch analysis including the two lowest array modes accounts for the remaining five, with five of these being dominated by transitions involving superinductor array modes."}, {"id": "2606.17338", "t": "Effects of Josephson Junction Non-idealities on Adiabatic Quantum Flux Parametron Circuits", "a": "Daryoush Shiri, Likai Yang, Mohamed A. Hassan, Philip Krantz, Eric T. Holland", "d": "2026-06-17", "s": 78.1, "x": "This work demonstrates hierarchical simulation of adiabatic quantum flux parametron (AQFP) gates in Keysight ADS using symbolically defined devices (SDD) to model Josephson junctions with arbitrary current-phase relations. The non-sinusoidal $I(\\phi)$ characteristics of SNS and weak-link junctions are shown to substantially alter AQFP switching speed, output current swing ($\\pm 20$ µA for SIS versus $\\pm 40$ µA for SNS), and timing margins."}, {"id": "2606.17709", "t": "Optimizing bias-tailored quantum error correction beyond code-capacity noise", "a": "César Benito, I. Jesán Velázquez-Reséndiz, Alejandro Bermudez", "d": "2026-06-17", "s": 66.3, "x": "This work quantifies how bias-tailored quantum error correction advantages predicted under code-capacity noise are substantially reduced by realistic circuit-level effects, and proposes a bias-filtering CNOT gadget to partially recover these advantages. The authors compare XZZX codes to optimized anisotropic surface codes and find that although anisotropic codes outperform XZZX under code-capacity noise, this advantage disappears under circuit-level noise due to bias degradation in syndrome extraction."}, {"id": "2606.17907", "t": "SPICE-Q and Large-Scale Quantum Chip Production", "a": "Cai, Ling Qiao, Bin Yang, Fumin Luo, Chang Liu, WeiGui Guo, GuoRong Zhang, XueFei Liu, Qinglang Guo, Bin Wu", "d": "2026-06-17", "s": 65.3, "x": "This paper proposes SPICE-Q, a design-technology co-optimization framework for superconducting quantum processors that unifies process rules, layout, electromagnetic simulation, circuit quantization, Hamiltonian extraction, noise analysis, and manufacturing feedback into a single traceable data chain. The framework draws an analogy with classical SPICE, which transformed integrated-circuit design from trial-and-error into model-driven engineering, arguing that quantum computing requires an analogous unified infrastructure to scale from NISQ toward fault-tolerant processors."}, {"id": "2606.18084", "t": "Cavity-enhanced superconducting response in an underdoped cuprate", "a": "Angela Montanaro, Vadim Plastovets, Nitesh Khatiwada, Jacopo Fiore, Giacomo Jarc, Abdullah Alabbadi, Antonio Mastropasqua, Enrico Maria Rigoni, Shahla Y. Mathengattil, Simone Dal Zilio, Francesca Fassioli Olsen, Fabio Novelli, Stephan Winnerl, Michael A. Sentef, Dante M. Kennes, Andrew J. Millis, Francesco Piazza, Daniele Fausti", "d": "2026-06-17", "s": 56.6, "x": "An underdoped YBa$_2$Cu$_3$O$_{7-δ}$ thin film embedded in a tunable terahertz cavity exhibits enhanced superconducting response with increased inferred superfluid weight below $T_c$, accompanied by an upward shift of the superconducting onset temperature. A cavity-coupled model for phase-fluctuating superconductors interprets the effect as cavity-enhanced phase stiffness that suppresses long-wavelength phase fluctuations and shifts the Berezinskii-Kosterlitz-Thouless transition to higher temperature."}, {"id": "2606.16055", "t": "Readout-Induced Leakage in Superconducting Circuits with Nonlinear Couplings", "a": "Sumeru Hazra, Wei Dai, Daniel K. Weiss, Pranav D. Parakh, Luigi Frunzio, Michel H. Devoret", "d": "2026-06-16", "s": 96.9, "x": "Native nonlinear qubit-readout couplings like cosine-cosine interactions promise intrinsic Purcell protection and suppression of drive-induced leakage through selection rules, but when realized via auxiliary mediator modes, these couplings reintroduce dense multiphoton resonance landscapes and remain highly sensitive to readout frequency. Experiments on a dimon device demonstrate that readout-induced leakage varies by more than an order of magnitude across a ~7% readout frequency window, showing that engineering such couplings requires careful spectral placement of auxiliary modes and elimination of parasitic electromagnetic modes."}, {"id": "2606.15190", "t": "Lattice surgery for near-term experimental logical qubit entanglement creation in planar architectures", "a": "Lukas Bödeker, Áron Márton, Luis Colmenarez, Ilya Besedin, Andreas Wallraff, Markus Müller", "d": "2026-06-16", "s": 91.4, "x": "This work describes a logical teleportation protocol between two surface-code logical qubits using lattice surgery on a superconducting qubit architecture, comparing fully modular and depleted variants and exploring adaptive syndrome extraction and optimal merge region widths. Stabilizer simulations with experimentally informed noise parameters from ETH Zurich surface-17 experiments show a $\\sim 2\\times$ fidelity improvement in the depleted scheme and identify parameter regimes where in-sequence decision logic and minimal interface widths optimize performance."}, {"id": "2606.16060", "t": "Enhanced Sensitivity near a Quantum Exceptional Point in the Absence of Engineered Dissipation", "a": "Réouven Assouly, Harry Hanlim Kang, Aziza Almanakly, Michael A. Gingras, Bethany M. Niedzielski, Hannah Stickler, Mollie E. Schwartz, Kyle Serniak, Max Hays, Jeffrey A. Grover, William D. Oliver", "d": "2026-06-16", "s": 78.6, "x": "A four-mode superconducting coplanar-waveguide resonator coupled to a SNAIL is used to emulate a $\\mathcal{PT}$-symmetric dimer via parametric drives, avoiding explicit gain and loss. Enhanced sensitivity to perturbations in the coupling strength is observed near the exceptional point in a classical-noise-limited regime, with eigenvalue splitting exhibiting the predicted $\\sqrt{\\epsilon}$ dependence."}, {"id": "2606.15398", "t": "Watching a Superconducting Coplanar Waveguide Heat Up with a Single Color Center", "a": "Ioannis Karapatzakis, Jeremias Resch, David Hunger, Wolfgang Wernsdorfer", "d": "2026-06-16", "s": 65.7, "x": "A single tin-vacancy (SnV) center in diamond is calibrated as a local on-chip thermometer using temperature-dependent optical transitions ($20$ K to few kelvin) and spin-lattice relaxation time $T_1$ (few kelvin to millikelvin), then applied to characterize microwave- and RF-induced heating in a niobium superconducting coplanar waveguide (CPW) on the same chip. At $2$ GHz and zero field, superconducting breakdown occurs at $P_{\text{crit}} \\approx 17.2$ dBm with abrupt heating to $\\sim 7.5$ K (inferred from linewidth), while at $20$ MHz and $400$ mT the CPW shows no measurable heating up to $P_{\text{RF}} = 9.4$ dBm ($B_{\text{ac}} \\sim 1.2$ mT), establishing a safe operating window for diamond-based quantum nodes."}, {"id": "2606.14847", "t": "High-fidelity two-qubit gates in a 7-qubit register for quantum networks", "a": "Margriet van Riggelen, Jiwon Yun, H. Benjamin van Ommen, Tim H. Taminiau", "d": "2026-06-16", "s": 61.4, "x": "High-fidelity two-qubit gates are demonstrated in a 7-qubit NV-center register in diamond, achieving average fidelity of 99.18(2)% and best-case 99.61(5)% using dynamically decoupled radiofrequency (DDRF) gates on nuclear spins coupled to the NV electron spin. The work characterizes crosstalk mechanisms, develops an efficient gate optimization procedure, and validates the gates with variational quantum eigensolver simulations of H$_2$ and LiH molecules, demonstrating performance at the threshold for distributed quantum computation."}, {"id": "2606.14522", "t": "Quantum gates with parametrically driven multi-qubit couplers", "a": "Verena Feulner, Marjan Fani, Lukas Heunisch, Stephan Tasler, Michael J. Hartmann", "d": "2026-06-15", "s": 81.5, "x": "This work demonstrates parametrically driven multi-qubit couplers based on dc-SQUIDs and tunable SNAILs for realizing high-fidelity gates between any pair of qubits in a four-qubit plaquette, including diagonal couplings, as well as native three- and four-qubit interactions. By carefully analyzing the Jacobi-Anger expansion of the time-dependent Hamiltonian and optimizing the drive parameters, the authors achieve $\\sqrt{\\mathrm{iSWAP}}$ gates with 99.9% fidelity in 50 ns for two qubits and 95% fidelity in 200 ns for three-qubit gates, while also demonstrating simultaneous execution of two disjoint two-qubit gates at 99.4% fidelity."}, {"id": "2606.13010", "t": "QuBE/Qubex: an integrated hardware-software system for superconducting qubit experiments with broadband control", "a": "Akinori Machino, Kazuhisa Ogawa, Takefumi Miyoshi, Hidehisa Shiomi, Shinichi Morisaka, Ryo Matsuda, Nilton F. G. Filho, Koichiro Ban, Takafumi Miyanaga, Keisuke Koike, Ryutaro Ohira, Toshi Sumida, Yoshinori Kurimoto, Yuuya Sugita, Yosuke Ito, Yasunari Suzuki, Peter A. Spring, Shiyu Wang, Hiroto Mukai, Arvind Mamgain, Shuhei Tamate, Yutaka Tabuchi, Yasunobu Nakamura, Makoto Negoro", "d": "2026-06-12", "s": 96.7, "x": "QuBE/Qubex is an integrated hardware-software control system combining broadband microwave generation (1.6 GHz instantaneous span, 7.25–10 GHz control, 9.5–11 GHz readout, 19–21 GHz pump) with a pulse-level software framework for scalable superconducting qubit experiments. Validation on a 64-qubit fixed-frequency transmon chip demonstrates automated setup, synchronized multi-unit operation, far-detuned cross-resonance gates with 98.34 % fidelity, and multilevel readout achieving 95.4 % state-assignment fidelity with JPA assistance."}, {"id": "2606.13052", "t": "Simple analytical flux-tuned iSWAP pulses for leakage suppression", "a": "Dimitrios Georgiadis, Boxi Li, Asier Galicia, Rami Barends, F. A. Cárdenas-López, Felix Motzoi", "d": "2026-06-12", "s": 80.1, "x": "This paper develops $Φ$-DRAG, an analytical flux-control method for suppressing leakage to non-computational states in fast iSWAP gates on tunable-coupler transmon architectures. The approach generalizes derivative-removal-by-adiabatic-gate (DRAG) techniques from microwave control to the flux domain, enabling leakage suppression below $10^{-4}$ for 15 ns gates through higher-order corrections to the effective coupling."}, {"id": "2606.13750", "t": "Tantalum as a base material for superconducting integrated circuits", "a": "Evgeniy V. Zikiy, Nikita S. Smirnov, Stanislav A. Kotenkov, Ilya A. Stepanov, Julia A. Agafonova, Daria A. Moskaleva, Aleksei R. Matanin, Anton I. Ivanov, Dmitry O. Moskalev, Julia A. Kurochkina, Aleksander V. Andriyash, Ilya A. Rodionov", "d": "2026-06-12", "s": 78.7, "x": "This review surveys tantalum as a superconducting thin-film material for quantum circuits, covering growth mechanisms, phase selection on various substrates, fabrication techniques, and performance in resonators and qubits. Key unresolved issues include the role of $\\eta$-phase impurities, HF effects on circuit characteristics, and anomalous low-temperature behavior of $\\alpha$-tantalum."}, {"id": "2606.13375", "t": "Driven-dissipative entanglement of distant giant atoms", "a": "Aziza Almanakly, Ariadna Soro, Alejandro Vivas-Viaña, Beatriz Yankelevich, Caspar Groiseau, David Pahl, Junyoung An, Gabriel Cutter, Michael E. Gingras, Bethany M. Niedzielski, Hannah Stickler, Renée DePéncier Piñero, Mollie E. Schwartz, Kyle Serniak, Max Hays, Jeffrey A. Grover, Anton Frisk Kockum, William D. Oliver", "d": "2026-06-12", "s": 78.6, "x": "This work demonstrates driven-dissipative entanglement generation in a superconducting waveguide-QED system using two giant atoms (transmon qubits coupled twice to a common waveguide). The protocol exploits correlated dissipation and interference at multiple coupling points to autonomously stabilize a Bell state with fidelity $F = 0.89 \\pm 0.02$, followed by frequency tuning to suppress individual dissipation for readout."}, {"id": "2606.12781", "t": "Quantum Network Routing based on Surface Code Error Correction", "a": "Tianjie Hu, Jindi Wu, Qun Li", "d": "2026-06-12", "s": 57.3, "x": "SurfNet is a quantum network architecture that encodes messages as surface codes and transmits them via dual channels: an entanglement-based channel for critical Core qubits and a plain channel for Support qubits, enabling fault-tolerant transfer with improved fidelity. The scheme combines benefits of teleportation-based and direct-transmission networks, supported by a custom decoder exploiting different error rates across code partitions and an integer programming routing protocol."}, {"id": "2606.12262", "t": "Substrate insulated Josephson junctions for superconducting quantum circuits", "a": "U. Strobel, L. Radtke, L. Kamps, J. N. Voss, J. Lisenfeld, J. Luo-Hofmann, D. Reuter, S. Masis, A. V. Ustinov, H. Rotzinger", "d": "2026-06-11", "s": 90.9, "x": "This work develops a substrate-patterned fabrication technique for Josephson junctions that eliminates organic resists and intentional oxides near the junction by using three-dimensional step-and-undercut geometries etched into the substrate. The approach enables high-quality underdamped Nb/AlOx/Nb junctions across multiple geometries (step-edge insulated, cross-step insulated, Manhattan trench, and cross-trench) without lossy dielectric contamination, achieving $J_c R_n$ values of ~1.6 mV and $R_{sg}/R_n$ up to ~50."}, {"id": "2606.11496", "t": "Logical error estimation from syndrome data of surface-code experiments", "a": "Evangelia Takou, Cesar Benito, Arian Vezvaee, Daniel A. Lidar, Kenneth R. Brown", "d": "2026-06-11", "s": 64.6, "x": "This work demonstrates that detector error model (DEM) event probabilities for surface-code decoders can be estimated directly from experimental syndrome data without separate calibration or device benchmarking. Syndrome-estimated DEMs reduce logical error probabilities by 5%–10% relative to baseline device-informed DEMs on both Google's Willow chip (rotated ZXXZ surface code with $d\\in\\{3,5,7\\}$) and IBM's ibm_miami processor (unrotated code with $d=3$), reaching ~38% improvement in single-cycle cases on IBM without requiring additional circuits or supervised fitting."}, {"id": "2606.10719", "t": "Ultra-high Q-factor superconducting tantalum resonators on 300 mm Si wafers", "a": "R. Acharya, D. Perez Lozano, Ts. Ivanov, S. Massar, C. Vrancken, Y. Canvel, Y. Li, A. M. Vadiraj, J. Van Damme, S. Aghaeimeibodi, A. Khalajhedayati, M. Mongillo, O. Painter, D. Wan, A. Potočnik, K. De Greve", "d": "2026-06-10", "s": 94.5, "x": "Planar $\\alpha$-Ta superconducting resonators fabricated on 300 mm ultra-high-resistivity MCZ silicon using industrial processes achieve median internal $Q$ factors exceeding 40 million and maxima above 60 million. Energy-participation-ratio analysis reveals interface loss as the dominant dissipation channel, with inferred substrate loss tangent below $1.0 \\times 10^{-8}$."}, {"id": "2606.10114", "t": "A Cryogenic Hybrid Photonic/CMOS Controller Architecture for Scalable Superconducting Qubit Control", "a": "Bowen Liu, Zhaoran Rena Huang", "d": "2026-06-10", "s": 91.5, "x": "This work proposes a hybrid photonic/CMOS cryogenic controller for superconducting qubits that distributes shared Gaussian and derivative optical pulse templates to 4 K, where local CMOS circuits apply channel-specific amplitude modulation, pulse gating, and hold timing before microwave upconversion. The architecture achieves 0.905 mW per qubit-control channel at N=1000 qubits with $G=16$ local fan-out groups, substantially below full-waveform Cryo-CMOS (3.448 mW) while retaining programmable amplitude calibration after optical distribution."}, {"id": "2606.10970", "t": "Inherent flux crosstalk and coupler-driven single-qubit gates in superconducting circuits", "a": "Balázs Gulácsi, Guido Burkard", "d": "2026-06-10", "s": 84.7, "x": "This work reveals that time-varying external flux threading a SQUID loop induces cross-voltage coupling to capacitively linked qubits through an inherent flux crosstalk mechanism, analogous to Faraday induction. This effect enables fast single-qubit gates via the coupler element in tunable-coupler architectures, potentially eliminating dedicated microwave control lines per qubit."}, {"id": "2606.10144", "t": "Synthesis and Characterization of Atomically-Sharp Superconductor-Dielectric Interface", "a": "Nathan Sitaraman, Zhaslan Baraissov, Alexis Grassl, Hongbin Yang, Daniel Tong, David Muller, Matthias Liepe", "d": "2026-06-10", "s": 59.1, "x": "This work demonstrates synthesis of highly crystalline ZrO$_2$ capping layers on niobium with atomically-sharp superconductor-dielectric interfaces, addressing two-level-system defect density at Nb/oxide interfaces critical for superconducting quantum device coherence. Multislice electron ptychography reveals monoclinic ZrO$_2$ grains (10–15 nm lateral size, 7–8 nm thickness) with 2–3 disordered atomic layers (≈2–5 Å) at the Nb interface and no detectable suboxide layer, in contrast to the amorphous Nb$_2$O$_5$ native oxide."}, {"id": "2606.09722", "t": "Frequency-resolved decoherence spectroscopy of a semiconductor charge qubit coupled to a high-impedance resonator", "a": "Ekaterina Al-Tavil, Wonjin Jang, David J. van Woerkom, Ville Maisi, Stefano Bosco, Jan A. Krzywda, Jeroen Danon, Christian Reichl, Werner Wegscheider, Thomas Ihn, Klaus Ensslin, Andreas Wallraff, Pasquale Scarlino", "d": "2026-06-09", "s": 91.8, "x": "A GaAs double-quantum-dot charge qubit coupled to a frequency-tunable SQUID-array resonator enables frequency-resolved decoherence spectroscopy from 3 to 6 GHz, revealing a crossover from dephasing-dominated to relaxation-dominated decoherence. The measured relaxation rate exhibits cubic scaling with qubit frequency, consistent with piezoelectric acoustic phonon coupling and demonstrating the utility of tunable hybrid circuits as quantitative probes of microscopic dissipation."}, {"id": "2606.08406", "t": "A K-band Kinetic Inductance Parametric Amplifier Near the Quantum Limit", "a": "Chaofan Wang, Shihan Liu, Yufeng Wu, Danqing Wang, Manuel C. C. Pace, Xiangzheng Li, Hong X. Tang", "d": "2026-06-09", "s": 68.6, "x": "A junction-free kinetic-inductance parametric amplifier (KIPA) in NbN thin film operates at 23 GHz in the K-band, achieving 40 dB gain, 100 MHz gain-bandwidth product, and added noise $\\leq 1.4$ quanta for phase-preserving amplification. The device demonstrates high saturation power of $-85$ dBm at 23 dB gain, enabling near-quantum-limited readout of millimeter-wave superconducting qubits and dark-matter searches at frequencies beyond conventional aluminum-based amplifiers."}, {"id": "2606.08453", "t": "A Dual Metastable-State Encoding Architecture for Quantum Processing with $^{171}\\mathrm{Yb}$ Atom Arrays", "a": "Chun-Wei Liu, Saiwei Nie, Eesha Banerjee, Micah Davidson, Nick Reynolds, Alyssa L. Miller, Alex P. Burgers", "d": "2026-06-09", "s": 55.6, "x": "This paper proposes a dual metastable-state qubit encoding in $^{171}\\mathrm{Yb}$ using the $(6s6p)\\,{}^3\\mathrm{P}_0$ and $(6s6p)\\,{}^3\\mathrm{P}_2$ manifolds to enable fast, mid-circuit quantum error correction in neutral-atom arrays. Through full master-equation simulations of gate operations and architectural resource estimation, the authors demonstrate that assigning the ${}^3\\mathrm{P}_2$ manifold (with $\\Delta_{\\mathrm{HF}} = 2\\pi \\times 6.7$ GHz) to QEC and ${}^3\\mathrm{P}_0$ to arithmetic logic reduces circuit overhead while maintaining fault-tolerant capabilities."}, {"id": "2606.06951", "t": "Contacting Josephson Junctions via Airbridges in Superconducting Circuits", "a": "Prakiran Baidya, Momčilo Milosavljević, Murali Krishna Kurmapu, Thomas Fösel, Harshanth Ram Murugesan, Victor Kemme, Mojahed Jaber, Markus Sondermann, Christopher Eichler", "d": "2026-06-08", "s": 95.1, "x": "This work demonstrates a single-step grayscale electron-beam lithography process for fabricating airbridges of varying sizes ($0.5$–$4$ µm width, $5$–$40$ µm length) that unify all electrical interconnects in superconducting circuits, eliminating the need for separate bandage contacts to Josephson junctions. Measured relaxation times exceeding $250$ µs in transmons and quality factors around $4 \times 10^5$ in CPW resonators show that airbridges provide high-quality contacts while substantially simplifying fabrication."}, {"id": "2606.07377", "t": "Coherent versus stochastic error injection on a repetition-code logical qubit in superconducting hardware", "a": "S. L. M. van der Meer, M. Serra-Peralta, Y. Xin, M. Finkel, H. M. Veen, M. W. Beekman, L. DiCarlo, B. M. Terhal", "d": "2026-06-08", "s": 93.6, "x": "This work experimentally investigates whether coherent and stochastic noise have different effects on quantum error correction using bitflip repetition codes on a transmon processor. Theory predicts a 1–2% coherent-stochastic gap in logical fidelity, but experiments on distance-3 and distance-5 codes find no observable difference, attributed to unmitigated qubit frequency drift that stochastifies injected coherent errors."}, {"id": "2606.06598", "t": "A superconducting surface-code processor with lattice-surgery logical operations", "a": "Yanzhe Wang, Fanhao Shen, Haipeng Xie, Aosai Zhang, Yu Gao, Chuanyu Zhang, Xuhao Zhu, Feitong Jin, Yiren Zou, Ning Wang, Zhengyi Cui, Zehang Bao, Zitian Zhu, Jiarun Zhong, Gongyu Liu, Jia-Nan Yang, Yihang Han, Yiyang He, Jiayuan Shen, Han Wang, Jiahua Huang, Xinrong Zhang, Sailang Zhou, Hang Dong, Jinfeng Deng, Yaozu Wu, Zixuan Song, Hekang Li, Zhen Wang, Chao Song, Qiujiang Guo, Pengfei Zhang, H. Wang, Ying Li", "d": "2026-06-08", "s": 92.8, "x": "This work demonstrates lattice-surgery operations between distance-three surface-code logical qubits on a 125-qubit superconducting processor, achieving per-cycle logical error rates of $0.0365(2)$ and $0.0282(1)$ for the two qubits. The authors realize deterministic Bell-state preparation, execute a two-qubit Deutsch-Jozsa algorithm at the logical level, and implement magic-state injection to achieve non-Clifford rotations with a logical $R_X(\\\\/4)$ gate fidelity of $0.943_{-9}^{+10}$."}, {"id": "2606.07339", "t": "Suppression of Quasiparticle Poisoning to $10^{-11}$ Levels in Superconducting Qubits via Infrared Shielding", "a": "Wei-En Lin, Chen-Hsun Ma, Erh-Hsiang Yeh, Wei-Lun Peng, Yu-Sen Wei, Hsi-Sheng Goan, Cen-Shawn Wu, Chung-Ting Ke, Yung-Fu Chen, Chii-Dong Chen", "d": "2026-06-08", "s": 86.5, "x": "This work demonstrates suppression of quasiparticle poisoning in superconducting transmon qubits to $x_{qp} = 1.88 \times 10^{-11}$ per Cooper pair using comprehensive infrared shielding with multi-layer copper/aluminum/mu-metal enclosures and proper thermalization to the mixing plate. The quasiparticle density is inferred from parity-switching rate measurements that decrease monotonically following cooldown and reach $0.069$ Hz by day 34, while initialization errors of $\thicksim 0.01\\%$ are achieved with qubits thermalized to $17$ mK."}, {"id": "2606.07140", "t": "Improved Cryogenic Photodiode Optical Biasing for Low-Noise and Low-Jitter Superconducting Nanowire Single-Photon Detectors", "a": "Jia-Hao Hu, Wei-Jun Zhang, Wen-Shuo Yu, Yu-Ze Wang, Dong-Wei Chu, Ya-Tao Peng, Hui-Qin Yu, Pu-Sheng Yuan, Ling Wu, Li-Xing You", "d": "2026-06-08", "s": 63.1, "x": "An improved optical biasing scheme for SNSPDs using a cryogenic InGaAs-InP photodiode as a local bias source is demonstrated, achieving performance comparable to electrical biasing with 80.7% system detection efficiency and 57.5 ps timing jitter. By screening stray photons from the photodiode, an ultra-low intrinsic dark count rate of $10^{-4}$ cps is obtained, establishing cryogenic-PD-based optical biasing as a viable low-noise alternative for all-photonic SNSPD systems."}, {"id": "2606.07699", "t": "Correlation-Assisted Odd-Parity Encoded Gates in Coupled Fluxonium Qubits under Non-Markovian TLS Noise", "a": "Chenghong Ji, Chaoying Zhao", "d": "2026-06-08", "s": 63.0, "x": "Odd-parity encoded logical gates in coupled fluxonium qubits benefit from spatially correlated longitudinal TLS noise, which converts harmful differential fluctuations into common-mode components. Projecting the two-qubit Hamiltonian onto the subspace $\\{|01\\rangle, |10\\rangle\\}$ yields logical $X_L$ and $Z_L$ rotations driven by exchange coupling and detuning, with encoded gate fidelity monotonically improving as noise correlation coefficient $\\rho$ increases."}, {"id": "2606.06455", "t": "Breakeven demonstration of quantum low-density parity-check codes", "a": "Edwin Tham, Michael L. Goldman, Shantanu Debnath, Ashay N. Patel, Jyothi Saraladevi, Jason Nguyen, Erik Nielsen, Neal Pisenti, Kenneth Wright, John Gamble, Nicolas Delfosse", "d": "2026-06-05", "s": 78.1, "x": "This work demonstrates breakeven quantum error correction with five distinct high-rate qLDPC codes on a 40-ion $^{133}$Ba trapped-ion system, achieving logical error rates $9\\times$ better than prior superconducting demonstrations and logical qubit lifetimes comparable to physical qubits ($3.95 \\pm 0.68$ s vs. $3.84 \\pm 0.48$ s). The key innovation is a full implementation of the optical-metastable-ground (OMG) architecture enabling mid-circuit measurement without ion transport or dedicated coolant ions, providing sufficient flexibility to implement three code families (qLDPC, topological, concatenated) with different connectivity requirements on a single device without reconfiguration."}, {"id": "2606.06069", "t": "Forbidden transitions in superconducting artificial atoms", "a": "Alberto Del Ángel, Théo Sépulcre, Ricardo Gutiérrez-Jáuregui, Anton Frisk Kockum", "d": "2026-06-05", "s": 70.5, "x": "This work develops a microscopic theory of Josephson junctions coupled to structured electromagnetic fields, going beyond lumped-circuit models by explicitly accounting for spatial and vectorial field profiles. As a key example, the authors demonstrate theoretically that a junction can be driven via a quadrupole transition—sensitive to field gradients rather than intensity—enabling excitation in regions where the electric field vanishes."}, {"id": "2606.06062", "t": "Barbell Codes: qLDPC Codes for Superconducting Quantum Hardware", "a": "Shin Ho Choe, Vincent Steffan, Florian Vigneau, Pedro Parrado-Rodríguez, Hsiang-Sheng Ku, Martin Leib, Francisco Revson Fernandes Pereira, Fedor Šimkovic", "d": "2026-06-05", "s": 65.6, "x": "Barbell codes are qLDPC codes designed for superconducting quantum processors using a six-qubit star lattice plus near-local coupler architecture, achieving up to 8× qubit overhead reduction compared to surface codes while maintaining constant hardware complexity with increasing code distance. Circuit-level noise simulations demonstrate that distance-14 barbell codes preserve information at physical error rates above $10^{-4}$ for several trillion QEC cycles, with logical error rates comparable to surface codes of the same distance."}, {"id": "2606.06152", "t": "2.4 GHz Flip-flop Device within Nonequilibrium Superconducting Diode", "a": "Xiangyu Bi, Hongyi Li, Aoshen Yang, Yuqiang Fang, Ganyu Chen, Shichong Yang, Yicheng Shen, Qizheng Sun, Junwei Huang, Wei Jiang, Da Wang, Fuqiang Huang, Haijun Zhang, Qianghua Wang, Hongtao Yuan", "d": "2026-06-05", "s": 56.1, "x": "A nonequilibrium Josephson junction in 2M-WS$_2$ van der Waals superconductor demonstrates polarity-controllable superconducting diode action with edge-triggered flip-flop operation up to 2.4 GHz. The device achieves 67% diode efficiency, on-off ratio exceeding $10^5$, and tunable pulse characteristics across 12 orders of magnitude frequency range via thickness-engineered inversion asymmetry."}, {"id": "2606.05815", "t": "Engineered dissipation for faster adiabatic state preparation", "a": "Yuanyang Zhou, Biao Wu", "d": "2026-06-05", "s": 55.7, "x": "Engineered dissipation using a filtered reservoir that induces downward transitions in the instantaneous energy eigenbasis while keeping the ground state dark can accelerate adiabatic state preparation. This directional cooling mechanism improves runtime scaling from $\\mathcal{O}(\\Delta^{-2})$ to $\\mathcal{O}(\\Delta^{-1})$ in the strong-relaxation regime, with finite-temperature thermal excitations introducing an error floor that is surmountable when heating remains below target tolerance."}, {"id": "2606.05010", "t": "Measurement-induced state transitions in multi-qubit transmon processors", "a": "Baptiste Hoyau, Alexander McDonald, Boris M. Varbanov, Manuel H. Muñoz-Arias, Alexandre Blais", "d": "2026-06-04", "s": 94.8, "x": "This work introduces a multimode Floquet branch analysis method to characterize measurement-induced state transitions (MIST) when a transmon qubit under dispersive readout is coupled to spectator modes in a quantum processor. The method reveals that spectator qubits and tunable couplers can dramatically alter MIST thresholds, with implications for readout fidelity in multi-qubit systems."}, {"id": "2606.04914", "t": "Tunable Resonator Integrated Magnetometry", "a": "Colin Stack, Brian Sears, Aruna Ramanayaka, David Ferguson, Ilya Sochnikov, Tony X. Zhou", "d": "2026-06-04", "s": 76.3, "x": "A tunable superconducting resonator (tRes) integrated magnetometer combines the fast readout of an LC circuit with SQUID-level flux sensitivity for cryogenic magnetometry at MHz sampling rates. The device demonstrates quantum non-demolition measurement characteristics and operates across three circuit topologies of increasing complexity at milli-kelvin temperatures."}, {"id": "2606.04629", "t": "Circuit-Level Noise Estimation via Shuttling in Plaquette Circuits", "a": "Huyen Do, Alexandru Paler", "d": "2026-06-04", "s": 51.5, "x": "This paper presents a method to estimate circuit-level noise for surface-code QEC by analyzing repeated plaquette measurements under two ancilla strategies: FRESH (fresh syndrome qubits per round) and RECYCLE (reused syndrome qubit). The approach extracts effective plaquette error rates, idle errors, and time-correlated errors from single-shot measurement statistics without requiring access to low-level gate calibrations."}, {"id": "2606.03815", "t": "A Tutorial for Characterizing Transmon Qubits", "a": "Alexandre M. Souza, Davi A. D. Chaves, Carmem M. Gilardoni, Roberto S. Sarthour, João P. Sinnecker, Ivan S. Oliveira", "d": "2026-06-03", "s": 95.1, "x": "This tutorial presents a comprehensive experimental workflow for characterizing and calibrating tunable transmon qubits, demonstrated on a commercial five-qubit Soprano-D2 processor in a dilution refrigerator. The paper details procedures from cryogenic setup through parametric amplifier optimization, flux sweet-spot identification, pulse calibration, readout optimization, and qubit-qubit coupling characterization, with emphasis on practical considerations and expected parameter ranges."}, {"id": "2606.03897", "t": "Parametrically induced strong coupling between a superconducting quantum circuit and a solid-state spin ensemble", "a": "Alejandro E. Baptista, Jinwoong Kim, Sonia Rani, Xi Cao, Wolfgang Pfaff", "d": "2026-06-03", "s": 86.5, "x": "Dynamically controlled strong coupling between a superconducting SNAIL coupler and a rare-earth spin ensemble ($\\mathrm{Yb}^{171}_{3+}$:YSO) was demonstrated using parametric pumping, achieving MHz-scale on-demand coupling to enable quantum state transfer. Simulations predict $\\geq 98\\%$ fidelity single-excitation swaps in $\\sim 200$ ns, paving the way for hybrid quantum memories with coherence times ($\\sim 10$ ms for spins versus $\\sim 1$ ms for superconducting qubits) surpassing circuit-alone storage."}, {"id": "2606.04079", "t": "Quantum error correction with the toric code", "a": "Atom Computing, Collaborators", "d": "2026-06-03", "s": 85.2, "x": "This work demonstrates repeated syndrome extraction cycles in a twisted toric code using tweezer-trapped $^{171}$Yb atoms, with mid-circuit measurement, qubit reloading from a MOT, and role-swapping to mitigate heating and loss. Up to 90 syndrome extraction cycles are performed with detector probability maintained at constant baseline $\\approx 0.2$, and logical information outlasts physical qubit lifetimes of $\\sim 10$ s by more than 200× when encoded in distance-7 repetition codes."}, {"id": "2606.02761", "t": "Superconducting Qubits with Altermagnetic Josephson Junctions", "a": "Johanne Bratland Tjernshaugen, Morten Amundsen, Jacob Linder", "d": "2026-06-03", "s": 72.9, "x": "This work demonstrates through microscopic calculations that altermagnetic Josephson junctions enable superconducting qubits with simultaneously enhanced protection against decoherence and improved anharmonicity, operating near $0$–$\\pi$ transitions or $\\phi$-states. The qubit performance is tunable via the Néel field strength and crystallographic orientation, with strain-engineered modulation proposed to dynamically balance protection and gate speed."}, {"id": "2606.02715", "t": "Trapping 11,000 Atoms in a Tweezer Array Generated by a Single Metasurface", "a": "Yuqing Wang, Zhongchi Zhang, Tao Zhang, Yuxuan Liao, Hanteng Wang, Ye Tian, Binjie Ji, Yujia Wu, Luming Ma, Chen Qing, Chengshu Li, Wei Zhang, Yidong Huang, Wenjun Zhang, Xue Feng, Wenlan Chen, Hui Zhai", "d": "2026-06-03", "s": 63.2, "x": "A 19.8 mm diameter silicon-nitride metasurface generates an 18,225-site optical tweezer array that traps 11,022 ± 167 $^{87}$Rb atoms with 60.5% filling fraction, reaching the tens-of-thousands-qubit scale for the first time across all platforms. The metasurface is positioned 1.5 cm outside the vacuum cell, eliminating the need for microscope objectives and achieving superior power efficiency (0.823 mW per tweezer, 12.2 W total diffraction power) compared to conventional SLM and AOD approaches."}, {"id": "2606.03916", "t": "Practical gates by Majorana fermion motion", "a": "Yuri D. Lensky, Bryce Kobrin, Kostyantyn Kechedzhi, Igor Aleiner", "d": "2026-06-03", "s": 51.8, "x": "This work develops a macroscopic description of 2D Pauli stabilizer codes and fault-tolerant logical operations using Majorana fermion motion, showing that braiding-based gates achieve lower space overhead than lattice surgery for near-term error rates. The framework captures code properties from lattice scales to asymptotic regimes, enabling compact design of fault-tolerant 2-qubit Clifford gates."}, {"id": "2606.03884", "t": "20 Second Parity Lifetime in an InAs--Pb Tetron Device", "a": "Morteza Aghaee, Zulfi Alam, Mariusz Andrzejczuk, Andrey Antipov, Theodora Asimakidis, Mikhail Astafev, Lukas Avilovas, Ahmad Azizimanesh, Amin Barzegar, Bela Bauer, Jonathan Becker, Umesh Kumar Bhaskar, Andrea G. Boa, Srini Boddapati, Nichlaus Bohac, Jouri Bommer, Jan Borovsky, Léo Bourdet, Samuel Boutin, Srivatsa Chakravarthi, Benjamin J. Chapman, Nikolaos Chatzaras, Tzu-Chiao Chien, Jason Cho, Patrick T. Codd, William Cole, Paul W. Cooper, Fabiano Corsetti, Ajuan Cui, Tareq El Dandachi, Konstantinos Divanis, Clayton Doyle, Andreas Ekefjard, Javier A. Falcon, Saeed Fallahi, Luca Galletti, Geoffrey C. Gardner, Haris Gavranovic, João Pedro Morais Gomes, Deshan Govender, Flavio Griggio, Ruben Grigoryan, Sebastian Grijalva, Sergei Gronin, Jan Gukelberger, Marzie Hamdast, Esben Bork Hansen, Sebastian Heedt, Samantha Ho, Laurens Holgaard, Kevin van Hoogdalem, Jinnapat Indrapiromkul, Henrik Ingerslev, Lovro Ivancevic, Max Jantos, Thomas Jensen, Jaspreet Singh Jhoja, Vidul R. Joshi, Konstantin V. Kalashnikov, Ray Kallaher, Rachpon Kalra, Farhad Karimi, Torsten Karzig, Maren Elisabeth Kloster, Christina Knapp, Jonathan Knoblauch, Jonne Koski, Anders Kringhøj, Tom Laeven, Jeffrey Lai, Gijs de Lange, Thorvald W. Larsen, Kyunghoon Lee, Kongyi Li, Shuang Liang, Tyler Lindemann, Luna Lochmatter, Marijn Lucas, Roman Lutchyn, Morten Hannibal Madsen, Nasiari Madulid, Ivan Maliyov, Yanick Mampaey, Michael Manfra, Signe Brynold Markussen, Esteban A. Martinez, J. R. Mattinson, Mónica Meira, Camille A. Mikolas, Sarang Mittal, Gopakumar Mohandas, Christian Mollgaard, Michiel W. A. de Moor, Chris Moore, George Moussa, Bhargav Nabar, Anirudh Narla, Ahmad Naseri, Chetan Nayak, Bjørn Funch Schrøder Nielsen, Jens Hedegaard Nielsen, Michael J. Nystrom, Eoin O'Farrell, Keita Ohtani, Theodore Rex Orth, Sara Di Paolo, Camille Papon, Luca Petit, Dima Pikulin, Mohana Rajpalke, Alejandro Alcaraz Ramirez, Katrine Rasmussen, David Razmadze, Yuan Ren, Mariya Romanova, Loïc Roure, Ivan Sadovskyy, Lauri Sainiemi, Juan Carlos Estrada Saldaña, Irene Sanlorenzo, Tatiane Pereira dos Santos, Carl Vincent C. Saruda, Simon Schaal, John Schack, Emma R. Schmidgall, Christina Sfetsou, Cristina Sfiligoj, Zahra Shekason, Sarat Shankar Sinha, Patrick Sohr, Maria João Lourenço de Sousa, Kasper Roed Spiegelhauer, Tomas Stankevic, Henri J. Suominen, Judith Suter, Attila Szénási, Samuel M. L. Teicher, Naganivetha Thiyagarajah, Raj Tholapi, Mason Thomas, Dennis Tom, Emily Toomey, Joshua Tracy, Michelle Turley, Matthew D. Turner, Ivan Urban, Aakash Valliappan, Dmitrii V. Viazmitinov, Anna Wulff Viazmitinova, Dominik Johannes Vogel, Wenbo Wang, Christopher A. Watson, John Watson, Alex Webster, Joseph Weston, Timothy Williamson, Georg W. Winkler, David J. van Woerkom, Brian Paquelet Wuetz, Cécile X. Yu, Emrah Yucelen, Jesús Herranz Zamorano, Roland Zeisel, Guoji Zheng, A. M. Zimmerman", "d": "2026-06-03", "s": 51.7, "x": "This work demonstrates parity lifetimes exceeding 20 s in InAs–Pb tetron devices via interferometric readout, representing a $>1000\times$ improvement over Al-based tetrons and validating that larger superconducting gap directly suppresses quasiparticle poisoning errors. The authors introduce rf-based wire spectroscopy to measure Majorana splitting $E_M < 1$ µeV with $μ$eV precision and identify operating regimes where both Majorana hybridization and non-equilibrium poisoning are strongly suppressed."}, {"id": "2606.03891", "t": "Efficient Quantum Error Mitigation for Unitary k-Designs", "a": "Ayush Pancholy, K. Birgitta Whaley", "d": "2026-06-03", "s": 50.0, "x": "This paper introduces circuit balancing and depolarizing parameter estimation techniques to mitigate two-qubit gate errors in unitary $k$-design circuits without two-qubit gate overhead. The method leverages the uniform Pauli support distribution of such circuits, combined with gate benchmarking data and Pauli twirling to suppress coherent error, achieving over 92% Hellinger distance reduction in simulations and doubling the Loschmidt echo survival probability on IBM Fez."}, {"id": "2606.02440", "t": "Microwave Crosstalk in Planar Superconducting Quantum Devices", "a": "Yongxin Song, Dominic Hagmann, Kieran Dalton, Felix Henrich, Felix Wagner, Mohsen Bahrami Panah, Marek Pechal, Andreas Wallraff", "d": "2026-06-02", "s": 95.9, "x": "This work systematically identifies and quantitatively models two dominant microwave crosstalk mechanisms in planar superconducting quantum devices: proximity-induced crosstalk from drive lines routed near qubits, and crossover-induced crosstalk from drive lines crossing qubit-qubit couplers via air bridges. Electrostatic and RF finite-element simulations combined with experimental measurements on test structures and a 17-qubit processor establish predictive models showing that package-mediated coupling decays as $-2.7$ dB/mm (much slower than direct capacitance at $-26$ dB/mm), imposing stringent layout constraints on scaling."}, {"id": "2606.00473", "t": "Accelerating Surface Radiation Content to Investigate the Impact of Radon Progeny on Superconducting Qubits", "a": "Sagar S. Poudel, Dylan J. Temples, Ryan Linehan, Alejandro Rodriguez, Matthew Hall, Dax Kay, Nathaniel Rodenburg, Daniel Baxter, Enectali Figueroa-Feliciano, Richard W. Schnee, Lauren Hsu", "d": "2026-06-02", "s": 85.0, "x": "This work develops an accelerated radon daughter plateout facility that enhances deposition rates by $7 \\times 10^4$ relative to ambient conditions, enabling in situ studies of $^{222}$Rn progeny impacts on superconducting qubits. Simulations and measurements show that $^{210}$Po surface activity from radon plateout can contribute high-energy $\\alpha$-decays ($\\approx 5.3$ MeV) at rates comparable to cosmic-ray protons in surface labs, and becomes dominant in shielded underground operation."}, {"id": "2606.01647", "t": "Extensible Fluxonium Architecture Using Tunable Couplers with Low Shunt Capacitance", "a": "Peng Zhao, Peng Xu, Zheng-Yuan Xue", "d": "2026-06-02", "s": 76.7, "x": "This work proposes an extensible 2D architecture for scaling fluxonium qubits using low-shunt-capacitance tunable couplers based on generalized flux-qubit circuits (quarton and fluxonium designs). The architecture addresses the capacitance loading problem by achieving coupling strengths $\\sim250$–$500$ MHz with coupling capacitances $C_{qt} \\approx 1.7$–$5.5$ fF (versus $3.5$–$12.2$ fF for transmon-based designs), enabling multiple connections in 2D grids while maintaining tunable control of plasmon interactions and suppression of spectator errors."}, {"id": "2606.01226", "t": "Realizing leakage elimination operator-based adiabatic speedup on a superconducting quantum processor", "a": "Jia-Yi Fan, Kai-Yu Yuan, Zong-Yuan Ge, Feng-Hua Ren, Zhao-Ming Wang", "d": "2026-06-02", "s": 66.4, "x": "This work demonstrates leakage elimination operator (LEO)-based adiabatic speedup on IBM superconducting quantum processors, achieving fidelities of $\\sim 0.96$ at short evolution times ($T_{\\mathrm{tot}} = \\pi/2$) compared to $\\sim 0.6$ without control. The results validate the feasibility of using ideal zero-area rectangular LEO pulses for accelerating adiabatic quantum computation while mitigating noise accumulation."}, {"id": "2606.00358", "t": "Software compensation of trigger-synchronous control-frame errors in qubits and qudits", "a": "Gaurav A. Tathed, Nicholas C. F. Zutt, Collin J. C. Epstein, Crystal Senko", "d": "2026-06-02", "s": 65.0, "x": "This work demonstrates software compensation of trigger-synchronous coherent errors in trapped-ion qubits and qudits by measuring AC mains-induced magnetic-field perturbations and updating control pulse frequencies and phases to track instantaneous transition frequencies. The compensation reduces AC line-induced detuning by $21(9)\\times$ and phase amplitude below measurement uncertainty, recovers single-qubit gate fidelity of $99.93(1)\\%$ in randomized benchmarking, and improves Bernstein–Vazirani success probability from $10(7)\\%$ to $70(9)\\%$ in a 16-level system."}, {"id": "2606.00433", "t": "Learning Mid-circuit Measurement Backaction from Three Repeated Measurements", "a": "Chia-Tung Chu, Su-un Lee, Han Zheng, Senrui Chen, Bibek Pokharel, Alireza Seif, Liang Jiang", "d": "2026-06-02", "s": 60.5, "x": "This paper introduces an efficient protocol for learning single-qubit mid-circuit measurement (MCM) instruments on superconducting qubits by measuring readout-backaction correlations from three repeated MCMs on a maximally mixed input. The learned instrument, which is $Z$-twirled to eliminate coherences while preserving joint classical-outcome and post-measurement-state statistics, improves Pauli-observable prediction by $\\sim 100\\times$ over confusion-matrix models on IBM Heron transmons and reveals $T_1$-decay-dominated backaction with $\\eta_{\\downarrow} \\gg \\eta_{\\uparrow}$ ($10^1$--$10^2$ asymmetry)."}, {"id": "2605.30425", "t": "Dually tunable YBCO coplanar waveguide resonators based on helium-ion-generated Josephson inductances", "a": "Kenny Fohmann, Timo J. Glebe-Märklin, Benedikt Wilde, Mohamad Kazouini, Christoph Schmid, Dieter Koelle, Reinhold Kleiner, Daniel Bothner", "d": "2026-06-01", "s": 86.1, "x": "YBCO coplanar waveguide cavities integrated with helium-ion-generated Josephson junctions exhibit GHz-range flux tunability via periodic SQUID oscillations overlaid with Fraunhofer-like single-junction modulation due to out-of-plane junction barriers. The devices operate up to 14 K with junction-induced quality factors of $Q_{J0} \\sim 200$–$700$, enabling independent tuning of resonance frequency and flux responsivity."}, {"id": "2605.31185", "t": "Fast coherent control of a charge qubit on solid neon with a spin-qubit-compatible resonator", "a": "Jun Wang, Yiran Tian, Ivan Grytsenko, Asher Jennings, Beatriz Pérez González, Xianjing Zhou, Hirotaka Terai, Dafei Jin, Monica Benito, Erika Kawakami", "d": "2026-06-01", "s": 71.7, "x": "A single electron trapped on solid neon is coupled to a superconducting NbTiN nanowire resonator to realize a charge qubit with coherent microwave control at Rabi frequencies up to 76 MHz, an order of magnitude higher than previous work. The electron position is inferred from coupling strengths to multiple electrodes, and despite non-optimal trapping due to neon surface roughness, spin-qubit fidelities up to 99.995% are estimated to be achievable with integrated ferromagnets."}, {"id": "2605.30455", "t": "A Denser Planar Surface Code", "a": "Guang Hao Low, William J. Huggins, Dominic W. Berry, Tanuj Khattar, Alec F. White, Nicholas C. Rubin, Ryan Babbush", "d": "2026-06-01", "s": 62.9, "x": "This work demonstrates a surface code implementation on a regular 2D hexagonal lattice achieving up to 4.5× the encoding rate of a rotated surface code patch by dense packing of twist defects with optimal 6-layer stabilizer measurement and no distance-reducing hook errors. Applied to chemically accurate ground state energy estimation of utility-scale molecules like the 108-spin-orbital FeMoco nitrogen fixation catalyst, the approach enables solution in under a month using only 89 k noisy qubits at $10^{-3}$ error rate, representing 36× space and 6.6× spacetime improvement over prior Toffoli-minimized designs."}, {"id": "2605.30765", "t": "Real-Time Quantum Error Correction System Stack: Architecture, Algorithms, and Engineering Practice", "a": "Yaojian Chen, Chun-Yang Luan, Peilin Zheng, Xianghong Zeng, Jia-Yi Hou, Zhuo Fu, Yirong Jin, Fei Wang, Guangwen Yang, Dingshun Lv", "d": "2026-06-01", "s": 50.5, "x": "This white paper analyzes real-time quantum error correction as a systems engineering problem, proposing a six-layer reference architecture from syndrome acquisition to logical operations and benchmarking major decoders (MWPM, Union-Find, BP+OSD, neural networks) across surface codes and qLDPC codes. The work quantifies the gap between current decoder performance and real-time requirements: MWPM meets the 1 μs per-round deadline for superconducting platforms only at $d \\leq 7$ in batch mode, while window-mode decoding is 2–4× more expensive, and GPU-accelerated BP+OSD sustains <1 ms per round for $[\\![288,12,18]\\!]$ qLDPC codes."}, {"id": "2605.30217", "t": "Programmable Dissipation via Partial Quantum Error Correction", "a": "Sameer Dambal, Michael AD Taylor, Yu Zhang", "d": "2026-05-29", "s": 65.3, "x": "This work shows that quantum error correction (QEC) cycles can be repurposed to programmably synthesize target dissipative dynamics at the logical level by treating the syndrome-averaged channel as a CPTP map and randomizing recovery operations. The framework enables resource-efficient simulation of open quantum systems on fault-tolerant devices through convex mixtures of implementable logical channels, avoiding explicit bath registers needed by dilation-based approaches."}, {"id": "2605.29514", "t": "Non-Clifford Crosstalk Noise in Surface Codes Using Hybrid Stabilizer-Tensor Network Methods", "a": "Ben Harper, Azar C. Nakhl, Martin Sevior, Muhammad Usman", "d": "2026-05-29", "s": 54.7, "x": "This work uses hybrid stabilizer-tensor network methods to simulate coherent crosstalk noise during syndrome extraction in surface codes, capturing non-Clifford noise dynamics inaccessible to previous classical simulations. The inclusion of coherence in the noise model increases logical error rates and lowers the code threshold compared to incoherent-only models."}, {"id": "2605.28536", "t": "Trapped-Ion Multiqubit Gates are Compatible with Scalable Quantum Error Correction", "a": "Ori Grossman, Yotam Kadish, Snir Gazit, Amit Ben-Kish, Roee Ozeri, Yotam Shapira", "d": "2026-05-28", "s": 78.9, "x": "This work develops a microscopic noise model for multiqubit gates in trapped-ion systems by deriving effective single- and two-qubit error channels from phonon heating, motional dephasing, and photon scattering. The analysis shows that scattering errors and two-qubit errors from dephasing are largely confined to gate-coupled qubits, and demonstrates a finite threshold for surface-code error correction with physically realistic error rates."}, {"id": "2605.28808", "t": "Device-Agnostic Microwave Noise Metrology for Nonlinear Cryogenic Quantum Devices", "a": "Andrea Celotto, Alessandro Alocco, Bernardo Galvano, Luca Fasolo, Emanuele Palumbo, Luca Callegaro, Luca Oberto, Patrizia Livreri, Emanuele Enrico", "d": "2026-05-28", "s": 69.8, "x": "This paper presents a device-agnostic in situ noise metrology protocol for cryogenic microwave quantum devices that combines Planck spectroscopy using a Variable Temperature Stage with Short-Open-Load-Reciprocal S-parameter calibration, ensuring both noise and scattering measurements refer to the same cryogenic reference planes. The protocol avoids embedding the DUT's nonlinear model into readout-chain calibration by substituting the noise source for the DUT, and is demonstrated on a Josephson Traveling Wave Parametric Amplifier under multimode nonlinear conditions."}, {"id": "2605.28342", "t": "Low-cost quantum error mitigation via auxiliary qubit return validation", "a": "Gilad Kishony, Avi Elazari, Ron Cohen, Lior Gazit", "d": "2026-05-28", "s": 64.6, "x": "This work introduces a post-selection error mitigation technique that measures auxiliary qubits at circuit points where they are expected to return to the $|0\\rangle$ state; shots with measurement outcomes inconsistent with the zero state are rejected based on a likelihood model accounting for gate and measurement noise. Simulations on arithmetic circuits compiled by the Classiq platform show a $\\sim 10\\%$ reduction in false-negative rate while discarding only $\\sim 1\\%$ of valid shots."}, {"id": "2605.28759", "t": "Absolute measurement of penetration depth of superconducting thin films using microwave stripline resonators", "a": "Arghya Dutta, Ajeet Salunke, Mahesh Poojary, Vivas Bagwe, Sangita Bose, Pratap Raychaudhuri", "d": "2026-05-28", "s": 62.4, "x": "A hybrid method combining microwave stripline resonator measurements with COMSOL finite-element simulations is developed to extract absolute penetration depth values from superconducting thin films over wide temperature ranges. The technique is demonstrated on NbN films using variable thicknesses and extended to lower-$T_c$ materials via a flip-film geometry with a NbN resonator separated by Mylar dielectric."}, {"id": "2605.26528", "t": "Crosstalk In Contemporary Quantum Devices", "a": "Spiro Gicev, Ben Harper, Haiyue Kang, Muhammad Usman, Martin Sevior", "d": "2026-05-27", "s": 63.8, "x": "This comprehensive review surveys crosstalk phenomena across six major quantum computing platforms—superconducting circuits, trapped ions, neutral atoms, photonics, semiconductors, and nitrogen vacancy centres—examining physical origins, characterization methods, and mitigation strategies. The authors document platform-specific crosstalk mechanisms (always-on $ZZ$ interactions in superconductors, pulse spillover in trapped ions, frequency crowding in semiconductors) and discuss security vulnerabilities enabling adversarial attacks and information leakage in multi-tenant quantum processors."}, {"id": "2605.25948", "t": "Unified Flux Control Architecture for Fluxonium Qubits", "a": "Xianchuang Pan, Jiahui Wang, Tao Zhou, Yanbo Guo, Fei Wang, Ze Zhan, Liang Xiang, Zishuo Li, Lu Ma, Xizheng Ma, Huijuan Zhan, Tao Zhang, Kannan Lu, Xing Zhu, Guicheng Gong, Chunqing Deng, Tenghui Wang", "d": "2026-05-26", "s": 90.3, "x": "This work demonstrates a unified flux control architecture for fluxonium qubits that consolidates both transverse ($XY$) and longitudinal ($Z$) operations into a single flux-control channel, reducing hardware overhead compared to conventional multi-channel approaches. High-fidelity operation is achieved through frequency-selective cryogenic filtering combined with compensated waveform synthesis and instruction-level FPGA-native synthesis."}, {"id": "2605.24262", "t": "Quantum non-demolition measurements as a practical primitive for fault-tolerant computation against biased noise", "a": "Christophe Vuillot, Diego Ruiz, Jérémie Guillaud, Mazyar Mirrahimi", "d": "2026-05-26", "s": 82.4, "x": "High-fidelity quantum non-demolition (QND) multi-qubit Pauli $Z$ measurements provide a practical alternative to bias-preserving CNOT gates for fault-tolerant computation with phase-flip-dominant noise, working universally across all qubit platforms including two-dimensional systems. Circuit-level simulations show that asymmetric XZZX surface codes with weight-four QND $Z$ measurements achieve a phase-flip threshold of $\\sim\\!1.25\\%$ and up to $6\\times$ qubit overhead reduction compared to bias-unaware codes at $\\eta = 10^4$, while repetition codes reach $\\sim\\!2.3\\%$ threshold with overhead comparable to bias-preserving CNOT schemes."}, {"id": "2605.24522", "t": "Synchronization of Bloch Oscillations in array of parallel Josephson Junctions", "a": "R. Shaikhaidarov, R. Hussain, V. N. Antonov, E. Il'ichev", "d": "2026-05-26", "s": 58.7, "x": "Synchronization of Bloch oscillations in a parallel array of 69 Al/AlOx/Al Josephson junctions in the coherent quantum phase slip regime yields a quantized current step at $I_1 = 426$ nA under 19.325 GHz microwave excitation, exceeding previous single-junction demonstrations. The quantization accuracy does not degrade with array scaling, though thermal noise in screening resistors limits plateau flatness to $\neq 1$ ppm, preventing metrological acceptance."}, {"id": "2605.24501", "t": "Performance Limits of Fault-Tolerant Quantum Error Correction Schemes", "a": "Lorenzo Valentini, Diego Forlivesi, Marco Chiani", "d": "2026-05-26", "s": 57.8, "x": "This paper derives analytical upper and lower bounds on the failure probability of Shor-style fault-tolerant quantum error correction (FT-QEC) schemes under depolarizing noise, explicitly accounting for faulty gates and measurements. The analysis separates two failure mechanisms: decoding errors (when the decoder fails to correct) and residual errors (undetected errors from the FT circuit itself that escape a single syndrome extraction round)."}, {"id": "2605.25830", "t": "Utility-scale quantum experiments using dynamic circuits to address collective dissipation in interacting qubits", "a": "Benjamin Tirado, Joana Fraxanet, Adrián Juan-Delgado, Javier Aizpurua, Ruben Esteban", "d": "2026-05-26", "s": 52.2, "x": "This work demonstrates utility-scale quantum simulation of Markovian dissipative dynamics with collective decay channels on up to 86 emitters (129 total qubits including ancillas) using the IBM Heron processor. The approach combines ancilla-assisted circuit implementations, dynamic circuits with mid-circuit measurements, biased Clifford data regression error mitigation, and Monte Carlo tensor-network validation to reproduce open quantum system evolution beyond classical tractability."}, {"id": "2605.23385", "t": "Non-Local and Non-Markovian Effects of a Microscopic Two-Level Defect in Superconducting Quantum Circuits", "a": "Yang Gao, Yujia Zhang, Huikai Xu, Pan Shi, Feiyu Li, Yaqing Feng, Weijie Sun, Jiayu Ding, Yang Liu, He Wang, Ruixia Wang, Zhen Yang, Yirong Jin, Haifeng Yu, Fei Yan", "d": "2026-05-25", "s": 90.7, "x": "A coherent two-level system (TLS) residing in a tunable coupler is observed to couple simultaneously to two spatially distant superconducting qubits, enabling controllable TLS-qubit coupling via coupler frequency detuning. The work reconstructs the TLS dephasing noise spectrum over ten decades (0.1 mHz–1 MHz) revealing discrete fluctuator signatures and demonstrates non-Markovian dynamics, correlated two-qubit evolution, and quantifies iSWAP gate error penalties reaching order-unity degradation at strong coupling."}, {"id": "2605.21662", "t": "Fidelity-Aware Frequency Allocation and Transpilation Co-Design for Tunable Coupler Quantum Systems", "a": "Dylan VanAllen, Evan McKinney, Israa G. Yusuf, Girgis Falstin, Gaurav Agarwal, Jason Pollack, Michael Hatridge, Alex K. Jones", "d": "2026-05-22", "s": 85.7, "x": "This paper presents a co-design framework connecting frequency allocation in SNAIL-based tunable-coupler systems to fidelity-aware circuit transpilation, introducing an error budgeting model that captures both spectator-induced coherent errors and $T_1$-limited incoherent losses. The work demonstrates that frequency crowding fundamentally limits module size to ~4 qubits while achieving >0.99 fidelity, and develops FINESSE, a noise-aware transpiler that achieves 8.9% reduction in log-infidelity cost over SABRE on SNAIL architectures."}, {"id": "2605.21898", "t": "Concatenating Algebraic Codes over High-Rate Quantum LDPC Codes", "a": "Adam Wills, Michael E. Beverland, Lev S. Bishop, Jay M. Gambetta, Patrick Rall, Vikesh Siddhu, Andrew W. Cross", "d": "2026-05-22", "s": 71.2, "x": "This paper concatenates quantum Reed–Solomon codes with large-alphabet Galois qudits ($q = 2048$) as outer codes over the 144-qubit gross bivariate bicycle code as inner code, reaching the teraquop regime (logical error rates $10^{-14}$–$10^{-13}$ per logical qubit-round) at uniform physical noise $p = 10^{-3}$ with lower space overhead than the 288-qubit two-gross code down to $4.1 \\times 10^{-15}$ per logical qubit-round. The construction introduces spacetime error mixing to handle unknown logical error distributions of the inner code and demonstrates fault-tolerant syndrome extraction via Galois qudit Shor schemes with time-like Reed–Solomon codes protecting measurement errors."}, {"id": "2605.20652", "t": "WSi weak link element with a non-sinusoidal current-phase relation", "a": "Sarah Garcia Jones, Trevyn F. Q. Larson, Sai Pavan Chitta, Heli Vora, Varun Verma, Sae Woo Nam, José Aumentado, Jens Koch, Raymond W. Simmonds, András Gyenis", "d": "2026-05-21", "s": 66.0, "x": "Tungsten silicide nanowires embedded in an RF-SQUID exhibit nonlinear behavior consistent with a Josephson junction having a sawtooth-like current-phase relation or a quantum phase slip element. Time-domain measurements reveal relaxation times exceeding one hour for metastable persistent-current states trapped in potential minima."}, {"id": "2605.19590", "t": "Photolithography-Only Fabrication of Transmons Using Double-Oblique Evaporation", "a": "K. Aoyanagi, S. Abe, S. Chen, T. Inada, C. Kawai, Y. Mino, K. Nakamura, K. Nakazono, T. Nitta, K. Watanabe", "d": "2026-05-20", "s": 78.2, "x": "This work demonstrates photolithography-only fabrication of transmon Josephson junctions using double-oblique Al shadow evaporation, achieving a geometrical junction area of ~$10^4$ nm$^2$ well below the ~1 µm optical linewidth. The fabricated junctions are characterized at room temperature and integrated into a 3D cavity qubit at 20 mK, demonstrating functional transmon operation with $f_{01} = 4.865$ GHz, $T_1 \thicksim 9$ µs, and $T_2^* \thicksim 0.4$ µs."}, {"id": "2605.19854", "t": "Unveiling Energetic Advantage in Superconducting Cat-Qubits Quantum Computation", "a": "Pedro Ramos, Marco Pezzutto, Yasser Omar", "d": "2026-05-20", "s": 78.2, "x": "This paper analyzes the energy consumption of the Semiclassical Quantum Fourier Transform on superconducting cat-qubit platforms, incorporating quantum error correction and comparing with classical FFT implementations. A quantum energetic advantage is found for systems with more than 26 logical qubits at the macroscopic level, arising before computational advantage and persisting with realistic cryogenic overhead."}, {"id": "2605.18962", "t": "Scalable Single-Step Generation of W States in 2D Superconducting Qubit Lattices", "a": "João H. Romeiro, Federico A. Roy, Niklas Bruckmoser, Ivan Tsitsilin, Niklas J. Glaser, Christian M. F. Schneider, Gerhard B. P. Huber, Saya A. Schöbe, Johannes Schirk, Florian Wallner, Malay Singh, Julius Feigl, Leon Koch, Lasse Södergren, Max Werninghaus, Stefan Filipp", "d": "2026-05-20", "s": 74.7, "x": "This work demonstrates single-step generation of W states in superconducting qubit lattices by engineering time-independent Hamiltonians that coherently distribute a single excitation across arbitrary geometries. In 2D lattices, simultaneous propagation along multiple directions reduces entanglement time to scale with the largest dimension, enabling a six-qubit W state with 83.9±1.0% fidelity in 99 ns on a 3×2 array and a seven-qubit W state with 79.6±1.3% fidelity in 264 ns."}, {"id": "2605.19471", "t": "Efficient Fault-Tolerant Ancilla Preparation for Quantum BCH codes via Cyclic Symmetry", "a": "Kohei Yamamoto, Keisuke Fujii", "d": "2026-05-20", "s": 54.2, "x": "This paper presents an efficient fault-tolerant ancilla preparation method for quantum BCH codes by leveraging their cyclic symmetry to optimize entanglement-distillation protocols. The approach reduces required ancilla qubits by more than half compared to standard distillation while achieving lower logical error rates, with threshold analysis demonstrating code rates 2–4× higher than the Steane code at comparable distances."}, {"id": "2605.18658", "t": "Universal Jaynes-Cummings Control of an Oscillator", "a": "Jordan Huang, Ethan Kasaba, Thomas J. DiNapoli, Tanay Roy, Srivatsan Chakram", "d": "2026-05-19", "s": 85.2, "x": "This work demonstrates universal control of a superconducting cavity mode using Jaynes-Cummings (JC) interactions between the cavity and a transmon ancilla, achieving a mean post-selected process fidelity of 96.3% for qutrit gates with leakage errors suppressed by construction. The JC interaction is realized via sideband drives on the transmon, and the dispersive shift is exploited as a compilation resource to reduce circuit depth from $\\mathcal{O}(d^2)$ layers without detuning optimization to lower effective depths for high-dimensional qudits."}, {"id": "2605.16559", "t": "Measurement and Control of the Complex Berry Phase in a Quantum System", "a": "Pratik J. Barge, Qian Cao, Niklas Hörnedal, Aurélia Chenu, Kater W. Murch", "d": "2026-05-19", "s": 72.1, "x": "This work reports experimental measurement of both real and imaginary components of the Berry phase in a superconducting transmon circuit with engineered dissipation, realizing a non-Hermitian two-level system through postselection on no-jump trajectories. The imaginary Berry phase arises from state-dependent amplification or attenuation during adiabatic evolution and enables non-unitary geometric quantum control."}, {"id": "2605.17824", "t": "Cryogenic Time-Division-Multiplexed Voltage Control for Scalable Trapped-Ion Quantum Processors", "a": "Ryutaro Ohira, Shinichi Morisaka, Yoshinori Kurimoto, Toshiaki Inada, Ippei Nakamura, Takefumi Miyoshi, Atsushi Noguchi", "d": "2026-05-19", "s": 64.8, "x": "This work demonstrates cryogenic time-division-multiplexed (TDM) voltage control for trapped-ion quantum processors, implementing a 32-channel static-electrode demultiplexer at 27 K with 37.5 kHz update rate and a four-channel dynamic-electrode demultiplexer at 14 K with 1 MHz update rate, both operating over $\\pm 10$ V. The results validate TDM as a practical approach to mitigate the vacuum feedthrough bottleneck in scalable quantum-charge-coupled-device (QCCD) architectures, reducing required feedthrough connections from 32 to 8 for the static system."}, {"id": "2605.17457", "t": "Quantum Error Correction Assisted Axion Search in CMOS Spin Qubit Arrays", "a": "Xiangjun Tan, Zhanning Wang", "d": "2026-05-19", "s": 55.5, "x": "This paper demonstrates that repetition-code quantum error correction (QEC) can substantially enhance axion dark matter search sensitivity in CMOS semiconductor spin qubit arrays by mitigating longitudinal dephasing that otherwise suppresses entanglement gain. Integrating repetition codes with logical GHZ block entanglement yields closed-form quantum Fisher information expressions showing that modest QEC cycle frequencies restore multi-qubit sensing advantages across a broad axion mass range."}, {"id": "2605.15554", "t": "Interface Piezoelectric Loss in Superconducting Qubits", "a": "Haoxin Zhou, Kangdi Yu, Yashwanth Balaji, Sanjit Shirol, Leo Sementilli, Zi-Huai Zhang, Adam Schwartzberg, Alp Sipahigil", "d": "2026-05-18", "s": 94.3, "x": "This work demonstrates interface piezoelectricity as a dissipation mechanism in superconducting qubits fabricated on high-resistivity silicon by integrating a transmon qubit into a surface acoustic wave resonator, observing up to 50% reduction in qubit lifetime $T_1$ when tuned into resonance with mechanical modes. Finite-element simulations predict that interface piezoelectric loss scales as $\\Gamma_{\\mathrm{piezo}} \\propto f_q^{3.4}$ and will dominate over two-level system loss above approximately 10 GHz, posing a critical challenge for millimeter-wave superconducting qubits."}, {"id": "2605.16010", "t": "Demonstration of a Multiplexing Trapped Ion Quantum Processing Unit", "a": "F. Anmasser, M. Abu Zahra, K. Schüppert, M. Pototschnig, J. Wahl, M. Dietl, M. Pfeifer, Y. Colombe, J. Repp, M. Brandl, P. Schindler, C. Rössler", "d": "2026-05-18", "s": 67.2, "x": "A surface ion trap integrated with a cryogenic multiplexer based on analog switches and sample-and-hold capacitances demonstrates sub-phonon heating rates and compatible performance for scaling trapped-ion processors. The multiplexed architecture reduces the wiring bottleneck by distributing 22 DAC inputs across 199 DC electrodes using time-division multiplexing with integrated 15–50 pF capacitances."}, {"id": "2605.15389", "t": "Radio-frequency reflectometry in silicon carbide large-area transistors", "a": "Alexander Zotov, Conor McGeough, Megan Powell, Alessandro Rossi", "d": "2026-05-18", "s": 60.2, "x": "This work demonstrates gate-based RF reflectometry on a large-area vertical 4H-SiC MOSFET (Wolfspeed CPM2-1200-0025A) with parasitic capacitances of order nanofarads, showing gate-dependent reflectometry response at room temperature near $f_0 \\approx 566$ MHz but complete loss of sensitivity below $T \\approx 45$ K despite maintained DC transport. The signal degradation at cryogenic temperatures is attributed to carrier freeze-out in the drift region increasing $R_\\mathrm{drift}$ from sub-ohms to $\\approx 8.6$ kΩ at 28 K, which redirects RF current through gate-independent parasitic capacitive paths and suppresses the current-participation factor governing reflectometry contrast."}, {"id": "2605.15988", "t": "Ultra-Weak-Pump Microwave-to-Optical Quantum Transduction via a Single Color Center", "a": "Kyosuke Goto, Hodaka Kurokawa, Hideo Kosaka, Kazuki Koshino", "d": "2026-05-18", "s": 56.9, "x": "This work proposes a microwave-to-optical quantum transducer based on resonant scattering of a single neutral nitrogen-vacancy ($\\mathrm{NV}^0$) center in a diamond optomechanical resonator, achieving coherent conversion at ultralow pump powers of 48 pW. The scheme enables remote entanglement generation between superconducting qubits at kilohertz rates with fidelity exceeding 0.9, demonstrating a viable path toward distributed fault-tolerant quantum computing."}, {"id": "2605.15751", "t": "Equidistant resonance jumps in superconducting coplanar resonators driven by Abrikosov vortices", "a": "Dmitrii S. Kalashnikov, Denis Yu. Vodolazov, Ruslan I. Kinzibaev, Andrei G. Shishkin, Vasily S. Stolyarov", "d": "2026-05-18", "s": 52.6, "x": "Niobium coplanar quarter-wave resonators exhibit staircase-like jumps in resonance frequency and quality factor when exposed to perpendicular magnetic fields up to 40 Oe, with the jumps forming an equidistant series at $\\Delta H \\simeq 1.7$–$1.8$ Oe upon field reversal. These signatures are attributed to discrete multiple-vortex entry and exit events, with the effect strongly dependent on superconducting film quality and persistent only in higher-quality samples above 5 K."}, {"id": "2605.14656", "t": "Blind Quantum Computation on a Modular Superconducting Processor", "a": "Yongxin Song, Johannes Knörzer, Kieran Dalton, Andreas Wallraff, Jean-Claude Besse", "d": "2026-05-15", "s": 85.7, "x": "This work demonstrates measurement-based blind quantum computation on a modular superconducting processor with separate server and client modules, where the server generates two-dimensional cluster states and the client performs universal quantum computation through adaptive measurements without revealing the algorithm or results. The protocol is validated through resource-state characterization, single- and two-qubit gate implementations achieving process fidelities of 0.902 and 0.845, and a three-qubit Deutsch-Jozsa algorithm with 79.7% success probability, with Holevo information of $2.3 \\times 10^{-4}$ bits confirming information-theoretic blindness."}, {"id": "2605.14586", "t": "Fraxonium: Fractional fluxon states for qudit encoding", "a": "Luca Chirolli, Valentina Brosco, Uri Vool, Gianluigi Catelani, Luigi Amico", "d": "2026-05-15", "s": 74.5, "x": "This work proposes fraxonium, a superconducting circuit hosting $d$ degenerate low-energy states separated from higher levels by a large gap, generalizing the fluxonium to encode qudits protected from leakage errors. The system uses fractional fluxon states (fraxons) localized in minima of a Josephson potential engineered via Fourier harmonics using multi-harmonic elements composed of Josephson junctions and inductors."}, {"id": "2605.14582", "t": "Quantum battery optimized by parametric amplification", "a": "Fang-Mei Yang, Jun-Hong An, Fu-Quan Dou", "d": "2026-05-15", "s": 65.1, "x": "This work proposes a superconducting circuit platform for quantum batteries consisting of a two-photon-driven LC resonator coupled to an array of transmon qubits, showing that parametric amplification exponentially enhances the cavity-qubit coupling to enable rapid charging. The scheme achieves 12.5× enhancement in maximum charging power at squeezing parameter $r/\\delta_c = 3$ while maintaining $N^{1.5}$ collective scaling, and demonstrates dark-state protection that stabilizes energy storage in open-system conditions including dissipation rates $\\kappa/\\gamma = 0.01$–$0.10$."}, {"id": "2605.14829", "t": "Superconducting single-photon detectors for integrated quantum photonics", "a": "Ilya A. Stepanov, Oksana I. Shmonina, Evgeniy V. Sergeev, Aleksandr S. Baburin, Danila Yu. Ulyanov, Kirill A. Buzaverov, Sergey S. Avdeev, Aleksey B. Kramarenko, Yuri V. Panfilov, Ilya A. Rodionov", "d": "2026-05-15", "s": 60.1, "x": "This comprehensive review examines integrated superconducting nanowire single-photon detectors (iSNSPDs), covering their operational principles, performance metrics, material platforms, and integration strategies for quantum photonic systems. State-of-the-art iSNSPDs achieve on-chip detection efficiency exceeding 99% at telecom wavelengths, dark count rates below 0.0001 Hz, sub-500 ps recovery times, and timing jitter below 15 ps, with demonstrated photon-number resolution up to 100 photons."}, {"id": "2605.14080", "t": "Dual Shapiro steps and fundamental transconductance in the dc-driven Bloch transistor", "a": "A. B. Zorin", "d": "2026-05-15", "s": 59.5, "x": "This paper proposes a superconducting circuit based on the Bloch transistor (two serial Josephson junctions with a small island) that generates coupled Josephson oscillations at frequency $f_J = 2e\\overline{V_J}/h$ and Bloch oscillations at frequency $f_B = \\overline{I_B}/2e$, which can phase-lock to produce dual Shapiro steps without external microwave drive. When phase-locked, the device exhibits quantized transconductance $\\overline{I_B}/\\overline{V_J} = 1/R_Q = 4e^2/h$, providing an alternative superconducting quantum resistance standard without requiring strong magnetic fields."}, {"id": "2605.12588", "t": "Coherent control of spinmons", "a": "Johanne Bratland Tjernshaugen, Florinda Viñas Boström, Jeroen Danon, Jacob Linder, Karsten Flensberg, Antonio L. R. Manesco", "d": "2026-05-14", "s": 84.0, "x": "Spinmons are superconducting qubits formed by entangling a transmon with the spin of a trapped Andreev quasiparticle in a mesoscopic Josephson junction, offering potential simultaneous protection against multiple decoherence channels. Full qubit control is achieved through electrostatic gating and AC flux driving, with computed relaxation rates below 100 Hz and protection against charge noise via operation at a stationary point of qubit frequency."}, {"id": "2605.13571", "t": "Cryogenic microwave frequency combs based on quantum paraelectric superconducting resonators", "a": "Prasad Muragesh, Harikrishnan Sundaresan, Madhu Thalakulam", "d": "2026-05-14", "s": 60.0, "x": "An all-electrical, on-chip microwave frequency comb is demonstrated using a superconducting cavity loaded with SrTiO$_3$ in its quantum paraelectric phase, exploiting field-induced Pockels-like $χ(2)$ for cavity phase modulation. The high dielectric constant (> 20,000) of SrTiO$_3$ enables miniaturization and direct integration with cryogenic superconducting qubits and quantum metrology platforms without requiring external optical systems."}, {"id": "2605.12429", "t": "Entangling Superconducting Qubits via Energy-Selective Local Reservoirs", "a": "Qihao Guo, Botao Du, Ruichao Ma", "d": "2026-05-13", "s": 87.2, "x": "We implement programmable energy-selective local reservoirs in superconducting qubits by parametrically modulating coupling to readout resonators, achieving incoherent pump and loss that autonomously stabilize entangled Bell states. We demonstrate stabilization of the single-excitation state $|{-}\\rangle$ with $90.8\\%$ fidelity using a two-qubit transmon array with $J \\approx 2\\pi \\times 6$ MHz and validate characterization via robust classical shadow estimation."}, {"id": "2605.11488", "t": "Breaking the scalability barrier via a vertical tunable coupler in 3D integrated transmon system", "a": "Xudong Liao, Shuyi Pan, Zhenxing Zhang, Sainan Huai, Zhiwen Zong, Xiaopei Yang, Kunliang Bu, Wen Zheng, Xinsheng Tan, Yang Yu, Yuan Li, Yi-Cong Zheng, Tianqi Cai, Shengyu Zhang", "d": "2026-05-13", "s": 86.0, "x": "This work demonstrates a three-dimensional integrated superconducting quantum processor with two qubit chips vertically stacked on opposing sides of a carrier chip, coupled through vertical tunable couplers embedded in the carrier. Single-qubit gates achieve 99.87% simultaneous fidelity with negligible crosstalk, two-qubit $\\mathrm{CZ}$ gates reach 97.5% fidelity for both intrachip and interchip operations, and four-qubit $W$-state generation confirms coherent multipartite entanglement across chips."}, {"id": "2605.12385", "t": "Lower overhead fault-tolerant building blocks for noisy quantum computers", "a": "Prithviraj Prabhu", "d": "2026-05-13", "s": 74.9, "x": "This dissertation develops hardware-agnostic optimizations of fault-tolerant quantum computing by redesigning key building blocks including stabilizer measurement, state preparation, error correction, and logical gates to reduce qubit and time overhead. Techniques include flag-based fault tolerance with logarithmic ancilla requirements, deterministic state preparation for CSS codes with 100% yield, distance-four codes encoding six logical qubits using one-tenth the qubits of distance-five surface codes, and temporal encoding of lattice surgery reducing gate time by factors of 2–6."}, {"id": "2605.11088", "t": "Tolerating Device Failure in Distributed Quantum Computing", "a": "Evan Sutcliffe, Coral M. Westoby", "d": "2026-05-13", "s": 60.1, "x": "This work demonstrates that distributed quantum error correction codes implemented over modular quantum networks can tolerate both scheduled node replacement and catastrophic unscheduled node failure, whereas monolithic systems hit a logical error rate floor from such events. For a per-round node failure probability of $p/100$, distributed toric codes outperform monolithic implementations below a physical error rate of 0.05%."}, {"id": "2605.12442", "t": "Programmable Superradiance in an Interacting Qubit Array", "a": "Botao Du, Qihao Guo, Ruichao Ma", "d": "2026-05-13", "s": 52.8, "x": "A superconducting qubit array coupled to a common microwave waveguide enables programmable control of collective dissipation with simultaneous access to microscopic many-body dynamics. Site-resolved measurements reveal how strong coherent interactions reshape superradiant and subradiant decay through spectrally structured many-body eigenstates, with tunable quantum correlations enabling exploration of collective phenomena beyond the ideal Dicke model."}, {"id": "2605.08591", "t": "Quasiparticle Quality Factors in Superconducting Resonators: Effects of Bath Temperature and Readout Power", "a": "Zhenyuan Sun, S Withington, Songyuan Zhao", "d": "2026-05-12", "s": 76.1, "x": "This work extends the Rothwarf-Taylor equations with a microwave power-dependent quasiparticle generation term to model the quality factor of superconducting resonators as a function of bath temperature and readout power. Measurements on NbN microstrip resonators with β-Ta terminations over a 40 dB power dynamic range and temperatures up to $T_c/2$ show excellent agreement with the model across the low-temperature saturation plateau, crossover, and high-temperature exponential decay regimes."}, {"id": "2605.09632", "t": "A Superconducting Levitating Oscillator with < 1 $μ$Hz Resonance Linewidth", "a": "M. Arrayás, J. L. Trueba, C. Uriarte, J. Clothier, C. C. E. Elmy, R. Schanen, D. E. Zmeev, Š. Midlik", "d": "2026-05-12", "s": 51.9, "x": "A superconducting lead sphere magnetically levitated in a millikelvin dilution refrigerator achieves a ring-down time exceeding 110 hours, corresponding to a resonance linewidth of $(0.76 ± 0.02)$ μHz and $T/τ ≈ 10^{-8}$ K s$^{-1}$. The system demonstrates femtonewton-scale force sensitivity by detecting drag from $^3$He impurities at the level of $\bm{3 × 10^{-8}}$ in superfluid $^4$He, with prospects for reaching $T/τ ∼ 10^{-10}$ K s$^{-1}$ using adiabatic nuclear demagnetization."}, {"id": "2605.08341", "t": "Quantum metrology via partial quantum error correction", "a": "Yinan Chen, Zongyuan Wang, Sisi Zhou", "d": "2026-05-12", "s": 51.3, "x": "This work introduces partial quantum error correction (QEC) for metrology using CSS codes, where probe states are superpositions of different code sectors and only a subset of stabilizer checks are needed to suppress noise while maintaining super-SQL scaling. The method achieves polynomial suppression $p^\\delta$ (with $\\delta = \\lfloor(l+1)/2\\rfloor$) of parallel noise and an adaptive strategy to balance performance against both parallel and perpendicular noise."}, {"id": "2605.07868", "t": "Systematic frequency-collision analysis of the cross-resonance gate outside the straddling regime", "a": "Shinichi Inoue, Shotaro Shirai, Shuhei Tamate, Shu Watanabe, Kohei Matsuura, Rui Li, Yasunobu Nakamura", "d": "2026-05-11", "s": 83.8, "x": "This work develops a systematic frequency-collision analysis for cross-resonance gates in the far-detuned regime ($3\\alpha_c \\le \\Delta_{ct} \\le \\alpha_c$) of fixed-frequency transmon processors, showing that this regime significantly improves tolerance to fabrication-induced qubit-frequency spread compared to the conventional straddling regime. Using a long-time-averaged numerical method to accurately model high-intensity smoothly-ramped drives, the authors derive collision-free conditions, perform frequency-allocation optimization via linear programming, and demonstrate that 1024-qubit square-lattice devices require only $\\sigma_f/2\\pi \\le 6.8$ MHz for 10% collision-free yield at 0.1% error threshold—approximately twofold better than current achievable spread."}, {"id": "2605.06928", "t": "Realistic Simulation of Quantum Repeater with Encoding and Classical Error Correction", "a": "Sagar Patange, Caitao Zhan, Bikun Li, Joaquin Chung, Allen Zang, Liang Jiang, Rajkumar Kettimuthu", "d": "2026-05-11", "s": 58.3, "x": "This paper implements and simulates the quantum repeater with encoding and classical error correction (QRE-CEC) protocol in SeQUeNCe, extending the simulator with a stabilizer-based backend supporting CSS code operations and realistic noise models. The protocol distributes logical Bell pairs using Steane $\\lfloor 7,1,3 \\rfloor$ codes with encoded entanglement swapping and classical error correction for Pauli-frame corrections, achieving 0.91 fidelity over 2000 km while suppressing errors to second order."}, {"id": "2605.07033", "t": "Analytic $C_{\\ell_1}$ norm of Coherence Evolution for Bell States under a Two-Qubit Superconducting Hamiltonian", "a": "Seyed Mohsen Moosavi Khansari", "d": "2026-05-11", "s": 50.0, "x": "An exact analytic solution for coherence evolution is derived for a two-qubit superconducting system with $ZZ$-coupling and transverse Josephson tunneling, yielding closed-form time-dependent density matrices and an explicit $C_{\nable_1}$ norm expression for all four Bell state initial conditions. Two Bell states are dynamically invariant with constant coherence, while the other two display parameter-dependent oscillations governed by two distinct frequency scales mapping directly to circuit parameters."}, {"id": "2605.06372", "t": "Coherence limitations of a Fourier-engineered $\\cos(2\\varphi)$ transmon qubit", "a": "Nataliia K. Zhurbina, Siddharth Singh, Lukas J. Splitthoff, Eugene Y. Huang, Figen Yilmaz, A. Mert Bozkurt, Christian Kraglund Andersen", "d": "2026-05-08", "s": 84.2, "x": "This work experimentally realizes a $\\cos(2\\varphi)$ superconducting qubit using Fourier engineering of the energy-phase relation in a multi-junction circuit, achieving suppression of odd harmonics through an interference-based SQUID architecture. Despite the design's intended protection against charge noise, the qubit's lifetime at the flux symmetry point is strongly limited by $1/f$ flux noise due to residual first-harmonic fluctuations, reaching only $\\sim 5$ µs compared to $\\sim 130$ µs predicted for a fluxonium with matched spectrum."}, {"id": "2605.06430", "t": "Revisiting the multi-mode rhombus circuit as a biased-noise qubit", "a": "Pablo Aramburu Sanchez, Trevyn F. Q. Larson, Anthony P. McFadden, Constantin Schrade, Joshua Combes, András Gyenis", "d": "2026-05-08", "s": 66.4, "x": "This work revisits the rhombus qubit—a four-junction interferometer protected against charge noise—by intentionally introducing junction asymmetry ($\\alpha = 0.63$) to raise the qubit frequency toward 100 MHz and mitigate low-frequency noise sources. The modified soft-rhombus qubit achieves $T_1 \\approx 500$ μs in the biased-noise regime (away from frustration) and $T_1 \\approx 27$ μs at half-flux frustration, with flux noise and quasiparticle tunneling identified as dominant loss mechanisms at low frequencies."}, {"id": "2605.05881", "t": "Surface-Code Thresholds and Qubit Footprints in Shuttling-Based Spin-Qubit Railways", "a": "Arun John Moncy, Reza Dastbasteh, Josu Etxezarreta Martinez, Ryo Nagai, Pedro M. Crespo, Normann Mertig, Charles Smith, Ruben M. Otxoa", "d": "2026-05-08", "s": 66.2, "x": "This paper develops a fault-tolerant mapping of rotated surface codes onto a $2\\times N$ silicon spin-qubit railway using coherent electron shuttling, with circuit-level noise modeling showing that the XZZX surface code outperforms CSS variants under dephasing-biased noise inherent to shuttling. A distance-7 code achieving Megaquop requires only $p = 10^{-3}$ physical error rate, reducing qubit footprint by up to 72% compared to symmetric noise models."}, {"id": "2605.06101", "t": "Syndrome resampling enhances quantum error correction thresholds", "a": "Luis Colmenarez, Áron Márton, Markus Müller", "d": "2026-05-08", "s": 65.2, "x": "Syndrome resampling (SR) enhances quantum error correction thresholds by reweighting syndromes according to powers of their probability distribution, establishing a connection to Rényi coherent information phase transitions. Applied to surface codes, SR reduces logical error rates by up to four orders of magnitude in simulation and two orders in experimental lattice-surgery data without additional hardware or decoder modifications."}, {"id": "2605.04892", "t": "Real-time Surface-Code Error Correction Using an FPGA-based Neural-Network Decoder", "a": "Xiaohan Yang, Xuandong Sun, Zhiyi Wu, Jiawei Zhang, Ji Jiang, Xiayu Linpeng, Yuxuan Zhou, Ji Chu, Jingjing Niu, Youpeng Zhong, Song Liu, Dapeng Yu", "d": "2026-05-07", "s": 83.2, "x": "An FPGA-based LSTM neural-network decoder integrated into a superconducting quantum processor achieves real-time surface-code error correction with 550 ns closed-loop latency and 124 ns decoding latency on a distance-3 code. The system demonstrates logical error rates ($\\epsilon_L = 6.9\\%(2)$ per round) comparable to offline MWPM decoding and enables mid-circuit feedback in non-Clifford logical circuits where Pauli-frame tracking alone fails."}, {"id": "2605.05256", "t": "Error Mitigation in Dynamic Circuits for Hamiltonian Simulation", "a": "Sumeet Shirgure, Siyuan Niu", "d": "2026-05-07", "s": 65.5, "x": "This work systematically evaluates error mitigation strategies for dynamic circuits executing Hamiltonian simulation and ground state estimation on IBM quantum hardware, specifically combining dynamical decoupling (DD) during mid-circuit measurement and feed-forward latencies with zero-noise extrapolation (ZNE). The integrated DD+ZNE approach yields at least 60% improvement in energy gap for ground state estimation and recovers 15%–99% of energy gap error for the Ising model time evolution, with more modest 3%–20% improvements for the Heisenberg model."}, {"id": "2605.04663", "t": "Distributed Quantum Error Correction with Bivariate Bicycle Codes in a Modular Architecture", "a": "Nitish Kumar Chandra, Eneet Kaur, Reza Nejabati, Kaushik P. Seshadreesan", "d": "2026-05-07", "s": 55.8, "x": "This work studies distributed implementations of the [[144,12,12]] bivariate bicycle code across 4, 6, and 12 quantum processors connected via a star network using shared Bell pairs for nonlocal gates. The pseudo-threshold decreases monotonically from $p_0 \\approx 0.0063$ (monolithic, $\\alpha=1$) to $p_0 \\approx 0.0016$–$0.0023$ as nonlocal gate error penalty $\\alpha$ increases to 7, with coarser partitioning (4 QPU) outperforming finer ones ($\\alpha \\geq 3$)."}, {"id": "2605.05035", "t": "Network-Mediated Capacitive Coupling Drives Fast OTOC Saturation in Superconducting Circuits", "a": "Carla Caro Villanova, Alan C. Santos", "d": "2026-05-07", "s": 51.9, "x": "This work demonstrates that capacitance-network-mediated interactions in superconducting transmon arrays drive rapid operator scrambling via Out-of-Time-Ordered Correlators (OTOCs), accelerating saturation compared to nearest-neighbor approximations. The system exhibits partial ergodicity with level-spacing ratios intermediate between Poisson and GOE limits, rather than fully developed quantum chaos, within experimentally accessible parameter regimes where $C_C/C_q \\approx 0.15$–0.2."}, {"id": "2605.03187", "t": "Operating a bistable qubit", "a": "Fabrizio Berritta, Jan A. Krzywda, Tom Dvir, Paul Buttles, Stanislav Eilhart, Jeroen Danon, Ferdinand Kuemmeth", "d": "2026-05-06", "s": 85.5, "x": "This work demonstrates a real-time adaptive feedback protocol for operating a superconducting transmon qubit that exhibits bistable frequency switching induced by a strongly coupled TLS defect. The 1-bit feedback scheme estimates which of two qubit frequency modes is active from a single optimally-timed measurement ($\\tau_{\\mathrm{opt}} \\approx 1.33$ µs), then updates the control frequency accordingly to suppress dephasing and stabilize gate fidelities."}, {"id": "2605.03054", "t": "Closed form logical error rate approximations for surface codes", "a": "Shaked Regev, Daniel Dilley, Ryan Bennink", "d": "2026-05-06", "s": 56.2, "x": "This work develops a closed-form method to calculate logical error rates $L$ for surface codes by recursively counting minimum-length logical paths (MLLPs) containing $d_e = (d+1)/2$ errors, avoiding expensive decoder simulations. The approach proves accurate when $pd^2 \\ll 1$ and provides rigorous bounds for the regime $pd^2 \\gtrsim 1$, and is extended to locally and globally correlated error models plus measurement errors."}, {"id": "2605.02755", "t": "Readout failures in superconducting qubits due to TLS-defects in tunnel junctions", "a": "J. Lisenfeld, A. K. Händel, A. Bilmes, A. V. Ustinov", "d": "2026-05-05", "s": 98.8, "x": "A strongly coupled two-level system (TLS) in a transmon qubit's tunnel junction creates a qubit-mediated effective resonant coupling to the readout resonator via virtual qubit excitations, producing an avoided-level crossing that shifts the resonator frequency and spoils readout fidelity. Multi-photon spectroscopy combined with mechanical strain tuning reveals this mechanism and maps the rich spectrum of the qubit-resonator-TLS system, with effective coupling $g_\text{eff} = g_r g_x / \text{δ}$ reaching 1.5 MHz at 500 MHz detuning."}, {"id": "2605.02861", "t": "Opportunities and challenges in scaling quantum error detection on hardware", "a": "Yanis Le Fur, Ethan Egger, Hong-Ye Hu, Vincent Russo, William J. Zeng, Ryan LaRose", "d": "2026-05-05", "s": 66.2, "x": "This paper presents a detailed benchmarking study of quantum error detection on IBM quantum computers using the repetition code and triangular color code, demonstrating exponential convergence of expectation values to noiseless results as code distance increases up to 74 physical qubits. The work characterizes the practical challenges of sampling overhead and classical post-processing, and identifies pseudothresholds below which error detection outperforms unencoded circuits."}, {"id": "2605.00552", "t": "Suppression of Universal Errors in DFS-Encoded Superconducting Geometric Logical \\emph{T} Gate", "a": "Cheng-Yun Ding, Li-Hua Zhang, Jian Zhou", "d": "2026-05-04", "s": 64.0, "x": "This work proposes a decoherence-free subspace (DFS) encoded superconducting geometric logical $T$ gate using optimized composite pulse engineering to achieve fourth-order suppression of Rabi frequency, detuning, and residual inter-qubit crosstalk errors while inherently suppressing collective dephasing. Numerical simulations on tunable transmon circuits with parametric coupling show the two-loop optimized composite geometric $T$ gate achieves $>99.9\\%$ fidelity over a wide error range, outperforming conventional composite geometric and dynamical $T$ gates."}, {"id": "2604.27679", "t": "Parametrically Driven iSWAP Gate Using a Capacitively Shunted Double-Transmon Coupler at the Zero-Flux Sweet Spot", "a": "Shinichi Inoue, Rui Li, Kentaro Kubo, Yinghao Ho, Yasunobu Nakamura, Hayato Goto", "d": "2026-05-01", "s": 92.4, "x": "This work demonstrates a parametrically driven iSWAP gate between fixed-frequency transmons coupled via a capacitively shunted double-transmon coupler (CSDTC), achieving 99.92(2)% fidelity with 112 ns total duration at zero flux bias. The gate uses second-harmonic activation of the exchange interaction through a sinusoidal flux drive, avoiding large flux excursions and predistortion calibration required by baseband-flux CZ gates on the same device."}, {"id": "2604.27080", "t": "High-fidelity iSWAP gate with Double Transmon Coupler", "a": "Tarush Tiwari, Sudhir K. Sahu, Guilhem Ribeill, Michael Senatore, Matthew D. LaHaye, Raymond W. Simmonds, Daniel L. Campbell, Archana Kamal, Leonardo Ranzani", "d": "2026-05-01", "s": 91.0, "x": "This work demonstrates a parametric iSWAP gate between transmon qubits coupled via a double transmon coupler (DTC), achieving 99.827% fidelity in 40 ns operation. The DTC provides an internally-defined cancellation point that robustly suppresses static coupling and cross-Kerr interactions without requiring fine-tuning of capacitive coupling."}, {"id": "2604.27457", "t": "Demonstration of Exponential Quantum Speedup with Constant-Depth Compiled Circuits for Simon's Problem", "a": "Phattharaporn Singkanipa, Victor Kasatkin, Daniel A. Lidar", "d": "2026-05-01", "s": 58.6, "x": "This work demonstrates exponential algorithmic quantum speedup for Simon's problem on superconducting qubits by compiling the oracle to constant depth using hardware-aware optimization. Experiments on IBM's 156-qubit Boston and 120-qubit Miami processors show polylogarithmic NTS scaling in $N_w$ (exponential speedup) for restricted-Hamming-weight cutoffs $w \\geq 4$ on Boston and across low-to-intermediate weights on Miami, without error suppression."}, {"id": "2604.28037", "t": "Branch-Resolved Characterization of Feed-Forward Error in Dynamic Teleportation via Classical Choi Shadows", "a": "Mason Edwards, Prabhat Mishra", "d": "2026-05-01", "s": 58.3, "x": "This paper presents a branch-resolved characterization framework for feed-forward error in dynamic quantum teleportation on superconducting processors, reconstructing branch Choi operators via classical shadows and comparing three correction strategies across two physical qubit layouts. Experiments on IBM Fez with perfect and symmetric W$_4$ resource states reveal a reversal in the relative effectiveness of post-processing versus PROM mitigation depending on mid-circuit measurement readout error, with feed-forward penalties ranging from 0.02–0.03 (low readout error layout) to ~0.07 (high readout error layout)."}, {"id": "2604.26373", "t": "System-Level Design of Scalable Fluxonium Quantum Processors with Double-Transmon Couplers", "a": "Guo Xuan Chan, Wangwei Lan, Tenghui Wang, Xizheng Ma, Chunqing Deng, Lijing Jin", "d": "2026-04-30", "s": 89.3, "x": "This work presents a comprehensive design framework for scalable fluxonium quantum processors using double-transmon couplers (DTCs), addressing the scalability challenges that arise from competing demands of strong coupling, qubit isolation, and wiring density. The framework employs frequency-partitioned architecture and multi-objective optimization to simultaneously achieve single-qubit fidelities $F_{1q} > 99.99\\%$, two-qubit MAP-gate fidelities $F_{2q} > 99.9\\%$, leakage $\\eta < 10^{-3}$, fast reset ($t_{\\mathrm{reset}} < 300$ ns), and spectator crosstalk suppression ($\\zeta < 10$ kHz."}, {"id": "2604.26423", "t": "Large-Scale Quantum Circuit Simulation on an Exascale System for QPU Benchmarking", "a": "J. A. Montanez-Barrera, Kristel Michielsen", "d": "2026-04-30", "s": 63.0, "x": "This work benchmarks Quantinuum Helios-1, a 98-qubit trapped-ion QPU, using linear-ramp QAOA and noiseless reference simulations on JUPITER (an exascale supercomputer) for circuits up to 48 qubits with 3,384 two-qubit gates. The study establishes that Helios-1 maintains noise-tolerant performance up to 48 qubits where outputs match noiseless simulations, extends to 93 qubits (12,834 two-qubit gates) with statistically distinguishable algorithmic signal, and transitions to random-like outputs at 95–98 qubits."}, {"id": "2604.25987", "t": "High-fidelity entangling gates and nonlocal circuits with neutral atoms", "a": "Simon J. Evered, Muqing Xu, Sophie H. Li, Alexandra A. Geim, J. Pablo Bonilla Ataides, Marcin Kalinowski, Dolev Bluvstein, Nishad Maskara, Christian Kokail, Markus Greiner, Vladan Vuletić, Mikhail D. Lukin", "d": "2026-04-30", "s": 62.0, "x": "Neutral-atom quantum processors achieve 99.854(4)% raw fidelity and 99.941(3)% loss-postselected fidelity for $CZ$ entangling gates using high Rabi frequency smooth-amplitude pulses ($\\Omega \\approx 2\\pi \\times 17$ MHz) on $^{87}$Rb atoms in $n=53$ Rydberg states, with stable performance over 10 hours without recalibration. These gates enable quantum circuits with coherent atom rearrangement, including cluster state benchmarks and nonlocal scrambling circuits with super-ballistic entanglement growth, demonstrating compatibility with deep-circuit fault-tolerant computation."}, {"id": "2604.26008", "t": "Continuous Noise Model for Quantum Circuits", "a": "Yunos El Kaderi, Andreas Honecker, Iryna Andriyanova", "d": "2026-04-30", "s": 55.2, "x": "This work compares continuous coherent noise modeled as von Mises–Fisher distributed rotations on the Bloch sphere with discrete Pauli noise in quantum circuits, testing both on [[5,1,3]] and [[7,1,3]] stabilizer codes and Grover search algorithms. An entropy-matched comparison scheme and an approximate analytical method for propagating coherent errors through circuits are introduced, showing that continuous and Pauli noise produce comparable logical-error trends when syndrome extraction is applied."}, {"id": "2604.25303", "t": "Millikelvin digital-to-analog converter for superconducting quantum processors", "a": "Ruizi Hu, Zongyuan Li, Zhancheng Yao, Yufei Wu, Qiang Zhang, Yining Jiao, Quan Guan, Lijing Jin, Wangwei Lan, Chengyao Li, Lu Ma, Liyong Mao, Huijuan Zhan, Ze Zhan, Ran Gao, Lijuan Hu, Kannan Lu, Xizheng Ma, Tenghui Wang, Peng Xiang, Chunqing Deng, Shasha Zhu", "d": "2026-04-29", "s": 85.0, "x": "A superconducting digital-to-analog converter (DAC) programmed by single-flux-quantum (SFQ) pulses has been integrated with fluxonium qubits in a multi-chip module, enabling millikelvin flux tuning without coherence degradation. The DAC stores persistent analog flux signals in an rf-SQUID with screening parameter $\\beta_L = 243$, providing deterministic quantized control compatible with SFQ routing architectures for scalable qubit parameter adjustment."}, {"id": "2604.25195", "t": "A simple method to fabricate Josephson junctions", "a": "Imran Mahboob, Satoshi Sasaki, Takaaki Takenaka", "d": "2026-04-29", "s": 75.1, "x": "A simplified photolithography-based method for fabricating Al/AlO$_x$/Al Josephson junctions with 1–6 µm$^2$ areas and tunable resistance from below 50 Ω to ~1 kΩ is demonstrated, eliminating reactive ion etching and complex resist stacks. SQUIDs fabricated with this approach exhibit reduced resistance variation (±25%) compared to electron-beam lithography (±200%), stable flux response over 10+ thermal cycles, and parametric gain of ~40 dB with quantum-limited noise."}, {"id": "2604.25863", "t": "MCMit: Hardware-Software Co-Design for Mid-Circuit Measurement Error Mitigation", "a": "Emmanouil Giortamis, Felix Gust, Aleksandra Świerkowska, Sandra Stankovic, Innocenzo Fulginiti, Yanbin Chen, Xiaorang Guo, Benjamin Lienhard, Martin Schulz, Pramod Bhatotia", "d": "2026-04-29", "s": 63.7, "x": "MCMit is a hardware-software co-design that mitigates mid-circuit measurement (MCM) errors and classical feedback latency in superconducting quantum processors through a constant-latency multi-qubit branch instruction, two neural network discriminators achieving 62% higher accuracy for 250–500 ns readout, and circuit-level optimization. Implemented on Qubic and evaluated on experimental readout traces, MCMit reduces feedback latency by 70%, improves QEC logical error rates by 1.2–9.4× for surface codes, and delivers 18–30% fidelity gains for distributed quantum computing workloads."}, {"id": "2604.25871", "t": "3D integration of a hybrid quantum dot circuit-QED device for fast gate dispersive charge readout and coherent spin-photon coupling", "a": "Sebastien Granel, Frederic Gustavo, Jean-Luc Thomassin, Heimanu Niebojewski, Benoit Bertrand, Frederic Berger, Alain Gueugnot, Chafik Mhamdi, Etienne Dumur, Romain Maurand, Simon Zihlmann", "d": "2026-04-29", "s": 51.2, "x": "A 3D-integrated hybrid circuit-QED device couples a silicon MOS hole double quantum dot to a high-impedance NbN superconducting resonator using 5 µm indium bump interconnects at 10 µm pitch, achieving a cavity quality factor $Q_i \\sim 10^4$ and demonstrating both fast dispersive charge readout and strong spin-photon coupling. The platform demonstrates record charge readout sensitivity with SNR = 100 in 300 ns and spin-photon coupling strength $g_s/2\\pi = 75$ MHz, establishing the viability of 3D integration for quantum dot based hybrid cQED."}, {"id": "2604.24716", "t": "Gate-dependent offset charge shifts and anharmonicity in gatemon qubits in the weak tunneling regime", "a": "Utkan Güngördü, Rusko Ruskov, Silas Hoffman, Kyle Serniak, Andrew J. Kerman, Charles Tahan", "d": "2026-04-28", "s": 78.8, "x": "This paper quantifies the observable impact of gate-voltage-dependent capacitance renormalization ($\\delta C_\\Sigma$) and charge offsets ($\\delta n_g$ and $n_z$) on gatemon qubit spectra in the weak tunneling regime ($\\Gamma_{L,R} \\ll \\Delta$), derived from a many-body treatment with self-consistent phase quantization. The main prediction is an effective charge offset shift $\\delta n_\\mathrm{eff}(\\epsilon_g)$ in asymmetric junctions ($\\Gamma_L \\neq \\Gamma_R$) that manifests as an $\\epsilon_g$-dependent displacement of charge-parity oscillations in $E_{01}(n_g)$."}, {"id": "2604.23777", "t": "Architecture-aware Unitary Synthesis", "a": "Frans Perkkola, Arianne Meijer-van de Griend, Jukka K. Nurminen", "d": "2026-04-28", "s": 64.7, "x": "This work presents a method for architecture-aware transpilation of general $n$-qubit unitary synthesis on superconducting quantum hardware, tightly integrating transpilation with the optimized block-ZXZ decomposition that uses $\\Theta(4^n)$ CNOT gates. The method combines greedy qubit mapping, adaptive Gray code selection with qubit swapping, and CNOT-ladder heuristics to achieve 34–36% CNOT reductions versus Qiskit/Pennylane and 553× speedup versus TKET on 20-qubit IQM Garnet (square lattice) and 156-qubit IBM Marrakesh (heavy-hex) platforms for 3–11 qubits."}, {"id": "2604.22086", "t": "Tantalum Damascene Coplanar Waveguide Resonators Fabricated Using 300 mm Scale Processes", "a": "Ekta Bhatia, Yingge Du, Krishna P Koirala, Chung Kow, Mingzhao Liu, Juan Macy, Tharanga R. Nanayakkara, Francisco Ponce, Satyavolu S. Papa Rao, Drew J. Rebar, Peter V. Sushko, Brent A VanDevender, Chongmin Wang, Marvin G. Warner, Zhihao Xiao", "d": "2026-04-27", "s": 90.5, "x": "This work demonstrates tantalum damascene coplanar waveguide resonators fabricated on 300 mm wafers, where the superconductor is embedded in the silicon substrate to eliminate native oxide sidewalls. Cryogenic measurements show a modest $\\times 2$ improvement in internal quality factor for pristine Ta/Si interfaces compared to buried-oxide interfaces, though significant performance variance remains."}, {"id": "2604.22112", "t": "Enhanced Tantalum Superconducting Resonator Performance via All-Surface Organic Monolayer Passivation", "a": "Harsh Gupta, Moritz Singer, Benedikt Schoof, Anna Cattani-Scholz, Shreya Sharma, Luca Rommeis, Marc Tornow", "d": "2026-04-27", "s": 79.9, "x": "Self-assembled organic monolayers deposited on tantalum and silicon surfaces suppress native oxide regrowth and reduce interfacial two-level-system losses in coplanar waveguide resonators. Internal quality factors reach $1.8 \\times 10^6$ at $100$ mK in the single-photon regime, a $\\sim140\\%$ improvement over untreated devices."}, {"id": "2604.22650", "t": "Strain engineering of Andreev spin qubits in Germanium", "a": "Vittorio Coppini, Patrick Del Vecchio, Antonio L. R. Manesco, Anton Akhmerov, Valla Fatemi, Bernard van Heck, Stefano Bosco", "d": "2026-04-27", "s": 63.3, "x": "Strain engineering is identified as the key mechanism controlling spin splitting of Andreev bound states in germanium Josephson junctions, with compressive strain suppressing while tensile strain enhancing the spin-orbit interaction. Numerical k·p calculations predict spin splittings in the GHz range for unstrained and tensile-strained $\\mathrm{Ge/GeSn}$ heterostructures, enabling all-electric gate operations in ~100 ns and establishing viable platforms for Andreev spin qubits that were previously unobservable in compressively-strained $\\mathrm{Ge/SiGe}$ devices."}, {"id": "2604.22214", "t": "Non-volatile superconducting tunnelling magnetoresistance memory enabled by exchange-field gap engineering", "a": "Sonam Bhakat, Pushpak Banerjee, Ahmedullah Aziz, Jackson Miller, Avradeep Pal", "d": "2026-04-27", "s": 58.2, "x": "A superconducting tunnelling magnetoresistance device is demonstrated as a non-volatile cryogenic memory element by integrating a de Gennes spin valve with a superconducting tunnel junction in current perpendicular-to-plane geometry, enabling exchange-field control of the superconducting gap. The device operates with millivolt bias, nanowatt-level read power, and zero standby dissipation from 0.25 K across the full superconducting temperature range, with vertical Nb-based architecture compatible with superconducting logic."}, {"id": "2604.22471", "t": "Boundary-Aware Stabilizer Scheduling for Distributed Quantum Error Correction", "a": "Sanidhya Gupta, Sanidhay Bhambay, Narges Alavisamani, Neil Walton, Thirupathaiah Vasantam", "d": "2026-04-27", "s": 53.7, "x": "This paper develops seam-measurement scheduling policies for distributed quantum error correction using triangular color codes partitioned across multiple QPUs connected by photonic links. The Skip-Seam-$\\tau$ (SS-$\\tau$) and Adaptive Skip-$\\tau$ (AST) schemes reduce how often remote seam stabilizers are measured to balance Bell-pair generation delays against syndrome staleness, achieving lower logical error rates than the Measure-All baseline in identified parameter regimes."}, {"id": "2604.22596", "t": "Resonance Frequency Shift Measurements of SRF Cavities at DESY", "a": "Rezvan Ghanbari, Thorsten Buettner, Wolfgang Hillert, Karol Kasprzak, Tom Krokotsch, Ricardo Monroy-Villa, Detlef Reschke, Lea Steder, Alexey Sulimov, Hans Weise, Marc Wenskat, Mateusz Wiencek, Jonas Wolff", "d": "2026-04-27", "s": 53.2, "x": "This paper develops and validates a frequency-shift measurement setup for superconducting radio-frequency cavities, enabling precision determination of resonance frequency and quality factor during warm-up from 5 K to 12 K across the superconducting-to-normal transition. The setup quantifies electron mean free paths in both regimes and characterizes an anomalous frequency dip near $T_c$ in mid-temperature heat-treated niobium cavities, with recent upgrades reducing measurement uncertainty to ~25% of empirical drifts and achieving spatial temperature gradients as low as ~2 K/m."}, {"id": "2604.21565", "t": "Pulse Shaping for Superconducting Qubits", "a": "Animesh Patra, Ankur Raina", "d": "2026-04-24", "s": 87.2, "x": "This pedagogical review integrates pulse-shaping physics, analytical derivations via the Magnus expansion, and practical hardware considerations for superconducting-qubit control. The paper reconstructs quantum gate implementation from first principles, covering single-qubit DRAG pulses, hardware signal generation (AWG, LO, IQ mixing), and multi-qubit cross-resonance gates with error-suppression sequences."}, {"id": "2604.21230", "t": "Time-optimal Qubit Reset via Environmental Spectral Structure", "a": "Hong-Bo Huang, Hui Dong", "d": "2026-04-24", "s": 73.3, "x": "This work solves the time-optimal qubit reset problem for frequency-tunable superconducting qubits coupled to a structured environment by applying Pontryagin's minimum principle to derive an optimal switch–restore–switch control sequence. For representative environmental spectra, the scheme achieves reset times as short as 20 ns with fidelity $10^{-5}$, about 40% of typical two-qubit gate times, while exploiting spectral structure as a practical resource."}, {"id": "2604.21692", "t": "Bipartite entanglement under frequency comb pumping in parametric Josephson circuits", "a": "Mikael Vartiainen, Ilari Lilja, Ekaterina Mukhanova, Kirill Petrovnin, Gheorghe Sorin Paraoanu, Pertti Hakonen", "d": "2026-04-24", "s": 72.1, "x": "This paper experimentally and theoretically investigates how bipartite entanglement between mode pairs degrades in a Josephson parametric amplifier (JPA) when the number of parametric pump tones is increased from one to fifteen. The work demonstrates that additional pumps redistribute two-mode squeezing correlations across a larger network of modes and idler frequencies, reducing the logarithmic negativity of any individual mode pair despite constant or increasing total pump power."}, {"id": "2604.21463", "t": "Dynamical Regimes of Finite-Length Transmission Lines in Circuit Quantum Electrodynamics", "a": "Fabio Borrelli, Giovanni Miano, Adrian Parra-Rodriguez, Carlo Forestiere", "d": "2026-04-24", "s": 56.9, "x": "This paper establishes a unified dynamical regime map for finite-length transmission lines capacitively coupled to transmon qubits, showing that the appropriate description—continuum reservoir, discrete multimode coupler, or single-mode resonator—is selected by the hierarchy among the qubit frequency $\\omega_q$, transmission line characteristic frequency $\\omega_{\\mathrm{TL}} = 2\\pi v_p/d$, and coupling characteristic frequency $\\omega_g = 2\\pi/(Z_{\\mathrm{TL}}C_s)$. Using hierarchical equations of motion and symmetry-resolved decomposition into even/odd parity sectors, the authors characterize memory effects, non-Markovianity via the Breuer–Laine–Piilo measure, and the validity of perturbative approximations across all three regimes."}, {"id": "2604.19871", "t": "Co-Designing Error Mitigation and Error Detection for Logical Qubits", "a": "Rohan S. Kumar, Takahiro Tsunoda, Sophia H. Xue, Dantong Li, Robert J. Schoelkopf, Yongshan Ding", "d": "2026-04-23", "s": 85.3, "x": "This work develops a co-designed architecture combining Probabilistic Error Cancellation (PEC) and Quantum Error Detection (QED) on logical qubits, deriving conditions for sampling advantage and introducing steady-state extraction to handle position-dependent error behavior in QED codes. On a $[[6,4,2]]$ Iceberg code running QAOA at depths $p=4$--$8$, PEC+QED achieves $2$--$11\\times$ lower absolute error and up to $31\\times$ lower MSE versus PEC on physical qubits."}, {"id": "2604.18714", "t": "Efficient Routing of Quantum LDPC Codes on Programmable 2D Toric Architectures", "a": "Kun Liu, Takahiro Tsunoda, Sophia H. Xue, Evan McKinney, Zeyuan Zhou, Shifan Xu, Robert J. Schoelkopf, Yongshan Ding", "d": "2026-04-22", "s": 80.2, "x": "This paper presents a hardware-software co-design for implementing bivariate bicycle quantum LDPC codes on superconducting platforms using a programmable 2D toric network of oscillators as a communication fabric, reducing required long-range couplers from $O(n)$ to $O(\\sqrt{n})$. Circuit-level simulations achieve a logical error rate of 3.06% per logical qubit per cycle for the $[[18,4,4]]$ code with dual-rail qubits and Swap-Wait-Swap gates, a 2.6× improvement over prior experiments."}, {"id": "2604.19115", "t": "Wave--particle transition and quantum Zeno effect in which-way experiments with a superconducting quantum processor", "a": "Shiyu Wang, Zhiguang Yan, Clemens Gneiting, Rui Li, Franco Nori, Yasunobu Nakamura", "d": "2026-04-22", "s": 60.3, "x": "A 16-qubit superconducting processor implements Mach–Zehnder interferometry on 4 and 12 qubits to demonstrate the wave-to-particle transition controlled by which-way measurement strength and observe the quantum Zeno effect under continuous measurement. Quantum state tomography reveals complementarity relations: $2(1-P_s)+V^2 \\leq 1$ (purity-visibility) and $S_s \\leq S_s^\\mathrm{sym}(V)$ (von Neumann entropy-visibility), connecting wave-particle duality to quantum information leakage."}, {"id": "2604.19481", "t": "Fault-Tolerant Quantum Computing with Trapped Ions: The Walking Cat Architecture", "a": "Felix Tripier, Woo Chang Chung, Jacob Young, Safwan Alam, Bryce Bjork, Aharon Brodutch, Finn Lasse Buessen, Nolan J. Coble, Thomas Dellaert, Dmitri Maslov, Martin Roetteler, Edwin Tham, Mark Webster, Min Ye, John Gamble, Andrii Maksymov, J. P. Marceaux, Nicolas Delfosse", "d": "2026-04-22", "s": 59.8, "x": "A fault-tolerant architecture for trapped-ion quantum computers using LDPC codes and cat-state factories for logical operations is proposed, with detailed compiler, decoder, and micro-architecture specifications. The dense variant achieves 110 logical qubits with $\\sim$1 million T gates per day using 2,514 physical qubits, and estimates 100-site Heisenberg simulation within one month on 10,000 physical qubits."}, {"id": "2604.19855", "t": "Rings Around the Ancilla: A Workload-Aware FTQC Architecture", "a": "Archisman Ghosh, Avimita Chatterjee, Swaroop Ghosh", "d": "2026-04-22", "s": 50.1, "x": "This paper proposes a stacked-annulus architecture for fault-tolerant quantum computing that organizes data tiles in concentric rings around a central compute region, jointly optimizing execution latency and data-tile density. The design includes workload-aware qubit placement based on T-gate and Y-gate characteristics, a selective fast-Y optimization knob, and support for concurrent multi-workload execution."}, {"id": "2604.18387", "t": "Engineered broadband Purcell protection using a shared $Π$ filter for multiplexed superconducting qubits", "a": "Samuel D. Escribano, Yael Kriheli, Samuel Goldstein, Daniel Dahan, Nadav Katz", "d": "2026-04-21", "s": 89.2, "x": "A shared $\\Pi$-shaped Purcell filter integrated into the feedline provides broadband qubit protection in multiplexed circuit-QED via passive microwave interference between two open-ended stubs. For realistic parameters, the design achieves Purcell-limited relaxation times exceeding 1 ms over approximately 1.5 GHz while preserving dispersive readout."}, {"id": "2604.18186", "t": "Fundamentals and Applications of Hybrid Electro- and Opto-mechanical system coupled to Superconducting Qubit: A Short Review", "a": "Roson Nongthombam, Urmimala Dewan, Amarendra K. Sarma", "d": "2026-04-21", "s": 87.9, "x": "This review comprehensively covers superconducting hybrid quantum electromechanical and electro-optomechanical systems, focusing on transmon and fluxonium qubits coupled to mechanical resonators through charge and phase degrees of freedom. The paper discusses coupling mechanisms, coherent interactions, and applications including ground-state cooling, quantum state transfer, entanglement generation, and quantum sensing using these integrated platforms."}, {"id": "2604.17891", "t": "Numerical simulation methods for quantum sensing at parametric criticality", "a": "Kirill Petrovnin, Jiaming Wang, Gheorghe Sorin Paraoanu", "d": "2026-04-21", "s": 53.2, "x": "This work develops numerical simulation methods for microwave photon detection using superconducting Kerr parametric resonators operated near the parametric instability threshold. The authors solve Heisenberg-Langevin and Fokker-Planck equations in a semiclassical approximation to characterize switching dynamics and show that detection efficiency is enhanced by probe signals down to single-photon levels."}, {"id": "2604.15971", "t": "A Modular Cryogenic Link for Microwave Quantum Communication Over Distances of Tens of Meters", "a": "Josua D. Schär, Simon Storz, Paul Magnard, Philipp Kurpiers, Janis Lütolf, Melvin Gehrig, Jean-Claude Besse, Anatoly Kulikov, Andreas Wallraff", "d": "2026-04-20", "s": 96.2, "x": "A modular cryogenic link comprising superconducting radiation shields, copper braids, and a WR90 waveguide connects two dilution refrigerators over 30 meters while maintaining millikelvin temperatures and enabling quantum communication between spatially separated superconducting qubits. The system achieves base temperatures below 50 mK along its entire length with a 6.5-day cooldown time, and detailed thermal modeling predicts extensions to 120 m using additional cooling units spaced at 15 m intervals."}, {"id": "2604.16292", "t": "Fast, High-Fidelity Erasure Detection of Dual-Rail Qubits with Symmetrically Coupled Readout", "a": "Jimmy Shih-Chun Hung, Arbel Haim, Mouktik Raha, Gihwan Kim, Ziwen Huang, Ming-Han Chou, Mitch D'Ewart, Erik Davis, Anurag Mishra, Patricio Arrangoiz Arriola, Amirhossein Khalajhedayati, David Hover, Fernando G. S. L. Brandão, Aashish A. Clerk, Alex Retzker, Harry Levine, Oskar Painter", "d": "2026-04-20", "s": 92.5, "x": "This paper demonstrates high-fidelity mid-circuit erasure detection in transmon dual-rail qubits using a symmetrically coupled readout resonator (SRO), achieving 384 ns erasure checks with $6.0(2) \\times 10^{-4}$ residual error per check and enabling continuous parallel erasure detection during gates at $7.2 \\times 10^{-5}$ error per X90 gate. The symmetric coupling achieves $\\chi$-matching with $|\\chi_{\\mathrm{DR}}/\\chi| < 1 \\times 10^{-2}$ over 600 MHz, suppressing measurement-induced dephasing while maintaining strong erasure-state discrimination."}, {"id": "2604.15895", "t": "Digital Predistortion for Flux Control of Tunable Superconducting Qubits", "a": "Dharun Venkateswaran, Felice Francesco Tafuri, Yuanzheng Paul Tan, Bruno Aznar Martinez, Alisa Danilenko, Likai Yang, Arnaud Carignan-Dugas, Christoph Hufnagel, Rainer Dumke, Philip Krantz, Eric T. Holland", "d": "2026-04-20", "s": 89.8, "x": "This paper presents a digital predistortion (DPD) framework using cascaded IIR and FIR filters to compensate for distortion in flux-control signals of superconducting qubits, achieving sub-percent deviations from ideal behavior. Experiments on a 20-qubit IQM Garnet QPU demonstrate correction of combined classical (AWG, cryogenic line, bias-tee) and quantum chip voltage-to-flux transfer function distortions using Cryoscope characterization."}, {"id": "2604.16216", "t": "A digitally controlled silicon quantum processing unit", "a": "Members of the HRL Quantum Team, Collaborators, :, Michael Abraham, Edwin Acuna, Tower S. Adams, Moonmoon Akmal, Matthew R. Alfaro, I. Alvarado, Jacob Amontree, Carter Andrews, Reed W. Andrews, Michael Antcliffe, Andre R. Aséncio, Ryan M. Avila Batres, Cynthia D. Baringer, David W. Barnes, Katherine M. Beech, Russell G. Blakey, Zachery T. Bloom, Aaron J. Bluestone, Jacob Z. Blumoff, Matthew G. Borselli, Koel A. Bose, Brydon Boyd, Jacob T. Boyer, Teresa L. Brecht, Christopher C. Brough, Rex A. Brown, Steven L. Brown, Tyler A. Cain, John B. Carpenter, Stephen Carr, Faustin W. Carter, Mitchell Casanova, Jacob L. Chambers, Matthew D. Chambers, Khamsorn L. Chanthavong, James M. Chappell, Rhian Chavez, Kevin C. Chen, Peter S. Chen, Maxwell D. Choi, Krishna Choudhary, Matthew N. H. Chow, Justin E. Christensen, Aaron M. Chronister, Andrew M. Clapper, Abigail A. Coker, Michael D. Cornelius, Albert E. Cosand, Ian T. Counts, Edward T. Croke, Gregory M. Crosswhite, Adam Dally, Erik S. Daniel, Tuan A. Dao, Dominic Daprano, Tiffany Davis, Neha Deshpande, Rachel S. Dey, D. Scott Diamond, Claire E. Dickerson, J. P. Dodson, James B. Dragan, Marc Dvorak, Lisa F. Edge, Charles R. Elliott, Kenneth R. Elliott, Kevin Eng, Jacob Fast, Colin P. Feeney, David J. Fialkow, Dylan H. Finestone, Micha N. Fireman, Bryan H. Fong, Trevor M. Fowler, Sean Frazier, Kiera L. Fuller, Christina A. C. Garcia, Kacy L. Garstka, Kara C. Garvey, Zachary A. Geiger, Galen R. Gledhill, Caleigh M. Goodwin-Schoen, Joseph L. Goralka, Bradley W. Greene, Hrayr K. Gurgenian, Sieu D. Ha, Wonill Ha, Nathanial R. Hapeman, Brooke M. Hardesty, Jim W. Harrington, Patrick M. Harrington, Thomas R. B. Harris, Ben M. Harrison, Anthony T. Hatke, Robert R. Hayes, Kevin He, Raul Hernandez Garcia, Ryan M. Hickey, Jocelyn Hicks-Garner, Alex Hirman, Donald A. Hitko, David Ho, Holland Y. Ho, Vinh S. Ho, nathan holman, Adam Holmes, Nerys Huffman, Daniel R. Hulbert, Eric B. Isaacs, Clayton A. C. Jackson, Logan Jaeger, Ian Jenkins, Cameron Jennings, Paul C. Jerger, B. Johnson, Aaron M. Jones, Michael P. Jura, Adour V. Kabakian, Raj M. Katti, Tyler Keating, Joseph Kerckhoff, Joseph D. Kern, Isaac Khalaf, Aditya Kher, Jake J. Kim, Erich W. Kinder, Andrey A. Kiselev, William F. Koehl, Patrick W. Krantz, Thaddeus D. Ladd, Pierce G. Laing, Sanaaya Lakdawala, Nathan J. Lang, Robert Lanza, Elias Lawson-Fox, Dustin Le, Kangmu Lee, Nathan R. A. Lee, Jaime Lerma, Mark P. Levendorf, Alwina R. Liu, Henry Lizarraga, Aurelio Lopez, Hoa C. Ly, Torrey T. Lyons, Theodore K. Macioce, Matthew M. Mackey, John K. Maeda, Ryan M. Martin, Daniel S. Matic, Justine W. Matten, Gavin C. Mazur, Max S. McCready, Olivia Means, Kevin E. Millner, Ivan Milosavljevic, Matthew Morris, Susan L. Morton, Samuel Mumford, Bryce D. Murley, Robert G. Nagele, Taro A. Naoi, Cameron R. Nelson, Georgia A. Newman, David B. Nguyen, Tina Niknejad, Rebecca N. Nishide, Liam C. O'Brien, Colin B. E. O'Keefe, Riley P. O'Neil, Andrew E. Oriani, Anthony F. Ortiz, John J. Ottusch, Andrew Pan, Pamela R. Patterson, Uttam Paudel, Julius C. Perez, Christi A. Peterson, Vu T. Phan, Nickolas H. Pilgram, Clifford E. Plesha, Winston Pouse, Eric M. Prophet, Daniel R. Queen, Nicholas Quirk, Kate Raach, Matthew T. Rakher, Matthew D. Reed, Brandon D. Reynolds, Luke D. Robertson, Zechariah Rogers, Yakov Royter, Matthew J. Ruiz, Golam Sabbir, Roshan Sajjad, Christopher D. Sanborn, Rachel H. Sarmiento, Christian J. Schnaible, Cole Scott, Nicholas M. Sebastiani, Eric M. Segall, Alen Senanian, Adalberto Sicairos, Shariq Siddiqui, Kartik Singh, Aaron Smith, Daniel E. Smith, Robert S. Smith, Sarah F. Sontag, Emilio A. Sovero, Kevin C. Staley, Andrea Su, June Suh, Bo Sun, Danny Sun, Christopher M. Swank, Noah Swimmer, Mariano J. Taboada, Bryan J. Thomas, Yessica Torres, Jeremy W. Touve, Alan Tran, Ivan Tran, Chantang Tsen, Skylar Turner, Miguel Valencia, Irma Valles, James R. van Meter, Nicholas D. VanRensselaer, Franklin Vartanian, Daniel Volya, Zachary J. Vrba, Phuong Hong Vu, Annette L. Wagner, John Wallner, Michael P. Walsh, Shuoqin Wang, Tong Wang, Daniel R. Ward, Aaron J. Weinstein, Terry B. Welch, Thomas V. Westrick, Evan T. White, Randall M. White, Samuel J. Whiteley, Gananath Wijeratne, Parker Williams, Jack T. Wilson, Courtney P. Wilt, Deborah E. Winklea, Onnik Yaglioglu, Daniel Yap, Clifford S. YoungSciortino, Daniel Zehnder, Andrew Ziegler", "d": "2026-04-20", "s": 88.5, "x": "This work demonstrates a fully integrated silicon exchange-only qubit processing unit combining a custom cryogenic CMOS controller at 4 K, a superconducting Nb/polyimide ribbon cable, and a 54-dot quantum chip, achieving single-qubit gate errors of $2 \times 10^{-4}$ and CNOT errors of $3 \times 10^{-3}$—an order of magnitude improvement over prior EO qubits. The system validates quantum error correction capability through distance-5 repetition codes and a [[4,2,2]] quantum error detecting code with logical fidelities of $F_L = 0.95$ post-selected."}, {"id": "2604.15432", "t": "Efficient $n$-qubit entangling operations via a superconducting quantum router", "a": "Xuntao Wu, Haoxiong Yan, Gustav Andersson, Alexander Anferov, Christopher R. Conner, Yash J. Joshi, Bayan Karimi, Amber M. King, Shiheng Li, Howard L. Malc, Jacob M. Miller, Harsh Mishra, Hong Qiao, Minseok Ryu, Jian Shi, Andrew N. Cleland", "d": "2026-04-20", "s": 84.7, "x": "This work demonstrates efficient multi-qubit entangling operations on a superconducting quantum processor with a central reconfigurable router, achieving three- and four-qubit W states with fidelities $\rac{97.72(3)\\\\\\\\ \\text{%}$ and $94.70(4)\\\\\\\\ \\text{%}$ in single-step interactions, and using model-free reinforcement learning (PPO) to synthesize native three-qubit gates. The RL-trained controlled-Z gate reaches $96.56 \\text{ %} \\pm 0.12 \\text{ %}$ fidelity (25 % infidelity reduction versus hand-tuned), while the controlled-SWAP and controlled-controlled-phase gates achieve $85.74(78) \\text{ %}$ and $84.59(75) \\text{ %}$ respectively, outperforming decomposition into two-qubit gates."}, {"id": "2604.16209", "t": "Towards Ultra-High-Rate Quantum Error Correction with Reconfigurable Atom Arrays", "a": "Chen Zhao, Casey Duckering, Andi Gu, Nishad Maskara, Hengyun Zhou", "d": "2026-04-20", "s": 63.1, "x": "This work co-designs ultra-high-rate quantum low-density parity-check codes with reconfigurable neutral-atom hardware, achieving encoding rates exceeding $1/2$ at block lengths $\\sim 1000$ qubits by constraining affine permutation matrices to commute with reference maps whose orbits decompose into simple atom rearrangements. Circuit-level simulations at $p = 0.1\\%$ yield per-logical-per-round error rates of $1.3_{-0.9}^{+3.0} \\times 10^{-13}$ for the $[[2304,1156,\\leq 14]]$ code and $2.9_{-1.5}^{+3.1} \\times 10^{-11}$ for the $[[1152,580,\\leq 12]]$ code using a hierarchical decoder combining belief propagation with integer-programming fallback."}, {"id": "2604.14296", "t": "Scalable quantum error correction tailored for a heavy-hex qubit array", "a": "Seok-Hyung Lee, Xanda C. Kolesnikow, Jun Zen, Evan T. Hockings, Campbell K. McLauchlan, Georgia M. Nixon, Thomas R. Scruby, Stephen D. Bartlett, Robin Harper, Benjamin J. Brown", "d": "2026-04-17", "s": 71.7, "x": "A distance-5 dynamic compass code is demonstrated on the IBM Quantum Heron heavy-hex processor, incorporating detailed noise characterization via ACES and soft readout information from IQ data to improve logical error rates. The noise-informed decoding approach yields 24–38% reduction in logical error rates compared to standard calibration-based decoders, with leakage post-selection providing an additional 11–16% improvement."}, {"id": "2604.14623", "t": "Quantum Landscape of Superconducting Diodes", "a": "Muhammad Nadeem, Xiaolin Wang", "d": "2026-04-17", "s": 59.7, "x": "This perspective maps superconducting diodes (SDs) onto circuit quantum electrodynamics (c-QED) architectures, showing how device-level nonreciprocity and Kerr-free nonlinearity address fundamental scalability and control challenges in superconducting quantum processors. SD-integrated platforms promise isothermal classical-quantum hybrid workflows, directional qubit transfer, efficient power management, and quantum-limited amplification without bulky external isolators or circulators."}, {"id": "2604.14931", "t": "Learning to Concatenate Quantum Codes", "a": "Nico Meyer, Christopher Mutschler, Dominik Seuß, Andreas Maier, Daniel D. Scherer", "d": "2026-04-17", "s": 56.7, "x": "This work introduces a level-wise adaptive concatenation strategy for quantum error correction that estimates the effective noise channel after each concatenation level and selects tailored codes accordingly, switching between variational non-additive encoders for structured noise and standard stabilizer codes once noise becomes nearly uniform. Simulations demonstrate that this hybrid approach reduces qubit overhead by one to two orders of magnitude compared to stabilizer-only concatenation for structured initial noise."}, {"id": "2604.13881", "t": "High-gain and large-bandwidth Josephson parametric amplifier influenced by Fabry-Pérot interference", "a": "Shingo Kono, Jesper Ilves, Arjan F. van Loo, Yoshiki Sunada, C. W. Sandbo Chang, Yutaka Takeda, Kenshi Yuki, Takeaki Miyamura, Kohei Matsuura, Kazuki Koshino, Yasunobu Nakamura", "d": "2026-04-16", "s": 93.9, "x": "We develop a flux-driven Josephson parametric amplifier (JPA) with a SQUID array achieving 20 dB net gain and 50 MHz bandwidth, and demonstrate that its performance is significantly shaped by Fabry–Pérot interference from impedance mismatches in the measurement chain. We model this interference using quantum input–output formalism and show the device achieves near-quantum-limited noise ($\bar{N}_\text{added} \bnApprox 0.8$ photons) with maximum gain reaching 44 dB and 220 kHz bandwidth."}, {"id": "2604.13363", "t": "Scalable Fluxonium Quantum Processors via Tunable-Coupler Architecture", "a": "Ze Zhan, Zishuo Li, Fei Wang, Wangwei Lan, Xianchuang Pan, Liang Xiang, Xu Dou, Ran Gao, Guicheng Gong, Yanbo Guo, Quan Guan, Lijuan Hu, Ruizhi Hu, Honghong Ji, Lijing Jin, Yongyue Jin, Chengyao Li, Kannan Lu, Lu Ma, Xizheng Ma, Hongcheng Wang, Jiahui Wang, Huijuan Zhan, Tao Zhou, Xing Zhu, Chunqing Deng, Tenghui Wang", "d": "2026-04-16", "s": 91.2, "x": "Superconducting quantum processors have largely converged on transmon-based architectures, while alternative qubit modalities with intrinsic error protection have lacked a demonstrated path to scalable system integration. In particular, although tunable-coupler-mediated interactions have been validated for small fluxonium systems, it remains unclear whether such designs can be scaled to a multi-qubit lattice."}, {"id": "2604.13176", "t": "Measuring quasiparticle dynamics for particle impact reconstruction in a superconducting qubit chip", "a": "E. Celi, R. Linehan, P. M. Harrington, M. Li, H. D. Pinckney, K. Serniak, W. D. Oliver, J. A. Formaggio, E. Figueroa-Feliciano, D. Baxter", "d": "2026-04-16", "s": 85.8, "x": "Superconducting transmon qubits are used to measure quasiparticle dynamics induced by particle impacts on a silicon substrate, establishing a statistical framework to extract the recombination rate $r$ and linear loss timescale $\\tau_{ss}$ in aluminum films and reconstruct both deposited energy and interaction position. The measured recombination constants $r = 0.052$–$0.095$ ns$^{-1}$ and an unexpected correlation between $\\tau_{ss}$ and deposited energy are validated against Monte Carlo simulation, demonstrating superconducting qubit arrays as energy-resolving particle detectors."}, {"id": "2604.13177", "t": "Quantum computational displacement sensing", "a": "Sridhar Prabhu, Saeed A. Khan, Xingrui Song, Mathieu Ouellet, Ryotatsu Yanagimoto, Saswata Roy, Alen Senanian, Logan G. Wright, Valla Fatemi, Peter L. McMahon", "d": "2026-04-16", "s": 76.7, "x": "This work demonstrates quantum computational displacement sensing (QCDS) using a superconducting qubit coupled to a microwave cavity oscillator, where parameterized quantum circuits directly map displacement classification tasks onto qubit measurement outcomes without estimating the displacement itself. The protocol achieves up to 15 percentage-points higher classification accuracy than conventional quantum sensing baselines for certain binary classification tasks by computing task-specific functions of the sensed displacement in the quantum domain."}, {"id": "2604.13364", "t": "Loss Mechanisms in Cryogenic Microwave Epitaxial AlN Resonators", "a": "Hemant Gulupalli, Navnil Choudhury, Jiacheng Xie, Yufeng Wu, Huili Grace Xing, Hong X. Tang, Debdeep Jena, Kanad Basu, Wenwen Zhao", "d": "2026-04-16", "s": 57.2, "x": "An epitaxial 15.6 GHz AlN FBAR on SiC exhibits loaded $Q_\text{max}$ increasing from 363 at 294 K to 1589 at 6.5 K ($Q f \\approx 5.66$ to 24.79 THz), with acoustic performance limited by anchor loss at cryogenic temperatures and electrode resistance at room temperature. A temperature-dependent loss model incorporating Landau–Rumer and Akhiezer phonon scattering, thermoelastic damping, dielectric loss, and anchor radiation explains the measured $Q(T)$ trend and identifies the crossover near 270 K where $\\omega_0\\tau_\\text{ph} = 1$."}, {"id": "2604.13219", "t": "Fault-Tolerant Error Detection Above Break-Even for Multi-Qubit Gates", "a": "Colburn Riffel, Reece Robertson, Peter Hendrickson", "d": "2026-04-16", "s": 54.2, "x": "A fully fault-tolerant implementation of the Iceberg $[[2m, 2m-2, 2]]$ quantum error-detection code applied to Toffoli and Bell state preparation circuits achieved beyond-break-even fidelity on a 36-qubit trapped-ion computer, demonstrating fidelity gains by filtering error-flagged runs. The work highlights that strategic circuit compilation for error-detection codes—particularly leveraging transversal Hadamard operations—is critical for achieving overhead-tolerant encoded circuits."}, {"id": "2604.12261", "t": "Long-range tunable coupler for modular fluxonium quantum processors", "a": "Peng Zhao, Peng Xu, Zheng-Yuan Xue", "d": "2026-04-15", "s": 75.1, "x": "This paper proposes a long-range tunable coupler (LTC) based on two quarter-wave CPW resonators coupled via an rf-SQUID to enable tunable interactions between fluxonium qubits separated by over one centimeter for modular quantum processors. The coupler achieves sub-100-ns CZ gates with intrinsic errors below $10^{-4}$ while maintaining low quantum crosstalk and supporting degree-four connectivity for surface codes and higher-degree connectivity for quantum LDPC codes."}, {"id": "2604.12947", "t": "Emission and Absorption of Microwave Photons in Orthogonal Temporal Modes across a 30-Meter Two-Node Network", "a": "Alonso Hernández-Antón, Josua D. Schär, Aleksandr Grigorev, Guillermo F. Peñas, Ricardo Puebla, Juan José García-Ripoll, Jean-Claude Besse, Andreas Wallraff, Anatoly Kulikov", "d": "2026-04-15", "s": 69.3, "x": "This work demonstrates emission, transmission, and absorption of microwave photons shaped into three mutually orthogonal temporal modes across a 30-meter cryogenic waveguide connecting two superconducting qubits. The orthogonality of these modes enables mode-selective absorption at the receiver, achieving a selectivity ratio of 40 dB between diagonal and off-diagonal transfer matrix elements."}, {"id": "2604.12742", "t": "Josephson coupling through a magnetic racetrack", "a": "A. A. Mazanik, F. S. Bergeret", "d": "2026-04-15", "s": 58.5, "x": "This paper investigates Josephson coupling in a ferromagnetic racetrack with a Bloch-like domain wall using the linearized Usadel equation in the diffusive limit, showing that the critical current $I_c$ can be tuned via domain wall position and exhibit $0$--$\\pi$ transitions. The supercurrent distribution exhibits non-trivial spatial structure including vortex-like loops at the junction edges and position-dependent attraction or repulsion of supercurrent by the domain wall."}, {"id": "2604.09796", "t": "Resist-free shadow deposition using silicon trenches for Josephson junctions in superconducting qubits", "a": "Tathagata Banerjee, Stephen Daniel Funni, Saswata Roy, Judy J. Cha, Valla Fatemi", "d": "2026-04-14", "s": 86.9, "x": "A resist-free Josephson junction fabrication method based on etched silicon trenches enables Al-AlO$_x$-Al junctions without polymer contamination, producing qubits with median $T_1 = 184$ µs, median $Q_1 = 3.26$ million, and exceptionally stable coherence fluctuations over 36 hours. STEM/EELS confirms minimal carbon and oxygen contamination at the metal-substrate interface, with the process offering CMOS compatibility and broad material flexibility for future qubit platforms."}, {"id": "2604.11722", "t": "First-principles study of dispersive readout in circuit QED", "a": "Angela Riva, Prakritish Gogoi, Nicolas Gheeraert, Serge Florens, Alex W. Chin, Alain Sarlette, Alexandru Petrescu", "d": "2026-04-14", "s": 72.9, "x": "A first-principles tensor-network simulation of circuit QED dispersive readout captures the full unitary dynamics of a qubit and resonator coupled to a microscopic bath with arbitrary spectral density, avoiding standard Lindblad approximations. The study reveals that the qubit energy relaxation time $T_1$ can either decrease or increase with readout drive amplitude ($n̄$ photons) depending sensitively on the bath spectral function, with a Purcell notch filter at $ω_q$ producing qualitatively different behavior ($T_1$ increases with $n̄$) than Ohmic or flat spectra, contradicting predictions from simple Lindblad master equations."}, {"id": "2604.11266", "t": "Multiplexed cryo-CMOS control of an isolated double quantum dot", "a": "Mathieu Darnas, Mathilde Ouvrier-Buffet, Antoine Faurie, Jean-Baptiste Casanova, Benoit Bertrand, Candice Thomas, Jean Charbonnier, Jean-Philippe Michel, Bruna Cardoso Paz, Yvain Thonnart, Franck Badets, Franck Balestro, Matias Urdampilleta, Tristan Meunier, Baptiste Jadot", "d": "2026-04-14", "s": 66.7, "x": "A cryo-CMOS sample-and-hold multiplexing circuit successfully controls a silicon double quantum dot at 0.5 K, demonstrating stable biasing of all five charge configurations from $(4,0)$ to $(0,4)$ and rapid voltage pulsing that resolves single-electron tunneling events. This validates that SH-based multiplexed control is compatible with both static and dynamic operation of isolated quantum dots, advancing scalable architectures for large-scale spin-qubit processors."}, {"id": "2604.09956", "t": "Logical Compilation for Multi-Qubit Iceberg Patches", "a": "Cordell Mazzetti, Sayam Sethi, Rich Rines, Pranav Gokhale, Jonathan Mark Baker", "d": "2026-04-14", "s": 64.1, "x": "This paper addresses the problem of mapping program qubits to logical qubits in high-rate quantum error detection codes, specifically the $[[4,2,2]]$ Iceberg code which encodes two logical qubits per patch. The authors present a compilation framework combining Hadamard commutation, gate merging, and noise-biased packing heuristics that reduces circuit depth by 34%, gate counts by 31% and 17% for one- and two-qubit gates respectively, and improves logical selection rate by 86% relative to naive compilation."}, {"id": "2604.08672", "t": "Hardware-Efficient Erasure Qubits With Superconducting Transmon Qutrits", "a": "Bao-Jie Liu, Ying-Ying Wang, Yu-Xin Wang, Manthan Badbaria, Shruti Puri, Chen Wang", "d": "2026-04-13", "s": 98.1, "x": "This work demonstrates hardware-efficient erasure qubits using the ground and second-excited states of individual superconducting transmon qutrits, with erasure detection via a microwave-activated two-qutrit SWAP gate to an ancilla. Post-selected logical $T_1$ and $T_2$ lifetimes exceed 500 μs and 300 μs respectively—ten times longer than the bare transmon—with single-qubit Clifford gate infidelity of $7.6 \\times 10^{-4}$ under erasure detection."}, {"id": "2604.08655", "t": "High-Fidelity Transmon Reset with a Multimode Acoustic Resonator", "a": "Andraž Omahen, Simon Storz, Igor Kladarić, Yiwen Chu", "d": "2026-04-13", "s": 97.8, "x": "A transmon qubit is coupled to a high-overtone bulk acoustic resonator (HBAR) and reset via repeated iSWAP gates with different GHz-frequency acoustic modes, achieving residual excited-state population $\\langle p \\rangle = 8.3 \\times 10^{-5}$ with 95% confidence interval $[0.027, 2.52] \\times 10^{-4}$. This represents a 5–10× improvement over existing microwave-based schemes and demonstrates that phononic baths provide intrinsically colder, hardware-efficient resources for high-fidelity qubit initialization."}, {"id": "2604.09050", "t": "Tantalum-Encapsulated Niobium Superconducting Resonators: High Internal Quality Factor and Improved Temporal Stability via Surface Passivation", "a": "Anas Alkhazaleh, Juan Villegas, Florent Ravaux, Alexey Zharinov", "d": "2026-04-13", "s": 88.3, "x": "Niobium coplanar waveguide resonators are encapsulated with thin tantalum capping layers to suppress the lossy native NbOx surface oxide and replace it with a more uniform Ta2O5 interface. Fresh Nb/Ta bilayer devices achieve internal quality factors up to $2.4 \times 10^6$ in the single-photon regime with reduced two-level-system loss compared to uncapped Nb controls, and remain superior after six months of storage despite moderate degradation."}, {"id": "2604.08813", "t": "Investigation of coherence of niobium-based resonators enabled by a fast-sealing microwave cavity", "a": "Chi Zhang, Richard Germond, Noah Janzen, Anne-Marie Valente-Feliciano, Mustafa Bal, Adrian Lupascu", "d": "2026-04-13", "s": 86.2, "x": "A fast-sealing microwave cavity that evacuates samples within 5 minutes of HF etching suppresses niobium oxide regrowth and enables coplanar stripline resonators with intrinsic quality factors exceeding $(2.5 ± 0.3) × 10^6$ at single-photon power. Deliberate re-oxidation after 8 days in air yields a measured Nb$_2$O$_5$ regrowth thickness of $2.5$ nm and a metal–air interface loss tangent of $(2.9 ± 0.7) × 10^{-3}$, providing quantitative control over oxidation kinetics."}, {"id": "2604.08861", "t": "Crosstalk-robust superconducting two-qubit geometric gates using tunable couplers", "a": "Bo-Xun Deng, Jia-Qi Hu, Cheng-Yun Ding, Zheng-Yuan Xue, Tao Chen", "d": "2026-04-13", "s": 74.7, "x": "This paper proposes an unconventional nonadiabatic geometric quantum computation (UNGQC) scheme for implementing crosstalk-robust two-qubit gates in tunable-coupler superconducting systems by introducing parametric degrees of freedom ($\\delta$ and $\\varphi$) that steer evolution along optimized trajectories on the Bloch sphere. Numerical simulations demonstrate that the scheme achieves $>99.7\\%$ fidelity for controlled-phase gates while suppressing ZZ crosstalk errors and maintaining robustness against qubit frequency drift, even under realistic conditions including decoherence and high-frequency oscillation terms."}, {"id": "2604.08955", "t": "Impact of Pump Phase-Noise on Josephson Traveling-Wave Parametric Amplifiers", "a": "Daryoush Shiri, Likai Yang, Saesun Kim, Mohamed A. Hassan, Philip Krantz, Eric T. Holland", "d": "2026-04-13", "s": 71.9, "x": "This work investigates how pump phase noise affects Josephson traveling-wave parametric amplifiers (JTWPAs), finding that the three-wave mixing (3WM) process exhibits significant phase noise regrowth at high frequency offsets while the four-wave mixing (4WM) process does not. The mechanism is traced to even-order nonlinearities in 3WM that create cyclo-stationary noise through overlapping of harmonic sidebands, resulting in over 10 dB of phase noise growth at 100 MHz offset as pump power increases from $-100$ dBm to $-86$ dBm."}, {"id": "2604.08515", "t": "Measurement-induced state transitions across the fluxonium qubit landscape", "a": "Alex A. Chapple, Boris M. Varbanov, Alexander McDonald, Alexandre Blais", "d": "2026-04-10", "s": 89.8, "x": "This paper systematically studies measurement-induced state transitions (MIST) in fluxonium qubits across the experimentally explored parameter space using branch analysis over $2 \times 10^6$ parameter combinations, finding that lighter fluxoniums ($E_J/E_L \to 3$–$6$) are less susceptible to MIST than heavier ones. The authors identify three physical mechanisms responsible for this difference: lower density of multi-photon resonances, smaller required coupling for a target dispersive shift $\bar{\bar{\bar{\bar{\bar{}}}}}$, and more harmonic charge operator structure in light fluxoniums."}, {"id": "2604.06319", "t": "Heterogeneous architectures enable a 138x reduction in physical qubit requirements for fault-tolerant quantum computing under detailed accounting", "a": "Pranav S. Mundada, Aleksei Khindanov, Yulun Wang, Claire L. Edmunds, Paul Coote, Michael J. Biercuk, Yuval Baum, Michael Hush", "d": "2026-04-09", "s": 59.0, "x": "This work introduces Q-NEXUS, a heterogeneous quantum computing architecture with specialized modules for computation (small fixed-size QPUs), memory (STQM and RAQM), and communication (quantum bus), orchestrated by the Q-CHESS compiler. For RSA-2048 factorization, Q-NEXUS reduces physical qubit requirements from 0.9 M in a monolithic baseline to 0.19 M (with qLDPC codes) or 0.25 M, achieving 138× reduction in total qubits and 11× reduction in local couplers while maintaining comparable runtimes."}, {"id": "2604.07163", "t": "Robust and High-Fidelity Controlled Two-Qubit Gates via Asymmetric Parallel Resonant Excitation", "a": "Licheng Lin, Jize Han, Peng Zhu, Ziyu Wang, Ying Yan, Jie Lu, Zhiguo Huang", "d": "2026-04-09", "s": 52.0, "x": "A robust resonant two-qubit gate scheme for rare-earth-ion systems uses asymmetric parallel excitation and pulse engineering to achieve decoupled qubit control, avoiding susceptibility to frequency errors and AC Stark shifts. Simulations demonstrate gate fidelities exceeding 99% within a 170 kHz detuning tolerance with off-resonant excitation below 0.2%."}, {"id": "2604.05693", "t": "A plug-and-play superconducting quantum controller at millikelvin temperatures enables exceeding 99.9% average gate fidelity", "a": "Kuang Liu, Zhiyuan Wang, Xiaoliang He, Siqi Li, Hao Wu, Xiangyu Ren, Zhengqi Niu, Wangpeng Gao, Chenluo Zhang, Pei Huang, Yu Wu, Liliang Ying, Wei Peng, Jaw-Shen Tsai, Zhirong Lin", "d": "2026-04-08", "s": 97.4, "x": "A superconducting quantum controller fabricated in Nb on high-resistivity silicon achieves 99.9% average Clifford fidelity with $10^{-4}$-level leakage when integrated at 10 mK with a transmon qubit, using single-flux-quantum (SFQ) pulse trains for all-digital qubit control. The device combines a fully passive bias network and spectrum-engineering unit to suppress quasiparticle poisoning and high-energy-level leakage, operating at an average gate energy of 0.121 fJ with negligible thermal load."}, {"id": "2604.05105", "t": "A superconducting quantum circuit single artificial atom maser", "a": "Maria Mucci, Nicholas Hougland, Chun-Che Wang, Israa Yusuf, Chenxu Liu, David Pekker, Michael Hatridge", "d": "2026-04-08", "s": 95.1, "x": "This work demonstrates a circuit QED micromaser using a multi-level artificial atom (SNAIL-transmon hybrid) as the gain medium, pumped into population inversion via microwave drive and coupled to a superconducting cavity. The device exhibits three distinct pump cycles and produces coherent maser output with linewidth narrowed to 54 Hz, approximately 365 times below the bare cavity linewidth of 19.7 kHz."}, {"id": "2604.05048", "t": "Unlocking a fast adiabatic CZ gate and exact residual $ZZ$ cancellation between fixed-frequency transmons using a floating tunable coupler", "a": "Angela Q. Chen, Xian Wu, Sarah Strong, Stefano Poletto", "d": "2026-04-08", "s": 87.2, "x": "A symmetric floating tunable coupler enables fast adiabatic CZ gates between fixed-frequency transmons while maintaining exact residual $ZZ=0$ cancellation at idling, exploiting favorable energy-level ordering that eliminates the traditional trade-off between gate speed and adiabatic evolution. The work demonstrates a 24 ns gate with fidelity $99.919 \text{ ± } 0.010\text{ %}$ using adiabatically-weighted pulse shaping based on instantaneous adiabatic factors."}, {"id": "2604.05126", "t": "In-Situ Simultaneous Magic State Injection on Arbitrary CSS qLDPC Codes", "a": "Kun Liu, Shifan Xu, Tomas Jochym-O'Connor, Zhiyang He, Shraddha Singh, Yongshan Ding", "d": "2026-04-08", "s": 65.4, "x": "This work presents the first in-situ magic state injection scheme for arbitrary CSS qLDPC codes, where logical magic states are prepared directly within a code block using only syndrome extraction resources. Circuit-level simulations on the $[[144,12,12]]$ Bivariate Bicycle code achieve injection error rates of $1.62 \\times 10^{-3}$ per logical qubit when simultaneously injecting four logical $|Y\\rangle$ states under depolarizing noise at $p=10^{-3}$, falling to $6.7 \\times 10^{-4}$ under asymmetric noise where single-qubit errors are 10% of two-qubit errors."}, {"id": "2604.03726", "t": "Leakage Suppression in Quantum Control via Static Parameter Offsets", "a": "Ting Lin, Zi-Hao Qin, Zheng-Yuan Xue, Tao Chen", "d": "2026-04-07", "s": 67.9, "x": "This work proposes suppressing leakage errors in quantum gates by applying small static offsets to tunable system parameters, without modifying control pulse shapes or adding time overhead. Numerical validation on superconducting transmon qubits demonstrates high-fidelity single-qubit gates (NOT and Hadamard reaching 99.98% and 99.92%), two-qubit iSWAP gates (99.87%), multi-level state transfer (99.91%), and cooperative suppression of leakage and ZZ crosstalk via integration with geometric trajectory correction."}, {"id": "2604.03702", "t": "Analytical evaluation of surface barrier and resistance in iron-based superconducting multilayers for Superconducting Radio-Frequency applications", "a": "Carlos Redondo Herrero, Akira Miyazaki", "d": "2026-04-07", "s": 51.5, "x": "This work presents analytical calculations of surface barriers and RF surface resistance in superconducting multilayer structures for SRF cavity applications, comparing conventional materials (NbN, Nb$_3$Sn) with iron-based superconductors (FeSe). Simultaneous optimization of vortex penetration field $B_v$ and surface resistance $R_s$ is proposed as a design strategy, with FeSe/I/Nb$_3$Sn achieving $B_v = 508.3$ mT and ultra-low $R_s = 9.31 \\times 10^{-3}$ nΩ compared to bulk Nb's $B_v = 180$ mT and $R_s = 22.26$ nΩ."}, {"id": "2604.04438", "t": "Digital-Analog Quantum Simulation and Computing: A Perspective on Past and Future Developments", "a": "Lucas Lamata", "d": "2026-04-07", "s": 50.2, "x": "This Perspective reviews the emergence and evolution of the digital-analog quantum paradigm over the past decade, which combines native analog interactions from quantum platforms (acting on tens to hundreds of qubits) with digital single- and two-qubit gates to enable scalable, versatile quantum simulation and computing without requiring quantum error correction in the near term. Implementations across trapped ions, superconducting circuits, and Rydberg atoms have demonstrated record numbers of qubits for useful computations, establishing digital-analog techniques as the de facto standard for current large-scale quantum experiments."}, {"id": "2604.02809", "t": "Characterizing charge-parity detection based on an offset-charge-tunable transmon qubit via randomized benchmarking", "a": "Yao-Yao Jiang, Tang Su, Yuxiang Liu, Yi-Ming Guo, Yidong Song, Yu-Long Li, Yanjie Zeng, Guang-Ming Xue, Wei-Jie Sun, Mei-Ling Li, Yi-Rong Jin, Junhua Wang, Xuegang Li, Hai-Feng Yu", "d": "2026-04-06", "s": 88.3, "x": "This work demonstrates high-fidelity charge-parity detection using an offset-charge-tunable transmon qubit with a gate control line, achieving single-qubit gate fidelity of 99.96% and charge-parity mapping fidelity of 99.37% via a spin-echo-based sequence (EchoCPM) with net-zero gate pulses. Continuous monitoring of charge-parity state reaches 93.4% fidelity at 4 μs sampling, with qubit readout identified as the primary error source limiting detection performance."}, {"id": "2604.01145", "t": "FerBo: a noise resilient qubit hybridizing Andreev and fluxonium states", "a": "J. J. Caceres, D. Sanz Marco, J. Ortuzar, E. Flurin, C. Urbina, H. Pothier, M. F. Goffman, F. J. Matute-Cañadas, A. Levy Yeyati", "d": "2026-04-02", "s": 78.5, "x": "FerBo is a superconducting qubit combining a high-transparency Andreev weak link with an LC circuit, achieving simultaneous suppression of both relaxation and dephasing through hybridization of fermionic Andreev bound states with the bosonic electromagnetic mode. The qubit states have disjoint support in Andreev sector space and delocalized wavefunctions in phase, providing protection over a well-defined and experimentally accessible parameter regime."}, {"id": "2604.00212", "t": "Building Block For Universal Continuous Variables Computation In Superconducting Devices", "a": "Bruno A. Veloso, Ciro M. Diniz, Luiz O. R. Solak, Antonio S. M. de Castro, Daniel Z. Rossatto, Celso J. Villas-Bôas", "d": "2026-04-02", "s": 57.2, "x": "This work designs a two-layer superconducting architecture implementing all five universal continuous-variable gates (rotation, displacement, squeezing, Kerr, and beam splitter) using a DC-SQUID mode, a fluxonium qubit for nonlinear interactions, and two ancillary qubits. Numerical simulations achieve fidelities $\\geq 98\\%$ across all gates within state-of-the-art parameter regimes, with gate times ranging from 33 ns (displacement) to 228 µs (Kerr at $\\mathcal{F} = 98.8\\%$)."}, {"id": "2603.29498", "t": "Junction-Intrinsic Dissipation in Hybrid Superconductor-Semiconductor Gatemon Qubits", "a": "Zhenhai Sun, David Feldstein-Bofill, Ksenia Shagalov, Amalie T. J. Paulsen, Casper Wied, Shikhar Singh, Brian D. Isakov, Jacob Hastrup, Christopher W. Warren, Svend Krøjer, Anders Kringhøj, András Gyenis, Morten Kjaergaard", "d": "2026-04-01", "s": 88.9, "x": "This work co-fabricates InAs/Al nanowire-based gatemons and SIS-junction transmons on identical high-resistivity silicon substrates with shared circuit layouts and dielectrics to isolate junction-intrinsic dissipation. Co-integrated transmons reach $T_1 = 25.8$–93.8 µs while gatemons saturate at $T_1 = 0.69$–9.1 µs (roughly sixfold gap), with a comprehensive loss budget showing Purcell decay ($T_{1,\text{Pur}} > 300$ µs), gate-line spontaneous emission ($T_{1,\text{spont}} > 30$ µs), and internal dielectric loss ($Q_\text{int} \times 2\text{π} f_q$, tens of microseconds) all exceeding measured gatemon values by $> 10\times$, indicating temperature-independent junction-intrinsic dissipation."}, {"id": "2603.29065", "t": "Oxide-nitride heteroepitaxy for low-loss dielectrics in superconducting quantum circuits", "a": "David A. Garcia-Wetten, Mitchell J. Walker, Peter G. Lim, André Vallières, Maria G. Jimenez-Guillermo, Miguel A. Alvarado, Dominic P. Goronzy, Anna Grassellino, Jens Koch, Vinayak P. Dravid, Mark C. Hersam, Michael J. Bedzyk", "d": "2026-04-01", "s": 76.4, "x": "This work grows crystalline $\\gamma$-Al$_2$O$_3$ as a single-crystal dielectric layer sandwiched between TiN electrodes using pulsed laser deposition, achieving a measured intrinsic two-level system loss of $\\delta_{\\text{TLS}}^0 = (2.8 \\pm 0.1) \\times 10^{-5}$ via microwave resonator spectroscopy. The heteroepitaxial oxide-nitride platform with minimal interface interdiffusion and defects opens a path toward low-loss dielectrics for superconducting qubit architectures."}, {"id": "2603.29525", "t": "Non-perturbative CPMG scaling and qutrit-driven breakdown under compiled superconducting-qubit control: a single-qubit study", "a": "Jun Ye", "d": "2026-04-01", "s": 61.4, "x": "This paper couples instruction-set-level waveform generation to hierarchical equations of motion (HEOM) to study non-perturbative decoherence in superconducting transmons under $1/f$ pure dephasing and compiled control. Y-CPMG exhibits axis-dependent scaling-law breakdown—non-monotonic decoherence and population imbalance ($0.204$ vs $<0.01$)—driven by third-level anharmonicity amplified by bath memory, while X-CPMG maintains power-law scaling with finite-$n$ transient consistent with non-Markovian effects; waveform-level differences remain undetectable across all coupling strengths."}, {"id": "2603.29439", "t": "PAEMS: Precise and Adaptive Error Model for Superconducting Quantum Processors", "a": "Songhuan He, Yifei Cui, Bo Liu, Kai Guo, Cheng Wang", "d": "2026-04-01", "s": 56.9, "x": "PAEMS is a qubit-error model with $O(n^2)$ complexity that captures spatial heterogeneity, temporal error accumulation, and leakage propagation in superconducting QPUs by using qubit-specific depolarizing channels initialized from calibration and optimized via CMA-ES on repetition-code datasets. On IBM Brisbane, Sherbrooke, and Torino, PAEMS achieves 19.5×, 9.3×, and 5.2× reductions in timelike, spacelike, and spacetime error-correlation differences versus prior models, and shows 58–73% lower total variation distance than Google's SI1000 across five QPU platforms."}, {"id": "2603.18780", "t": "Comparing optical-microwave conversion and all-microwave control schemes for a transmon qubit", "a": "Volodymyr Monarkha, Massimo Borrelli, Reza Hajitashakkori Kenari, Mohammad Kobba, Eugenio Cataldo, Beer de Zoeten, Mahnaz Zarrinfar, Kamal Pandey, Abhinand Pusuluri, Filippo D. Michelacci, Eliot Jouan, Bennett Sprague, Simon Groeblacher, Thierry C. van Thiel, Robert Stockill, Russell E. Lake", "d": "2026-03-20", "s": 90.1, "x": "This work compares optical-to-microwave conversion and conventional coaxial control for a transmon qubit, finding no statistically significant difference in coherence over 20 hour measurement runs. Thermal simulations for scaled systems show optical control can reduce heat loads at cryogenic stages compared to all-coaxial wiring."}, {"id": "2603.18977", "t": "XCOM: Full Mesh Network Synchronization and Low-Latency Communication for QICK (Quantum Instrumentation Control Kit)", "a": "Diego Martin, Luis H. Arnaldi, Kenneth Treptow, Neal Wilcer, Sho Uemura, Sara Sussman, David I Schuster, Gustavo Cancelo", "d": "2026-03-20", "s": 80.5, "x": "XCOM is a full-mesh network architecture for synchronizing multiple QICK boards and their absolute time counters to within 100 ps while providing deterministic all-to-all data communication with latency below 186 ns at 100 MHz clock speed (reducible to 62 ns at 300 MHz). The system combines PLL nested zero-delay mode locking, multi-tile DAC/ADC synchronization, and LVDS-based point-to-point communication via a central fanout hub to enable scalable multi-board control for superconducting and spin qubit systems."}, {"id": "2603.18666", "t": "On-chip Parametric Amplification in a Double Quantum Dots Circuit", "a": "Yong-Qiang Xu, Rui Wu, Si-Si Gu, Shun-Li Jiang, Shu-Kun Ye, Bao-Chuan Wang, Hai-Ou Li, Guang-Can Guo, Chang-Ling Zou, Gang Cao, Guo-Ping Guo", "d": "2026-03-20", "s": 72.2, "x": "This work demonstrates a single-atom parametric amplifier (SAPA) based on a GaAs double quantum dot (DQD) integrated with a superconducting NbTiN microwave cavity ($\\omega_r / 2\\pi = 5.198$ GHz, $\\kappa / 2\\pi = 14$ MHz), achieving a parametric gain exceeding 11 dB via four-wave mixing. When one DQD operates as amplifier for readout of a second DQD, the signal-to-noise ratio improves by approximately twofold (SNR enhanced from 5.5 to 10.9)."}, {"id": "2603.18231", "t": "Iterative Decoding of Stabilizer Codes under Radiation-Induced Correlated Noise", "a": "Anuj K. Nayak, Paul G. Baity, Peter J. Love, Nicholas Jeon, Byung-Jun Yoon, Adolfy Hoisie, Lav R. Varshney", "d": "2026-03-20", "s": 66.4, "x": "This paper develops iterative decoding algorithms for stabilizer codes under radiation-induced correlated noise by jointly inferring quasiparticle (QP) density and decoding from syndrome measurements. Two algorithms are presented: a gradient-based sliding-window approach (Algorithm 1) and an extended Kalman filter variant (Algorithm 2), both using belief propagation with ordered statistics decoding."}, {"id": "2603.18457", "t": "Simulating Quantum Error Correction beyond Pauli Stochastic Errors", "a": "Jordan Hines, Corey Ostrove, Kenneth Rudinger, Stefan Seritan, Kevin Young, Robin Blume-Kohout, Timothy Proctor", "d": "2026-03-20", "s": 57.0, "x": "This paper presents a computationally efficient method for constructing detector error models (DEMs) that accurately capture the effects of general Markovian circuit-level errors—including coherent and non-Pauli errors—on fault-tolerant quantum error correction, enabled by propagating errors through Clifford circuits using the elementary error generator (EEG) basis. The analysis shows that coherent errors can shift code thresholds, increase space-time costs for magic state cultivation, and boost logical error rates by up to an order of magnitude compared to equivalent stochastic Pauli errors, with validation on surface codes, bivariate bicycle codes, and $S$-state cultivation."}, {"id": "2603.17936", "t": "Exploration of Fluxonium Parameters for Capacitive Cross-Resonance Gates", "a": "Eugene Y. Huang, Christian Kraglund Andersen", "d": "2026-03-19", "s": 79.4, "x": "This work demonstrates that an all-fluxonium cross-resonance (CR) architecture with only direct capacitive coupling can achieve CNOT gate durations under 200 ns with residual ZZ rates of 50 kHz, using a semi-analytical approach that combines numerical Floquet diagonalization with perturbative two-qubit coupling. Detailed frequency-collision analysis and Monte Carlo simulations show that the high anharmonicity of fluxoniums enables substantially improved scalability compared to transmons, requiring only ~1–2% Josephson-energy disorder to maintain >50% collision-free yield for surface codes up to distance 21."}, {"id": "2603.17253", "t": "Efficient and flexible preparation of photonic NOON states in a superconducting system", "a": "Dong-Sheng Li, Yi-Hao Kang, Zhi-Cheng Shi, Yang Xiao, Ye-Hong Chen, Yan Xia", "d": "2026-03-19", "s": 78.0, "x": "This work proposes a three-step protocol for preparing NOON states with arbitrary photon number $N$ in two microwave cavities coupled to a five-level superconducting qudit, requiring only linear interactions and classical field adjustments. Numerical simulations demonstrate fidelities exceeding 99% for $N=2,3,4$ under realistic superconducting system parameters, with robustness to systematic errors, coupling strength deviations, inter-cavity crosstalk, and decoherence effects."}, {"id": "2603.17214", "t": "A Dayem Loop Qubit Based on Interfering Superconducting Nanowires", "a": "Cliff Sun, Alexey Bezryadin", "d": "2026-03-19", "s": 71.4, "x": "This paper proposes a Dayem loop qubit based on two parallel superconducting nanowires connected as a SQUID, where quantum interference between the nanowires restores cubic nonlinearity in the current-phase relationship (CPR) even when individual wires have weak or higher-order nonlinearities. The design achieves sufficient anharmonicity for transmon operation by applying a perpendicular magnetic field to tune the phase shift between wires, eliminating the need for tunnel junctions or material interfaces."}, {"id": "2603.17167", "t": "Optimizing Logical Mappings for Quantum Low-Density Parity Check Codes", "a": "Sayam Sethi, Sahil Khan, Maxwell Poster, Abhinav Anand, Jonathan Mark Baker", "d": "2026-03-19", "s": 57.4, "x": "This paper addresses logical qubit mapping for the Gross code, a spatially efficient quantum error correction code, by developing a two-stage compilation pipeline that reduces inter-module measurement errors. The approach uses hypergraph partitioning to cluster logical qubits and a priority-based algorithm for module assignment, achieving ~13% average reduction in non-fixed error rates and up to ~36% in optimal cases compared to existing NISQ and FTQC mappers."}, {"id": "2603.17194", "t": "$\\textit{Ab initio}$ Identification of Hydrogen Tunneling as Two-Level Systems in Nb$_2$O$_5$ and Ta$_2$O$_5$", "a": "Cristóbal Méndez, Tomás A. Arias", "d": "2026-03-19", "s": 53.6, "x": "This work identifies hydrogen tunneling as a plausible microscopic origin of two-level systems (TLS) in native Nb$_2$O$_5$ and Ta$_2$O$_5$ oxides that limit superconducting-qubit coherence and SRF-cavity quality factors. Machine-learned interatomic potentials accelerate sampling of hydrogen configurations and diffusion barriers in amorphous oxides, revealing that H is the only light interstitial with barrier–distance combinations yielding tunnel splittings in the $\nu_{\text{TLS}} \to f \text{ range} \true \text{ of } 0.1{-}10$ GHz."}, {"id": "2603.16993", "t": "Chiral and bond-ordered phases in a triangular-ladder superconducting-qubit quantum simulator", "a": "Matthew Molinelli, Joshua C. Wang, Jeronimo G. C. Martinez, Sonny Lowe, Andrew Osborne, Rhine Samajdar, Andrew A. Houck", "d": "2026-03-19", "s": 51.2, "x": "This work demonstrates a superconducting-qubit quantum simulator of the Bose-Hubbard model on a triangular-ladder lattice with tunable synthetic magnetic flux, preparing and characterizing half-filling ground states through measurements of current-current correlators and bond kinetic energies. The experiments reveal chiral superfluids at $\\pi$ flux with staggered loop currents, Meissner superfluids at zero flux with suppressed rung currents, and signatures of bond-ordered insulating phases."}, {"id": "2603.16494", "t": "Distinguishing types of correlated errors in superconducting qubits", "a": "Hannah P. Binney, H. Douglas Pinckney, Kate Azar, Patrick M. Harrington, Shantanu Jha, Mingyu Li, Jiatong Yang, Felipe Contipelli, Renée DePencier Piñero, Michael Gingras, Bethany M. Niedzielski, Hannah Stickler, Mollie E. Schwartz, Jeffrey A. Grover, Max Hays, Kyle Serniak, Joseph A. Formaggio, William D. Oliver", "d": "2026-03-18", "s": 97.5, "x": "This work distinguishes two populations of correlated errors in superconducting transmon qubits: radiation-induced events with $\\tau \\approx 5$ ms decay time and pulse-tube (PT)-induced events with longer lifetimes occurring at $\\approx 1.4$ Hz. Gap-engineered devices with $\\delta\\Delta_{JJ} > f_q$ show suppression of both error types, suggesting a quasiparticle-mediated mechanism for PT errors."}, {"id": "2603.16693", "t": "A Compact Broadband Purcell Filter for Superconducting Quantum Circuits in a 3D Flip-Chip Architecture", "a": "Zhen Luo, Lea Richard, Ivan Tsitsilin, Anirban Bhattacharjee, Christian M. F. Schneider, Stefan Filipp, Amelie Hagelauer", "d": "2026-03-18", "s": 97.4, "x": "A four-pole broadband Purcell filter implemented on a 3D flip-chip platform achieves 1 GHz flat passband centered at 7.68 GHz with >45 dB suppression at typical qubit frequencies, demonstrated with six multiplexed readout resonators on a compact 10×6 mm² chip fabricated in 150 nm Nb. An analytical model based on coupling matrices accurately predicts the transmission response and enables rapid circuit synthesis, accounting for spiral and CPW resonators with conformal-mapping calculations and validated against HFSS eigenmode and driven-modal simulations."}, {"id": "2603.16608", "t": "CryoCMOS RF multiplexer for superconducting qubit control, readout and flux biasing at millikelvin temperatures with picowatt power consumption", "a": "Liam Fallik, Sriram Balamurali, Alican Caglar, Rohith Acharya, Jacques Van Damme, Tsvetan Ivanov, Shana Massar, Ruben Asanovski, A. M. Vadiraj, Massimo Mongillo, Jan Craninckx, Alexander Grill, Danny Wan, Anton Potočnik, Kristiaan De Greve", "d": "2026-03-18", "s": 88.3, "x": "A cryoCMOS RF multiplexer operating at 10 mK with 200 pW static power dissipation achieves $<2$ dB insertion loss and $>30$ dB isolation across DC–8 GHz, enabling integrated multiplexing of readout, flux bias, and drive signals at the qubit plane. Direct connection to transmon qubits preserves coherence times in the 100 µs range, addressing the input-output bottleneck in large-scale superconducting qubit systems."}, {"id": "2603.15804", "t": "Enhancing qubit readout fidelity with two-mode squeezing of the coherent measurement signal", "a": "Baleegh Abdo, William Shanks, Oblesh Jinka, J. R. Rozen", "d": "2026-03-18", "s": 81.7, "x": "This work enhances superconducting qubit readout fidelity by exploiting two-mode squeezed states generated at the signal and idler frequencies of a nondegenerate Josephson mixer, coherently combining simultaneous measurements to amplify the qubit-encoded quadrature while suppressing noise. The scheme achieves fidelity improvements of 2–6% for practical gains (2–13 dB) and noise levels (8–50 photons), with improvements of 0.05–0.25% remaining possible above 99.5% fidelity at $G = 20$ dB, without requiring hardware changes or in-situ phase matching."}, {"id": "2603.16522", "t": "Stroboscopic detection of itinerant microwave photons", "a": "Hanna Zeller, Lukas Danner, Max Hofheinz, Ciprian Padurariu, Joachim Ankerhold, Björn Kubala", "d": "2026-03-18", "s": 77.0, "x": "This paper presents a scheme for single-photon detection of itinerant microwave radiation using stroboscopically repeated projective measurements of a cavity coupled to a dc-biased Josephson junction device. By cascading a photon multiplier with the detector, detection efficiencies of 88.5% with dark counts $\\sim 10^{-4} \\gamma_a$ are achieved theoretically, promising near-unity efficiency for higher multiplication factors."}, {"id": "2603.16203", "t": "A Scalable Open-Source QEC System with Sub-Microsecond Decoding-Feedback Latency", "a": "Junyi Liu, Yi Lee, Yilun Xu, Gang Huang, Xiaodi Wu", "d": "2026-03-18", "s": 63.7, "x": "This work presents a fully integrated, open-source quantum error correction (QEC) system built on RISC-Q and implemented on AMD ZCU216 RFSoCs, combining distributed multi-core qubit control, fiber-optic networking, and hardware-accelerated decoding. The system achieves measured end-to-end decoding-feedback latency of 446 ns for a distance-3 surface code and extrapolates to sub-microsecond latency up to distance-21 surface codes (~881 physical qubits)."}, {"id": "2603.15758", "t": "Quantum Noise Suppression at Scale with Crosstalk-Robust Gate Sets", "a": "Andy J. Goldschmidt, Emilio Peláez Cisneros, Ryan Sitler, Kevin Olsson, Kaitlin N. Smith, Gregory Quiroz", "d": "2026-03-18", "s": 60.3, "x": "This work introduces crosstalk-robust gate sets (CRGS) designed via optimal control to suppress pairwise quantum crosstalk in parallel single-qubit operations on superconducting qubit devices. Demonstrations on IBM Brisbane (127-qubit Eagle processor with heavy-hex layout) and in-house transmon hardware show $4\\times$ median improvement in transverse-field Ising model simulation fidelity, $4$–$5\\times$ reduction in decay rates under dynamical decoupling, and enable faster two-qubit gates through hardware–software co-design."}, {"id": "2603.16502", "t": "High Fidelity Single-NV Qubit Quantum State Tomography by Photoelectric Readout", "a": "Boo Carmans, Michael Petrov, Milos Nesladek", "d": "2026-03-18", "s": 52.9, "x": "This work demonstrates Rabi phase quantum state tomography on a single NV center spin using photoelectric readout instead of conventional optical detection, achieving a reconstruction fidelity of $0.995 \\ \\pm 0.0062$ across 21 measurements. The photoelectric approach offers improved spatial resolution, integration with electronics, and compact device scaling while maintaining fidelity comparable to optical readout."}, {"id": "2603.13857", "t": "Readout-induced degradation of transmon lifetimes: interplay of TLSs and qubit spectral reshaping", "a": "Ziwen Huang, Jimmy Shih-Chun Hung, Mouktik Raha, Ming-Han Chou, Harry Levine, Alex Retzker, Connor T. Hann, David Hover, Fernando G. S. L. Brandão, Aashish A. Clerk, Arbel Haim, Oskar Painter", "d": "2026-03-17", "s": 97.7, "x": "This work develops a theory for readout-induced transmon lifetime degradation by incorporating drive-renormalized qubit spectral shapes beyond the weak-coupling limit, showing that the qubit emission spectrum becomes non-Lorentzian and depends sensitively on readout drive frequency even at fixed measurement rate. Experiments on a strongly dispersive transmon ($|\\chi|/\\kappa = 1$ to $4$) validate the predictions quantitatively and reveal that driving at the ground-state resonator frequency $\\omega_r^{(g)}$ minimizes $T_1$ degradation by producing the narrowest emission spectrum."}, {"id": "2603.13837", "t": "Millimeter Wave Readout of a Superconducting Qubit", "a": "Akash V. Dixit, Zachary L. Parrott, Dennis Chunikhin, Bradley Hauer, Trevyn F. Q. Larson, John D. Teufel", "d": "2026-03-17", "s": 94.2, "x": "A transmon qubit at $\\omega_q = 2\\pi \\times 3.1$ GHz is readout using a millimeter-wave cavity at $\\omega_r = 2\\pi \\times 34.7$ GHz with coupling rate $g = 2\\pi \\times 1.3$ GHz, achieving a large detuning ratio $\\omega_r/\\omega_q > 10$ that suppresses drive-induced unwanted state transitions. Measurement fidelity exceeds 99% with over 100 readout photons and no quantum-limited amplifier, with resilience demonstrated up to $1,000$ drive photons."}, {"id": "2603.13653", "t": "Quantum dial", "a": "Aashish Sah, Suman Kundu, Priyank Singh, Eemeli Forsbom, Vasilii Vadimov, Mikko Möttönen", "d": "2026-03-17", "s": 93.4, "x": "A quantum dial is a tunable on-chip band-stop filter integrated with a dc SQUID array that dynamically modulates qubit–environment coupling by several orders of magnitude on nanosecond timescales, enabling fast switching between isolation (T₁ > 150 µs), resonant control (99.9% gate fidelity at 40 ns, −110 dBm), and dissipative reset (T₁ ≈ 200 ns, >97% ground-state population in 1.2 µs from |e⟩, |f⟩, |h⟩). The same device performs near-Cramér–Rao-bound qubit thermometry with noise-equivalent temperature of 0.6 mK/√Hz at 60 mK, unifying reset, control, and readout functions on a single tunable transmission line without separate dissipative elements."}, {"id": "2603.15534", "t": "Analog-Digital Quantum Computing with Quantum Annealing Processors", "a": "Rahul Deshpande, Majid Kheirkhah, Chris Rich, Richard Harris, Jack Raymond, Emile Hoskinson, Pratik Sathe, Andrew J. Berkley, Stefan Paul, Brian Barch, Daniel A. Lidar, Markus Müller, Gabriel Aeppli, Andrew D. King, Mohammad H. Amin", "d": "2026-03-17", "s": 86.9, "x": "This work demonstrates analog-digital quantum computing in a 1178-qubit D-Wave quantum annealer using multicolor annealing to independently control source, target, and detector qubits. The protocol combines arbitrary-basis initialization and measurement via auxiliary qubits with coherent analog evolution under an effective XY Hamiltonian, achieving coherence times exceeding normalized evolution $|\\mathcal{J}|t/\\hbar \\gtrsim 100$."}, {"id": "2603.15356", "t": "Error semitransparent universal control of a bosonic logical qubit", "a": "Saswata Roy, Owen C. Wetherbee, Valla Fatemi", "d": "2026-03-17", "s": 86.8, "x": "This work demonstrates error semi-transparent (EsT) universal control of a bosonic logical qubit using linear drives on a binomial 'kitten' code in a superconducting cavity coupled to a transmon ancilla. EsT operations leverage dynamic encoding subspaces to achieve fault-tolerant gates with reduced infidelity conditioned on photon loss, extending active-manipulation lifetimes under quantum error correction."}, {"id": "2603.13726", "t": "Phononic Bragg Reflectors for Thermal Insulation of Scalable Cryogenic Control Electronics from Qubits", "a": "Isabelle V. Sprave, Denny Dütz, Sebastian Kock, René Otten, Tobias Hangleiter, Felix Mende, Marcus Wislicenus, Hendrik Bluhm", "d": "2026-03-17", "s": 75.3, "x": "This work demonstrates a phononic distributed Bragg reflector (DBR) cryopackaging concept to thermally isolate cryogenic control electronics from superconducting qubits while maintaining high-density electrical interconnects. Experiments on Ta/SiO$_2$ DBRs with 10 bilayers and thickness up to 600 nm achieve thermal conduction below 1 mW/cm$^2$ from 1.5 K to 100 mK, enabling Watt-level power dissipation at higher stages of a dilution refrigerator while keeping qubits near 100 mK."}, {"id": "2603.14455", "t": "Quantum-limited traveling-wave parametric amplifier based on DUV-defined planar structures", "a": "Hao Li, Marco Scigliuzzo, Evgenii Guzovskii, Seog-Tae Han, Kyungho Han, Tobias J. Kippenberg", "d": "2026-03-17", "s": 68.6, "x": "A compact four-wave-mixing TWPA is demonstrated using a hybrid DUV-lithography and electron-beam-defined Josephson-junction process, achieving a 6.6 mm × 6.6 mm footprint with broadband gain over 3–11 GHz, sub-dB insertion loss, and added noise of 0.4 photons above the standard quantum limit in the 4–8 GHz band. The device combines scalable planar fabrication with quantum-limited amplification performance suitable for frequency-multiplexed qubit readout."}, {"id": "2603.15610", "t": "Universal Weakly Fault-Tolerant Quantum Computation via Code Switching in the [[8,3,2]] Code", "a": "Shixin Wu, Dawei Zhong, Todd A. Brun, Daniel A. Lidar", "d": "2026-03-17", "s": 64.4, "x": "Code-switching between two versions of the [[8,3,2]] code enables universal fault-tolerant quantum computation in the error-detecting (postselected) regime. Version 1 supports weakly fault-tolerant logical Clifford gates via two-qubit rotations, while Version 2 supports transversal logical $\\overline{\\mathrm{CCZ}}$ via $T/T^\\dagger$ gates, yielding an overcomplete universal gate set with quadratic suppression of logical errors in accepted runs."}, {"id": "2603.15587", "t": "A direct controlled-phase gate between microwave photons", "a": "Adrian Copetudo, Amon M. Kasper, Tanjung Krisnanda, Gregoire Veyrac, Shushen Qin, Hui Khoon Ng, Yvonne Y. Gao", "d": "2026-03-17", "s": 59.2, "x": "This work demonstrates a Raman-assisted cross-Kerr interaction between microwave photons in two superconducting cavities without populating the mediating transmon coupler, achieving a controlled-phase gate with ~5% infidelity and performing bosonic parity checks that preserve the code space. The engineered coupling is $g_{ab}/2\\pi \\approx 90$ kHz (two orders of magnitude stronger than the residual always-on interaction), enabling deterministic entanglement generation and opening a pathway toward fault-tolerant bosonic quantum computing."}, {"id": "2603.14113", "t": "Analysis of Hydrogen Contamination in Al/AlOx/Al Josephson Junctions", "a": "Yu Zhu, Aldilene Saraiva-Souza, Félix Beaudoin, Hong Guo", "d": "2026-03-17", "s": 58.0, "x": "This work combines molecular dynamics simulations using CHGNet with NEGF-DFT transport calculations in NanoDCAL to investigate hydrogen contamination in Al/AlO$_x$/Al Josephson junctions, finding that H atom incorporation follows a beta-binomial distribution across 400 samples and acts as p-type dopant to increase tunneling transmission. For 2.56 at.% average hydrogen content, the predicted Josephson energy is $E_J/h = 10.92 \\\\ \\pm 0.26$ GHz, providing an atomistic picture of device-to-device variability."}, {"id": "2603.13460", "t": "Characterization of Radiation-Induced Errors in Superconducting Qubits Protected with Various Gap-Engineering Strategies", "a": "H. Douglas Pinckney, Thomas McJunkin, Alan W. Hunt, Patrick M. Harrington, Hannah P. Binney, Max Hays, Yenuel Jones-Alberty, Kate Azar, Felipe Contipelli, Renée DePencier Piñero, Jeffrey M. Gertler, Michael Gingras, Aranya Goswami, Cyrus F. Hirjibehedin, Mingyu Li, Mathis Moes, Bethany M. Niedzielski, Mallika T. Randeria, Ryan Sitler, Matthew K. Spear, Hannah Stickler, Jiatong Yang, Wouter Van De Pontseele, Mollie E. Schwartz, Jeffrey A. Grover, Kevin Schultz, Kyle Serniak, Joseph A. Formaggio, William D. Oliver", "d": "2026-03-16", "s": 97.8, "x": "Radiation-induced correlated errors in transmon qubits are characterized using $^{241}$Am α-particles (5.5 MeV) and a pulsed 10–20 MeV electron linac, showing that gap engineering at both the Josephson junction ($δΔ_\\mathrm{JJ}$) and capacitor/ground-plane interface ($δΔ_\\mathrm{M1}$) mitigates but does not eliminate radiation sensitivity. A coupled quasiparticle dynamics model qualitatively reproduces the observed $T_1$, $T_2$, and transient frequency shifts across different gap profiles and junction orientations."}, {"id": "2603.12367", "t": "Absence of Charge Offset Drift in a Transmon Qubit", "a": "Adria Rospars, Hector Hutin, Yannick Seis, Cristóbal Lledó, Réouven Assouly, Romain Cazali, Rémy Dassonneville, Ambroise Peugeot, Alexandre Blais, Audrey Bienfait, Benjamin Huard", "d": "2026-03-16", "s": 97.8, "x": "A tantalum-based transmon qubit exhibits an exceptionally stable charge offset $n_g$ pinned at zero for nearly three months across two thermal cycles with $T_1 = 21$–$24$ µs, a phenomenon attributed to an incomplete wet-etch of tantalum on sapphire creating a highly inductive ($L > 20$ µH) or resistive ($R \\gg 0.2$ GΩ) path in parallel with the Josephson junction. The charge offset stability was fragile and disappeared in later cooldowns, but deliberately engineering such a parallel layer could eliminate charge-offset drift in superconducting circuits."}, {"id": "2603.13183", "t": "Quantifying surface losses in superconducting aluminum microwave resonators", "a": "Elizabeth Hedrick, Faranak Bahrami, Alexander C. Pakpour-Tabrizi, Atharv Joshi, Q. Rumman Rahman, Ambrose Yang, Ray D. Chang, Matthew P. Bland, Apoorv Jindal, Guangming Cheng, Nan Yao, Robert J. Cava, Andrew A. Houck, Nathalie P. de Leon", "d": "2026-03-16", "s": 97.4, "x": "This work measures microwave absorption from surface two-level systems in superconducting aluminum resonators and correlates losses with materials characterization, finding that the native 2.7 nm AlOx layer dominates losses with a loss tangent of $(1.74 ± 0.7) × 10^{-2}$, over three times higher than tantalum oxide. HF treatment reduces oxide thickness to 1.9 nm and lowers loss by a factor of 1.8, but rapid oxide regrowth and fabrication residues limit improvements, with Al interfaces estimated to contribute 27% of relaxation in state-of-the-art Ta-on-Si qubits incorporating Al Josephson junctions."}, {"id": "2603.13114", "t": "Experimental realization of a $\\cos(2\\varphi)$ transmon qubit", "a": "Erwan Roverc'h, Alvise Borgognoni, Marius Villiers, Kyrylo Gerashchenko, W. Clarke Smith, Christopher Wilson, Benoit Douçot, Alexandru Petrescu, Philippe Campagne-Ibarcq, Zaki Leghtas", "d": "2026-03-16", "s": 97.0, "x": "This work demonstrates a $\\cos(2\\varphi)$ transmon qubit using a KITE (Kinetic Interference co-Tunneling Element) operating in the soft transmon regime with qubit frequency $\\omega_q/2\\pi = 13.6$ MHz and $\\mathcal{E}_{J2}/\\mathcal{E}_C = 22$, achieving charge protection via Cooper-pair-parity symmetry. The measured $T_1 = 70$ µs and $T_2^\\mathrm{echo} = 2.5$ µs are limited by $1/f$ flux noise ($A_\\Phi = 5.6$ µ$\\Phi_0$/Hz) rather than dielectric loss, with a 100-fold suppression of the charge matrix element demonstrating protection at a level that places dielectric decay limits above 10 ms."}, {"id": "2603.13174", "t": "Beta Tantalum Transmon Qubits with Quality Factors Approaching 10 Million", "a": "Atharv Joshi, Apoorv Jindal, Paal H. Prestegaard, Faranak Bahrami, Elizabeth Hedrick, Matthew P. Bland, Tunmay Gerg, Guangming Cheng, Nan Yao, Robert J. Cava, Andrew A. Houck, Nathalie P. de Leon", "d": "2026-03-16", "s": 96.6, "x": "This work demonstrates that $\\beta$-Ta transmon qubits on sapphire achieve quality factors approaching $10^7$, with the best qubit recording $Q = (10.1 \\pm 1.3) \\times 10^6$ and mean $Q$ across 11 qubits of $(5.6 \\pm 2.3) \\times 10^6$, challenging the assumption that the low $T_c = 0.7$ K of $\\beta$-Ta is detrimental to qubit performance. Surface two-level systems dominate losses with apparent loss tangent $\\tan\\delta = (1.6 \\pm 0.1) \\times 10^{-3}$ (twice that of $\\alpha$-Ta), while $\\beta$-Ta films exhibit large kinetic inductance with magnetic penetration depth $\\lambda = (1.78 \\pm 0.02)$ µm and sheet kinetic inductance up to $259$ pH$/\\square$, enabling compact device designs."}, {"id": "2603.13124", "t": "On-Demand Correlated Errors in Superconducting Qubits from a Particle Accelerator", "a": "Thomas McJunkin, A. W. Hunt, Yenuel Jones-Alberty, T. M. Haard, M. K. Spear, James Shackford, Tom Gilliss, Mayra Amezcua, C. A. Watson, T. M. Sweeney, J. A. Hoffmann, Kevin Schultz", "d": "2026-03-16", "s": 93.3, "x": "This work presents CLIQUE, a facility coupling an 18.5 MeV electron linear accelerator to a dilution refrigerator to study on-demand ionizing radiation effects in superconducting qubits, and demonstrates radiation-induced relaxation, excitation, detuning, and dephasing errors in a nine-qubit transmon chip with energy deposition closely matching cosmic-ray muons. Single linac electrons enable precise timing and rapid event statistics collection, revealing junction-orientation-dependent error signatures with low-gap-island qubits showing relaxation decay times of 6–9 ms versus 300–400 μs for high-gap-island qubits."}, {"id": "2603.13175", "t": "Fluxon Time-Delay Readout of a Superconducting Qubit Protected by a Spectral Gap in a Josephson Transmission Line", "a": "Shunsuke Kamimura, Aree Taguchi, Masamitsu Tanaka, Tsuyoshi Yamamoto", "d": "2026-03-16", "s": 93.1, "x": "This work theoretically investigates a readout scheme for transmon qubits based on time delay of single flux quanta (fluxons) propagating in Josephson transmission lines (JTLs) with capacitive coupling. The approach exploits the spectral gap in the JTL to exponentially suppress radiative decay and unwanted transitions while avoiding fluxon pinning, offering integration advantages over conventional dispersive readout."}, {"id": "2603.12327", "t": "A Traveling-Wave Parametric Amplifier With Integrated Diplexers", "a": "C. Denney, K. Genter, K. Cicak, J. D. Teufel, J. Aumentado, F. Lecocq, M. Malnou", "d": "2026-03-16", "s": 85.5, "x": "This work presents a traveling-wave parametric amplifier with integrated on-chip input and output diplexers for pump delivery and routing, eliminating external microwave components. The device achieves 13 dB broadband gain across 2 GHz (6–8 GHz signal band) with average system-added noise of 2 quanta, as measured by shot-noise tunnel junction calibration."}, {"id": "2603.12312", "t": "Qubit measurement and backaction in a multimode nonreciprocal system", "a": "B. T. Miller, Lindsay Orr, A. Metelmann, F. Lecocq", "d": "2026-03-16", "s": 71.3, "x": "This paper develops a general theoretical framework for understanding qubit measurement and backaction in multimode nonreciprocal readout networks, and experimentally implements a three-mode parametric device to validate the theory. The work extends phase-space methods to handle arbitrary networks of linearly coupled modes with embedded qubits, demonstrating quantitative agreement between measured and predicted measurement rates and dephasing with no free parameters."}, {"id": "2603.12391", "t": "Hybrid Analog-Digital Simulation of the Abelian Higgs model", "a": "Muhammad Asaduzzaman, Rayleigh W. Parker, Noah Goss, Ahmed I. Mohamed, Max Neiderbach, Zane Ozzello, Ravi K. Naik, Alexander F. Kemper, Irfan Siddiqi, Yannick Meurice, Machiel S. Blok", "d": "2026-03-16", "s": 68.8, "x": "This work demonstrates hybrid analog-digital and fully digital quantum simulations of the (1+1)D Abelian Higgs model using superconducting transmon qutrits on two lattice sites. Both protocols observe real-time dynamics of electric-field-like observables ($L_z$ and $L_z^2$) by encoding the spin-1 truncated model naturally into the three-level Hilbert space of transmons."}, {"id": "2603.11188", "t": "Rhenium as a material platform for long-lived transmon qubits", "a": "Yanhao Wang, Suhas Ganjam, Ishan Narra, Luigi Frunzio, Robert J. Schoelkopf", "d": "2026-03-13", "s": 95.0, "x": "Rhenium on sapphire transmons achieve $T_1$ up to 407 µs at 5 GHz, competitive with tantalum despite suppression of native oxide formation. A loss budget constructed from tripole and segmented stripline resonators reveals surface loss dominates, with the rhenium-aluminum interface contributing negligibly."}, {"id": "2603.12114", "t": "Measurement-Induced State transitions in Inductively-Shunted Transmons", "a": "Nicholas Zobrist, John Mark Kreikebaum, Mostafa Khezri, Sergei V. Isakov, Brian J. Lester, Yaxing Zhang, Agustin Di Paolo, Daniel Sank, W. Clarke Smith", "d": "2026-03-13", "s": 94.8, "x": "This work characterizes measurement-induced state transitions (MIST) in inductively-shunted transmon (IST) qubits, showing experimentally that the inductive shunt eliminates offset-charge dependence and stabilizes MIST compared to standard transmons. The results are explained using full quantum simulations and a modified semiclassical model that accounts for the IST's unbounded potential energy structure."}, {"id": "2603.11889", "t": "Probing the memory of a superconducting qubit environment", "a": "Nicolas Gosling, Denis Bénâtre, Nicolas Zapata, Paul Kugler, Mitchell Field, Sumeru Hazra, Simon Günzler, Thomas Reisinger, Martin Spiecker, Mathieu Féchant, Ioan M. Pop", "d": "2026-03-13", "s": 88.1, "x": "The authors demonstrate that non-Poissonian quantum jump correlations in superconducting qubits reveal coupling to long-lived two-level systems (TLSs) that violate the Born-Markov approximation and retain memory of past qubit states. By fitting the Solomon equations to measured quantum jump dynamics and performing correlation spectroscopy versus qubit frequency and electric field bias, they identify individual TLSs with lifetimes orders of magnitude exceeding the qubit $T_1$ and characterize their electric-field susceptibility."}, {"id": "2603.11692", "t": "Demonstration of High-Fidelity Gates in a Strongly Anharmonic with Long-Coherence C-Shunt Flux Qubit", "a": "Silu Zhao, Li Li, Weiping Yuan, Xinhui Ruan, Jinzhe Wang, Bingjie Chen, Yunhao Shi, Guihan Liang, Shi Xiao, Jiacheng Song, Jinming Guo, Xiaohui Song, Kai Xu, Heng Fan, Zhongcheng Xiang, Dongning Zheng", "d": "2026-03-13", "s": 72.4, "x": "This work demonstrates high-fidelity single-qubit gates on a C-shunt flux qubit combining large anharmonicity ($\\mathcal{A}/2\\pi = 848$ MHz) with long relaxation time ($T_1 = 23$ µs) using DRAG-corrected Gaussian pulses and randomized benchmarking. Gate fidelities exceed 99.9% for all single-qubit rotations, including 99.99% for the identity gate and 99.91–99.94% for $\\pi/2$ gates around $X$ and $Y$ axes."}, {"id": "2603.11469", "t": "Impact of Oxygen Vacancies in Josephson Junction on Decoherence of Superconducting Qubits", "a": "Hanqin Bai, Shi-Yao Hou, Mu Lan", "d": "2026-03-13", "s": 68.2, "x": "This work uses first-principles calculations and ab initio molecular dynamics to investigate how oxygen vacancies in amorphous Al$_2$O$_3$ Josephson junction barriers affect superconducting qubit coherence. Both the coordination environment (2-, 3-, or 4-fold) and concentration of $V_O$ defects are shown to dramatically alter electrical conductivity, which translates to critical current noise and reduced coherence times via $1/f$ noise mechanisms."}, {"id": "2603.11568", "t": "Hybrid Quantum Error Correction and Mitigation by Purification", "a": "Jonathan Raghoonanan, Tim Byrnes", "d": "2026-03-13", "s": 53.3, "x": "We introduce purification quantum error suppression (PQES), which uses SWAP tests on multiple noisy copies to physically suppress errors while retaining all measurement outcomes through signed branch averaging, accessing the power-purified state $\\rho^N/\\mathrm{Tr}(\\rho^N)$. PQES combines quantum error correction's physical error removal with quantum error mitigation's outcome-record processing, achieving error thresholds of $p_{\\mathrm{th}}=3/4$ for local depolarizing noise and $p_{\\mathrm{th}}=1/2$ for local dephasing on product-state families."}, {"id": "2603.11018", "t": "Mitigating crosstalk errors for simultaneous single-qubit gates on a superconducting quantum processor", "a": "Jaap J. Wesdorp, Eric Hyyppä, Joona Andersson, Janos Adam, Rohit Beriwal, Ville Bergholm, Saga Dahl, Simone Diego Fasciati, Alejandro Gomez Friero, Zheming Gao, Daria Gusenkova, Andrew Guthrie, Johannes Heinsoo, Tuukka Hiltunen, Keiran Holland, Amin Hosseinkhani, Sinan Inel, Joni Ikonen, Shan W. Jolin, Kristinn Juliusson, Seung-Goo Kim, Anton Komlev, Roope Kokkoniemi, Otto Koskinen, Joonas Kylmälä, Alessandro Landra, Julia Lamprich, Magdalena Lehmuskoski, Nizar Lethif, Per Liebermann, Tianyi Li, Aleksi Lintunen, Fabian Marxer, Kunal Mitra, Jakub Mrożek, Lucas Ortega, Miha Papič, Matti Partanen, Alexander Plyushch, Stefan Pogorzalek, Michael Renger, Jussi Ritvas, Sampo Saarinen, Indrajeet Sagar, Matthew Sarsby, Mykhailo Savytskyi, Ville Selinmaa, Ivan Takmakov, Brian Tarasinski, Francesca Tosto, David Vasey, Panu Vesanen, Jeroen Verjauw, Alpo Välimaa, Nicola Wurz, Hsiang-Sheng Ku, Frank Deppe, Juha Hassel, Caspar Ockeloen-Korppi, Wei Liu, Jani Tuorila, Chun Fai Chan, Attila Geresdi, Antti Vepsäläinen", "d": "2026-03-12", "s": 93.8, "x": "This work demonstrates crosstalk error mitigation for simultaneous single-qubit gates on a 49-qubit superconducting processor by combining model-based qubit frequency optimization with pulse shaping. The authors introduce an analytical model of crosstalk-induced gate error and experimentally achieve 99.96% mean fidelity for simultaneous $X_{\\pi/2}$ gates at 16 ns duration on 46 qubits, with simulations showing scalability to 1000 qubits."}, {"id": "2603.10699", "t": "Efficient and accurate two-qubit-gate operation in a high-connectivity transmon lattice utilizing a tunable coupling to a shared mode", "a": "Tuure Orell, Hao Hsu, Joona Andersson, Jani Tuorila, Frank Deppe, Hsiang-Sheng Ku", "d": "2026-03-12", "s": 85.0, "x": "This theoretical work proposes a honeycomb lattice architecture for superconducting qubits with high connectivity, where each qubit is coupled via dedicated tunable couplers to a shared central mode, enabling all-to-all connectivity within unit cells. A novel single-step CZ gate protocol is introduced with gate times roughly 2× faster than prior sequential MOVE-CZ-MOVE schemes, achieving infidelities ~$6 \\times 10^{-7}$ in the minimal two-qubit system."}, {"id": "2603.10224", "t": "Reducing Quantum Error Mitigation Bias Using Verifiable Benchmark Circuits", "a": "Joseph Harris, Kevin Lively, Peter Schuhmacher", "d": "2026-03-12", "s": 74.3, "x": "This work introduces verifiable benchmark circuits that mirror application circuit structure to reduce bias in quantum error mitigation methods, achieving up to 15% fidelity improvements on 100-qubit circuits with up to 2000 entangling gates on IBM superconducting hardware. The method is applied to zero-noise extrapolation and a new variant called benchmarked-noise ZNE (bnZNE), validated on Trotterized Ising and Heisenberg simulations."}, {"id": "2603.10193", "t": "Charge-tunable Cooper-pair diode", "a": "Jon Ortuzar, Stefano Trivini, Leonard Edens, F. Sebastian Bergeret, Jose Ignacio Pascual", "d": "2026-03-12", "s": 56.2, "x": "A superconducting diode effect is demonstrated in nanoscale lead islands on graphene using Coulomb blockade to break particle-hole symmetry without external magnetic fields or ferromagnets. Gate-tunable nonreciprocal Cooper-pair currents are achieved through resonant charge states, enabling rectification with a rectification ratio near 10 and microwave photodetection with responsivity $1.38$ nA/pW at $10$–$20$ GHz."}, {"id": "2603.10506", "t": "Temporal-Mode Engineering for Multiplexed Microwave Photons and Mode-Selective Quantum State Transfer", "a": "Keika Sunada, Takeaki Miyamura, Kohei Matsuura, Zhiling Wang, Jesper Ilves, Shingo Kono, Yasunobu Nakamura", "d": "2026-03-12", "s": 54.1, "x": "This work demonstrates temporal-mode engineering for microwave photons using superconducting qubits, generating four orthogonal temporal modes via photon-shaping techniques with fixed-frequency transmons. Mode-selective absorption is achieved with efficiencies exceeding $0.89$ for matched modes and below $0.13$ for orthogonal modes, preserving orthogonality among rejected photons for multiplexed quantum networks."}, {"id": "2603.09870", "t": "Crosstalk in Multi-Qubit Fluxonium Architectures with Transmon Couplers", "a": "Martijn F. S. Zwanenburg, Christian Kraglund Andersen", "d": "2026-03-11", "s": 97.4, "x": "This work numerically investigates spectator-qubit crosstalk in scaled-up fluxonium-transmon-fluxonium (FTF) architectures, finding that trivial scaling limits fidelity below 90%. The authors demonstrate that reducing coupling strength to $g_{FT}/2\\pi = 200$ MHz and dynamically tuning inactive transmons to an off position suppresses spectator errors below $10^{-4}$ in 1D and 2D systems with up to six spectator qubits."}, {"id": "2603.08801", "t": "Large Language Model-Assisted Superconducting Qubit Experiments", "a": "Shiheng Li, Jacob M. Miller, Phoebe J. Lee, Gustav Andersson, Christopher R. Conner, Yash J. Joshi, Bayan Karimi, Amber M. King, Howard L. Malc, Harsh Mishra, Hong Qiao, Minseok Ryu, Xuntao Wu, Siyuan Xing, Haoxiong Yan, Jian Shi, Andrew N. Cleland", "d": "2026-03-11", "s": 87.7, "x": "The paper introduces HAL (Heuristic Autonomous Lab), an LLM-driven system that automates superconducting qubit experiments by generating and invoking Python code for pulse-level control via a knowledge base. The framework is demonstrated through autonomous resonator characterization and reproduction of a quantum non-demolition leakage measurement ($L = 0.124 \\ \\pm 0.017$) directly from published literature."}, {"id": "2603.09096", "t": "Reconfigurable Superconducting Quantum Circuits Enabled by Micro-Scale Liquid-Metal Interconnects", "a": "Zhancheng Yao, Nicholas E. Fuhr, Nicholas Russo, David W. Abraham, Kevin E. Smith, David J. Bishop", "d": "2026-03-11", "s": 75.8, "x": "This work demonstrates gallium-based liquid-metal interconnects for modular superconducting quantum circuits, enabling non-destructive chip replacement while maintaining microwave performance comparable to conventional coplanar waveguides. The liquid-metal interconnects show negligible degradation after multiple thermal cycles and achieve virtually zero resistance before and after module replacement, with the observed kinetic inductance fraction attributed to $β$-tantalum identified via X-ray characterization."}, {"id": "2603.09913", "t": "Quantum control of the environment in open quantum systems enables rapid qubit reset", "a": "Carlos Ortega-Taberner, Eoin O'Neill, Paul Eastham", "d": "2026-03-11", "s": 61.5, "x": "This work demonstrates that polaron formation due to qubit-environment entanglement limits dissipative reset fidelity in transmon qubits, and shows this can be overcome by time-dependent control of the system-environment coupling. Optimized smooth switching protocols achieve excited-state populations of $10^{-6}$ in 10 ns at zero temperature, with achievable protocols reaching $10^{-6.5}$."}, {"id": "2603.09302", "t": "Fictitious Copy Quantum Error Mitigation", "a": "Akib Karim, Harish J. Vallury, Muhammad Usman", "d": "2026-03-11", "s": 50.3, "x": "Fictitious Copy Quantum Error Mitigation (FCQEM) corrects quantum errors through classical post-processing of probability distributions by squaring them, requiring no additional quantum resources and performing equivalently to first-order truncated Virtual Distillation for eigenstates. Experiments on a Rigetti 82-qubit superconducting processor demonstrate that FCQEM combined with Quantum Computed Moments recovers ground state energies of HeH$^+$ to $10^{-5}$ Ha and a 10-qubit TFIM to 0.3% accuracy despite noise."}, {"id": "2603.06848", "t": "Qubit Noise Sensing via Induced Photon Loss in a Superconducting Cavity", "a": "Nitzan Kahn, Dror Garti, Uri Goldblatt, Lalit M. Joshi, Fabien Lafont, Serge Rosenblum", "d": "2026-03-10", "s": 93.7, "x": "This work demonstrates a cavity-based method for measuring qubit frequency noise by detecting photon loss induced by dressed dephasing in a high-Q superconducting cavity coupled to a transmon. Repeated mid-circuit qubit measurements with post-selection separate noise-induced photon loss from intrinsic cavity decay, enabling noise spectroscopy at frequencies inaccessible to conventional qubit-based methods."}, {"id": "2603.06830", "t": "Anharmonicity and Charge-Noise Sensitivity of Fraunhofer Qubit", "a": "Longyu Ma, Tony Liu, Javad Shabani, Kasra Sardashti, Vladimir E. Manucharyan, Maxim G. Vavilov", "d": "2026-03-10", "s": 85.8, "x": "The Fraunhofer qubit uses Fraunhofer interference in a wide ballistic Josephson junction to achieve flux tunability while preserving charge-noise insensitivity. As magnetic flux approaches $\\Phi_0$, the junction potential transforms from quadratic to triangular, dramatically enhancing anharmonicity; tight-binding simulations confirm this enhancement persists with disorder and inhomogeneous potentials."}, {"id": "2603.06802", "t": "Quasiparticle spectroscopy in tantalum films with different Ta/sapphire interfaces", "a": "Bicky S. Moirangthem, Kamal R. Joshi, Anthony P. Mcfadden, Jin-Su Oh, Amlan Datta, Makariy A. Tanatar, Florent Lecocq, Raymond W. Simmonds, Lin Zhou, Matthew J. Kramer, Ruslan Prozorov", "d": "2026-03-10", "s": 80.3, "x": "Tunnel-diode resonator measurements of magnetic susceptibility reveal that Ta films with lower microwave quality factors ($Q_i$) exhibit non-activated, non-exponential low-temperature behavior indicating subgap spectral weight, while Ta deposited on a 5 nm Nb interlayer shows clean activated response consistent with a fully gapped spectrum. The superconducting-state quasiparticle spectrum correlates with device performance, with the Nb interlayer dramatically improving both the gap structure and interface quality."}, {"id": "2603.06817", "t": "Heterogeneous quantum error-correcting codes", "a": "Omid Khosravani, Guillermo Escobar-Arrieta, Kenneth R. Brown, Mauricio Gutierrez", "d": "2026-03-10", "s": 57.5, "x": "This work introduces heterogeneous quantum error-correcting codes where distinct qubit types with different error rates or noise biases are strategically placed within Clifford-deformed surface codes and studies their performance using tensor network decoding. For qubits with identical bias but different error rates, placing noisier qubits in the bulk (high syndrome multiplicity) yields thresholds exceeding 0.4 with exponential improvements in logical error rate; for qubits with identical error rates but different biases, the optimal strategy reverses, placing high-bias qubits on the boundary and increasing thresholds from 0.29 to 0.40 at $\\eta_{\\mathrm{high}} = 1000$."}, {"id": "2603.07190", "t": "Long-time storage of entangled logical states in decoherence-free subspaces", "a": "L. Zhang, Y. -L. Xu, Y. -K. Wu, C. Zhang, Z. -B. Cui, Y. -Y. Chen, W. -Q. Lian, J. -Y. Ma, B. -X. Qi, Y. -F. Pu, Z. -C. Zhou, L. He, P. -Y. Hou, L. -M. Duan", "d": "2026-03-10", "s": 50.7, "x": "A cryogenic trapped-ion system storing two-qubit entangled states encoded in decoherence-free subspaces of four $^{171}$Yb$^+$ ions achieves storage lifetimes of approximately one hour with $\\tau_\\mathrm{lower}(|\\psi_L^+\\rangle) = 4.9 \\times 10^3$ s and $\\tau_\\mathrm{lower}(|\\phi_L^+\\rangle) = 3.2 \\times 10^3$ s. The protocol employs dual-type qubit encoding for crosstalk-free sympathetic cooling, individually addressed entangling gates with 99.1% average Bell-state fidelity, and multi-state detection to separate leakage errors."}, {"id": "2603.06472", "t": "A persistent-current-biased and current-actuated switch for superconducting circuits", "a": "Ziyi Zhao, Eva Gurra, Michael R. Vissers, K. W. Lehnert", "d": "2026-03-09", "s": 91.5, "x": "This work demonstrates a superconducting switch based on an inductive Wheatstone bridge of tunable rf-SQUID inductors, controlled via a persistent current bias and direct current actuation rather than flux threading. The switch achieves >20 dB isolation over 1.9 GHz bandwidth, handles >100 pW power, and exhibits >600 MHz modulation bandwidth suitable for large-scale quantum processors."}, {"id": "2603.10039", "t": "A Non-Foster Superconducting Broadband Matching Network", "a": "Andrew K. Yi, Pamela Stark, Chelsea Bartram", "d": "2026-03-09", "s": 77.0, "x": "This work presents a Josephson junction-based non-Foster impedance matching network designed to achieve broadband signal matching without the bandwidth-sensitivity tradeoff inherent to passive linear circuits, with application to axion dark matter searches. WRSPICE simulations demonstrate power transfer of $-4$ dB across a 40 MHz band (30–70 MHz) comparable to a high-$Q$ resonant capacitive match at a single frequency, with potential bandwidth extension to $\\geq 10$ GHz if circuit models remain valid."}, {"id": "2603.04566", "t": "Universal Hamiltonian control in a planar trimon circuit", "a": "Vivek Maurya, Daria Kowsari, Kumar Saurav, S. A. Shanto, R. Vijay, Daniel A. Lidar, Eli M. Levenson-Falk", "d": "2026-03-06", "s": 92.5, "x": "A planar trimon superconducting circuit with three transmon-like modes coupled by strong all-to-all cross-Kerr interactions enables high-fidelity universal control of multi-qubit gates and qudit operations. The device demonstrates conditional-rotation gates with 99.93% fidelity via randomized benchmarking, Raman-mediated entangling gates (iSWAP and ibSWAP) at 99.19% and 99.59% fidelity, and qudit dynamical decoupling on up to 8 levels with coherence comparable to single qubits."}, {"id": "2603.04564", "t": "Demonstrating Noise-adapted Quantum Error Correction With Break-Even Performance", "a": "Vismay Joshi, Anubhab Rudra, Sourav Dutta, Siddharth Dhomkar, Prabha Mandayam", "d": "2026-03-06", "s": 80.9, "x": "This work demonstrates break-even performance of a noise-adapted 3-qubit probabilistic quantum error correction code on IBM superconducting qubits, achieving logical qubit lifetimes of ~740 µs compared to bare qubit T₁ ~ 220 µs. The scheme combines hardware-efficient variational circuits for encoding/recovery, dynamical decoupling (CHaDD) to suppress crosstalk dephasing, and introduces a gain metric accounting for post-selection overhead."}, {"id": "2603.04584", "t": "Fault-tolerant execution of error-corrected quantum algorithms", "a": "Michael A. Perlin, Zichang He, Anthony Alexiades Armenakas, Pablo Andres-Martinez, Tianyi Hao, Dylan Herman, Yuwei Jin, Karl Mayer, Chris Self, David Amaro, Ciaran Ryan-Anderson, Ruslan Shaydulin", "d": "2026-03-06", "s": 61.1, "x": "This work demonstrates fault-tolerant execution of two quantum algorithms—QAOA and HHL—using the $[[7,1,3]]$ Steane code on Quantinuum H2 and Helios trapped-ion processors, achieving near-break-even performance with encoded circuits outperforming unencoded ones for up to 8 logical qubits. The results include an improved logical $T$ gate with infidelity $2.6(4)\\times10^{-3}$, identification of Steane-swap as the optimal QEC protocol, and key demonstrations that active error correction and repeat-until-success limits improve algorithm performance."}, {"id": "2603.05145", "t": "Quantum advantages for syndrome-aware noisy logical observable estimation", "a": "Kento Tsubouchi, Hyukgun Kwon, Liang Jiang, Nobuyuki Yoshioka", "d": "2026-03-06", "s": 54.7, "x": "This work develops an information-theoretic framework to quantify how error-syndrome information improves logical observable estimation in fault-tolerant quantum computing. The key finding is a sharp separation: classical syndrome-aware protocols (fixed measurement basis) can improve effective logical error rates by at most a factor of two on average, but quantum syndrome-aware protocols (adaptive measurement basis) can achieve exponentially smaller error rates with multiple code blocks."}, {"id": "2603.05383", "t": "Temperature-Dependent Dielectric Function of Tantalum Nitride Formed by Atomic Layer Deposition for Tunnel Barriers in Josephson Junctions", "a": "Ekta Bhatia, Aaron Lopez Gonzalez, Yoshitha Hettige, Tuan Vo, Sandra Schujman, Kevin Musick, Thomas Murray, Kim Kisslinger, Chenyu Zhou, Mingzhao Liu, Satyavolu S. Papa Rao, Stefan Zollner", "d": "2026-03-06", "s": 53.8, "x": "Temperature-dependent ellipsometric measurements of ALD-deposited TaN films (13 nm and 25 nm thicknesses) show a dielectric function with band gap 1.5–1.8 eV, mid-infrared transparency, and no free-carrier absorption from 80–600 K, demonstrating insulating behavior suitable for Josephson junction tunnel barriers. XPS reveals N/Ta ratio ~1.2 throughout the films, with superior thermal stability and lower roughness compared to AlOx, enabling thicker barriers while maintaining required critical current densities for superconducting quantum circuits."}, {"id": "2603.05249", "t": "Robust and optimal control of open quantum systems", "a": "Zi-Jie Chen, Hongwei Huang, Lida Sun, Qing-Xuan Jie, Jie Zhou, Ziyue Hua, Yifang Xu, Weiting Wang, Guang-Can Guo, Chang-Ling Zou, Luyan Sun, Xu-Bo Zou", "d": "2026-03-06", "s": 51.9, "x": "This work introduces the approximate Open-GRAPE algorithm, a computationally efficient method for optimizing quantum controls in open systems that accounts for both parameter uncertainties and decoherence, demonstrated experimentally in a superconducting cavity-transmon system achieving infidelity below 0.60%. The algorithm maintains $\\mathcal{O}(d^2)$ complexity (only a modest constant factor increase over Closed-GRAPE) while dramatically improving the yield of high-fidelity pulses by over 340-fold compared to conventional approaches."}, {"id": "2603.03586", "t": "Analysis of an all-to-all connected star array of transmon qubits", "a": "Ricardo A. Pinto", "d": "2026-03-05", "s": 83.7, "x": "This paper analyzes quantum $XX$ and $ZZ$ couplings in a capacitively coupled three-transmon-qubit star array using dressed-state perturbation theory and numerical solutions of the Schrödinger equation. The work demonstrates that highly-connected systems exhibit multiple types of $ZZ$ couplings (three pairwise and one all-to-all) that create crosstalk channels and identifies detuning regimes where couplings can be suppressed."}, {"id": "2603.13322", "t": "Energy relaxation via quantum thermalization: A superconducting qubit coupled to an interacting many-body two-level system", "a": "Xue-Yi Guo", "d": "2026-03-05", "s": 50.6, "x": "This work demonstrates that irreversible exponential energy relaxation in a superconducting qubit emerges from intrinsic many-body thermalization of an interacting TLS environment, without external baths or phenomenological dissipation. The relaxation times exhibit $T_1, T_2 \\propto J_{q,\\tau}^{-2}$ scaling consistent with Fermi's golden rule, arising directly from unitary many-body dynamics driven by stochastic frequency fluctuations (FFTIE sequence) that enable information erasure."}, {"id": "2603.02415", "t": "Modulating Surface Acoustic Wave Generation through Superconductivity", "a": "Andrew Christy, Yuzan Xiong, Rui Sun, Yi Li, Kenneth O. Chua, Andrew H. Comstock, Junming Wu, Sidong Lei, Frank Tsui, Megan N. Jackson, Dali Sun, Valentine Novosad, James F. Cahoon, Wei Zhang", "d": "2026-03-04", "s": 73.7, "x": "Surface acoustic waves generated using superconducting niobium nitride (NbN) interdigitated transducers on lithium niobate show a sharp transition in transmission across the superconducting critical temperature ($T_c \\approx 11.4$ K), achieving a $16\\times$ modulation of $S_{21}$ between normal and superconducting states. The device exhibits a $Q$-factor of 2220 with a free spectral range of 0.733 MHz and a single-strip reflection coefficient $|r_s| \\approx 0.0043$, an order of magnitude lower than aluminum, enabling integration into all-nitride quantum architectures."}, {"id": "2603.03166", "t": "Enhancing the Energy Resolution in Scanning Tunneling Microscopy: from dynamical Coulomb blockade to cavity quantum electrodynamics", "a": "Xianzhe Zeng, Janis Siebrecht, Haonan Huang, Sujoy Karan, Joachim Ankerhold, Klaus Kern, Christian R. Ast", "d": "2026-03-04", "s": 70.6, "x": "The authors achieve energy resolution of 3.7 µeV at 10 mK in scanning tunneling microscopy by combining local electromagnetic shielding and low-pass filtering directly at the cryogenic scan head, improving spectroscopic precision by nearly an order of magnitude. The enhanced sensitivity reveals that the Josephson current couples to centimeter-scale cavity modes of the scan head, establishing a direct connection between atomic-scale tunneling and macroscopic cavity quantum electrodynamics."}, {"id": "2603.03051", "t": "Scaling of silicon spin qubits under correlated noise", "a": "Juan S. Rojas-Arias, Leon C. Camenzind, Yi-Hsien Wu, Peter Stano, Akito Noiri, Kenta Takeda, Takashi Nakajima, Takashi Kobayashi, Giordano Scappucci, Daniel Loss, Seigo Tarucha", "d": "2026-03-04", "s": 57.0, "x": "This work characterizes spatial noise correlations in a five-qubit Si/SiGe spin array and assesses their impact on quantum error correction, finding two distinct noise sources: global magnetic field drift producing perfect correlations independent of distance, and charge noise from two-level fluctuators generating short-range correlations decaying with separation. While the magnetic drift poses a fundamental challenge for QEC that requires mitigation strategies, the measured charge noise correlations are moderate, tunable via gate voltages, and compatible with fault-tolerant operation requiring only modest qubit overhead."}, {"id": "2603.03157", "t": "Achieving speedup in Dark Matter search experiments with a transmon-based NISQ algorithm", "a": "Roberto Moretti, Pietro Campana, Rodolfo Carobene, Alessandro Cattaneo, Marco Gobbo, Danilo Labranca, Matteo Borghesi, Marco Faverzani, Elena Ferri, Sara Gamba, Angelo Nucciotti, Andrea Giachero", "d": "2026-03-04", "s": 55.9, "x": "An ancilla-assisted gate-based protocol enhances sensitivity to hidden photon kinetic mixing using a single two-qubit entangling gate on NISQ devices, achieving up to 10-fold reduction in integration time compared to Rabi-sampling experiments. Under realistic noise with three years of data taking, the projected exclusion limit on the mixing parameter reaches $\\varepsilon \\approx 1 \\times 10^{-14}$ across $2.5$–$6.0$ GHz ($10$–$25$ µeV)."}, {"id": "2603.03015", "t": "Analytical Quantum Full-Wave Analysis of Few-Photon Transport Through a Superconducting Cavity Qubit", "a": "Soomin Moon, Thomas E. Roth", "d": "2026-03-04", "s": 53.1, "x": "This work develops analytical quantum full-wave solutions for single- and two-photon transport through a rectangular waveguide cavity containing a transmon qubit coupled to two coaxial ports using quantum input-output theory. The analysis reveals dramatically different photon scattering signatures between single- and two-photon regimes across the good and bad cavity limits of cavity QED."}, {"id": "2603.01672", "t": "Extremely weak electron-phonon coupling in Josephson junctions built on InAs on Insulator", "a": "Giorgio De Simoni, Sebastiano Battisti, Alessandro Paghi, Lucia Sorba, Francesco Giazotto", "d": "2026-03-03", "s": 75.1, "x": "Al/InAsOI Josephson junctions exhibit exceptionally weak electron-phonon coupling with $\\Sigma \\approx (3$-$4) \\times 10^7$ W/(m$^3$K$^n$) and $n \\approx 5.8$ at sub-Kelvin temperatures, enabling strong thermal decoupling while maintaining high-quality superconductivity with $T_c \\approx 1.2$ K. The platform combines transparent S-Sc interfaces, full electrostatic tunability, and a noise-equivalent temperature of 100-200 μK/Hz for Josephson thermometry, making it suitable for coherent caloritronics and gate-controlled thermal circuits."}, {"id": "2603.01612", "t": "Sustaining high-fidelity quantum logic in neutral-atom circuits via mid-circuit operations", "a": "Rui Lin, You Li, Le-Tian Zheng, Tai-Ran Hu, Si-Yuan Chen, Hong-Ming Wu, Yu-Chen Zhang, Hao-Wen Cheng, Yu-Hao Deng, Zhan Wu, Ming-Cheng Chen, Jun Rui, Chao-Yang Lu, Jian-Wei Pan", "d": "2026-03-03", "s": 74.6, "x": "This work demonstrates sustainable high-fidelity quantum logic in neutral-atom arrays by integrating mid-circuit cooling and re-initialization to counteract motional heating and atom loss across deep circuits. A controlled logic gate achieving 99.60(1)% raw fidelity is improved to 99.81(1)% via non-destructive erasure detection, with fidelities maintained at ~99.8% across multiple operational rounds without degradation."}, {"id": "2603.00441", "t": "Optimizing CMOS-compatible, superconducting titanium nitride resonators: Deposition conditions and structuring processes", "a": "Simon J. K. Lang, Alexandra Schewski, Ignaz Eisele, Johannes Weber, Carla Moran-Guizan, Zhen Lou, Moritz Singer, Benedikt Schoof, Marc Tornow, Thomas Mayer, Daniela Zahn, Rui N. Pereira, Christoph Kutter", "d": "2026-03-03", "s": 70.6, "x": "This work systematically investigates TiN CPW resonators on 200 mm high-resistivity Si wafers, isolating how deposition conditions, dry-etch power, and resist-strip temperature affect two-level-system (TLS) losses across three distinct crystal orientations (111, 200, mixed). The dominant loss mechanism is interfacial oxide formation at metal-air and substrate-air interfaces during structuring, recoverable by buffered oxide etch, yielding $\\delta_{\\mathrm{TLS}} = 9.67 \\times 10^{-7}$ and $Q_i \\approx 10^6$."}, {"id": "2603.01676", "t": "4-Pixel NbN Hot-Electron Bolometer Integrated in a Si$_3$N$_4$ Planar Optical Waveguide with On-Chip Fiber-Alignment Trench", "a": "N. A. Vovk, G. A. Matveev, M. A. Mumlyakov, M. V. Shibalov, I. A. Filippov, I. D. Burkov, S. D. Perov, N. V. Porohov, N. N. Osipov, M. A. Tarkhov", "d": "2026-03-03", "s": 68.3, "x": "A four-pixel NbN hot-electron bolometer array is integrated with individual Si$_3$N$_4$ planar waveguides on a single chip, with fiber coupling via U-shaped grooves etched in the substrate. The measured voltage responsivity reaches 3800 V/W at 3 GHz with process reproducibility across pixels ($T_c = 7.45$–7.52 K, responsivity spread $\\sim$10–15%), demonstrating effective optical isolation via on-chip Si$_3$N$_4$ scatterers despite 10 µm waveguide spacing."}, {"id": "2603.00837", "t": "ReloQate: Transient Drift Detection and In-Situ Recalibration in Surface Code Quantum Error Correction", "a": "Maxwell Poster, Jason Chadwick, Jonathan Mark Baker", "d": "2026-03-03", "s": 55.2, "x": "This work develops a real-time logical error rate (LER) predictor for surface code QEC by correlating detector fire rate (DFR)—readily available from stabilizer measurements—with LER using circuits simulated with physical error rates from real hardware. The approach pairs this predictor with a dynamic remapping scheme that relocates drifted logical qubits to fresh tiles while their original tiles undergo recalibration, demonstrating effective drift mitigation for small code distances."}, {"id": "2603.02106", "t": "Obstacles to Continuous Quantum Error Correction via Parity Measurements", "a": "Anton Halaski, Christiane P. Koch", "d": "2026-03-03", "s": 54.9, "x": "Continuous quantum error correction requires weak continuous parity measurements, but implementing these via two-body qubit-meter couplings in circuit QED and other platforms causes uncorrectable dephasing of logical states. The fundamental issue is that approximating required three-body interactions from native two-body couplings lifts degeneracy in one parity subspace, leading to distinguishability and entanglement with the meter during non-equilibrium dynamics."}, {"id": "2603.01987", "t": "Cavity-enhanced optical readout and control of nuclear spin qubits", "a": "Alexander Ulanowski, Johannes Früh, Fabian Salamon, Adrian Holzäpfel, Andreas Reiserer", "d": "2026-03-03", "s": 52.4, "x": "All-optical initialization, coherent control, and single-shot readout of $^{167}$Er nuclear spin qubits are demonstrated by embedding dopants in yttrium orthosilicate within a 65 MHz linewidth Fabry-Perot cavity that selectively enhances spin-preserving transitions. A large 6.8 T magnetic field freezes paramagnetic impurities, enabling 91(2)% readout fidelity, $T_2^* = 0.62(3)$ ms dephasing time, and coherence times reaching 0.28(8) s under dynamical decoupling, establishing a promising platform for fiber-based quantum networks at telecommunications wavelengths."}, {"id": "2602.24003", "t": "3D Integrated Embedded Filters for Superconducting Quantum Circuits", "a": "Waqas Ahmad, Gioele Consani, Mohammad Tasnimul Haque, Jacob Dunstan, Brian Vlastakis", "d": "2026-03-02", "s": 93.2, "x": "This work demonstrates integration of Purcell filters into multilayer PCBs for superconducting quantum processors, with each embedded triangular patch antenna filter coupling to up to nine readout resonators and providing ~1000-fold radiative isolation at the qubit frequency. Experimental validation on a 35-qubit OQC-Toshiko device achieved median $T_1 = 84$ µs and $T_2^{\\mathrm{echo}} = 110$ µs while maintaining fast readout with external quality factors $Q_{\\mathrm{ext}} \\sim 8 \\times 10^3$."}, {"id": "2602.24098", "t": "A frequency-agile microwave-optical interface for superconducting qubits", "a": "Yufeng Wu, Yiyu Zhou, Haoqi Zhao, Danqing Wang, Matthew D. LaHaye, Daniel L. Campbell, Hong X. Tang", "d": "2026-03-02", "s": 88.6, "x": "A cascaded microwave-to-microwave (M2M) and microwave-to-optical (M2O) transduction system demonstrates continuous frequency coverage from 5.0 to 8.5 GHz using flux-tunable NbN kinetic-inductance resonators, enabling optical readout of superconducting qubits detuned by gigahertz-scale offsets from the M2O native resonance. Optical readout of a qubit at 7.339 GHz (1.7 GHz detuned from the M2O resonance at 5.669 GHz) yields $T_1 = 28.7 ± 3.1$ µs and $T_2 = 2.6 ± 0.3$ µs, consistent with microwave readout measurements."}, {"id": "2602.23888", "t": "Characterization of Josephson Junction Aging and Annealing Under Different Environments", "a": "Rangga P. Budoyo, Rasanayagam S. Kajen, Bing Wen Cheah, Long H. Nguyen, Rainer Dumke", "d": "2026-03-02", "s": 81.3, "x": "This work characterizes aging and annealing of Al/AlO$_x$/Al Josephson junctions over 2–3 months under different storage environments and thermal conditions. Aging follows a logarithmic curve where the amplitude is set by fabrication (oxidation parameters) while aging speed is governed by storage conditions, with ambient atmosphere aging 3–5× faster than nitrogen or vacuum storage."}, {"id": "2602.23544", "t": "High-Temporal-Resolution Measurements of the Impacts of Ionizing Radiation on Superconducting Qubits", "a": "Jihee Yang, Thomas J. Carroll, Philip Mason, Robert Schwartz, Kenneth M. O'Hara, Jennifer Lund, Michael Gottschalk, Timothy Stephenson, Lawrence H. Friedman, Francisco Yumiceva, Justin Hackley, Aurelius L. Graninger, Chris Rotella, Pat Warner, Jonathan M. Cochran, Adam V. Bruce, Melody Wagner, James Wenner, Stan Steers, Christopher Moore, Alex Marakov, Bradley G. Christensen", "d": "2026-03-02", "s": 72.8, "x": "Superconducting transmons on a silicon chip were monitored at 1 μs temporal resolution using co-integrated microwave kinetic inductance detectors (MKIDs) to study ionizing radiation effects. No correlation was found between TLS scrambling events and cosmic-ray-induced ionizing radiation across 371 TLS events and 18,454 radiation triggers, suggesting previous charge-jump correlations arise from lower-energy processes."}, {"id": "2602.24075", "t": "Highly-linear flux-to-voltage transducer based on superconducting quantum interference proximity transistors", "a": "Angelo Greco, Giorgio De Simoni, Francesco Giazotto", "d": "2026-03-02", "s": 68.6, "x": "The bi-SQUIPT is a flux-to-voltage transducer employing a dual-loop proximity-based architecture with differential readout that achieves $60$ dB spurious-free dynamic range (SFDR) while maintaining femtowatt-level power dissipation and operational stability up to $600$ mK. The device linearizes the inherently nonlinear periodic response of conventional SQUIDs by exploiting flux-modulated density-of-states changes in proximitized weak links, with performance comparable to superconducting quantum arrays but without the scaling penalties."}, {"id": "2602.23975", "t": "Coherent Control of Population and Quantum Coherence in Superconducting Circuits", "a": "Madan Mohan Mahana, Gunjan Yadav, Tarak Nath Dey", "d": "2026-03-02", "s": 56.7, "x": "This review article comprehensively covers coherent control of population and quantum coherence in superconducting quantum circuits (SQCs), progressing from field quantization through the Jaynes-Cummings model to multilevel phenomena in circuit QED. The work demonstrates how dressed-state engineering enables quantum-optical effects such as electromagnetically induced transparency (EIT), Autler-Townes splitting (ATS), and stimulated Raman adiabatic passage (STIRAP) in superconducting artificial atoms coupled to microwave resonators."}, {"id": "2602.22970", "t": "Demonstrating Single Photon Counting with Kinetic Inductance Detectors from 3.8 to 25 $μ$m", "a": "Wilbert G. Ras-Vinke, Kevin Kouwenhoven, Jochem J. A. Baselmans, Kenichi Karatsu, David J. Thoen, Vignesh Murugesan, Pieter J. de Visser", "d": "2026-02-27", "s": 61.1, "x": "This work demonstrates single-photon counting with superconducting microwave kinetic inductance detectors (MKIDs) across the mid-infrared from 3.8 to 25 µm, achieving energy resolving powers $E/\\delta E$ of 9.9, 5.9, 3.2, and 3.3 respectively with dark count rates of 4, 8, 34, and 48 mHz. Membrane-suspended aluminum detectors reach phonon-loss-limited performance at 3.8 µm, more than doubling performance versus solid-substrate devices."}, {"id": "2602.22117", "t": "Loss Mechanisms in High-coherence Multimode Mechanical Resonators Coupled to Superconducting Circuits", "a": "Raquel Garcia Belles, Alexander Anferov, Lukas F. Deeg, Loris Colicchio, Arianne Brooks, Tom Schatteburg, Maxwell Drimmer, Ines C. Rodrigues, Rodrigo Benevides, Marco Liffredo, Jyotish Patidar, Oleksandr Pshyk, Matteo Fadel, Luis Guillermo Villanueva, Sebastian Siol, Gerhard Kirchmair, Yiwen Chu", "d": "2026-02-26", "s": 85.0, "x": "This work studies dissipation mechanisms in high-overtone bulk acoustic-wave resonators (HBARs) coupled to superconducting qubits, finding that defect density in the piezoelectric AlN layer and its interface with sapphire limit coherence. The devices achieve phonon lifetimes of 396 µs and mechanical coherence times approaching 806 µs in the quantum regime, yielding a record cooperativity $C_{T_2} = 1.1 \times 10^5$ for circuit quantum acoustodynamics."}, {"id": "2602.21293", "t": "Teleportation transition of surface codes on a superconducting quantum processor", "a": "Yiren Zou, Hong-Kuan Xia, Aosai Zhang, Xuhao Zhu, Feitong Jin, Qingyuan Wang, Yu Gao, Chuanyu Zhang, Ning Wang, Zhengyi Cui, Fanhao Shen, Zehang Bao, Zitian Zhu, Jiarun Zhong, Gongyu Liu, Jia-Nan Yang, Yihang Han, Yiyang He, Jiayuan Shen, Han Wang, Yanzhe Wang, Jiahua Huang, Xinrong Zhang, Sailang Zhou, Hang Dong, Jinfeng Deng, Yaozu Wu, Zixuan Song, Hekang Li, Zhen Wang, Chao Song, Qiujiang Guo, Pengfei Zhang, Guo-Yi Zhu, H. Wang", "d": "2026-02-26", "s": 80.9, "x": "This work demonstrates teleportation of distance-7 topological surface codes on a 125-qubit superconducting processor, mapping out the phase diagram by tuning coherent errors and showing that the teleportation threshold increases from $0.122(2)\\pi$ (at $\\theta=\\pi/2$) to $0.175(5)\\pi$ (at $\\theta=\\pi/4$) through electric–magnetic duality symmetry. The experiment achieves logical error rates of $0.025(3)$ for Bob's teleported qubits and successfully teleports arbitrary logical states including magic states, validating operation below threshold with single-qubit gate fidelity 99.94% and two-qubit gate fidelity 99.64%."}, {"id": "2602.22174", "t": "Beyond Single-Shot Fidelity: Chernoff-Based Throughput Optimization in Superconducting Qubit Readout", "a": "Sinan Bugu", "d": "2026-02-26", "s": 79.6, "x": "This work reframes superconducting qubit readout optimization from maximizing single-shot fidelity to minimizing wall-clock certification time by treating dispersive measurement as a stochastic communication channel governed by classical Chernoff information. For transmon parameters with $\\chi/2\\pi = 1.2$ MHz, $\\kappa/2\\pi = 5.0$ MHz, $n̄ = 80$, $\\eta = 0.45$, and $T_1 = 30$ µs, the throughput-optimal integration time $\\tau_\\mathrm{rate} \\approx 1.22$ µs exceeds the fidelity-optimal time $\\tau_\\mathrm{fid} \\approx 0.78$ µs, yielding 9–11% certification speedups that saturate at 1.13× in high-power, high-overhead regimes."}, {"id": "2602.22211", "t": "Computing with many encoded logical qubits beyond break-even", "a": "Shival Dasu, Matthew DeCross, Andrew Y. Guo, Ali Lavasani, Jan Behrends, Asmae Benhemou, Yi-Hsiang Chen, Karl Mayer, Chris N. Self, Selwyn Simsek, Basudha Srivastava, M. S. Allman, Jake Arkinstall, Justin G. Bohnet, Nathaniel Q. Burdick, J. P. Campora, Alex Chernoguzov, Samuel F. Cooper, Robert D. Delaney, Joan M. Dreiling, Brian Estey, Caroline Figgatt, Cameron Foltz, John P. Gaebler, Alex Hall, Craig A. Holliman, Ali A. Husain, Akhil Isanaka, Colin J. Kennedy, Yuga Kodama, Nikhil Kotibhaskar, Nathan K. Lysne, Ivaylo S. Madjarov, Michael Mills, Alistair R. Milne, Brian Neyenhuis, Annie J. Park, Anthony Ransford, Adam P. Reed, Steven J. Sanders, Charles H. Baldwin, David Hayes, Ben Criger, Andrew C. Potter, David Amaro", "d": "2026-02-26", "s": 63.0, "x": "This work demonstrates computations with many encoded logical qubits that outperform their unencoded counterparts using high-rate iceberg quantum error detecting and correcting codes on a trapped-ion quantum processor. Beyond-break-even performance is achieved with 48–94 logical qubits across benchmarks including state preparation, logical gates, GHZ state preparation, and partially fault-tolerant simulation of a three-dimensional $XY$ model."}, {"id": "2602.20275", "t": "Pulse-level control for quantum resource preparation", "a": "K. De La Ossa Doria, T. Merlo Vergara, D. Goyeneche", "d": "2026-02-25", "s": 55.8, "x": "This work demonstrates pulse-level quantum state preparation in transmon qubits by directly optimizing entanglement measures rather than targeting specific states, achieving Bell states with negativity $\\mathcal{N}(\\rho_{01}) \\approx 0.499$, GHZ states with three-tangle $\\tau_3 \\approx 0.999$, and W states with balanced squared concurrences $\\mathcal{C}^2(\\rho_{ij}) \\approx 0.44$ on the IBM Sherbrooke architecture. The resource-oriented approach yields substantially shorter pulse sequences—1379 dt for Bell, 3750 dt for GHZ, and 6132 dt for W states—compared to transpiled gate-based circuits (2912 dt, 5315 dt, and 8224 dt respectively), with reduced expressivity that naturally suppresses barren plateaus in variational algorithms."}, {"id": "2602.20614", "t": "First- and Second-Order Digital Quantum Simulation of Three-Level Jaynes-Cummings Dynamics on Superconducting Quantum Processors", "a": "J. Thirunirai Selvam, S. Saravana Veni, Ria Rushin Joseph", "d": "2026-02-25", "s": 52.3, "x": "This work presents a digital quantum simulation of three-level Jaynes-Cummings dynamics on IBM Quantum superconducting processors, encoding a qutrit in two qubits and a cavity mode in one qubit, with evolution implemented via first- and second-order Suzuki-Trotter decomposition. Comparison across IBM backends reveals a trade-off between algorithmic accuracy and hardware noise: second-order Trotter provides better excitation-number conservation and reduced population leakage, but first-order circuits achieve higher aggregate fidelity (~94.6% on ibm_marrakesh vs ~88.4% for second-order), with ibm_torino most faithfully preserving Jaynes-Cummings selection rules despite lower calibration-based fidelity."}, {"id": "2602.20002", "t": "Electrical post-fabrication tuning of aluminum Josephson junctions at room temperature", "a": "Christian Križan, Maurizio Toselli, Irshad Ahmad, Hadi Khaksaran, Marcus Rommel, Nermin Trnjanin, Janka Biznárová, Mamta Dahiya, Emil Hogedal, Halldór Jakobsson, Andreas Nylander, Jonas Bylander, Per Delsing, Giovanna Tancredi", "d": "2026-02-24", "s": 95.7, "x": "Electrical post-fabrication tuning of Al-AlO$_x$-Al Josephson junctions using room-temperature voltage pulses can increase junction resistance up to 270% with a stepped manipulation protocol, enabling transmon qubit frequency shifts of nearly 2 GHz while maintaining quality factors above 1 million. The rate of resistance increase scales exponentially with pulse amplitude ($V_0 = 55$–91 mV depending on oxide dose), and post-manipulation relaxation exhibits both fixed and manipulation-dependent contributions that follow logarithmic time dependence, halting at cryogenic temperatures and resuming at room temperature."}, {"id": "2602.19042", "t": "Quantum Error Correction and Dynamical Decoupling: Better Together or Apart?", "a": "Victor Kasatkin, Mario Morford-Oberst, Arian Vezvaee, Daniel A. Lidar", "d": "2026-02-24", "s": 60.9, "x": "This work develops a unified framework using weight enumerator polynomials to analyze when logical dynamical decoupling (LDD) combined with quantum error correction or detection outperforms either approach alone. The authors derive closed-form entanglement-fidelity expressions and establish conditions under which hybrid protocols achieve advantage, illustrated through analysis of the $[[7,1,3]]$, $[[5,1,3]]$, $[[13,1,3]]$, and $[[4,2,2]]$ codes."}, {"id": "2602.20123", "t": "CQM: Cyclic Qubit Mappings", "a": "Maxwell Poster, Sayam Sethi, Jonathan Baker", "d": "2026-02-24", "s": 58.9, "x": "Cyclic Qubit Mappings (CQM) is a dynamic remapping technique that periodically relocates logical qubits within a surface code architecture to mitigate spatiotemporal hardware heterogeneity and guarantee each qubit experiences the average logical error rate across positions. The approach requires minimal compilation overhead and addresses uncertainty in physical error rates by spreading qubit exposure across the device topology during idle periods via lattice surgery operations."}, {"id": "2602.18555", "t": "Engineering quantum criticality and dynamics on an analog-digital simulator", "a": "Alexandra A. Geim, Nazli Ugur Koyluoglu, Simon J. Evered, Rahul Sahay, Sophie H. Li, Muqing Xu, Dolev Bluvstein, Nik O. Gjonbalaj, Nishad Maskara, Marcin Kalinowski, Tom Manovitz, Ruben Verresen, Susanne F. Yelin, Johannes Feldmeier, Markus Greiner, Vladan Vuletic, Mikhail D. Lukin", "d": "2026-02-24", "s": 56.6, "x": "This work demonstrates an analog-digital hybrid quantum simulator using $^{87}$Rb Rydberg atom arrays, coherently mapping between interacting Rydberg and digital hyperfine qubits to engineer and probe complex many-body dynamics. On a 271-site kagome lattice, the team prepares a non-equilibrium $\\mathrm{U}(1)$ quantum spin liquid via Floquet driving and closed-loop optimization, observing key signatures including equal-amplitude dimer superpositions, many-body coherences extending over 18 sites, and universal correlations matching field theory predictions."}, {"id": "2602.19399", "t": "Imaging the Superconducting Proximity Effect in S-S'-S Transition Edge Sensors", "a": "Austin R. Kaczmarek, Samantha Walker, Jason Austermann, Douglas Bennett, W. Bertrand Doriese, Shannon M. Duff, Johannes Hubmayr, Kelsey Morgan, Michael D. Niemack, Dan Schmidt, Daniel Swetz, Joel Ullom, Joel Weber, Katja C. Nowack", "d": "2026-02-24", "s": 52.0, "x": "This work uses scanning SQUID susceptometry to spatially image the diamagnetic response in S-S'-S transition edge sensors, directly resolving proximity effects that extend over tens of micrometers and reveal how neighboring superconducting leads enhance while normal metal contacts suppress the local transition temperature. Ginzburg-Landau and self-consistent Usadel modeling quantitatively capture the observed spatial structure of the superconducting state, establishing a framework for understanding proximity-induced tuning of superconducting properties in heterogeneous device geometries."}, {"id": "2602.18388", "t": "Qubit error bursts in superconducting quantum processors of Quantum Inspire: quasiparticle pumping and anomalous time dependence", "a": "G. R. Di Carlo, M. Samiotis, A. Kamlapure, M. Finkel, N. Muthusubramanian, M. W. Beekman, N. Haider, M. S. Moreira, J. F. Marques, B. Segers, S. Vallés-Sanclemente, L. DiCarlo", "d": "2026-02-23", "s": 95.2, "x": "This study investigates qubit error bursts in two Quantum Inspire transmon processors (Starmon-5 with Dolan junctions and Starmon-7 with Manhattan junctions) and reveals junction-specific signatures, including quasiparticle pumping in Dolan devices and an anomalous surge-and-suppression pattern in burst rate. Burst rates of $\\gamma_\\mathrm{kept} \\approx 1.5$ and $1$ min$^{-1}$ are comparable to prior work after area normalization, with recovery times differing by $\\times 8$ between devices ($t_\\mathrm{rec} \\sim 2$ ms versus $\\sim 250$ µs)."}, {"id": "2602.18122", "t": "Flux-Activated Resonant Control of a Bosonic Quantum Memory", "a": "Fernando Valadares, Aleksandr Dorogov, Tanjung Krisnanda, May Chee Loke, Ni-Ni Huang, Pengtao Song, Yvonne Y. Gao", "d": "2026-02-23", "s": 85.6, "x": "This work demonstrates direct resonant control of a superconducting cavity using flux-tunable Jaynes–Cummings interactions, achieving preparation of arbitrary Fock state superpositions and Givens rotations between cavity levels. The implementation integrates broadband on-chip flux delivery with cascaded Chebyshev filtering to protect the cavity lifetime at $T_1 = 590 ± 40$ µs while enabling nanosecond-timescale transmon frequency tuning."}, {"id": "2602.16889", "t": "In situ calibration of microwave attenuation and gain using a cryogenic on-chip attenuator", "a": "Thomas Descamps, Linus Andersson, Vittorio Buccheri, Simon Sundelin, Mohammed Ali Aamir, Simone Gasparinetti", "d": "2026-02-20", "s": 91.8, "x": "A compact cryogenic noise source based on a chromium on-chip attenuator heated with nanowatt-level DC power enables in situ calibration of microwave drive-line attenuation and amplifier noise by comparing Johnson–Nyquist noise generated via Joule and RF heating. The method determines input-line attenuation to ±0.5 dB over 4–8 GHz with millisecond thermal response times and negligible cryostat perturbation, yielding 23.6 ± 2.8 photons of added noise and 70.2 ± 0.5 dB gain for a HEMT-based readout chain."}, {"id": "2602.17249", "t": "Near-single-domain superconducting aluminum films on GaAs(111)A with exceptional crystalline quality for scalable quantum circuits", "a": "Hsien-Wen Wan, Yi-Ting Cheng, Chao-Kai Cheng, Jui-Min Chia, Chien-Ting Wu, Sheng-Shiuan Yeh, Chia-Hung Hsu, Jueinai Kwo, Minghwei Hong", "d": "2026-02-20", "s": 67.8, "x": "Superconducting Al films grown on GaAs(111)A by molecular beam epitaxy achieve record-low twin-domain ratios of $5 \times 10^{-5}$ to $3 \times 10^{-4}$ and azimuthal rocking-curve FWHM down to $0.55°$, establishing a near-single-domain platform. Critical temperatures approach bulk values with atomically abrupt interfaces and macroscopic in-plane uniformity confirmed by synchrotron X-ray diffraction, EBSD, and STEM."}, {"id": "2602.17438", "t": "Fault-tolerant preparation of arbitrary logical states in the cat code", "a": "Zi-Jie Chen, Weizhou Cai, Liang-Xu Xie, Qing-Xuan Jie, Xu-Bo Zou, Guang-Can Guo, Luyan Sun, Chang-Ling Zou", "d": "2026-02-20", "s": 67.8, "x": "This work presents a fault-tolerant framework for preparing arbitrary logical states in the four-legged cat code using error-detectable operations in 3D superconducting cavities coupled to ancilla qubits. Numerical simulations achieve logical infidelities of $10^{-4}$ with quadratic suppression of first-order errors in photon loss and dephasing channels."}, {"id": "2602.16948", "t": "Fault-tolerant interfaces for quantum LDPC codes", "a": "Matthias Christandl, Omar Fawzi, Ashutosh Goswami", "d": "2026-02-20", "s": 54.8, "x": "This paper constructs fault-tolerant interfaces for quantum low-density parity-check codes that map encoded logical qubits to bare physical qubits with constant space overhead, improving on previous constructions requiring polylogarithmic overhead. The key innovation is a sequential procedure that gradually decreases the encoding level while increasing the number of code blocks in parallel, enabling constant-overhead fault-tolerant state preparation."}, {"id": "2602.15948", "t": "Enhanced Superconducting Nanowire Single Photon Detector Performances using Silicon Capping", "a": "C. Klein, S. Cohen, T. Descamps, A. Iovan, P. Zolotov, P. Vennéguès, I. Florea, F. Semond, V. Zwiller", "d": "2026-02-19", "s": 56.0, "x": "Silicon capping of NbTiN superconducting nanowire single-photon detectors (SNSPDs) suppresses oxidation and enables superconductivity in films as thin as 3 nm at 3 K, while significantly extending the detection saturation plateau from visible to 2050 nm. Devices with 250 nm wide nanowires and 20×20 μm² active areas maintain sub-50 ps timing jitter and show saturated detection efficiency across visible through near-infrared wavelengths."}, {"id": "2602.14165", "t": "Bidirectional Quantum Processor Interfacing by a 4-Kelvin Analog Signal Chain for Superconducting Qubit Control and Quantum State Readout", "a": "Deepak R, Lokendra Kanawat, Jayadeep K, Priyesh Shukla", "d": "2026-02-17", "s": 90.0, "x": "This paper presents a complete bidirectional cryogenic analog signal processing architecture operating at 4 K for superconducting qubit control and readout, featuring a PLL-based I/Q modulator, power amplifier, LNA with 14 dB gain, and 8-PSK demodulator. All circuits are validated through LTSpice simulations with 180 nm cryogenic MOSFET models, achieving I/Q phase error below 2°, image rejection exceeding 35 dB, and symbol error rate below $10^{-6}$."}, {"id": "2602.14333", "t": "High-fidelity Quantum Readout Processing via an Embedded SNAIL Amplifier", "a": "Leon Bello, Boris Mesits, Michael Hatridge, Hakan E. Türeci", "d": "2026-02-17", "s": 88.1, "x": "This paper proposes embedding a SNAIL amplifier on-chip within the readout chain of superconducting qubits to enable coherent, directional signal processing and parametric amplification, replacing bulky external isolators and achieving higher readout fidelity through a \"Catch-Process-Release\" protocol. The architecture uses frequency-multiplexed parametric interactions to sequentially squeeze, displace, convert, and amplify the readout signal while it remains in the high-Q readout and SNAIL resonators, then releases it to a fast output resonator for extraction."}, {"id": "2602.13736", "t": "Quantum dynamics of microwave photons in synthetic frequency dimension", "a": "Zheshu Xie, Luojia Wang, Jiawei Qiu, Libo Zhang, Yuxuan Zhou, Ziyu Tao, Wenhui Huang, Yongqi Liang, Jiajian Zhang, Yuanzhen Chen, Song Liu, Jingjing Niu, Yang Liu, Youpeng Zhong, Luqi Yuan, Dapeng Yu", "d": "2026-02-17", "s": 79.7, "x": "A superconducting qubit integrated with a 16 m aluminum coaxial cable and SQUID-based modulator realizes single-photon quantum dynamics in a synthetic frequency lattice with $\\Omega_{\\mathrm{fsr}}/2\\pi = 7.33$ MHz and mode coherence times $T_1 \\sim 29.1$ µs, $T_2 \\sim 57.9$ µs. The platform demonstrates quantum random walks, Bloch oscillations with period $T_B = 5$ µs, non-adiabatic unidirectional frequency conversion, band-structure mapping, and synthetic gauge fields via dual-tone driving."}, {"id": "2602.13563", "t": "Flux Pumped Kerr-Free Parametric Amplifier", "a": "Kagan Yanik, Irwin Huang, Bibek Bhandari, Bingcheng Qing, Ahmed Hajr, Ke Wang, David I. Santiago, Irfan Siddiqi, Justin Dressel, Andrew N. Jordan", "d": "2026-02-17", "s": 77.1, "x": "This paper proposes a flux-pumped superconducting parametric amplifier using symmetrically threaded SQUIDs (STS) with a linear inductor in the central branch that achieves Kerr-free operation at a static flux bias of $F = -\\pi/2$. The design maintains near-quantum-limited phase-preserving gain and efficiency up to 25 dB, substantially outperforming conventional single-loop SQUID-based JPAs limited by residual Kerr nonlinearity."}, {"id": "2602.13456", "t": "Shunt-controlled resistive state of superconducting wires", "a": "Khalil Harrabi, Zain Alzoubi, Leonardo Cadorim, Milorad Milosevic", "d": "2026-02-17", "s": 57.1, "x": "This work experimentally and numerically investigates how shunt resistance controls the resistive state of superconducting NbTiN wires (20 nm thick, 10 μm wide), revealing two distinct dynamic regimes: hot-spot and phase-slip behavior accessed through shunt-dependent current redistribution. Time-dependent Ginzburg–Landau simulations show that higher shunt resistance ($R_s \to 10 \\\\\\\\\\\bf{R}_{\\\\mathrm{GL}}$) accelerates the characteristic timescale $\\tau = L_K/(R_s + R_w)$ for Cooper-pair destruction/recovery cycles, transitioning the system from periodic hot-spot formation to stabilized quasi-phase-slip lines at smaller currents."}, {"id": "2602.14694", "t": "Demonstrating and Benchmarking Classical Shadows for Lindblad Tomography", "a": "Rune Thinggaard Birke, Johann Bock Severin, Malthe A. Marciniak, Emil Hogedal, Andreas Nylander, Irshad Ahmad, Amr Osman, Janka Biznárová, Marcus Rommel, Anita Fadavi Roudsari, Jonas Bylander, Giovanna Tancredi, Daniel Stilck França, Albert Werner, Christopher W. Warren, Jacob Hastrup, Svend Krøjer, Morten Kjaergaard", "d": "2026-02-17", "s": 55.5, "x": "This work experimentally demonstrates shadow Lindblad tomography (SLT) on a superconducting 5-qubit transmon processor, achieving exponential reduction in measurement overhead compared to extensible Lindblad tomography (ELT) while maintaining agreement within uncertainties. The protocol learns time-independent Lindblad parameters describing idling dynamics and two-qubit couplings in 9 hours versus an estimated 58 hours for ELT on the full processor."}, {"id": "2602.13399", "t": "Protection of Exponential Operation using Stabilizer Codes in the Early Fault Tolerance Era", "a": "Dawei Zhong, Todd A. Brun", "d": "2026-02-17", "s": 53.7, "x": "This work develops a systematic scheme to encode exponential maps $\\exp(-i\\theta P)$ into small stabilizer codes with simple circuit structures and low overhead, achieving 4–7× noise reduction compared to unencoded operations at current device noise levels ($p \\approx 10^{-3}$) with less than 3% postselection overhead. The encoding leverages postselection to suppress first-order logical errors without requiring full fault-tolerance, targeting near-term early fault-tolerant quantum computing applications."}, {"id": "2602.13593", "t": "Josephson-like magnetic tunnel junction -- transition from classical to quantum regime", "a": "V. V. Yurlov, P. N. Skirdkov, K. A. Zvezdin, A. K. Zvezdin", "d": "2026-02-17", "s": 51.9, "x": "This paper establishes a theoretical framework for implementing Josephson-like qubits using easy-plane magnetic tunnel junctions (MTJs) by exploiting the mathematical isomorphism between low-dissipation MTJ spin dynamics and superconducting Josephson junction physics. The authors develop a Hamiltonian formalism identifying three distinct MTJ-based qubit types—transmon, flux, and charge—and derive conditions on anisotropy constants, Gilbert damping $\\alpha \\lesssim 10^{-3}$, resonance frequency $\\omega_r \\sim 10^{10}$ rad/s, and temperature $T \\lesssim 0.36$ K for quantum operation."}, {"id": "2602.14637", "t": "A scalable non-superconducting tunnel junction technology", "a": "Juho Luomahaara, Kristupas Razas, Omid Sharifi Sedeh, Renan P. Loreto, Janne S. Lehtinen, Mingchi Xu, Armel A. Cotten, Aldo Tarascio, Peter Müller, Nikolai Yurttagül, Lassi Lehtisyrjä, Leif Grönberg, Christian P. Scheller, Jonathan R. Prance, Michael D. Thompson, Richard P. Haley, Mika Prunnila, Dominik M. Zumbühl", "d": "2026-02-17", "s": 51.5, "x": "A CMOS-compatible normal-metal tunnel junction technology based on TiW/Al-AlOx/TiW trilayers has been demonstrated with wafer-scale yield and validated using Coulomb blockade thermometers down to 20 mK. The TiW electrodes suppress Al superconductivity via proximity effects while preserving the high-quality AlOx barrier, enabling zero-field operation of non-superconducting junctions across a broad cryogenic temperature range."}, {"id": "2602.12773", "t": "Design and Operation of Wafer-Scale Packages Containing >500 Superconducting Qubits", "a": "Oscar W. Kennedy, Waqas Ahmad, Robert Armstrong, Amir Awawdeh, Anirban Bose, Kevin G. Crawford, Sergey Danilin, William D. David, Hamid El Maazouz, Darren J. Hayton, George B. Long, Alexey Lyapin, Scott A. Manifold, Kowsar Shahbazi, Ryan Wesley, Evan Wong, Connor D. Shelly", "d": "2026-02-16", "s": 89.0, "x": "This work presents a wafer-scale package architecture supporting >500 superconducting qubits on a single 3-inch die, engineered to suppress parasitic RF modes and material loss while managing cryogenic thermal contraction. Measurements of qubits loaded into the package demonstrate median $T_1, T_{2e} \\sim 100$ μs across ~100 qubits, readout fidelity of 97.5% (54 qubits), and effective qubit temperatures of 36 mK, validating that large-scale integration can be achieved without compromising device performance."}, {"id": "2602.11576", "t": "Control the qubit-qubit coupling with double superconducting resonators", "a": "Hui Wang, Rui Wang, Daichi Sugiyama, Chih-Yao Shih, Ching-Yeh Chen, Hiroto Mukai, Hang Xue, J. S. Tsai", "d": "2026-02-13", "s": 98.9, "x": "This work demonstrates tunable qubit-qubit coupling in a double-resonator coupler circuit using two fixed-frequency resonators (4.47 GHz and 4.80 GHz) coupled to two tunable Xmon qubits. By tuning the qubits' frequencies with DC-bias currents, the effective coupling $g_\text{eff}$ can be modulated from a switching-off point (near zero) to approximately 5 MHz through a frequency shift of only 50 MHz, measured via two-tone spectroscopy and vacuum Rabi oscillations."}, {"id": "2602.11739", "t": "Experimental setup for the combined study of spin ensembles and superconducting quantum circuits", "a": "Lukas Vogl, Gerhard B. P. Huber, Ana Strinić, Achim Marx, Stefan Filipp, Kirill G. Fedorov, Rudolf Gross, Nadezhda P. Kukharchyk", "d": "2026-02-13", "s": 89.8, "x": "This work demonstrates the first experimental setup integrating flux-tunable superconducting qubits and spin ensembles in separate sample volumes within a single dilution refrigerator, achieving magnetic field suppression by more than eight orders of magnitude. The hybrid architecture uses a superconducting NbTi solenoid generating fields up to 50 mT enclosed in layered Cryophy® and superconducting aluminum shields, with verified qubit stability under full field operation."}, {"id": "2602.11912", "t": "Millisecond-Scale Calibration and Benchmarking of Superconducting Qubits", "a": "Malthe A. Marciniak, Rune T. Birke, Johann B. Severin, Fabrizio Berritta, Daniel Kjær, Filip Nilsson, Smitha N. Themadath, Sangeeth Kallatt, James L. Webb, Kristoffer Bentsen, Tonny Madsen, Zhenhai Sun, Svend Krøjer, Christopher W. Warren, Jacob Hastrup, Morten Kjaergaard", "d": "2026-02-13", "s": 88.1, "x": "This work demonstrates an on-FPGA calibration and benchmarking workflow for superconducting qubits that achieves millisecond time-to-decision by co-locating pulse generation, data acquisition, analysis, and feedback on the control hardware. The workflow introduces analytical decay estimation (ADE) and sparse phase estimation (SPE) methods that enable rapid extraction of $T_1$, readout parameters, pulse amplitudes, and gate fidelities while operating a flux-tunable transmon in a closed-loop recalibration protocol over 6 hours."}, {"id": "2602.11469", "t": "Structural control of two-level defect density revealed by high-throughput correlative measurements of Josephson junctions", "a": "Oliver F. Wolff, Harshvardhan Mantry, Rahim Raja, Wei-Hsiang Peng, Kaushik Singirikonda, Seungkyun Lee, Shishir Sudhaman, Rafael Goncalves, Pinshane Y. Huang, Angela Kou, Wolfgang Pfaff", "d": "2026-02-13", "s": 87.3, "x": "This work establishes a high-throughput methodology to correlate two-level system (TLS) density in Al/AlOx/Al Josephson junctions with fabrication parameters and microstructure using 6,000 junctions and 600+ STEM images. A two-thirds reduction in TLS density ($\\rho_{\\mathrm{TLS}}$: from $0.20 \\pm 0.10$ to $0.07 \\pm 0.04$ GHz$^{-1}$ µm$^{-2}$) is achieved by increasing Al electrode thickness, which correlates with larger grain size (128 nm versus 40–60 nm) and reduced grain boundary density."}, {"id": "2602.12248", "t": "Simultaneous High-Fidelity Readout and Strong Coupling for a Donor-Based Spin Qubit", "a": "Si Yan Koh, Weifan Wu, Kelvin Onggadinata, Arghya Maity, Mark Chiyuan Ma, Calvin Pei Yu Wong, Kuan Eng Johnson Goh, Bent Weber, Hui Khoon Ng, Teck Seng Koh", "d": "2026-02-13", "s": 77.0, "x": "This paper demonstrates that simultaneous high-fidelity readout ($F \\geq 99\\%$, $\\mathrm{SNR}^2 \\geq 282$) and strong coupling ($g_s \\geq \\kappa$) are achievable in donor-based flip-flop qubits coupled to superconducting resonators by optimizing the tunnel coupling $V_t$. The authors rigorously map the competing trade-offs between spin-photon coupling strength, qubit relaxation, and readout efficiency, showing that intermediate $V_t \\approx 2\\pi \\times (10$–$16)$ GHz provides the widest operational window, with squeezed input fields offering a practical route to relax experimental constraints on charge-photon coupling $g_c$ and photon loss $\\kappa$."}, {"id": "2602.11127", "t": "Two-Level System Spectroscopy from Correlated Multilevel Relaxation in Superconducting Qubits", "a": "Tanay Roy, Xinyuan You, David van Zanten, Francesco Crisa, Sabrina Garattoni, Shaojiang Zhu, Anna Grassellino, Alexander Romanenko", "d": "2026-02-12", "s": 90.8, "x": "A novel spectroscopy method identifies individual two-level system (TLS) defects in fixed-frequency transmon qubits by measuring correlated fluctuations in the decay rates $\\Gamma_{10}$ and $\\Gamma_{21}$ of the first and second excited states over hours-long timescales. The technique reveals that TLSs detuned by $\\gtrsim 100$ MHz from the qubit transition $\\omega_{01}$ still significantly contribute to relaxation through the Lorentzian tails of their noise spectral density."}, {"id": "2602.11140", "t": "Reed-Muller Error-Correction Code Encoder for SFQ-to-CMOS Interface Circuits", "a": "Yerzhan Mustafa, Berker Peköz, Selçuk Köse", "d": "2026-02-12", "s": 57.7, "x": "A Reed-Muller RM(1,3) error-correction encoder is implemented in SFQ logic using the MIT-LL SFQ5ee process to protect 4-bit messages converted to 8-bit codewords against bit errors in the SFQ-to-CMOS interface. The encoder dissipates 101.5 μW, occupies 0.193 mm², and is evaluated via a JoSIM–MATLAB framework that models process parameter variations and fabrication defects."}, {"id": "2602.10010", "t": "Magneto-optical study of Nb thin films for superconducting qubits", "a": "Amlan Datta, Kamal R. Joshi, Sunil Ghimire, Makariy A. Tanatar, Cameron J. Kopas, Jayss Marshall, Josh Y. Mutus, David P. Pappas, Matthew J. Kramer, Ruslan Prozorov", "d": "2026-02-11", "s": 89.8, "x": "Magneto-optical imaging of Nb thin films reveals distinct flux-penetration regimes—from Bean critical states to thermo-magnetic dendritic avalanches—that correlate with film microstructure and quality factors in superconducting qubits. The Nb/Si interfacial layer emerges as a critical decoherence bottleneck, with optimal thermal coupling and superconducting order parameter achieved through high-power DC sputtering (sample C), which balances flux screening with thermal stability."}, {"id": "2602.07617", "t": "Effect of metal encapsulation on bulk superconducting properties of niobium thin films used in qubits", "a": "Amlan Datta, Kamal R. Joshi, Sunil Ghimire, Bicky S. Moirangthem, Makariy A. Tanatar, Mustafa Bal, Zuhawn Sung, Sabrina Garattoni, Francesco Crisa, Akshay Murthy, David A. Garcia-Wetten, Dominic P. Goronzy, Mark C. Hersam, Michael J. Bedzyk, Shaojiang Zhu, David Olaya, Peter Hopkins, Matthew J. Kramer, Alexander Romanenko, Anna Grassellino, Ruslan Prozorov", "d": "2026-02-10", "s": 90.0, "x": "Metal encapsulation of niobium thin films with gold or palladium/gold significantly alters bulk superconducting properties beyond surface passivation, including residual resistivity ratio, transition temperature, upper critical field, and London penetration depth. Comprehensive measurements of 110–163 nm thick Nb films on sapphire via resistivity, magnetization, magneto-optical imaging, and TDR reveal that Au-capped films exhibit the highest residual resistivity ratio ($\text{RRR} \\\napprox 34$ for epitaxial, $\\\napprox 24$ for sputtered) and transition temperature while showing the lowest upper critical field, London penetration depth, and critical current density."}, {"id": "2602.08869", "t": "A cavity-mediated reconfigurable coupling scheme for superconducting qubits", "a": "Shinyoung Hwang, Sangyeon Lee, Eunjong Kim", "d": "2026-02-10", "s": 88.4, "x": "A cavity-mediated architecture uses tunable qubit-cavity couplers to enable dynamically reconfigurable interactions between arbitrary superconducting qubit pairs through a shared bus resonator, achieving iSWAP and CZ gates in 45–70 ns with coherent errors below $10^{-4}$ and residual $ZZ$ interactions suppressed to kilohertz levels. Simulations of a four-qubit system demonstrate selective non-local two-qubit gates for all qubit pairs with fidelities exceeding 99.9% and minimal spectator crosstalk, relaxing geometric constraints on qubit placement."}, {"id": "2602.07522", "t": "Systematic Characterization of Transmon Qubit Stability with Thermal Cycling", "a": "Cong Li, Zhaohua Yang, Xinfang Zhang, Zhihao Wu, Shichuan Xue, Mingtang Deng", "d": "2026-02-10", "s": 82.6, "x": "This work presents a year-long longitudinal characterization of 27 frequency-tunable transmon qubits across four thermal cycles, revealing a clear stability hierarchy: intrinsic device parameters (qubit frequency and baseline $T_1$) remain robust with $|\\Delta f_{01}^{\\mathrm{max}}| < 0.5\\%$, while environmental variables (flux offsets and two-level system defect distributions) undergo stochastic reconfiguration. Through frequency-dependent relaxation spectroscopy and a novel $T_1$ Spectral Topography Fidelity metric, the authors demonstrate that each thermal cycle acts as a 'hard reset' of the defect landscape, inducing spectral randomization equivalent to $>1000$ hours of continuous low-temperature evolution."}, {"id": "2602.08890", "t": "Multiplexed microwave resonators by frequency comb spectroscopy", "a": "Angelo Greco, Jukka-Pekka Kaikkonen, Luca Chirolli, Alberto Ronzani, Jorden Senior, Francesco Giazotto, Alessandro Crippa", "d": "2026-02-10", "s": 73.5, "x": "A superconducting SQUID-based frequency comb generator operating at cryogenic temperature is used to perform spectroscopy of coplanar waveguide microwave resonators, achieving quality factor measurements comparable to vector network analyzer characterization. Bi-chromatic pumping generates intermodulation products enabling simultaneous multiplexed readout of multiple non-uniformly spaced resonators via frequency combs of the form $f_{n,m} = nf_{p1} + mf_{p2}$."}, {"id": "2602.08610", "t": "Quantum Charging Advantage in Superconducting Solid-State Batteries", "a": "Chang-Kang Hu, Chilong Liu, Jingchao Zhao, Liuzhu Zhong, Yuxuan Zhou, Mingze Liu, Haolan Yuan, Yongchang Lin, Yue Xu, Guantian Hu, Guixu Xie, Zixing Liu, Ruiyang Zhou, Yougui Ri, Wenxuan Zhang, Ruicheng Deng, Andreia Saguia, Xiayu Linpeng, Marcelo S. Sarandy, Song Liu, Alan C. Santos, Dian Tan, Dapeng Yu", "d": "2026-02-10", "s": 62.9, "x": "This work experimentally demonstrates quantum charging advantage (QCA) in superconducting quantum batteries with 2–12 transmon qubits arranged in a linear chain, using only nearest-neighbor pairwise two-photon interactions. The quantum charging protocol (double-excitation Hamiltonian $V_\\mathrm{qu} = \\sum_{n=1}^{N-1} \\hbar g(\\sigma_n^+ \\sigma_{n+1}^+ + \\sigma_n^- \\sigma_{n+1}^-)$) outperforms classical local driving ($V_\\mathrm{cl} = \\sum_n \\hbar \\Omega(\\sigma_n^+ + \\sigma_n^-)$) under equal energy constraints."}, {"id": "2602.06812", "t": "Hybrid Coupling Topology with Dynamic ZZ Suppression for Optimizing Circuit Depth during Runtime in Superconducting Quantum Processor", "a": "Uday Sannigrahi, Amlan Chakrabarti, Swapnil Saha, Shrinjita Biswas", "d": "2026-02-09", "s": 87.7, "x": "This work introduces a hybrid tunable-coupling architecture connecting four fixed-frequency transmon qubits ($\\omega_{1,2} \\approx 5.0$–$5.6$ GHz) through a single flux-tunable coupler, using off-resonant Stark drives to suppress static ZZ interactions dynamically. Simulation results show the design achieves $\\zeta_{\\mathrm{max}}/2\\pi \\approx 18$ MHz tunable ZZ strength with near-zero crossings for interaction suppression, and demonstrates approximately 20% circuit depth reduction versus IBM Heron's coupling topology on Grover's algorithm benchmarks."}, {"id": "2602.06202", "t": "Characterizing Quantum Error Correction Performance of Radiation-induced Errors", "a": "Paul G. Baity, Anuj K. Nayak, Lav R. Varshney, Nicholas Jeon, Byung-Jun Yoon, Peter J. Love, Adolfy Hoisie", "d": "2026-02-09", "s": 84.3, "x": "This paper develops a computational model integrating Geant4/G4CMP radiation transport simulations with surface code QEC simulations to characterize how radiation-induced quasiparticle poisoning affects superconducting qubit error rates. The authors introduce a performance gap metric $\\zeta_c$ to quantify QEC resilience and demonstrate that phonon downconversion via flipside Cu metallization requires increased qubit spacing (up to 4 mm from 1 mm) to fully suppress correlated errors from muon strikes on a 17-qubit [[9,1,3]] surface code."}, {"id": "2602.06587", "t": "Stability, degeneracy, and scalability of a 600-site cavity array microscope", "a": "Anna Soper, Danial Shadmany, Adam L. Shaw, Lukas Palm, David I. Schuster, Jonathan Simon", "d": "2026-02-09", "s": 62.0, "x": "This work demonstrates a cavity array microscope (CAM) with over 600 simultaneously resonant optical cavities, achieving array-averaged finesse $F = 114(17)$ and single-atom peak cooperativity $C > 10$ with 1.15 µm mode waists spaced by 10 µm, while systematically characterizing aberrations, losses, and misalignment sensitivities that limit scalability to tens of thousands of cavities. The authors identify field curvature from aspheric lenses and optical imperfections as primary constraints, provide quantitative alignment tolerances (300 nm transverse, 10 µm longitudinal for the spherical lens), and demonstrate nanometer-scale aberration characterization via interferometric degeneracy measurements."}, {"id": "2602.05806", "t": "Assessing the Sensitivity of Niobium- and Tantalum-Based Superconducting Qubits to Infrared Radiation", "a": "Michael Kerschbaum, Felix Wagner, Uroš Ognjanović, Giovanni Vio, Kuno Knapp, Dante Colao Zanuz, Alexander Flasby, Mohsen Bahrami Panah, Andreas Wallraff, Jean-Claude Besse", "d": "2026-02-06", "s": 97.7, "x": "Tantalum-based superconducting qubits exhibit quasiparticle tunneling rates approximately three times higher than niobium qubits (1542 Hz vs 461 Hz), with stronger dependence on infrared radiation power ($\\Gamma_0 \\propto P_W^{2.6 ± 0.1}$ for Ta vs $P_W^{1.4 ± 0.1}$ for Nb), but infrared filtering reduces tantalum tunneling rates to 300 Hz and niobium to 100 Hz. The time-dependent decay of tunneling rates over days after cooldown indicates slowly radiating components in the cryostat contribute significantly to quasiparticle generation in both materials."}, {"id": "2602.06108", "t": "Quantum-controlled synthetic materials", "a": "Andrei Vrajitoarea, Gabrielle Roberts, Kaden R. A. Hazzard, Jonathan Simon, David I. Schuster", "d": "2026-02-06", "s": 65.0, "x": "This work demonstrates quantum-controlled synthetic materials by entangling the lattice potential landscape of a superconducting Bose-Hubbard circuit with an ancilla qubit, enabling the system to evolve under superpositions of different lattice configurations. The approach generates novel strongly-correlated states where solid (Mott insulator) and fluid phases coexist as entangled $N00N$ states, which are probed and enhanced using many-body Ramsey interferometry and echo techniques."}, {"id": "2602.05959", "t": "Extended Rydberg Lifetimes in a Cryogenic Atom Array", "a": "Junlan Jin, Yue Shi, Youssef Aziz Alaoui, Jingxin Deng, Yukai Lu, Jeff D. Thompson, Waseem S. Bakr", "d": "2026-02-06", "s": 56.7, "x": "A $^{133}$Cs optical tweezer array enclosed in a 4 K radiation shield achieves Rydberg lifetimes of $406(36)$ μs for the $55P_{3/2}$ state, a factor of $3.3(3)$ longer than room temperature, by suppressing blackbody radiation-induced transitions to an effective temperature below 25 K. Single-photon excitation and small differential light-shift coefficient $\bm\beta = 29(15)$ kHz/MHz$^2$ enable coherent ground-Rydberg qubit control with $T_2^* = 6.2(4)$ μs and project $T_1$ contribution to two-qubit gate infidelity down to $1.6 \times 10^{-4}$ at optimized Rabi frequency."}, {"id": "2602.04831", "t": "Review of Superconducting Qubit Devices and Their Large-Scale Integration", "a": "Hiu Yung Wong", "d": "2026-02-05", "s": 87.9, "x": "This review covers superconducting qubit design principles, implementations of DiVincenzo's criteria (qubit types, two-photon gates, readout with Purcell filters and quantum-limited amplifiers, and two-level system defects), and pathways to large-scale integration. The paper emphasizes the role of electronic design automation and scalable architecture in advancing superconducting quantum computers beyond single-device demonstrations."}, {"id": "2602.03938", "t": "Detailed, interpretable characterization of mid-circuit measurement on a transmon qubit", "a": "Piper C. Wysocki, Luke D. Burkhart, Madeline H. Morocco, Corey I. Ostrove, Riley J. Murray, Tristan Brown, Jeffrey M. Gertler, David K. Kim, Nathan E. Miller, Bethany M. Niedzielski, Katrina M. Sliwa, Robin Blume-Kohout, Gabriel O. Samach, Mollie E. Schwartz, Kenneth M. Rudinger", "d": "2026-02-05", "s": 74.9, "x": "The paper extends the error generator formalism to mid-circuit measurements (MCMs) on superconducting qubits by modeling MCM errors using a circuit gadget representation and decomposing quantum instruments into physically interpretable elementary deviations. Gate set tomography characterization of a transmon dispersive readout reveals amplitude damping ($T_1$ effects), readout error, imperfect collapse (weakness), and AC Stark shift-induced non-Markovianity, with errors quantified as functions of readout pulse amplitude across $V = 0$ to $1.8 \\times V_0$."}, {"id": "2602.04719", "t": "Enabling large-scale digital quantum simulations with superconducting qubits", "a": "Laurin E. Fischer", "d": "2026-02-05", "s": 74.6, "x": "This doctoral thesis develops methods to advance digital quantum simulation on superconducting qubits through hardware innovations, noise modeling, error mitigation, and algorithmic improvements across the full computational stack. The work addresses the fundamental challenge that current noisy devices cannot yet achieve fault-tolerant operation, requiring hybrid quantum-classical strategies to extract meaningful results."}, {"id": "2602.03186", "t": "A Tunable, Modeless, and Hybridization-free Cross-Kerr Coupler for Miniaturized Superconducting Qubits", "a": "Gihwan Kim, Andreas Butler, Oskar Painter", "d": "2026-02-04", "s": 95.2, "x": "This work proposes SQUID couplers with small Josephson energies ($E_{J,C}/2\\pi \\lesssim 1$ GHz) for tunable cross-Kerr coupling between superconducting qubits, enabling high-fidelity CZ gates without introducing additional modes or mode hybridization. A scalable miniaturized mergemon processor architecture is presented where all interactions are mediated by junction-based couplers, achieving predicted 100 µm lattice constants and qubit densities up to $10^6$ per 10 cm × 10 cm."}, {"id": "2602.03765", "t": "Accelerating qubit reset through the Mpemba effect", "a": "Théo Lejeune, Miha Papič, John Goold, Felix C. Binder, François Damanet, Mattia Moroder", "d": "2026-02-04", "s": 70.2, "x": "This work proposes and experimentally demonstrates an Mpemba-inspired protocol to accelerate passive qubit reset in the $T_2 > T_1$ regime by converting local single-qubit coherences into fast-decaying global two-qubit coherences via a single entangling gate. The protocol achieves up to 50% reduction in reset time compared to standard passive reset and remains robust under non-Markovian noise and imperfect control on an IQM superconducting processor."}, {"id": "2602.03037", "t": "Device variability of Josephson junctions induced by interface roughness", "a": "Yu Zhu, Félix Beaudoin, Hong Guo", "d": "2026-02-04", "s": 63.7, "x": "This work develops a quantitative model connecting interface roughness at Al/AlO$_x$ interfaces to Josephson energy variability in superconducting qubits by modeling roughness as a Gaussian random field and computing transport via the Ambegaokar–Baratoff relation. Monte Carlo simulations of 5,000 junctions show $E_J$ follows a log-normal distribution, with mean $E_J/h = 20.447 \text{ GHz}$ (for $\bar{d} = 1.0$ nm, $\bar{U} = 1.1$ eV, $\bar{\".pm"}, {"id": "2602.01945", "t": "Real-time detection of correlated quasiparticle tunneling events in a multi-qubit superconducting device", "a": "Simon Sundelin, Linus Andersson, Hampus Brunander, Simone Gasparinetti", "d": "2026-02-03", "s": 83.4, "x": "This work demonstrates real-time detection of quasiparticle tunneling events in two moderately charge-sensitive transmons ($E_J/E_C \\approx 15$) coupled to a common waveguide, achieving single-hertz background resolution with 100 µs temporal resolution. The study reveals three distinct QP dynamics regimes: uncorrelated baseline switching ($\\Gamma_\\mathrm{slow}^{(1)} = 5.28$ s$^{-1}$, $\\Gamma_\\mathrm{slow}^{(2)} = 3.61$ s$^{-1}$), correlated bursts occurring ~1 min$^{-1}$ with thousand-fold rate enhancement ($\\Gamma_\\mathrm{fast} \\sim 4000$ s$^{-1}$) and ~7 ms lifetime, and a rarer subset showing offset-charge shifts ($\\sim1$–2 h$^{-1}$) consistent with ionizing events."}, {"id": "2602.00928", "t": "Electro-optic conversion of itinerant Fock states", "a": "Thomas Werner, Erfan Riyazi, Samarth Hawaldar, Rishabh Sahu, Georg Arnold, Paul Falthansl-Scheinecker, Jennifer A. Sánchez Naranjo, Dante Loi, Lucky N. Kapoor, Martin Zemlicka, Liu Qiu, Andrei Militaru, Johannes M. Fink", "d": "2026-02-03", "s": 80.7, "x": "This work demonstrates on-demand generation and upconversion of itinerant single microwave photons at 8.9 GHz from a superconducting transmon qubit to telecom-wavelength light at 193.4 THz using an electro-optic transducer based on a lithium niobate whispering gallery mode resonator. The transducer operates at exceptionally low added noise of 0.012 quanta and achieves a signal-to-noise ratio of $5.1 \times$ the measurement uncertainty, enabling quantum networking with superconducting circuits."}, {"id": "2602.02255", "t": "Long-range phase coherence and phase patterns in hybrid Josephson junction arrays", "a": "Xi Wang, Asbjørn C. C. Drachmann, Candice Thomas, Michael J. Manfra, Nandini Trivedi, Charles M. Marcus, Saulius Vaitiekėnas, Beena Kalisky", "d": "2026-02-03", "s": 56.0, "x": "This work uses scanning SQUID microscopy to directly image the spatial phase structure and susceptibility of a square-lattice hybrid Josephson junction array, revealing periodic phase patterns at commensurate magnetic fillings and fragmentation into phase-locked domains at fields $< 1\\%$ of $\\Phi_0$ per unit cell. The measurements provide the first direct observation of long-range superconducting phase coherence in such arrays and its suppression across a quantum phase transition."}, {"id": "2601.22286", "t": "Efficient learning of logical noise from syndrome data", "a": "Han Zheng, Chia-Tung Chu, Senrui Chen, Argyris Giannisis Manes, Su-un Lee, Sisi Zhou, Liang Jiang", "d": "2026-02-02", "s": 67.6, "x": "This paper extends prior work on learning logical noise from syndrome data from phenomenological to realistic circuit-level noise models, deriving necessary and sufficient learnability conditions via code-theoretic methods and spacetime code formalism. Efficient estimators using Fourier analysis and compressed sensing are developed with provable sample-complexity guarantees, achieving orders-of-magnitude savings over direct logical benchmarking in estimating logical error probabilities from syndrome data alone."}, {"id": "2601.23100", "t": "Andreev bound states in a superconducting qubit at odd parity", "a": "Manuel Houzet, Julia S. Meyer, Yuli V. Nazarov", "d": "2026-02-02", "s": 64.7, "x": "This work derives the low-energy spectrum of Andreev bound states in a superconducting qubit (single Josephson junction with capacitive environment) in the odd parity sector, where a quasiparticle is trapped at the junction. The bound-state structure differs markedly from the even parity sector, with multiple bound states appearing in certain regimes, ranging from the Cooper-pair box ($E_J \\ll E_C$) to the transmon ($E_J \\gg E_C$)."}, {"id": "2601.22785", "t": "Orders of magnitude sampling overhead reduction in quantum error mitigation", "a": "Raam Uzdin", "d": "2026-02-02", "s": 53.3, "x": "This work introduces virtual noise scaling (VNS) combined with layered mitigation to dramatically reduce sampling overhead in agnostic noise amplification (ANA) based quantum error mitigation, achieving orders-of-magnitude reductions compared to zero-noise extrapolation. The method is compatible with dynamic circuits and mid-circuit measurements, with a circuit-independent noise threshold at $s_{\\mathrm{min,2L}} \\approx 0.65$ determining when two-layer mitigation becomes preferable to single-layer mitigation."}, {"id": "2601.22503", "t": "Quantum-Enhanced Sensing Enabled by Scrambling-Induced Genuine Multipartite Entanglement", "a": "Guantian Hu, Wenxuan Zhang, Zhihua Chen, Liuzhu Zhong, Jingchao Zhao, Chilong Liu, Zixing Liu, Yue Xu, Yongchang Lin, Yougui Ri, Guixu Xie, Mingze Liu, Haolan Yuan, Yuxuan Zhou, Yu Zhang, Chang-Kang Hu, Song Liu, Dian Tan, Dapeng Yu", "d": "2026-02-02", "s": 52.0, "x": "Butterfly metrology is experimentally demonstrated on a superconducting quantum processor using information scrambling to achieve quantum-enhanced phase sensing with sensitivity approaching $N/2$ of the Heisenberg limit for up to 10 qubits. The protocol establishes genuine multipartite entanglement dynamically through many-body evolution, directly connecting information scrambling measured via out-of-time-order correlators to sensing performance."}, {"id": "2601.21616", "t": "A biased-erasure cavity qubit with hardware-efficient quantum error detection", "a": "Jiasheng Mai, Qiyu Liu, Xiaowei Deng, Yanyan Cai, Zhongchu Ni, Libo Zhang, Ling Hu, Pan Zheng, Song Liu, Yuan Xu, Dapeng Yu", "d": "2026-01-30", "s": 91.6, "x": "A biased-erasure qubit is demonstrated in a single 3D superconducting cavity using the vacuum and two-photon Fock states ($|0_L\\rangle = |0\\rangle$, $|1_L\\rangle = |2\\rangle$), achieving an erasure bias ratio exceeding 265 and converting over 99.3% of leakage errors into detected erasures with a transmon ancilla. After postselection against erasures, the qubit exhibits a strong error hierarchy with logical relaxation and dephasing rates of $(6.2~\\mathrm{ms})^{-1}$ and $(3.1~\\mathrm{ms})^{-1}$ exceeding the erasure rate by factors of 31 and 15, yielding a coherence gain of 6.0 beyond the break-even point and a residual single-qubit gate error of $2.9 \\times 10^{-3}$."}, {"id": "2601.21953", "t": "Fabrication effects on Niobium oxidation and surface contamination in Niobium-metal bilayers using X-ray photoelectron spectroscopy", "a": "Tathagata Banerjee, Maciej W. Olszewski, Valla Fatemi", "d": "2026-01-30", "s": 90.3, "x": "X-ray photoelectron spectroscopy was used to screen 17 metal and nitride capping layers on 60 nm Nb films for their ability to prevent oxygen diffusion through standard fabrication steps: annealing at 200 °C, AZ 300T resist stripping, and acid cleaning (2% HF, 10:1 BOE, Nanostrip). Resonator measurements on down-selected caps (Ta, TaN, TiN, Zr) showed Ta and TaN-capped samples achieve lower medium-power loss $\\delta_{\\mathrm{MP}}$ than bare Nb control, with Ta and TaN resilient to all tested processes while most other metals suffered oxidation or etching."}, {"id": "2601.21313", "t": "Dispersive Microwave Sensing for Quantum Computing with Floating Electrons", "a": "Yiran Tian", "d": "2026-01-30", "s": 76.3, "x": "This dissertation develops resonator-based readout techniques for floating-electron qubits on cryogenic substrates (liquid helium and solid neon) and demonstrates a low-power cryogenic microwave source. Three main experimental systems are demonstrated: RF reflectometry detection of Rydberg transitions on helium achieving $0.34$ aF/Hz capacitance sensitivity, NbTiN superconducting nanowire resonators for electrons on neon with $Q_\\mathrm{int} \\approx 2.3 \\times 10^5$, and a $140$ MHz tunnel-diode oscillator consuming $1$ μW for scalable qubit readout."}, {"id": "2601.21528", "t": "High-Coherence and High-frequency Quantum Computing: The Design of a High-Frequency, High-Coherence and Scalable Quantum Computing Architecture", "a": "Masroor H. S. Bukhari", "d": "2026-01-30", "s": 74.9, "x": "This work proposes a high-frequency transmon architecture operating at $12$ GHz (spanning $11$–$13.5$ GHz) designed to achieve longer coherence times and higher scalability than conventional $4$–$6$ GHz qubits. The design targets an 8-qubit prototype with pathways to $72$ qubits, aiming for $T_1 \\approx 1.9$ ms and quality factors $Q \\approx 2.75 \\times 10^7$ using tantalum and Nb/Al/AlO$_x$ trilayer junctions on high-resistivity Si."}, {"id": "2601.20927", "t": "Entangling logical qubits without physical operations", "a": "Jin Ming Koh, Anqi Gong, Andrei C. Diaconu, Daniel Bochen Tan, Alexandra A. Geim, Michael J. Gullans, Norman Y. Yao, Mikhail D. Lukin, Shayan Majidy", "d": "2026-01-30", "s": 71.4, "x": "Phantom codes are quantum error-correcting codes that implement logical entangling gates between all logical qubits purely through physical qubit permutations during compilation, achieving perfect fidelity with zero spatial and temporal overhead. Through exhaustive enumeration of $2.71 \times 10^{10}$ CSS codes up to $n=14$, SAT-based search, and analytic constructions using quantum Reed–Muller codes and binarized qudit codes, the work expands the phantom-code landscape from two known instances to over 100,000 codes, and demonstrates one-to-two order-of-magnitude reductions in logical infidelity for GHZ-state preparation and Trotterized many-body simulation compared to surface codes at comparable qubit overhead."}, {"id": "2601.21472", "t": "In-situ benchmarking of fault-tolerant quantum circuits. I. Clifford circuits", "a": "Xiao Xiao, Dominik Hangleiter, Dolev Bluvstein, Mikhail D. Lukin, Michael J. Gullans", "d": "2026-01-30", "s": 64.1, "x": "This paper develops a framework for learning physical and logical error rates in fault-tolerant quantum circuits directly from syndrome data using the spacetime code formalism. The method achieves polynomial sample complexity for learning logical error rates even when they are exponentially suppressed by code distance, providing an exponential advantage over direct logical measurements."}, {"id": "2601.21507", "t": "Quantum Simulation with Fluxonium Qutrit Arrays", "a": "Ivan Amelio, Quentin Ficheux, Nathan Goldman", "d": "2026-01-30", "s": 62.0, "x": "This work proposes using fluxonium superconducting circuits to implement qutrit quantum simulators with tunable parameters via external flux bias, identifying four distinct operational regimes characterized by plasmon-like versus fluxon-like excitations. The platform realizes an extended Bose-Hubbard model with three-body hard-core constraint, correlated single-particle and pair hopping, and non-local interactions, exhibiting rich phase diagrams including superfluid, pair-superfluid, Mott-insulator, and pair-checkerboard phases."}, {"id": "2601.21838", "t": "Error-detectable Universal Control for High-Gain Bosonic Quantum Error Correction", "a": "Weizhou Cai, Zi-Jie Chen, Ming Li, Qing-Xuan Jie, Xu-Bo Zou, Guang-Can Guo, Luyan Sun, Chang-Ling Zou", "d": "2026-01-30", "s": 58.1, "x": "This work introduces error-detectable (ED) universal control of bosonic modes using a higher-energy-level ancilla ($|g\\rangle$, $|e\\rangle$, $|f\\rangle$) to detect and post-select against ancilla relaxation events, suppressing operational errors that limit QEC gains in binomial codes. Numerical simulations demonstrate universal gate fidelities exceeding 99.6% and peak QEC gains of $8.33\\times$ beyond break-even, with analytical arguments establishing that gains beyond $10\\times$ are achievable with state-of-the-art transmon qubits having $T_1 \\sim 100$ µs."}, {"id": "2601.20458", "t": "Echo Cross Resonance gate error budgeting on a superconducting quantum processor", "a": "Travers Ward, Russell P. Rundle, Richard Bounds, Norbert Deak, Gavin Dold, Apoorva Hegde, William Howard, Ailsa Keyser, George B. Long, Benjamin Rogers, Jonathan J. Burnett, Bryn A. Bell", "d": "2026-01-29", "s": 92.3, "x": "This work presents an error budgeting and suppression procedure for the echo cross-resonance (ECR) gate on an OQC Toshiko Gen-1 32-qubit superconducting processor, identifying and mitigating control-qubit leakage, $I\\hat{Z}$ coherent errors, and background $ZZ$ interactions through pulse-shaping and compensating gates. Applied to a 16-qubit chain, the procedure achieves a 3.7× reduction in two-qubit gate error rates, improving the median error from 4.6% to 1.2% as measured by interleaved randomized benchmarking, with the largest improvements on previously under-performing pairs."}, {"id": "2601.20091", "t": "Krypton-sputtered tantalum films for scalable high-performance quantum devices", "a": "Maciej W. Olszewski, Lingda Kong, Simon Reinhardt, Daniel Tong, Xinyi Du, Gabriele Di Gianluca, Haoran Lu, Saswata Roy, Luojia Zhang, Aleksandra B. Biedron, David A. Muller, Valla Fatemi", "d": "2026-01-29", "s": 91.8, "x": "Krypton sputtering enables body-centered cubic tantalum film deposition on silicon at temperatures as low as 200 °C, compared to 350–650 °C for argon, while achieving higher electronic conductivity consistent with clean-limit superconductivity. Coplanar waveguide resonators exhibit median quality factors of 4.1 million at single-photon power (350 °C Kr), and transmon qubits with 20 µm capacitor gaps reach median $Q_1$ up to 14 million."}, {"id": "2601.20521", "t": "Scanning tunneling spectroscopy of superconducting nitridized aluminum thin films", "a": "Jose Antonio Moreno, Pablo García Talavera, Alba Torras-Coloma, Gemma Rius, P. Forn-Díaz, Edwin Herrera Vasco, Isabel Guillamón, Hermann Suderow", "d": "2026-01-29", "s": 60.6, "x": "Scanning tunneling spectroscopy of a 100 nm NitrAl thin film with $T_c = 2.4$ K reveals a superconducting gap $\\Delta_0 = 360$ µeV close to BCS prediction with spatial homogeneity (~10% variation) superior to typical disordered nitride films, and zero in-gap density of states up to 250 µeV. The work demonstrates STM as a materials-screening tool for superconducting quantum circuits, showing NitrAl's promise as an alternative to pure Al with enhanced critical temperature and field resilience."}, {"id": "2601.20818", "t": "Quantum Memory and Autonomous Computation in Two Dimensions", "a": "Gesa Dünnweber, Georgios Styliaris, Rahul Trivedi", "d": "2026-01-29", "s": 50.2, "x": "This paper proves the existence of a two-dimensional quantum system with local, translation-invariant, time-independent interactions that autonomously corrects quantum errors and performs universal computation without measurements or external control. The construction uses a dissipative quantum cellular automaton whose self-simulating structure implements a hierarchical concatenated code with Toom's rule protecting the control layer, and a nonzero noise threshold is established below which logical errors are suppressed exponentially with system size."}, {"id": "2601.19209", "t": "Pareto Front Engineering of Dynamical Sweet Spots in Superconducting Qubits", "a": "Zhen Yang, Shan Jin, Yajie Hao, Guangwei Deng, Xiu-Hao Deng, Re-Bing Wu, Xiaoting Wang", "d": "2026-01-28", "s": 80.4, "x": "This work introduces a Pareto-front optimization framework for periodic flux modulation of fluxonium qubits that simultaneously optimizes energy relaxation time $T_1$ and pure dephasing time $T_\\phi$, revealing trade-offs between these coherence metrics at dynamical sweet spots. For realistic device parameters ($E_C/2\\pi=1$ GHz, $E_L/2\\pi=0.79$ GHz, $E_J/2\\pi=4.43$ GHz), optimized waveforms achieve $T_\\phi$ enhanced by factors of 3–5 compared to prior DSS schemes while maintaining $T_1$ in the 500–900 μs range, and the framework proves a fundamental upper bound on $T_1$ within the DSS regime under $\\sigma_z$-coupled noise."}, {"id": "2601.19581", "t": "Flux-tunable transmon incorporating a van der Waals superconductor via an Al/AlO$_x$/4Hb-TaS$_2$ Josephson junction", "a": "Eliya Blumenthal, Ilay Mangel, Amit Kanigel, Shay Hacohen-Gourgy", "d": "2026-01-28", "s": 79.7, "x": "A flux-tunable transmon with an Al/AlO$_x$/4Hb-TaS$_2$ Josephson junction was realized by sequential deposition and full in-situ oxidation of Al layers on exfoliated 4Hb-TaS$_2$, embedded in a 3D copper cavity, and characterized via two-tone spectroscopy and time-domain measurements. The device exhibits SQUID-like tunability and sub-microsecond $T_1$ (0.08–0.69 µs across devices), but exhibits rapid dephasing ($T_2^* < 16$ ns), and shows a factor-of-five deviation from the Ambegaokar–Baratoff relation, suggesting nontrivial junction physics in the hybrid system."}, {"id": "2601.19235", "t": "AC Response Across the Metal Insulator Transition of YBCO Josephson Junctions Fabricated with a Helium Ion Beam", "a": "Adhilsha Parachikunnumal, Nirjhar Sarkar, Aravind Rajeev Sreeja, Sreekar Vattipalli, Rochelle Qu, Jay C. LeFebvre, Roger K. Lake, Shane A. Cybart", "d": "2026-01-28", "s": 77.7, "x": "This work demonstrates that focused helium-ion-beam-irradiated YBCO Josephson junctions exhibit nearly ideal AC Josephson behavior across the metal–insulator transition, with clean integer Shapiro steps and negligible higher harmonics in the current–phase relation. By varying the irradiation dose from 1.6 to 3.4 × 10$^{16}$ ions/cm$^2$, the barrier is continuously tuned from SNS (metallic, $R \thickapprox 0.5$–0.8 Ω) through a crossover at 2.4 × 10$^{16}$ ions/cm$^2$ to SIS (insulating, $R \thickapprox 6$–12 Ω), revealing qualitatively different oscillation periodicities in Shapiro step response to 18 GHz RF power."}, {"id": "2601.19762", "t": "Inter-branch message transfer on superconducting quantum processors: a multi-architecture benchmark", "a": "Cameron V. Cogburn", "d": "2026-01-28", "s": 53.4, "x": "This work implements and benchmarks Violaris' unitary inter-branch message-transfer protocol across IBM Eagle, Nighthawk, and Heron (r2/r3) superconducting processors for messages up to $n=32$ qubits without error mitigation. The sparse message family—which compiles to constant two-qubit depth—reveals device-level noise differences ($p_{\rm all}$ ranging from $\rm 0.07$ to $\rm 0.68$ at $n=32$), while half-weight and dense families expose routing overhead and transpiler-seed variability near the coherence frontier."}, {"id": "2601.18384", "t": "Quantum Error Correction on Error-mitigated Physical Qubits", "a": "Minjun Jeon, Zhenyu Cai", "d": "2026-01-27", "s": 71.5, "x": "This work establishes a general framework for applying linear quantum error mitigation (QEM) techniques, including probabilistic error cancellation (PEC), zero-noise extrapolation, and symmetry verification, directly to physical qubits within quantum error correction (QEC) codes without modifying the QEC decoder. Using PEC on memory experiments, the authors analytically prove and numerically verify that the leading-order logical error probability is suppressed from $\\mathcal{O}(p^{\\lceil d/2 \\rceil})$ to $\\mathcal{O}(p^{\\lceil d/2 \\rceil + 1})$, effectively increasing the code distance by 2."}, {"id": "2601.17580", "t": "PropHunt: Automated Optimization of Quantum Syndrome Measurement Circuits", "a": "Joshua Viszlai, Satvik Maurya, Swamit Tannu, Margaret Martonosi, Frederic T. Chong", "d": "2026-01-27", "s": 67.2, "x": "PropHunt is an automated optimization tool for syndrome measurement circuits in CSS codes that minimizes ambiguous errors in the circuit-level decoding graph rather than targeting gate depth or count. On surface codes, PropHunt recovers hand-designed circuit performance, and on Lifted Product and Random Quantum Tanner codes it achieves 2.5–4× lower logical error rates than standard coloration circuits at 0.1% physical error rate."}, {"id": "2601.16261", "t": "A First Demonstration of the SQUAT Detector Architecture: Direct Measurement of Resonator-Free Charge-Sensitive Transmons", "a": "H. Magoon, T. Aralis, T. Dyson, J. Anczarski, D. Baxter, G. Bratrud, R. Carpenter, S. Condon, A. Droster, E. Figueroa-Feliciano, C. W. Fink, S. Harvey, A. Simchony, Z. J. Smith, S. Stevens, N. Tabassum, B. A. Young, C. P. Salemi, K. Stifter, D. I. Schuster, N. A. Kurinsky", "d": "2026-01-26", "s": 96.3, "x": "The Superconducting Quasiparticle-Amplifying Transmon (SQUAT) is a new sensor architecture for meV/THz detection based on a weakly charge-sensitive transmon ($E_J/E_C \\sim 25$) directly coupled to a transmission line without an intermediate readout resonator. This first experimental demonstration validates the SQUAT design using aluminum-based prototypes on sapphire, achieving simultaneous readout of charge and parity signals with noise temperatures around 10.37 K and coherence times $T_1 \\sim 50$–100 ns."}, {"id": "2601.16369", "t": "Reducing TLS loss in tantalum CPW resonators using titanium sacrificial layers", "a": "Zachary Degnan, Chun-Ching Chiu, Yi-Hsun Chen, David Sommers, Leonid Abdurakhimov, Lihuang Zhu, Arkady Fedorov, Peter Jacobson", "d": "2026-01-26", "s": 84.4, "x": "A 2 Å titanium sacrificial layer deposited on sputtered α-tantalum acts as an oxygen getter to chemically reduce the native Ta oxide at the metal-air interface; after removal by buffered oxide etchant and high-vacuum annealing at 700°C for 10 hours, tantalum coplanar waveguide resonators on high-resistivity silicon exhibit internal quality factors $Q_i$ exceeding 1.5 million at single-photon occupancy, representing a 2–4× improvement over otherwise identical devices without the titanium layer. The method directly addresses two-level system losses at the metal-air interface, achieving extracted TLS loss tangents $F\tan\rlap{/}{\rule{2pt}{0.4pt}}\text{ }\raisebox{-0.4ex}{δ}_{\text{TLS}}$ as low as $0.58 \times 10^{-6}$ and $Q_i$ values exceeding 2 million at low power and 13 million at high photon occupancy on optimized samples."}, {"id": "2601.16416", "t": "Low-Loss, High-Coherence Airbridge Interconnects Fabricated by Single-Step Lithography", "a": "Jibang Fu, Bo Ren, Jiandong Ouyang, Cong Li, Kechengqi Zhu, Yonggang Che, Xiang Fu, Shichuan Xue, Zhaohua Yang, Mingtang Deng, Junjie Wu", "d": "2026-01-26", "s": 60.7, "x": "A single-step electron-beam lithography process using a triple-layer PMMA/MMA resist stack with triple-exposure-dose and thermal reflow produces smooth, suspended aluminum airbridges with sub-200-nm features and robust mechanical stability. Implemented in gradiometric SQUID transmon qubits, these airbridges achieve $T_1 \\approx 38.65$ μs (no measurable additional loss) and $T_2^* \\approx 36$ μs ($2.5\\times$ enhancement over standard X-mon), compared to $T_2^* \\approx 2$ μs for dielectric crossover controls."}, {"id": "2601.15971", "t": "Reaching the intrinsic performance limits of superconducting nanowire single-photon detectors up to 0.1 mm wide", "a": "Kristen M. Parzuchowski, Eli Mueller, Bakhrom G. Oripov, Benedikt Hampel, Ravin A. Chowdhury, Sahil R. Patel, Daniel Kuznesof, Emma K. Batson, Ryan Morgenstern, Robert H. Hadfield, Varun B. Verma, Matthew D. Shaw, Jason P. Allmaras, Martin J. Stevens, Alex Gurevich, Adam N. McCaughan", "d": "2026-01-23", "s": 54.6, "x": "Superconducting nanowire single-photon detectors (SNSPDs) with widths up to 100 µm are tuned to their intrinsic performance limit using adjacent current-biased superconducting rails that redistribute current density across the wire width, achieving a ten orders-of-magnitude reduction in dark count rates and near-unity internal detection efficiency at 4 µm for 20 µm-wide detectors. This rail-based current redistribution suppresses edge vortex penetration, enabling operation limited only by vortex-antivortex pair unbinding in the bulk and overcoming the Pearl length ($\\Lambda \\approx 600$ µm) limitation on device width."}, {"id": "2601.15101", "t": "Bose condensation and Bogoliubov excitation in resonator-embedded superconducting qubit network", "a": "Patrick Navez, Valentina Di Meo, Berardo Ruggiero, Claudio Gatti, Fabio Chiarello, Alessandro D'Elia, Alessio Rettaroli, Emanuele Enrico, Luca Fasolo, Mikhail Fistul, Ilya Eremin, Alexandre Zagoskin, Paolo Vanacore, Paolo Silvestrini, Mikhail Lisitskiy", "d": "2026-01-22", "s": 66.0, "x": "A superconducting flux qubit network (10 qubits) coupled to a low-dissipation hybrid resonator exhibits Bose-Einstein condensation of microwave photons and collective Bogoliubov-like excitations observed via two-tone spectroscopy. The system displays bistability and hysteresis in photon occupancy as a function of pump power, with theory based on a nonlinear Gross-Pitaevskii-type equation quantitatively reproducing the experimental transmission spectra."}, {"id": "2601.14547", "t": "Active interference suppression in frequency-division-multiplexed quantum gates via off-resonant microwave tones", "a": "Haruki Mitarai, Yukihiro Tadokoro, Hiroya Tanaka", "d": "2026-01-22", "s": 60.5, "x": "This work proposes active interference suppression (AIS) for frequency-division-multiplexed simultaneous single-qubit gates on microwave-controlled qubits, demonstrating that deliberately adding off-resonant orthogonal or quasi-orthogonal microwave tones reduces gate infidelity. The gate infidelity scales inversely with the square of the number of applied microwave tones, and this scaling is optimized by shifting the frequency allocation to compensate for fast-oscillating terms neglected under the rotating-wave approximation."}, {"id": "2601.14463", "t": "Lumped-Element Model of THz HEB Mixer Based on Sputtered MgB2 Thin Film", "a": "Changyun Yoo, Changsub Kim, Daniel P. Cunnane, Boris S. Karasik", "d": "2026-01-22", "s": 56.8, "x": "A lumped-element bolometric model of THz HEB mixers based on 40-nm sputtered MgB$_2$ thin films achieves quantitative agreement with measured conversion gain, noise temperature, and LO coupling. The analysis reveals that on-chip optical losses and Johnson noise are the dominant sensitivity limiters, with Johnson noise persisting as a fundamental constraint even with optimized optical coupling."}, {"id": "2601.13509", "t": "Gigahertz-frequency Lamb wave resonator cavities on suspended lithium niobate for quantum acoustics", "a": "Michele Diego, Hong Qiao, Byunggi Kim, Minseok Ryu, Shiheng Li, Gustav Andersson, Masahiro Nomura, Andrew N. Cleland", "d": "2026-01-21", "s": 74.6, "x": "Suspended lithium niobate acoustic resonator cavities supporting GHz-frequency antisymmetric $A_0$ Lamb waves are demonstrated with intrinsic quality factors reaching approximately 6000 at millikelvin temperatures. The devices are characterized across room and cryogenic regimes, with lumped-element parameters extracted to design inductive coupling to superconducting transmon qubits achieving coupling strengths above 1 MHz."}, {"id": "2601.13648", "t": "3D Stacked Surface-Code Architecture for Measurement-Free Fault-Tolerant Quantum Error Correction", "a": "GunSik Min, IlKwon Sohn, Jun Heo", "d": "2026-01-21", "s": 62.8, "x": "This work proposes a 3D stacked surface-code architecture for measurement-free quantum error correction that eliminates the $O(d)$ SWAP routing overhead required for transversal coupling between logical patches in 2D layouts. Vertical couplers enable constant-depth inter-layer operations, and performance analysis shows the 3D MFEC surface code achieves logical error rates orders of magnitude below standard measurement-based codes in regimes where measurements are slow and noisy."}, {"id": "2601.14226", "t": "Deep Learning Approaches to Quantum Error Mitigation", "a": "Leonardo Placidi, Ifan Williams, Enrico Rinaldi, Daniel Mills, Cristina Cîrstoiu, Vanya Eccles, Ross Duncan", "d": "2026-01-21", "s": 58.7, "x": "This work presents a systematic evaluation of deep learning architectures for mitigating noise in quantum circuit output probability distributions using IBM 5-qubit superconducting processors and over 246,000 unique circuits. Attention-based models, particularly the Transformer and Perceiver, consistently outperform classical baselines (SPAM, Repolarizer, Mix, Thresholding) and simpler neural networks, achieving mitigation on ~80% of real hardware circuits by reducing the $L_1$ distance between noisy and ideal distributions."}, {"id": "2601.11714", "t": "Experimental observation of dynamical blockade between transmon qubits via ZZ interaction engineering", "a": "Marco Riccardi, Aviv Glezer Moshe, Guido Menichetti, Riccardo Aiudi, Carlo Cosenza, Ashkan Abedi, Roberto Menta, Halima Giovanna Ahmad, Diego Nieri Orfatti, Francesco Cioni, Davide Massarotti, Francesco Tafuri, Vittorio Giovannetti, Marco Polini, Francesco Caravelli, Daniel Szombati", "d": "2026-01-20", "s": 89.1, "x": "This paper demonstrates strong ZZ coupling between capacitively coupled transmon qubits, achieving cross-Kerr interaction strengths up to 350 MHz—more than an order of magnitude larger than prior capacitive implementations—and uses this to observe a dynamical blockade effect analogous to Rydberg-atom dipole blockade. The engineered longitudinal interaction enables interaction-dominated physics in superconducting circuits suitable for globally controlled quantum architectures."}, {"id": "2601.12168", "t": "Single-shot Quantum State Classification via Nonlinear Quantum Amplification", "a": "Elif Cüce, Saeed A. Khan, Boris Mesits, Michael Hatridge, Hakan E. Türeci", "d": "2026-01-20", "s": 65.0, "x": "This work demonstrates that operating cryogenic quantum amplifiers in the nonlinear regime, rather than optimizing for linear quantum-limited performance, can enhance single-shot quantum state classification when the measurement chain is end-to-end optimized for task-specific objectives. The analysis uses two coupled SNAIL oscillators—a squeezer for state preparation and a nonlinear analyzer—and shows that exploiting Kerr nonlinearity to transduce information encoded in higher-order moments achieves classification fidelities approaching unity in regimes where linear amplification fails."}, {"id": "2601.11879", "t": "Scalable and telecom single-erbium system with record-long room-temperature quantum coherence", "a": "Alex Kaloyeros, Natasha Tabassum, Spyros Gallis", "d": "2026-01-20", "s": 52.0, "x": "Single Er$^{3+}$ ions in a CMOS-compatible platform achieve record optical coherence times exceeding 500 μs in the telecom C-band at room temperature, surpassing previously cryogenic-only performance. Background-free upconversion-enabled single-photon readout and self-aligned nanofabrication enable scalable, individually addressable Er-qudits (five-level systems) without cryogenic cooling."}, {"id": "2601.11086", "t": "Converting qubit relaxation into erasures with a single fluxonium", "a": "Chenlu Liu, Yulong Li, Jiahui Wang, Quan Guan, Lijing Jin, Lu Ma, Ruizi Hu, Tenghui Wang, Xing Zhu, Hai-Feng Yu, Chunqing Deng, Xizheng Ma", "d": "2026-01-19", "s": 92.7, "x": "This work demonstrates erasure conversion in a single fluxonium qubit operated at zero flux, where the logical qubit is encoded in the $|0\\rangle$–$|2\\rangle$ subspace and physical relaxation is routed through the intermediate $|1\\rangle$ state as a detectable erasure. A single resonator coupled dispersively to the qubit performs both mid-circuit erasure detection and end-of-line logical readout, achieving a four-fold increase in logical lifetime from 193 µs to 869 µs via post-selection on non-erasure outcomes."}, {"id": "2601.11316", "t": "Dressed-state relaxation in coupled qubits as a source of two-qubit gate errors", "a": "Ruixia Wang, Jiayu Ding, Chenlu Wang, Yujia Zhang, He Wang, Wuerkaixi Nuerbolati, Zhen Yang, Xuehui Liang, Weijie Sun, Haifeng Yu, Fei Yan", "d": "2026-01-19", "s": 89.0, "x": "This work demonstrates that noise at frequencies matching the dressed-state energy splitting $2g$ (set by inter-qubit coupling) induces a distinct relaxation channel in coupled superconducting qubits during two-qubit gates, with gate errors scaling as $\\epsilon_\\mathrm{avg} = \\frac{1}{5}\\Gamma_g \\tau$ where $\\Gamma_g = \\frac{1}{2}S_\\Delta(2g)$. The mechanism, validated experimentally on tunable transmon qubits with engineered noise spectra from 5–20 MHz, extends the concept of $T_{1\\rho}$ relaxation to interacting systems and applies universally to dual-rail and singlet-triplet encodings."}, {"id": "2601.11378", "t": "Transmon Architecture for Emission and Detection of Single Microwave Photons", "a": "Daniel L. Campbell, Stephen McCoy, Melinda Andrews, Alexander Madden, Viva R. Horowitz, Bakir Husremović, Samuel Marash, Christopher Nadeau, Man Nguyen, Andrew M. Brownell, Derrick Sica, Michael Senatore, Samuel Schwab, Erin Sheridan, Matthew D. LaHaye", "d": "2026-01-19", "s": 87.4, "x": "We develop a transmon emitter/detector (TED) superconducting circuit combining a data transmon, a double transmon coupler (DTC), and a waveguide-coupled transmon to enable tunable single-photon emission and detection while preserving data-qubit coherence. In a meter-scale pitch-and-detect configuration, we demonstrate 60% detection of emitted Fock states with inferred 95% intrinsic detection efficiency, with both emission and detection protocols completing in ~2 µs each."}, {"id": "2601.11303", "t": "Controlled Parity of Cooper Pair Tunneling in a Hybrid Superconducting Qubit", "a": "David Feldstein-Bofill, Leo Uhre Jakobsen, Ksenia Shagalov, Zhenhai Sun, Casper Wied, Shikhar Singh, Anders Kringhøj, Jacob Hastrup, András Gyenis, Karsten Flensberg, Svend Krøjer, Morten Kjaergaard", "d": "2026-01-19", "s": 75.2, "x": "A hybrid superconducting qubit combines aluminum-oxide tunnel junctions with a gate-tunable InAs/Al nanowire junction in a SQUID to achieve controlled parity of Cooper pair tunneling. By tuning a single gate voltage, the device suppresses odd Josephson harmonics by up to two orders of magnitude at half-flux quantum, producing a $\\cos(2\\phi)$-dominated potential with a deep double well."}, {"id": "2601.10786", "t": "Elevator Codes: Concatenation for resource-efficient quantum memory under biased noise", "a": "Peter Shanahan, Diego Ruiz", "d": "2026-01-19", "s": 63.9, "x": "Elevator codes are concatenated classical codes designed for biased-noise qubits, combining inner repetition phase-flip codes ($d_Z^\\mathrm{inner}$ variable, $d_X^\\mathrm{inner}=1$) with high-rate outer bit-flip codes executed at the logical level. For noise bias $\\eta \\geq 7\\times10^4$, these codes reduce qubit overhead by over 50% compared to rectangular and XZZX surface codes at $p_Z=10^{-3}$ and $\\eta=2\\times10^6$ when achieving logical error rate $10^{-12}$."}, {"id": "2601.11245", "t": "Concatenated continuous driving of silicon qubit by amplitude and phase modulation", "a": "Takuma Kuno, Takeru Utsugi, Andrew J. Ramsay, Normann Mertig, Noriyuki Lee, Itaru Yanagi, Toshiyuki Mine, Nobuhiro Kusuno, Hideo Arimoto, Sofie Beyne, Julien Jussot, Stefan Kubicek, Yann Canvel, Clement Godfrin, Bart Raes, Yosuke Shimura, Roger Loo, Sylvain Baudot, Danny Wan, Kristiaan De Greve, Shinichi Saito, Digh Hisamoto, Ryuta Tsuchiya, Tetsuo Kodera, Hiroyuki Mizuno", "d": "2026-01-19", "s": 56.3, "x": "This work proposes circular-modulated concatenated continuous driving (CMCCD) for silicon spin qubits, which simultaneously modulates both amplitude and phase of the microwave drive to generate a circularly polarized field that cancels counterrotating terms in the second rotating frame, eliminating systematic pulse-area errors from the imperfect rotating wave approximation. Experimental implementation on an isotopically purified $^{28}$Si-MOS quantum dot demonstrates that CMCCD achieves higher gate fidelity than conventional amplitude- or phase-modulated CCD schemes and exhibits significantly improved robustness to static detuning and Rabi frequency errors without requiring the second rotating wave approximation."}, {"id": "2601.09969", "t": "Interfacing Superconductor and Semiconductor Digital Electronics", "a": "Yerzhan Mustafa, Selçuk Köse", "d": "2026-01-16", "s": 86.3, "x": "This survey reviews superconductor-semiconductor interface circuits, focusing on output drivers that convert single-flux-quantum (SFQ) pulses (1 mV, 2 ps duration) into voltage signals processable by CMOS (hundreds of mV to volts). Two main categories are identified: Josephson-junction-based drivers (latching and SQUID-based) and multi-terminal devices (cryotrons and superconductor-based transistors)."}, {"id": "2601.10209", "t": "Coherence Limits in Interference-Based cos(2$\\varphi$) Qubits", "a": "S. Messelot, A. Leblanc, J. -S. Tettekpoe, F. Lefloch, Q. Ficheux, J. Renard, É. Dumur", "d": "2026-01-16", "s": 82.8, "x": "This paper investigates coherence properties of parity-protected $\\cos(2\\varphi)$ qubits based on interference between Josephson elements in a superconducting loop, showing that despite suppressing single Cooper pair tunneling for energy relaxation protection, a fundamental trade-off exists between charge and flux noise dephasing. With current circuit parameters, $T_1$ exceeds milliseconds while $T_\\varphi$ remains limited to microseconds, establishing practical constraints on this qubit class."}, {"id": "2601.10023", "t": "Hybrid superinductance with Al/InAs", "a": "Junseok Oh, Ido Levy, Tyler Cowan, Jacob Issokson, Archana Kamal, Javad Shabani, Andrew P. Higginbotham", "d": "2026-01-16", "s": 80.3, "x": "Planar Al/InAs Josephson junction chains achieve superinductance with characteristic impedance $Z = 4.7$ to $5.2~\text{k}\\ \\"}, {"id": "2601.10385", "t": "Experimental Realization of Rabi-Driven Reset for Fast Cooling of a High-Q Cavity", "a": "Eliya Blumenthal, Natan Karaev, Shay Hacohen-Gourgy", "d": "2026-01-16", "s": 75.9, "x": "This work demonstrates Rabi-Driven Reset (RDR), a measurement-free continuous cooling protocol for a superconducting cavity mode that achieves single-photon decay in $1.2$ µs (170× faster than the intrinsic $170$ µs lifetime) and cools $\\sim 30$ thermal photons to $\\bar{n} = 0.045 \\pm 0.025$ in $80$ µs. The method combines a strong Rabi drive on a transmon qubit with sideband drives on memory and readout modes detuned by the Rabi frequency to convert dispersive coupling into effective Jaynes–Cummings interactions, creating engineered dissipation that scales with qubit-mode coupling rather than intermode cross-Kerr."}, {"id": "2601.10144", "t": "Bridging Superconducting and Neutral-Atom Platforms for Efficient Fault-Tolerant Quantum Architectures", "a": "Xiang Fang, Jixuan Ruan, Sharanya Prabhu, Ang Li, Travis Humble, Dean Tullsen, Yufei Ding", "d": "2026-01-16", "s": 67.8, "x": "This paper proposes heterogeneous quantum architectures (HQA) pairing superconducting and neutral-atom platforms for fault-tolerant quantum computing, introducing two design strategies: MagicAcc offloads magic state factories to fast SC devices ($10–100$ ns gates, 99.9% fidelity) while executing computation on scalable NA arrays ($0.1–1$ µs gates, >6000 qubits), and Memory-Compute Separation utilizes NA qLDPC memory for high-density storage while SC provides fast surface-code processing. End-to-end cost modeling demonstrates that HT-MCSep-MAcc achieves $752 ×$ speedup over NA-only baselines and reduces physical qubit footprint by $10.8 ×$ compared to SC-only systems through principled role assignment based on complementary hardware strengths."}, {"id": "2601.09889", "t": "Multiple Andreev Reflection Effects in Asymmetric STM Josephson Junctions", "a": "Wan-Ting Liao, S. K. Dutta, R. E. Butera, C. J. Lobb, F. C. Wellstood, M. Dreyer", "d": "2026-01-16", "s": 63.5, "x": "This work generalizes multiple Andreev reflection (MAR) theory to asymmetric Josephson junctions with unequal superconducting gaps, enabling quantitative interpretation of STM-based Nb–Nb junctions across three transport regimes. By measuring $I$–$V$ characteristics over normal-state resistances $R_n = 1$ kΩ to 10 MΩ at 50 mK and 1.5 K, the authors extract the tip and sample gaps ($\\Delta_t \\approx 0.67$ meV, $\\Delta_s \\approx 1.51$ meV), barrier transparency ($D$ ranging from 0.1 to 0.6), and effective channel number ($N = 2$ to 20)."}, {"id": "2601.10446", "t": "Minimal-Energy Optimal Control of Tunable Two-Qubit Gates in Superconducting Platforms Using Continuous Dynamical Decoupling", "a": "Adonai Hilário da Silva, Octávio da Motta, Leonardo Kleber Castelano, Reginaldo de Jesus Napolitano", "d": "2026-01-16", "s": 58.8, "x": "This work presents a two-stage scheme combining continuous dynamical decoupling (CDD) with sub-Riemannian geodesic optimal control to generate high-fidelity two-qubit entangling gates in superconducting platforms. The CDD stage suppresses residual couplings and slow noise while preserving the designed $J_{3,3}$ ZZ coupling, followed by variational optimization using a backward-propagated adjoint equation to determine minimal-energy control fields."}, {"id": "2601.09921", "t": "Learning to Decode in Parallel: Self-Coordinating Neural Network for Real-Time Quantum Error Correction", "a": "Kai Zhang, Zhengzhong Yi, Shaojun Guo, Linghang Kong, Situ Wang, Xiaoyu Zhan, Tan He, Weiping Lin, Tao Jiang, Dongxin Gao, Yiming Zhang, Fangming Liu, Fang Zhang, Zhengfeng Ji, Fusheng Chen, Jianxin Chen", "d": "2026-01-16", "s": 56.4, "x": "This work presents a scalable parallel neural network decoder for surface codes that achieves state-of-the-art accuracy while enabling real-time decoding throughput by training a recurrent transformer to output local logical corrections per decoding window that self-coordinate across boundaries. A single TPU v6e achieves <1 μs per syndrome round for surface codes up to distance 25, compared to AlphaQubit's ~20 μs latency, validated experimentally on the Zuchongzhi 3.2 superconducting processor achieving logical error rates of 0.0078 ± 0.0001 per round at d=7."}, {"id": "2601.10461", "t": "Erasure conversion for singlet-triplet spin qubits enables high-performance shuttling-based quantum error correction", "a": "Adam Siegel, Simon Benjamin", "d": "2026-01-16", "s": 52.2, "x": "This paper presents a fault-tolerant quantum error correction framework based on singlet-triplet (dual-spin) qubits in semiconductor devices, establishing them as natural erasure qubits. A hardware-efficient leakage-detection protocol projects leaked qubits back to the computational subspace without measurement feedback, and when combined with the XZZX surface code achieves a twofold threshold increase and orders-of-magnitude logical error rate reductions."}, {"id": "2601.10480", "t": "Effects of Integrated Heatsinking on Superconductivity in Tantalum Nitride Nanowires at the 300 Millimeter Scale", "a": "Ekta Bhatia, Tharanga R. Nanayakkara, Chenyu Zhou, Tuan Vo, Wenli Collison, Jakub Nalaskowski, Stephen Olson, Soumen Kar, Hunter Frost, John Mucci, Brian Martinick, Ilyssa Wells, Thomas Murray, Corbet Johnson, Charles T Black, Mingzhao Liu, Satyavolu S Papa Rao", "d": "2026-01-16", "s": 51.1, "x": "TaN and TaN/Cu bilayer nanowires were fabricated on 300 mm wafers using CMOS-compatible processes, achieving $T_c = 4.1$ K and coherence length $\rlap{\raise 0.25em\\hbox{$\rlap{-}$}}\\xi_0 = 7$ nm for 39 nm thick TaN with <5% variation across the wafer. Cu integration provides ~100× enhancement in the SBT heat-transfer parameter $\\beta$ and near-unity critical-to-retrapping current ratio, enabling faster reset times in SNSPDs while maintaining superconducting performance."}, {"id": "2601.09591", "t": "Submicrometer tunnel ferromagnetic Josephson junctions with transmon energy scale", "a": "R. Satariano, R. Ferraiuolo, F. Calloni, H. G. Ahmad, D. Gatta, F. Tafuri, A. Bruno, D. Massarotti", "d": "2026-01-15", "s": 66.7, "x": "Submicron Al/AlO$_x$/Al/Ni$_{80}$Fe$_{20}$/Al tunnel ferromagnetic Josephson junctions have been fabricated using Manhattan-process lithography, achieving energy scales ($E_C \\sim 40$ µeV, $E_J \\sim 100$–130 µeV) compatible with transmon qubits. The junctions exhibit I-V characteristics and quantum phase diffusion signatures comparable to standard SIS junctions, with $C_J \\sim 2$ fF and switching-current reduction of 70% consistent with WKB theory, establishing feasibility of ferrotransmon integration in standard superconducting circuits."}, {"id": "2601.09014", "t": "Impact of control signal phase noise on qubit fidelity", "a": "Agata Barsotti, Paolo Marconcini, Gregorio Procissi, Massimo Macucci", "d": "2026-01-15", "s": 62.2, "x": "This work investigates phase noise effects on superconducting qubit fidelity through time-domain numerical simulations with Qiskit-Dynamics, resolving a previous misinterpretation that claimed high-frequency noise components dominate fidelity loss. The authors demonstrate that noise components near the Rabi frequency and low-frequency components with large amplitude are the primary fidelity degradation sources, with high-frequency noise contributing only marginally through residual amplitude modulation."}, {"id": "2601.09516", "t": "Reservoir-Engineered Refrigeration of a Superconducting Cavity with Double-Quantum-Dot Spin Qubits", "a": "Daryoosh Vashaee, Jahanfar Abouie", "d": "2026-01-15", "s": 51.4, "x": "This work develops an analytic theory of reservoir engineering for superconducting cavity cooling using gate-defined double-quantum-dot spin qubits as a tunable photon birth-death process. Lindblad simulations confirm millikelvin steady-state cavity temperatures achievable through collective bright-mode coupling in two-dot configurations, subject to constraints from memory effects, saturation, and dark-state formation."}, {"id": "2601.08213", "t": "Quantum State Discrimination Enhanced by FPGA-Based AI Engine Technology", "a": "Anastasiia Butko, Artem Marisov, David I. Santiago, Irfan Siddiqi", "d": "2026-01-14", "s": 68.4, "x": "This work presents a real-time quantum state discrimination system using a multi-layer neural network implemented on the AMD Xilinx VCK190 FPGA AI Engine to classify qubit IQ-plane readout data. The approach achieves $81.6$ ns kernel latency with $0.25\\%$ resource utilization on the AI Engine tile array, enabling mid-circuit measurements while preserving FPGA programmable logic resources for other quantum control tasks."}, {"id": "2601.07825", "t": "Mechanical Resonator-based Quantum Computing", "a": "Yu Yang, Igor Kladaric, Martynas Skrabulis, Michael Eichenberger, Stefano Marti, Simon Storz, Jonathan Esche, Raquel Garcia Belles, Max-Emanuel Kern, Andraz Omahen, Arianne Brooks, Marius Bild, Mateo Fadel, Yiwen Chu", "d": "2026-01-13", "s": 87.3, "x": "This work demonstrates mechanical resonator-based quantum computing (MRQC) using a superconducting transmon qubit coupled to a high-overtone bulk acoustic wave resonator (HBAR) with three phonon modes serving as quantum memory. A universal gate set including single-qubit operations and controlled arbitrary-phase gates is implemented, enabling quantum Fourier transform and period-finding algorithms with measured fidelities exceeding 85% for two-qubit gates."}, {"id": "2601.07529", "t": "Hardware-Economic Manipulation of Dual-Type ${}^{171}$Yb$^+$ Qubits", "a": "Y. -J. Yi, Y. -Y. Chen, Y. -H. Hou, Y. -K. Wu, L. Zhang, C. Zhang, Y. -L. Xu, J. Ye, W. -X. Guo, B. -X. Qi, Z. -C. Zhou, P. -Y. Hou, L. -M. Duan", "d": "2026-01-13", "s": 83.6, "x": "This work demonstrates hardware-economical control of dual-type $^{171}\\mathrm{Yb}^+$ qubits encoded in $S_{1/2}$ and $F_{7/2}$ hyperfine levels using a single 355 nm mode-locked pulsed laser with broad frequency comb structure. A direct entangling gate between the two qubit types is demonstrated with 70% fidelity, simplifying the experimental requirements for scalable trapped-ion quantum computation."}, {"id": "2601.06668", "t": "Comparison of Two-Level System Microwave Losses in Pure Bulk Microcrystalline Nb2O5 and NbO2 Oxide Samples", "a": "Vishal Ganesan, Jiankun Zhang, Drew G. Wild, Alexey Bezryadin", "d": "2026-01-13", "s": 65.0, "x": "This work isolates two-level system (TLS) microwave losses in commercial niobium oxide powders by measuring their quality factors in a 3D superconducting cavity. The authors find that monoclinic Nb$_2$O$_5$ exhibits clear TLS-dominated losses consistent with the tunneling model, while tetragonal NbO$_2$ shows negligible TLS signatures, suggesting oxide phase and crystal symmetry are critical factors in determining TLS loss in niobium resonators."}, {"id": "2601.06682", "t": "Aharonov-Casher Effect and the Coherent Flux Tunneling in the Hybrid Charge Quantum Interference Device", "a": "J. W. Dunstan, R. Shaikhaidarov, K. H. Kim, A. Shesterikov, I. Antonov, S. Linzen, E. V. Il'ichev, V. N. Antonov, O. V. Astafiev", "d": "2026-01-13", "s": 57.1, "x": "A hybrid charge quantum interference device (h-CQUID) combining Josephson junctions with a high kinetic-inductance NbN loop demonstrates control of fluxon tunneling via the Aharonov-Casher effect, with the interference between two tunneling paths modulated by charge on a superconducting island. At destructive interference conditions ($Q = 2e(n + 1/2)$), the phase-slip energy $E_S$ is suppressed, with minimum $E_S/h \\approx 0.4$ GHz achieved for asymmetric junctions with $\\nu_1 = 1.48$ GHz and $\\nu_2 = 1.08$ GHz tunneling rates."}, {"id": "2601.07860", "t": "Fault-Tolerant Quantum Error Correction: Implementing Hamming-Based Codes with Advanced Syndrome Extraction Techniques", "a": "Soham Bhadra, Diyansha Singh, Angana Chowdhury", "d": "2026-01-13", "s": 53.2, "x": "This paper implements and compares three fault-tolerant syndrome extraction strategies for the Steane $[\\![7,1,3]\\!]$ code: Shor's cat-state method (85–92% preparation success, 96.8% syndrome fidelity), Steane's encoded-ancilla approach (97.8% syndrome fidelity), and a unified CSS scheduler framework. Extensive Qiskit simulations under realistic noise ($p_{\\mathrm{phys}}=10^{-3}$) achieve logical error rates as low as $5.1 \\times 10^{-5}$ and demonstrate 2.4$\\times$ improvement in error suppression compared to standard syndrome extraction."}, {"id": "2601.05326", "t": "Oxygen distribution and segregation at grain boundaries in Nb and Ta-encapsulated Nb thin films for superconducting qubits", "a": "Jaeyel Lee, Dieter Isheim, Zuhawn Sung, Francesco Crisa, Sabrina Garattoni, Mustafa Bal, Cameron J. Kopas, Josh Y. Mutus, Hilal Cansizoglu, Jayss Marshall, Kameshwar Yadavalli, Dominic P. Goronzy, Mark C. Hersam, David N. Seidman, Alex Romanenko, Anna Grassellino, Akshay A. Murthy", "d": "2026-01-12", "s": 82.7, "x": "Atom-probe tomography and TEM reveal oxygen segregation at grain boundaries in Nb and Ta/Nb thin films used for superconducting qubits, with enrichment factors $C_\text{gb}/C_\text{grain}$ of 2.7 ± 0.3 for bare Nb and 2.3 ± 0.3 for Ta-capped Nb (Ta layer itself shows 3.0 ± 0.3). Higher oxygen concentration in Nb grains correlates with stronger GB segregation and suppressed critical temperature $T_c$, suggesting oxygen control during deposition and processing is critical for reducing a potential decoherence mechanism."}, {"id": "2601.04975", "t": "Fast, high-fidelity Transmon readout with intrinsic Purcell protection via nonperturbative cross-Kerr coupling", "a": "Guillaume Beaulieu, Jun-Zhe Chen, Marco Scigliuzzo, Othmane Benhayoune-Khadraoui, Alex A. Chapple, Peter A. Spring, Alexandre Blais, Pasquale Scarlino", "d": "2026-01-09", "s": 98.0, "x": "Junction readout achieves fast, high-fidelity transmon measurement by coupling the qubit to its readout resonator through both a Josephson junction and a capacitance, creating a nonperturbative cross-Kerr interaction with intrinsic Purcell protection. Operating a bifurcation-based readout on this architecture yields 99.4% assignment fidelity in 68 ns and 98.4% QND fidelity without external Purcell filters or near-quantum-limited amplifiers."}, {"id": "2601.05231", "t": "Scalable Suppression of XY Crosstalk by Pulse-Level Control in Superconducting Quantum Processors", "a": "Hui-Hang Chen, Chiao-Hsuan Wang", "d": "2026-01-09", "s": 84.1, "x": "This work develops pulse-level control strategies to suppress residual XY coupling crosstalk in superconducting qubit processors during single-qubit operations and idle periods. Two methods are proposed: frequency modulation (FM) applying sinusoidal Z-drives and dynamical decoupling (DD) applying periodic Z-pulses, both engineered to average out the exchange interaction through phase accumulation."}, {"id": "2601.04830", "t": "Noise tailoring for error mitigation and for diagnozing digital quantum computers", "a": "Thibault Scoquart, Hugo Perrin, Kyrylo Snizhko", "d": "2026-01-09", "s": 68.5, "x": "This paper introduces Noise Tailoring (NT), a sampling technique that reshapes two-qubit gate noise from an arbitrary Pauli channel to a target structure (depolarizing) to improve error mitigation protocol efficiency. Classical emulations show up to 5× accuracy improvement for BCS quench simulations with NT+NEC versus NEC alone, but experiments on IBM quantum computers reveal that NT amplifies unaccounted error sources, making it impractical for current NISQ devices at finite sampling."}, {"id": "2601.05147", "t": "Low-loss Material for Infrared Protection of Cryogenic Quantum Applications", "a": "Markus Griedel, Max Kristen, Biliana Gasharova, Yves-Laurent Mathis, Alexey V. Ustinov, Hannes Rotzinger", "d": "2026-01-09", "s": 61.3, "x": "A non-magnetic infrared filter for cryogenic quantum devices is demonstrated using Mie scattering from sapphire spheres (0.45–700 µm diameter) embedded in epoxy resin, achieving IR attenuation $\\mu_{\\mathrm{ext}} \\approx 2$ mm$^{-1}$ below 200 µm while maintaining microwave transparency. A prototype coaxial filter based on the SP0.45-700 composition shows insertion loss below 0.4 dB at frequencies up to 10 GHz at 15 mK, with approximately 25× lower pass-band attenuation than metal-powder alternatives at comparable IR blocking."}, {"id": "2601.04645", "t": "SurgeQ: A Hybrid Framework for Ultra-Fast Quantum Processor Design and Crosstalk-Aware Circuit Execution", "a": "Xinxuan Chen, Hongxiang Zhu, Zhaohui Yang, Zhaofeng Su, Jianxin Chen, Feng Wu, Hui-Hai Zhao", "d": "2026-01-09", "s": 61.2, "x": "SurgeQ is a hardware-software co-design framework for superconducting qubits that accelerates two-qubit gate execution by increasing coupling strength (Surge factor $s$ up to 1.8) while mitigating the resulting crosstalk through a crosstalk-free scheduler that eliminates nearest-neighbor ZZ interactions. Evaluated on 127 real-world benchmarks spanning 17 categories on 127-qubit heavy-hex and 225-qubit grid topologies, SurgeQ achieves fidelities up to $10^6$ times higher than baseline Qiskit O3 on large circuits and remains effective even on dense QSIH circuits, where crosstalk-free scheduling introduces $1.61\\times$ depth overhead."}, {"id": "2601.05113", "t": "Unitary fault-tolerant encoding of Pauli states in surface codes", "a": "Luis Colmenarez, Remmy Zen, Jan Olle, Florian Marquardt, Markus Müller", "d": "2026-01-09", "s": 50.8, "x": "This work presents the first distance-preserving unitary encoding scheme for preparing Pauli eigenstates $|0\\rangle_L$ and $|+\\rangle_L$ in surface codes, generalizing strategies discovered by reinforcement learning for the surface-17 code to arbitrary distances and both rotated and unrotated variants. The scheme uses only geometrically local gates with circuit depth $\\mathcal{O}(d)$, avoiding classical feedback while preserving the code's fault distance during state preparation."}, {"id": "2601.03922", "t": "Integration and Resource Estimation of Cryoelectronics for Superconducting Fault-Tolerant Quantum Computers", "a": "Shiro Kawabata", "d": "2026-01-08", "s": 79.5, "x": "This review examines cryoelectronics integration for scaling superconducting fault-tolerant quantum computers (FTQCs), addressing how to move classical control and readout electronics from room-temperature racks into cryogenic stages to reduce wiring overhead and thermal load. Using an RSA-2048 benchmark ($\\sim 9 \\times 10^5$ physical qubits), the authors present a first-order power-budget framework connecting per-qubit dissipation, effective throughput $F$, and stage-wise cooling constraints across cryo-CMOS at 4 K and superconducting digital logic (SFQ/AQFP) at mK stages."}, {"id": "2601.04082", "t": "Surface Optimization of Superconducting Aluminum Resonators for Robust Quantum Device Fabrication", "a": "Simon J. K. Lang, Ignaz Eisele, Alwin Maiwald, Emir Music, Luis Schwarzenbach, Carla Moran-Guizan, Johannes Weber, Daniela Zahn, Thomas Mayer, Rui N. Pereira, Christoph Kutter", "d": "2026-01-08", "s": 74.4, "x": "This work investigates surface post-processing strategies for aluminum superconducting resonators to preserve low dielectric losses during the 24-hour delays encountered in industrial multi-chip fabrication before cryogenic measurement. Selective oxide removal using HF vapor and phosphoric acid achieves the best performance, with median $\\tilde{\\delta}_\\mathrm{TLS} = 3.6 \\times 10^{-7}$ ($Q_\\mathrm{TLS} \\approx 2.8$ M) in the single-photon regime, while fluorine passivation, though effective at stabilizing Al against subsequent wet etch processes, increases loss by a factor of 2.4–2.9."}, {"id": "2601.05286", "t": "Investigation of Hardware Architecture Effects on Quantum Algorithm Performance: A Comparative Hardware Study", "a": "Askar Oralkhan, Temirlan Zhaxalykov", "d": "2026-01-08", "s": 54.9, "x": "This paper presents a systematic benchmarking of five quantum algorithms (Bell states, GHZ states, QFT, Grover's search, QAOA) across trapped-ion (IonQ Aria-1, Forte-1) and superconducting (IQM Garnet, Rigetti Ankaa-3) platforms using Amazon Braket. Performance depends critically on hardware topology and noise: 10-qubit GHZ states achieved fidelities of 0.84 on IonQ but dropped to 0.09–0.12 on superconducting devices due to routing overhead and two-qubit gate errors."}, {"id": "2601.02474", "t": "Probing Dark Matter-Electron Interactions with Superconducting Qubits", "a": "Yonit Hochberg, Majed Khalaf, Noah Kurinsky, Alessandro Lenoci, Rotem Ovadia", "d": "2026-01-07", "s": 66.6, "x": "Transmon qubits are used to constrain dark matter–electron scattering by leveraging residual quasiparticle populations that exceed thermal expectations, which can arise from dark matter energy deposits breaking Cooper pairs in the superconductor. The analysis of existing transmon coherence measurements yields the strongest terrestrial laboratory constraints to date on spin-independent dark matter–electron scattering in the 1–100 keV mass range and competitive bounds on dark photon absorption."}, {"id": "2601.02183", "t": "Developments in superconducting erasure qubits for hardware-efficient quantum error correction", "a": "Maria Violaris, Luciana Henaut, James Wills, Gioele Consani, Jamie Friel, Brian Vlastakis", "d": "2026-01-06", "s": 93.3, "x": "This Perspective reviews superconducting erasure qubits, which encode logical information in dual-rail configurations where the dominant noise consists of detectable amplitude-damping events that leave the computational subspace. Erasure qubits enable hardware-efficient quantum error correction by concatenating an inner dual-rail code with outer codes like the surface code, achieving thresholds up to 50% in the code-capacity limit compared to ~19% for depolarizing noise, with realistic implementations showing 5.2× improvement in tolerable Pauli error rates."}, {"id": "2601.02137", "t": "Flux-noise-resilient transmon qubit via a doubly-connected gradiometric design", "a": "J. B. Fu, Da-Wei Wang, B. Ren, Z. H. Yang, S. Hu, G. Y. Huang, S. H. Cao, D. D. Liu, X. F. Zhang, X. Fu, S. C. Xue, Y. G. Che, Yu-xi Liu, M. T. Deng, J. J. Wu", "d": "2026-01-06", "s": 90.5, "x": "A doubly-connected gradiometric transmon (8-mon) qubit with nano-airbridge interconnect achieves a nearly threefold enhancement in Ramsey coherence time $T_2^*$ compared to reference X-mons while preserving full electrical tunability and maintaining energy relaxation times $T_1$ in the 20–45 µs range. A spatially correlated flux-noise model reveals that the gradiometric geometry suppresses low-frequency magnetic noise through destructive interference between oppositely wound loops, with suppression factor $S(\">d) \\ propto (d/\\xi)^2$ for long-wavelength noise."}, {"id": "2601.01990", "t": "Parallel Quantum Gates via Scalable Subsystem-Optimized Robust Control", "a": "Xiaodong Yang, Ran Liu, Jun Li", "d": "2026-01-06", "s": 56.8, "x": "This work develops a subsystem-optimized robust control framework for implementing high-fidelity parallel quantum gates by reducing full-system optimization to crosstalk-robust control over constant-sized subsystems. The method is validated on coupled NV centers, a 12-qubit NMR processor, and superconducting-qubit arrays up to 200 qubits, achieving linear noise scaling for parallel single-qubit gates and order-of-magnitude reductions for parallel multi-qubit operations."}, {"id": "2601.02064", "t": "Cutting Quantum Circuits Beyond Qubits", "a": "Manav Seksaria, Anil Prabhakar", "d": "2026-01-06", "s": 52.1, "x": "This work extends quantum circuit cutting to heterogeneous registers of mixed-dimensional qudits by decomposing non-local interactions into tensor products of local generalized Gell-Mann matrices, generalizing the qubit-based CNOT decomposition to arbitrary qudit dimensions $d_1$ and $d_2$. Validation on qubit–qutrit interfaces achieves exact state reconstruction with Total Variation Distance of 0 within single-precision tolerance and demonstrates a memory reduction from 128 MB to 64 KB for an 8-particle dimension-8 system."}, {"id": "2601.01394", "t": "Distant Entanglement Generation between Magnon and Superconducting Qubits in Magnon-Mediated Hybrid Systems", "a": "Guosen Liu, Pei Pei", "d": "2026-01-06", "s": 52.1, "x": "This work proposes a two-stage protocol for generating entanglement between a local superconducting qubit and remote magnons in a hybrid magnon-mediated system. Stage 1 uses shortcuts to adiabaticity to create a Bell state between the superconducting qubit and local magnons; Stage 2 coherently transfers entanglement to remote magnons via engineered Hamiltonian dynamics mediated by a waveguide."}, {"id": "2601.00078", "t": "Double-Pumped Kerr Parametric Amplifier Beyond the Gain-Bandwidth Limit", "a": "Nicolas Zapata, Najmeh Etehadi Abari, Mitchell Field, Patrick Winkel, Simon Geisert, Soeren Ihssen, Anja Metelmann, Ioan M. Pop", "d": "2026-01-02", "s": 77.4, "x": "A double-pumped granular aluminum Bose–Hubbard dimer exploits balanced four-wave mixing to achieve parametric amplification without operating near instability, enabling sixfold bandwidth improvement at 20 dB gain while surpassing the conventional gain–bandwidth tradeoff up to 25 dB. The device maintains added noise near the quantum limit and demonstrates a 41 dB phase-sensitive gain modulation, recommending grAl as a source of pure Kerr nonlinearity for multi-pump parametric amplifiers."}, {"id": "2601.00425", "t": "Chip-scale superconducting quantum gravimeter combining a SQUID, a transmon, and a nanomechanical resonator", "a": "Salman Sajad Wani, Mughees Ahmed Khan, Abrar Ahmed Naqash, Saif Al-Kuwari", "d": "2026-01-02", "s": 70.5, "x": "A chip-scale superconducting gravimeter couples a flux-tunable transmon qubit longitudinally to a nanomechanical beam via a parallel SQUID geometry, encoding gravitational acceleration as a geometric phase on the qubit. Stroboscopic readout at mechanical revival times suppresses entanglement-induced dephasing and achieves projected sensitivities of $6.5 \times 10^{-9}$ to $6.7 \times 10^{-10}$ m/s$^2$ with sub-millisecond interrogation."}, {"id": "2512.24448", "t": "Incorporating multi-qubit exchange coupling effects between transmon qubits in Maxwell-Schrödinger numerical methods", "a": "Ghazi Khan, Thomas E. Roth", "d": "2026-01-01", "s": 82.9, "x": "This paper develops Maxwell-Schrödinger numerical methods that incorporate multi-qubit exchange coupling effects for transmon qubits operating in the dispersive regime, enabling self-consistent simulation of coupled Schrödinger and classical Maxwell equations. The method reveals that qubit back-action on electromagnetic circuitry produces classical crosstalk in cross-resonance gates, explaining experimentally observed effects that prior quantum theory could not account for."}, {"id": "2512.24466", "t": "A Boundary Condition Perspective on Circuit QED Dispersive Readout", "a": "Mustafa Bakr", "d": "2026-01-01", "s": 66.0, "x": "This paper develops a boundary-condition perspective on circuit QED dispersive readout, showing how the transmon-terminated transmission line resonator provides a frequency-dependent boundary condition whose pole structure encodes qubit transition frequencies and produces state-dependent resonator frequencies. Starting from the circuit Lagrangian and applying Sturm-Liouville theory with eigenparameter-dependent boundaries, the framework derives the dispersive shift $\\chi = g^2 \\alpha/[\\Delta(\\Delta + \\alpha)]$, proves a level repulsion theorem preventing dressed modes from coinciding with transmon transitions, and extends the analysis to matched two-qubit parity measurement where engineered suppression of linear dispersive terms enables true parity-only response."}, {"id": "2512.24926", "t": "High-performance quantum interconnect between bosonic modules beyond transmission loss constraints", "a": "Hongwei Huang, Jie Zhou, Weizhou Cai, Weiting Wang, Yilong Zhou, Yunlai Zhu, Ziyue Hua, Yifang Xu, Lida Sun, Juan Song, Tang Su, Ming Li, Haifeng Yu, Chang-Ling Zou, Luyan Sun", "d": "2026-01-01", "s": 56.3, "x": "This work demonstrates a high-performance quantum interconnect between two superconducting modules using a 13.5 cm aluminum coaxial cable with $Q = 1.7 \\times 10^6$ for the bus mode, enabling 98.2% single-photon state transfer fidelity and 92.5% Bell state fidelity via three-wave mixing through SNAIL couplers. By achieving such low transmission losses (0.2% infidelity contribution), the performance bottleneck has shifted to module-channel interface effects and Kerr nonlinearities, with successful transfer of high-dimensional binomially encoded logical states achieved."}, {"id": "2512.24992", "t": "Mathieu Control of the Effective Coupling in Superconducting Qubits", "a": "Yi-Han Yu, Xin-Yi Li, Kai Xu, Heng Fan", "d": "2026-01-01", "s": 55.5, "x": "Mathieu control uses off-resonant two-photon drives on superconducting qubit circuits to engineer selective nonlinear frequency shifts that tune interactions while preserving computational subspace integrity. The scheme enables continuous ZZ coupling tuning (including zero), low-leakage gates with process fidelities $>99.94\\%$ and $1-\\mathrm{Tr}(\\chi^2) \\sim 10^{-5}$, and programmable XXZ Hamiltonians in scalable qubit-coupler chains."}];